# 2. ENTRY ALIGNMENT — 2-of-3 LTF + 2-of-3 HTF required for new entries
# ═══════════════════════════════════════════════════════════════════════════════
def check_entry_alignment(
    indicators: Dict[str, Any], is_long: bool
) -> Tuple[bool, str]:
    """Returns (allowed, reason). Requires 2/3 LTF (k_1m/3m/15m) AND 2/3 HTF (1h/4h/D) aligned.
    No crash hard-block here — hedges and trend-following entries must pass through.
    Crash ratio enforcement lives in compute_applied_ratio and ratio_rebalance_loop."""
    k_1m, d_1m = _sf(indicators.get("stoch_k_1m")), _sf(indicators.get("stoch_d_1m"))
    k_3m, d_3m = _sf(indicators.get("stoch_k_3m")), _sf(indicators.get("stoch_d_3m"))
    k_15m, d_15m = (
        _sf(indicators.get("stoch_k_15m")),
        _sf(indicators.get("stoch_d_15m")),
    )
    k_1h, d_1h = _sf(indicators.get("stoch_k_1h")), _sf(indicators.get("stoch_d_1h"))
    k_4h, d_4h = _sf(indicators.get("stoch_k_4h")), _sf(indicators.get("stoch_d_4h"))
    k_D, d_D = _sf(indicators.get("stoch_k_D")), _sf(indicators.get("stoch_d_D"))
    ha_D = str(indicators.get("ha_D", "neutral"))
    if is_long:
        ltf = int(k_1m > d_1m) + int(k_3m > d_3m) + int(k_15m > d_15m)
        htf = int(k_1h > d_1h) + int(k_4h > d_4h) + int(ha_D == "green" or k_D > d_D)
        d_aligned = ha_D == "green" or k_D > d_D
    else:
        ltf = int(k_1m < d_1m) + int(k_3m < d_3m) + int(k_15m < d_15m)
        htf = int(k_1h < d_1h) + int(k_4h < d_4h) + int(ha_D == "red" or k_D < d_D)
        d_aligned = ha_D == "red" or k_D < d_D
    # MFI cross-TF quality (RSI unreliable — MFI is volume-weighted, proven more consistent)
    mfi_1h_a = _sf(indicators.get("mfi_1h"), 50.0)
    mfi_4h_a = _sf(indicators.get("mfi_4h"), 50.0)
    if is_long:
        mfi_quality = int(mfi_1h_a < 50) + int(mfi_4h_a < 50)
        mfi_tag = (
            f"MFI_MR({mfi_1h_a:.0f}/{mfi_4h_a:.0f})"
            if mfi_quality >= 1
            else f"MFI_OB({mfi_1h_a:.0f}/{mfi_4h_a:.0f})"
        )
    else:
        mfi_quality = int(mfi_1h_a > 50) + int(mfi_4h_a > 50)
        mfi_tag = (
            f"MFI_EXH({mfi_1h_a:.0f}/{mfi_4h_a:.0f})"
            if mfi_quality >= 1
            else f"MFI_OS({mfi_1h_a:.0f}/{mfi_4h_a:.0f})"
        )
    # ENTRY: 3/3 LTF + 3/3 HTF (D is MANDATORY — not optional). Total 4+ TFs must agree.
    if ltf < 3:
        return False, f"LTF_ALIGN_FAIL({ltf}/3)"
    if htf < 2:
        return False, f"HTF_ALIGN_FAIL({htf}/3)"
    if not d_aligned:
        return (
            False,
            f"D_ALIGN_MANDATORY({'LONG' if is_long else 'SHORT'}_k_D={k_D:.0f}_d_D={d_D:.0f}_ha_D={ha_D})",
        )
    # BACKTEST_CHANGE_8: K3M_CAP blocks LONG when k_3m >= cap, SHORT when k_3m <= (100-cap)
    _k3m_cap = 70  # default; overridden by config at call sites
    if is_long and k_3m >= _k3m_cap:
        return False, f"K3M_CAP_LONG({k_3m:.0f}>={_k3m_cap})"
    if not is_long and k_3m <= (100 - _k3m_cap):
        return False, f"K3M_CAP_SHORT({k_3m:.0f}<={100 - _k3m_cap})"
    # BACKTEST_CHANGE_9: K3M_FLOOR blocks SHORT when k_3m <= floor (mirror of K3M_CAP)
    _k3m_floor = 30  # default; overridden by config at call sites
    if not is_long and k_3m <= _k3m_floor:
        return False, f"K3M_FLOOR_SHORT({k_3m:.0f}<={_k3m_floor})"
    if is_long and k_3m >= (100 - _k3m_floor):
        return False, f"K3M_FLOOR_LONG({k_3m:.0f}>={100 - _k3m_floor})"
    # BACKTEST_CHANGE_137: ADX regime filter — block entries in choppy/ranging markets (ADX < 20). 36%→182% improvement documented.
    if getattr(config, "ADX_REGIME_FILTER_ENABLED", False):
        _adx_1h = _sf(indicators.get(f"adx_{getattr(config, 'ADX_TF', '1h')}"), 25.0)
        if _adx_1h < getattr(config, "ADX_RANGING_THRESHOLD", 20.0):
            return (
                False,
                f"ADX_RANGING({_adx_1h:.0f}<{getattr(config, 'ADX_RANGING_THRESHOLD', 20.0):.0f})",
            )
    # BC_170: WT velocity 1h must confirm direction (strongest single predictor, d=0.347, 1947 trades)
    if getattr(config, "CT_WT_VELOCITY_GATE_ENABLED", False):
        _wt_vel = _sf(indicators.get("wt_velocity_1h"), 0.0)
        _min_vel = getattr(config, "CT_WT_VELOCITY_1H_MIN", 0.0)
        if is_long and _wt_vel < _min_vel:
            return False, f"CT_WT_VEL_LONG({_wt_vel:.1f}<{_min_vel})"
        if not is_long and _wt_vel > -_min_vel:
            return False, f"CT_WT_VEL_SHORT({_wt_vel:.1f}>-{_min_vel})"
    # BC_171: 15m momentum must confirm direction (d=0.345 stoch_k_15m, d=0.321 mfi_15m)
    if getattr(config, "CT_15M_MOMENTUM_GATE_ENABLED", False):
        _sk15 = _sf(indicators.get("stoch_k_15m"), 50.0)
        _mfi15 = _sf(indicators.get("mfi_15m"), 50.0)
        if is_long:
            if _sk15 < getattr(config, "CT_STOCH_K_15M_LONG_MIN", 45.0):
                return (
                    False,
                    f"CT_SK15_LONG({_sk15:.0f}<{getattr(config, 'CT_STOCH_K_15M_LONG_MIN', 45.0):.0f})",
                )
            if _mfi15 < getattr(config, "CT_MFI_15M_LONG_MIN", 45.0):
                return (
                    False,
                    f"CT_MFI15_LONG({_mfi15:.0f}<{getattr(config, 'CT_MFI_15M_LONG_MIN', 45.0):.0f})",
                )
        else:
            if _sk15 > getattr(config, "CT_STOCH_K_15M_SHORT_MAX", 55.0):
                return (
                    False,
                    f"CT_SK15_SHORT({_sk15:.0f}>{getattr(config, 'CT_STOCH_K_15M_SHORT_MAX', 55.0):.0f})",
                )
            if _mfi15 > getattr(config, "CT_MFI_15M_SHORT_MAX", 55.0):
                return (
                    False,
                    f"CT_MFI15_SHORT({_mfi15:.0f}>{getattr(config, 'CT_MFI_15M_SHORT_MAX', 55.0):.0f})",
                )
    # BC_172: Skip SHORT if DC basis just crossed over on 15m/1h (bullish break, d=-1.55 Dengi)
    if not is_long and getattr(config, "CT_DC_CROSSOVER_SKIP_ENABLED", False):
        if indicators.get("dc_basis_crossover_15m") or indicators.get(
            "dc_basis_crossover_1h"
        ):
            return (
                False,
                f"CT_DC_CO_SKIP(15m={indicators.get('dc_basis_crossover_15m')}_1h={indicators.get('dc_basis_crossover_1h')})",
            )
    # BC_173: Choppiness 4h gate (d=0.60 cross-trader, winners=40.5 losers=51.3)
    if getattr(config, "CT_CHOP_4H_GATE_ENABLED", False):
        _chop4h = _sf(indicators.get("choppiness_4h"), 50.0)
        if _chop4h > getattr(config, "CT_CHOP_4H_MAX", 50.0):
            return (
                False,
                f"CT_CHOP4H({_chop4h:.0f}>{getattr(config, 'CT_CHOP_4H_MAX', 50.0):.0f})",
            )
    # BC_174: Volume surge gate (d=2.80 Graal, d=0.59 ProTrend)
    if getattr(config, "CT_VOLUME_SURGE_GATE_ENABLED", False):
        _rv1h = _sf(indicators.get("relative_volume_1h"), 1.0)
        _rv4h = _sf(indicators.get("relative_volume_4h"), 1.0)
        _min_rv = getattr(config, "CT_REL_VOL_MIN", 1.3)
        if max(_rv1h, _rv4h) < _min_rv:
            return False, f"CT_VOL_LOW(rv1h={_rv1h:.1f}_rv4h={_rv4h:.1f}<{_min_rv})"
    return (
        True,
        f"ALIGNED_LTF({ltf}/3)_HTF({htf}/3)_D={'Y' if d_aligned else 'N'}_{mfi_tag}_MFI_Q{mfi_quality}/2",
    )


def check_dc_high_break_retest(
    indicators: Dict[str, Any], current_price: float, is_long: bool
) -> Tuple[bool, str, float]:
    """DC breakout retest: dc_high broke up (or dc_low broke down), price pulled back to retest
    the BROKEN LEVEL ITSELF, and is now bouncing. Enter at 1x on confirmation.
    LONG: dc_high expanded > dc_high_ant by >1.5%, price pulled back to dc_high_ant zone, k_3m turning up
    SHORT: dc_low expanded < dc_low_ant by >1.5%, price pulled back to dc_low_ant zone, k_3m turning down"""
    if current_price <= 0:
        return False, "NO_PRICE", 1.0
    k_3m = _sf(indicators.get("stoch_k_3m"), 50)
    d_3m = _sf(indicators.get("stoch_d_3m"), 50)
    k_3m_prev = _sf(indicators.get("k_3m_prev"), k_3m)
    tfs = [
        ("4h", 2.0),
        ("1h", 1.5),
        ("15m", 1.0),
        ("3m", 0.7),
        ("1m", 0.4),
    ]  # 2026-05-08: 1m added — never miss bounce/retest
    for tf, mult in tfs:
        if is_long:
            dc_high = _sf(indicators.get(f"dc_high_{tf}"), 0)
            dc_high_ant = _sf(indicators.get(f"dc_high_{tf}_ant"), 0)
            if dc_high <= 0 or dc_high_ant <= 0:
                continue
            bp = (dc_high - dc_high_ant) / dc_high_ant
            if bp < 0.015:
                continue
            retest_zone_top = dc_high_ant * 1.005
            retest_zone_bot = dc_high_ant * 0.99
            if not (retest_zone_bot <= current_price <= retest_zone_top):
                continue
            if not (k_3m > d_3m and k_3m > k_3m_prev):
                continue
            return (
                True,
                f"DC_HIGH_RETEST_{tf.upper()}_bp={bp * 100:.1f}%_level={dc_high_ant:.6f}_mult={mult:.1f}x",
                mult,
            )
        else:
            dc_low = _sf(indicators.get(f"dc_low_{tf}"), 0)
            dc_low_ant = _sf(indicators.get(f"dc_low_{tf}_ant"), 0)
            if dc_low <= 0 or dc_low_ant <= 0:
                continue
            bp = (dc_low_ant - dc_low) / dc_low_ant
            if bp < 0.015:
                continue
            retest_zone_bot = dc_low_ant * 0.995
            retest_zone_top = dc_low_ant * 1.01
            if not (retest_zone_bot <= current_price <= retest_zone_top):
                continue
            if not (k_3m < d_3m and k_3m < k_3m_prev):
                continue
            return (
                True,
                f"DC_LOW_RETEST_{tf.upper()}_bp={bp * 100:.1f}%_level={dc_low_ant:.6f}_mult={mult:.1f}x",
                mult,
            )
    return False, "NO_DC_RETEST", 1.0


