try:
    from typing import Any, Dict, List, Optional, Union

    import orjson

    def default_json_serializer(obj):
        if isinstance(obj, datetime):
            return obj.strftime("%Y-%m-%dT%H:%M:%S.%fZ")
        raise TypeError

    def json_dumps(obj: Any, **kwargs) -> bytes:
        return orjson.dumps(
            obj,
            default=default_json_serializer,
            option=orjson.OPT_SERIALIZE_NUMPY
            | orjson.OPT_INDENT_2
            | orjson.OPT_NON_STR_KEYS,
        )

    def safe_json_loads(s: Union[bytes, bytearray, memoryview, str], **kwargs) -> Any:
        return orjson.loads(
            s.encode("utf-8")
            if isinstance(s, str)
            else (s.tobytes() if isinstance(s, memoryview) else s)
        )

    JSONDecodeError = orjson.JSONDecodeError
except ImportError:
    import json
    from typing import Any, Dict, List, Optional, Union

    def default_json_serializer(obj):
        if isinstance(obj, datetime):
            return obj.strftime("%Y-%m-%dT%H:%M:%S.%fZ")
        return str(obj)

    def json_dumps(obj: Any, **kwargs) -> str:
        if "indent" not in kwargs:
            kwargs["indent"] = 2
        return json.dumps(obj, default=default_json_serializer, **kwargs)

    def safe_json_loads(s: Union[bytes, bytearray, memoryview, str], **kwargs) -> Any:
        if isinstance(s, (bytes, bytearray, memoryview)):
            if isinstance(s, memoryview):
                s = s.tobytes()
            else:
                s = s.decode("utf-8")
        return json.loads(s, **kwargs)

    JSONDecodeError = json.JSONDecodeError
