def timed_function(func_name: str):

    def decorator(func):
        @functools.wraps(func)
        async def async_wrapper(*args, **kwargs):
            start = time.perf_counter()
            try:
                result = await func(*args, **kwargs)
                elapsed = time.perf_counter() - start
                with _timing_lock:
                    _function_timings[func_name].append((time.time(), elapsed))
                return result
            except Exception as e:
                elapsed = time.perf_counter() - start
                with _timing_lock:
                    _function_timings[func_name].append((time.time(), elapsed))
                raise

        @functools.wraps(func)
        def sync_wrapper(*args, **kwargs):
            start = time.perf_counter()
            try:
                result = func(*args, **kwargs)
                elapsed = time.perf_counter() - start
                with _timing_lock:
                    _function_timings[func_name].append((time.time(), elapsed))
                return result
            except Exception as e:
                elapsed = time.perf_counter() - start
                with _timing_lock:
                    _function_timings[func_name].append((time.time(), elapsed))
                raise

        return async_wrapper if asyncio.iscoroutinefunction(func) else sync_wrapper

    return decorator


async def log_timing_summary():
    global _last_minute_summary
    while True:
        try:
            await asyncio.sleep(60)
            now = time.time()
            with _timing_lock:
                minute_ago = now - 60
                summary = {}
                for func_name, timings in list(_function_timings.items()):
                    recent = [
                        (ts, elapsed) for ts, elapsed in timings if ts >= minute_ago
                    ]
                    if recent:
                        elapsed_times = [e for _, e in recent]
                        summary[func_name] = {
                            "count": len(recent),
                            "total": sum(elapsed_times),
                            "avg": sum(elapsed_times) / len(recent),
                            "max": max(elapsed_times),
                            "min": min(elapsed_times),
                        }
                    old_timings = [
                        (ts, elapsed) for ts, elapsed in timings if ts < minute_ago
                    ]
                    if old_timings:
                        _function_timings[func_name] = [
                            (ts, elapsed) for ts, elapsed in timings if ts >= minute_ago
                        ]
                if summary:
                    sorted_funcs = sorted(
                        summary.items(), key=lambda x: x[1]["total"], reverse=True
                    )
                    if logger:
                        pass  # TIMING_SUMMARY removed - too verbose
        except Exception as e:
            if logger:
                logger.error(f"[TIMING_SUMMARY] Error: {e}")


class ActiveAccountStreamFilter(logging.Filter):
    def __init__(self, allowed_accounts: set):
        super().__init__()
        self.allowed_accounts = allowed_accounts
        self.strict_mode = len(allowed_accounts) == 1

    def filter(self, record: logging.LogRecord) -> bool:
        record_acc = getattr(record, "account_key", None)
        if record_acc in self.allowed_accounts:
            return True
        if not record_acc or record_acc == "unknown":
            return not self.strict_mode
        return False


