def _extract_ts_from_filename(path: Path) -> float:
    try:
        path = Path(config.DATA_DIR)
        match = re.search(
            r"market_data__?(\d{4})(\d{2})(\d{2})_(\d{2})(\d{2})(\d{2})", path.name
        )
        if match:
            y, m, d, H, M, S = map(int, match.groups())
            dt = datetime(y, m, d, H, M, S, tzinfo=timezone.utc)
            return dt.timestamp()
    except Exception:
        pass
    return 0.0


def _file_age_seconds(file_path: Path) -> float:
    try:
        resolved_path = file_path.resolve() if file_path.exists() else file_path
        file_mtime = os.path.getmtime(str(resolved_path))
        return max(0.0, time.time() - file_mtime)
    except (FileNotFoundError, OSError):
        return float("inf")
    except Exception:
        return float("inf")


def _is_file_fresh(file_path: Path, max_age: float) -> bool:
    return _file_age_seconds(file_path) <= max_age


async def load_json_safe(file_path: Union[str, Path], account_key: str = None) -> dict:
    file_path = Path(file_path)
    async with _global_file_write_semaphore:
        content = b""
        try:
            if not file_path.exists():
                return {}
            async with aiofiles.open(file_path, "rb") as f:
                content = await f.read()
            if not content.strip():
                return {}
            data = safe_json_loads(content)
        except Exception:
            data = {}
            recovery_success = False
            try:
                txt = content.decode("utf-8", errors="ignore").strip()
                end_idx = txt.rfind("}")
                if end_idx != -1:
                    fixed_txt = txt[: end_idx + 1]
                    data = orjson.loads(fixed_txt)
                    recovery_success = True
                    async with aiofiles.open(file_path, "wb") as f:
                        await f.write(orjson.dumps(data, option=orjson.OPT_INDENT_2))
            except Exception:
                pass
            if not recovery_success:
                backup_path = file_path.with_suffix(file_path.suffix + ".bak")
                if backup_path.exists():
                    try:
                        async with aiofiles.open(backup_path, "rb") as f:
                            bk_content = await f.read()
                        data = safe_json_loads(bk_content)
                        recovery_success = True
                        async with aiofiles.open(file_path, "wb") as f:
                            await f.write(bk_content)
                    except Exception:
                        pass
            if not recovery_success:
                try:
                    if file_path.exists():
                        os.remove(file_path)
                except Exception:
                    pass
                return {}
        if not isinstance(data, dict):
            return {}
        data = _convert_timestamp_strings(data)
        return data


_indicator_restart_lock = DummyLock()
_last_indicator_restart_ts = datetime.min.replace(tzinfo=timezone.utc)


async def _exec_shell_command(
    command: Optional[str], label: str, timeout: float = 10.0
) -> Optional[int]:
    if not command:
        return None
    try:
        proc = await asyncio.create_subprocess_shell(command)
        try:
            await asyncio.wait_for(proc.wait(), timeout=timeout)
        except asyncio.TimeoutError:
            logger.warning(
                f"[{label}] command timed out after {timeout:.1f}s; terminating"
            )
            with suppress(Exception):
                proc.kill()
            return None
        return proc.returncode
    except Exception as exc:
        logger.warning(f"[{label}] command failed: {exc}")
        return None


async def request_ez_indicators_restart(reason: str = "external") -> bool:
    cmd = getattr(config, "EZ_INDICATORS_START_CMD", None)
    if not cmd:
        return False
    cooldown = float(getattr(config, "EZ_INDICATORS_RESTART_COOLDOWN", 60.0))
    timeout = float(getattr(config, "EZ_INDICATORS_CMD_TIMEOUT", 10.0))
    now = datetime.now(timezone.utc)
    async with _indicator_restart_lock:
        global _last_indicator_restart_ts
        if (now - _last_indicator_restart_ts).total_seconds() < cooldown:
            return False
        logger.warning(f"[ez_indicators] Restart requested ({reason})")
        rc = await _exec_shell_command(
            cmd, f"ez_indicators restart ({reason})", timeout=timeout
        )
        _last_indicator_restart_ts = datetime.now(timezone.utc)
        return rc == 0 if rc is not None else False


async def _maybe_restart_indicators(
    trade_manager: Optional["MultiAccountTradeManager"], reason: str
) -> None:
    restarted = await request_ez_indicators_restart(reason)
    if restarted:
        logger.info(f"[ez_indicators] Restart command executed ({reason})")


@dataclass
class AccountConfig:
    prefix: str
    api_key: str = field(init=False)
    api_secret: str = field(init=False)
    webhook_url: str = field(init=False)
    webhook_secret: str = field(init=False)
    client: Optional[Client] = field(default=None, init=False)
    _last_used_weight: int = field(
        default=0, init=False
    )  # NEW: to track last logged weight
    _connector_lock: threading.Lock = field(default_factory=threading.Lock, init=False)
    _ip_cycle: Optional[deque] = field(default=None, init=False)
    _current_ip: Optional[str] = field(default=None, init=False)
    _banned_ips: dict = field(default_factory=dict, init=False)

    def __post_init__(self):
        self.time_offset = 0.0
        self._last_time_sync = 0.0
        self.api_key = os.getenv(f"{self.prefix.lower()}_API_KEY")
        self.api_secret = os.getenv(f"{self.prefix.lower()}_API_SECRET")
        self.webhook_url = os.getenv(f"{self.prefix.lower()}_WEBHOOK_URL")
        self.webhook_secret = os.getenv(f"{self.prefix.lower()}_WEBHOOK_SECRET")
        self.webhook_url_2 = os.getenv(f"{self.prefix.lower()}_WEBHOOK_URL2")
        self.webhook_secret_2 = os.getenv(f"{self.prefix.lower()}_WEBHOOK_SECRET2")
        self.webhook_url_3 = os.getenv(f"{self.prefix.lower()}_WEBHOOK_URL3")
        self.webhook_secret_3 = os.getenv(f"{self.prefix.lower()}_WEBHOOK_SECRET3")
        missing = []
        if not self.api_key:
            missing.append(f"{self.prefix.lower()}_API_KEY")
        if not self.api_secret:
            missing.append(f"{self.prefix.lower()}_API_SECRET")
        if not self.webhook_url:
            missing.append(f"{self.prefix.lower()}_WEBHOOK_URL")
        if not self.webhook_secret:
            missing.append(f"{self.prefix.lower()}_WEBHOOK_SECRET")
        if missing:
            raise ValueError(
                f"Missing environment variables for account '{self.prefix}': {', '.join(missing)}"
            )
        self._init_ip_cycle()

    def _init_ip_cycle(self):
        """Initialize IP rotation for API calls."""
        self._ip_cycle = None
        self._current_ip = None
        self._banned_ips = {}
        if (
            self.prefix.lower() in {"ang", "inf", "men", "flz", "fin"}
            and sys.platform != "darwin"
            and os.environ.get("EZ_DISABLE_IP_BINDING") != "1"
        ):
            self._ip_cycle = deque(["5.75.211.216", "49.13.39.233", "157.180.125.52"])
            logger.info(
                f"[{self.prefix}] IP switching enabled with IPs: {list(self._ip_cycle)}"
            )
        else:
            logger.info(
                f"[{self.prefix}] IP switching disabled - prefix: {self.prefix.lower()}, platform: {sys.platform}, env: {os.environ.get('EZ_DISABLE_IP_BINDING')}"
            )

    def _get_next_ip(self) -> Optional[str]:
        """Get next available IP for API calls."""
        if not self._ip_cycle:
            return None
        now = time.time()
        for _ in range(len(self._ip_cycle)):
            ip = self._ip_cycle[0]
            banned_until = self._banned_ips.get(ip, 0)
            if banned_until and banned_until > now:
                self._ip_cycle.rotate(-1)
                continue
            self._ip_cycle.rotate(-1)
            return ip
        return None

    def _mark_ip_banned(self, ip: str, cooldown_seconds: int = 900):
        """Mark an IP as banned for API calls."""
        if not ip:
            return
        self._banned_ips[ip] = time.time() + cooldown_seconds

    def _create_bound_adapter(self, ip: str) -> HTTPAdapter:
        if not ip:
            return HTTPAdapter()

        class SourceAddressAdapter(HTTPAdapter):
            def init_poolmanager(
                self, connections, maxsize, block=False, **pool_kwargs
            ):
                pool_kwargs["source_address"] = (ip, 0)
                super().init_poolmanager(
                    connections, maxsize, block=block, **pool_kwargs
                )

            def proxy_manager_for(self, *args, **kwargs):
                kwargs.setdefault("pool_kwargs", {})["source_address"] = (ip, 0)
                return super().proxy_manager_for(*args, **kwargs)

        return SourceAddressAdapter(max_retries=3)

    def _apply_ip_binding(self, client: Client):
        """Apply IP binding to the Binance client for API calls."""
        if (
            sys.platform == "darwin"
            or os.environ.get("EZ_DISABLE_IP_BINDING") == "1"
            or not self._ip_cycle
        ):
            return
        timeout_seconds = 20
        tried_ips = set()
        working_ip = None
        while True:
            candidate_ip = self._get_next_ip()
            if not candidate_ip or candidate_ip in tried_ips:
                break
            try:
                import socket

                probe = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                probe.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
                probe.bind((candidate_ip, 0))
                probe.close()
                working_ip = candidate_ip
                logger.debug(f"[{self.prefix}] IP {candidate_ip} is bindable")
                break
            except OSError as e:
                logger.warning(
                    f"[{self.prefix}] REST IP {candidate_ip} binding failed: {e}"
                )
                self._mark_ip_banned(candidate_ip)
                tried_ips.add(candidate_ip)
        if working_ip:
            adapter = self._create_bound_adapter(working_ip)
            client.session.mount("https://", adapter)
            client.session.mount("http://", adapter)
            logger.debug(
                f"[{self.prefix}] Bound client session to dedicated IP {working_ip}"
            )
            self._current_ip = working_ip
        else:
            logger.warning(
                f"[{self.prefix}] No dedicated REST IP available, using default routing."
            )
            self._current_ip = None

    def handle_api_ban(self, cooldown_seconds: int = 900):
        banned_ip = getattr(self, "_current_ip", None)
        logger.warning(
            f"[{self.prefix}] 🚫 IP BAN DETECTED on {banned_ip}, switching IPs..."
        )
        self._mark_ip_banned(banned_ip, cooldown_seconds)
        if self.client:
            self._apply_ip_binding(self.client)
            logger.warning(
                f"[{self.prefix}] Rotated REST IP after ban; previous={banned_ip}, active={self._current_ip}"
            )
        try:
            loop = asyncio.get_event_loop()
            if loop.is_running():
                asyncio.create_task(delete_heartbeat_on_ban())
            else:
                loop.run_until_complete(delete_heartbeat_on_ban())
        except Exception:
            pass

    async def initialize(self):
        """Initialize the Binance client."""
        if not self.client:
            try:
                logger.info(
                    f"[{self.prefix}] Initializing Binance client with API key: {self.api_key[:8]}...{self.api_key[-4:]} (len: {len(self.api_key)})"
                )
                self.client = Client(api_key=self.api_key, api_secret=self.api_secret)
                self._apply_ip_binding(self.client)
                self.sync_binance_time()
                logger.debug(
                    f"Initialized Binance client for account '{self.prefix}'",
                    extra={"color": "green"},
                )
            except BinanceAPIException as e:
                logger.error(
                    f"[{self.prefix}] Binance API error during initialization: {e} (code: {getattr(e, 'code', 'N/A')})",
                    extra={"color": "red"},
                )
                logger.error(
                    f"[{self.prefix}] API key used: {self.api_key[:8]}...{self.api_key[-4:]} (len: {len(self.api_key)})"
                )
            except Exception as e:
                logger.error(
                    f"Failed to initialize Binance client for account '{self.prefix}': {e}",
                    extra={"color": "red"},
                )

    def sync_binance_time(self):
        """Sync local time with Binance server time to prevent signature errors. Max once per hour."""
        current_time = time.time()
        if (
            hasattr(self, "_last_time_sync")
            and (current_time - self._last_time_sync) < 3600
        ):
            return True
        try:
            server_time_response = self.client.futures_time()
            server_time = server_time_response["serverTime"]
            local_time = int(time.time() * 1000)
            time_diff = server_time - local_time
            if abs(time_diff) > 1000:
                logger.warning(
                    f"[{self.prefix}] ⚠️ Significant time difference detected: {time_diff}ms. This may cause signature errors."
                )
                logger.warning(
                    f"[{self.prefix}] Please check system clock synchronization."
                )
            self.time_offset = time_diff
            self._last_time_sync = current_time
            return True
        except Exception as e:
            logger.error(f"[{self.prefix}] Failed to sync time with Binance: {e}")
            return False

    def get_binance_timestamp(self):
        """Get timestamp adjusted for Binance server time."""
        if self.time_offset:
            return int(time.time() * 1000) + self.time_offset
        return int(time.time() * 1000)

    async def close(self):
        """Close the Binance client."""
        if self.client:
            logger.debug(
                f"Closed Binance client for account '{self.prefix}'",
                extra={"color": "green"},
            )


