def safe_datetime(ts, fallback: Optional[datetime] = None) -> Optional[datetime]:
    if isinstance(ts, datetime):
        return ts if ts.tzinfo else ts.replace(tzinfo=timezone.utc)
    if isinstance(ts, (int, float)):
        try:
            return datetime.fromtimestamp(float(ts), tz=timezone.utc)
        except (OSError, OverflowError, ValueError):
            pass
    if isinstance(ts, str):
        candidate = ts.strip()
        if candidate:
            numeric = None
            try:
                numeric = float(
                    candidate[:-1] if candidate.endswith(("Z", "z")) else candidate
                )
            except (TypeError, ValueError):
                numeric = None
            if (
                numeric is not None
                and not math.isnan(numeric)
                and not math.isinf(numeric)
            ):
                try:
                    return datetime.fromtimestamp(
                        numeric / (1000.0 if numeric > 1e12 else 1.0), tz=timezone.utc
                    )
                except (OSError, OverflowError, ValueError):
                    numeric = None
            # FAST PATH (2026-05-09): try datetime.fromisoformat before pandas.
            # Profile showed pd.to_datetime via safe_datetime = 13.5s of 172s
            # (~8% of backtest runtime). fromisoformat is C-optimized and handles
            # the canonical ISO formats the engine emits ("YYYY-MM-DDTHH:MM:SS.ffffffZ"
            # and "...+00:00") in microseconds rather than milliseconds. On parse
            # failure we fall through to the original pd.to_datetime path so any
            # exotic input string still works exactly as before.
            try:
                _iso = candidate
                # datetime.fromisoformat in 3.10 doesn't accept trailing 'Z' — swap to +00:00.
                if _iso.endswith("Z") or _iso.endswith("z"):
                    _iso = _iso[:-1] + "+00:00"
                dt = datetime.fromisoformat(_iso)
                return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)
            except (ValueError, TypeError):
                pass
            try:
                dt = pd.to_datetime(candidate, utc=True).to_pydatetime()
                return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)
            except Exception as e:
                logger.debug(
                    f"[safe_datetime] Failed to parse timestamp string: {candidate} ({e})"
                )
    if ts is not None:
        logger.debug(f"[safe_datetime] Unexpected timestamp type: {type(ts)} -> {ts}")
    return fallback


position_key_context: ContextVar[str] = ContextVar("position_key", default="?")


def calculate_gain(position_side, current_price, entry_price):
    if entry_price <= 0:
        return 0.0
    if position_side == "LONG":
        return ((current_price - entry_price) / entry_price) * 100
    else:
        return ((entry_price - current_price) / entry_price) * 100


def calculate_tier_mult(i: dict, is_long: bool) -> int:
    """Calculates the safe retention tier based on Stoch RSI alignment across timeframes."""
    k_1m = safe_fetch_float(i.get("stoch_k_1m", 50))
    k_1m_prev = safe_fetch_float(i.get("k_1m_prev", 50))
    d_1m = safe_fetch_float(i.get("stoch_k_dm", 50))
    k_3m = safe_fetch_float(i.get("stoch_k_3m", 50))
    d_3m = safe_fetch_float(i.get("stoch_d_3m", 50))
    k_3m_prev = safe_fetch_float(i.get("k_3m_prev", 50))
    k_15m = safe_fetch_float(i.get("stoch_k_15m", 50))
    d_15m = safe_fetch_float(i.get("stoch_d_15m", 50))
    k_1h = safe_fetch_float(i.get("stoch_k_1h", 50))
    d_1h = safe_fetch_float(i.get("stoch_d_1h", 50))
    k_4h = safe_fetch_float(i.get("stoch_k_4h", 50))
    d_4h = safe_fetch_float(i.get("stoch_d_4h", 50))
    tick_ts = safe_fetch_float(i.get("tick_ts", 50))
    tier_mult = 0
    arrow1_good = (is_long and k_1m >= k_1m_prev) or (not is_long and k_1m <= k_1m_prev)
    if arrow1_good:
        tier_mult = 1
        arrow3_good = (is_long and k_3m >= k_3m_prev) or (
            not is_long and k_3m <= k_3m_prev
        )
        if arrow3_good:
            tier_mult = 2
            arrow15_good = (k_15m != 50 or d_15m != 50) and (
                (is_long and k_15m >= d_15m) or (not is_long and k_15m <= d_15m)
            )
            if arrow15_good:
                tier_mult = 4
                arrow1h_good = (k_1h != 50 or d_1h != 50) and (
                    (is_long and k_1h >= d_1h) or (not is_long and k_1h <= d_1h)
                )
                if arrow1h_good:
                    tier_mult = 6
                    arrow4h_good = (k_4h != 50 or d_4h != 50) and (
                        (is_long and k_4h >= d_4h) or (not is_long and k_4h <= d_4h)
                    )
                    if arrow4h_good:
                        tier_mult = 8
    return tier_mult


def is_safe_to_enter(
    ctx: dict, indicators: dict, current_price: float, is_long: bool
) -> tuple[bool, str]:
    i = (
        indicators
        if isinstance(indicators, dict) and indicators
        else ctx.get("indicators")
        if isinstance(ctx.get("indicators"), dict)
        else {}
    )
    if not i:
        return False, "NO_INDICATORS"
    trade_manager = ctx["trade_manager"]
    account_key = ctx["account_key"]
    account_positions = ctx["trade_manager"].positions_by_account.setdefault(
        ctx["account_key"], {}
    )
    position = account_positions.get(ctx["position_key"])
    if position is None:
        position = ctx["position"]
    if position and position.last_signal == "PROFIT_TAKE":
        return True, "SAFE_TO_ENTER"
    low_3m, low_15m, low_1h, low_4h = (
        i.get("low_3m", 0),
        i.get("low_15m", 0),
        i.get("low_1h", 0),
        i.get("low_4h", 0),
    )
    high_3m, high_15m, high_1h, high_4h = (
        i.get("high_3m", 0),
        i.get("high_15m", 0),
        i.get("high_1h", 0),
        i.get("high_4h", 0),
    )
    dc_low_3m, dc_low_15m, dc_low_1h, dc_low_4h = (
        i.get("dc_low_3m", 0),
        i.get("dc_low_15m", 0),
        i.get("dc_low_1h", 0),
        i.get("dc_low_4h", 0),
    )
    dc_high_3m, dc_high_15m, dc_high_1h, dc_high_4h = (
        i.get("dc_high_3m", 0),
        i.get("dc_high_15m", 0),
        i.get("dc_high_1h", 0),
        i.get("dc_high_4h", 0),
    )
    atr_3m, atr_15m = i.get("atr_3m", 0), i.get("atr_15m", 0)
    try:
        low_3m, low_15m, low_1h, low_4h = (
            float(low_3m or 0),
            float(low_15m or 0),
            float(low_1h or 0),
            float(low_4h or 0),
        )
        high_3m, high_15m, high_1h, high_4h = (
            float(high_3m or 0),
            float(high_15m or 0),
            float(high_1h or 0),
            float(high_4h or 0),
        )
        dc_low_3m, dc_low_15m, dc_low_1h, dc_low_4h = (
            float(dc_low_3m or 0),
            float(dc_low_15m or 0),
            float(dc_low_1h or 0),
            float(dc_low_4h or 0),
        )
        dc_high_3m, dc_high_15m, dc_high_1h, dc_high_4h = (
            float(dc_high_3m or 0),
            float(dc_high_15m or 0),
            float(dc_high_1h or 0),
            float(dc_high_4h or 0),
        )
        atr_3m, atr_15m = float(atr_3m or 0), float(atr_15m or 0)
    except (ValueError, TypeError) as e:
        logger.warning(
            f"[is_ safe_to_enter] Error converting indicator values to float: {e}"
        )
        low_3m = low_15m = low_1h = low_4h = high_3m = high_15m = high_1h = high_4h = (
            0.0
        )
        dc_low_3m = dc_low_15m = dc_low_1h = dc_low_4h = dc_high_3m = dc_high_15m = (
            dc_high_1h
        ) = dc_high_4h = 0.0
        atr_3m = atr_15m = 0.0
    if is_long:
        near_low_3m = low_3m > 0 and current_price <= low_3m + (float(atr_3m) * 1.0)
        near_low_15m = low_15m > 0 and current_price <= low_15m + (float(atr_15m) * 1.0)
        near_low_1h = low_1h > 0 and current_price <= low_1h + (float(atr_15m) * 1.5)
        near_low_4h = low_4h > 0 and current_price <= low_4h + (float(atr_15m) * 2.0)
        rocketship_3m = dc_high_3m > 0 and current_price > dc_high_3m
        rocketship_15m = dc_high_15m > 0 and current_price > dc_high_15m
        rocketship_1h = dc_high_1h > 0 and current_price > dc_high_1h
        rocketship_4h = dc_high_4h > 0 and current_price > dc_high_4h
        strong_uptrend_3m = dc_high_3m > 0 and current_price > dc_high_3m
        strong_uptrend_15m = dc_high_15m > 0 and current_price > dc_high_15m
        strong_uptrend_1h = dc_high_1h > 0 and current_price > dc_high_1h
        strong_uptrend_4h = dc_high_4h > 0 and current_price > dc_high_4h
        near_low_count = sum([near_low_3m, near_low_15m, near_low_1h, near_low_4h])
        rocketship_count = sum(
            [rocketship_3m, rocketship_15m, rocketship_1h, rocketship_4h]
        )
        strong_uptrend_count = sum(
            [
                strong_uptrend_3m,
                strong_uptrend_15m,
                strong_uptrend_1h,
                strong_uptrend_4h,
            ]
        )
        if rocketship_count >= 2:
            return (
                True,
                f"LONG_ROCKETSHIP_EXCEPTION (rocketship_count={rocketship_count}/4)",
            )
        if strong_uptrend_count >= 2:
            return (
                True,
                f"LONG_STRONG_UPTREND_PULLBACK (strong_uptrend_count={strong_uptrend_count}/4)",
            )
        if near_low_count < 2:
            return (
                False,
                f"LONG_NOT_NEAR_LOW (near_low_count={near_low_count}/4, need 2)",
            )
    else:
        near_high_3m = high_3m > 0 and current_price >= high_3m - (float(atr_3m) * 1.0)
        near_high_15m = high_15m > 0 and current_price >= high_15m - (
            float(atr_15m) * 1.0
        )
        near_high_1h = high_1h > 0 and current_price >= high_1h - (float(atr_15m) * 1.5)
        near_high_4h = high_4h > 0 and current_price >= high_4h - (float(atr_15m) * 2.0)
        rocketship_3m = dc_low_3m > 0 and current_price < dc_low_3m
        rocketship_15m = dc_low_15m > 0 and current_price < dc_low_15m
        rocketship_1h = dc_low_1h > 0 and current_price < dc_low_1h
        rocketship_4h = dc_low_4h > 0 and current_price < dc_low_4h
        strong_downtrend_3m = dc_low_3m > 0 and current_price < dc_low_3m
        strong_downtrend_15m = dc_low_15m > 0 and current_price < dc_low_15m
        strong_downtrend_1h = dc_low_1h > 0 and current_price < dc_low_1h
        strong_downtrend_4h = dc_low_4h > 0 and current_price < dc_low_4h
        near_high_count = sum([near_high_3m, near_high_15m, near_high_1h, near_high_4h])
        rocketship_count = sum(
            [rocketship_3m, rocketship_15m, rocketship_1h, rocketship_4h]
        )
        strong_downtrend_count = sum(
            [
                strong_downtrend_3m,
                strong_downtrend_15m,
                strong_downtrend_1h,
                strong_downtrend_4h,
            ]
        )
        if rocketship_count >= 2:
            return (
                True,
                f"SHORT_ROCKETSHIP_EXCEPTION (rocketship_count={rocketship_count}/4)",
            )
        if strong_downtrend_count >= 2:
            return (
                True,
                f"SHORT_STRONG_DOWNTREND_PULLBACK (strong_downtrend_count={strong_downtrend_count}/4)",
            )
        if near_high_count < 2:
            return (
                False,
                f"SHORT_NOT_NEAR_HIGH (near_high_count={near_high_count}/4, need 2)",
            )
    return True, "SAFE_TO_ENTER"


def get_most_recent_timestamp(*timestamps: Optional[datetime]) -> datetime:
    now = datetime.now(timezone.utc)
    valid = [ts for ts in timestamps if isinstance(ts, datetime)]
    return max(valid) if valid else now - timedelta(minutes=1000)


def now() -> datetime:
    return datetime.now(timezone.utc)


def ensure_tz(dt: datetime) -> datetime:
    return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)


def minutes_since(timestamp_obj, now=None):
    if not timestamp_obj:
        return 999999  # Very large number if no timestamp
    if now is None:
        now = datetime.now(timezone.utc)  # .replace(microsecond=0)
    try:
        if isinstance(timestamp_obj, str):
            dt = isoparse(timestamp_obj)
        elif isinstance(timestamp_obj, datetime):
            dt = timestamp_obj
        else:
            return 999999  # Invalid type
        if not isinstance(dt, datetime):
            return 999999  # Failed to parse
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return (now - dt).total_seconds() / 60.0
    except Exception:
        return 999999


def safe_time(x):
    if isinstance(x, datetime):
        return x
    if isinstance(x, str):
        try:
            return isoparse(x)
        except ValueError:
            pass
    return None


def safe_float(x, default=0.0):
    """Convert value to float, ensuring we never return None for Position creation"""
    try:
        if x is None:
            return default
        if isinstance(x, (int, float, Decimal)):
            return float(x)
        if isinstance(x, str):
            s = x.strip()
            if s == "":
                return default
            s = s.replace(",", "")
            return float(Decimal(s))
        if isinstance(x, dict):
            for k in ("amount", "qty", "positionAmt", "value"):
                if k in x:
                    return safe_float(x[k], default)
        return float(x)
    except (InvalidOperation, ValueError, TypeError) as e:
        try:
            logger.debug(f"[safe_float] failed to parse {repr(x)} -> {e}")
        except Exception:
            pass
        return default


def _convert_timestamp_strings(data: Any) -> Any:
    """Recursively convert all timestamp strings in dict/list to datetime objects - CRITICAL for all JSON loads"""
    if isinstance(data, dict):
        result = {}
        for key, value in data.items():
            if isinstance(value, str) and any(
                ts_key in key.lower()
                for ts_key in ["time", "timestamp", "updated", "at", "date"]
            ):
                try:
                    if "T" in value and (
                        "Z" in value or "+" in value or value.count("-") >= 2
                    ):
                        parsed = isoparse(value)
                        result[key] = (
                            parsed.replace(tzinfo=timezone.utc)
                            if parsed.tzinfo is None
                            else parsed
                        )
                    else:
                        result[key] = value
                except (ValueError, TypeError):
                    try:
                        parsed = pd.to_datetime(value, utc=True).to_pydatetime()
                        result[key] = (
                            parsed.replace(tzinfo=timezone.utc)
                            if parsed.tzinfo is None
                            else parsed
                        )
                    except (ValueError, TypeError):
                        result[key] = value
            elif isinstance(value, (dict, list)):
                result[key] = _convert_timestamp_strings(value)
            else:
                result[key] = value
        return result
    elif isinstance(data, list):
        return [_convert_timestamp_strings(item) for item in data]
    return data


@dataclass(slots=False)
class Position:
    symbol: str
    position_side: str
    entry_price: float
    mark_price: float
    positionAmt: float
    initial_quantity: float
    gain: float
    max_gain: float
    prev_gain: float
    max_quantity: float
    last_augmentation_amount: float
    last_augmentation_price: float
    last_augmentation_time: Optional[datetime]
    last_reduction_amount: float
    last_reduction_price: float
    last_reduction_time: Optional[datetime]
    max_positionSize: float
    opened_at: Optional[datetime]
    last_updated: Optional[datetime]
    last_signal: str
    realized_pnl: float = 0.0
    unrealized_pnl_USD: float = 0.0
    was_reentered: bool = False
    was_reduced: bool = False
    is_reduced: bool = False
    reduced_at: Optional[datetime] = None
    prev_gain_last_updated: Optional[datetime] = None
    augment_reason: str = ""
    reduction_reason: str = ""
    mark_price_last_updated: Optional[datetime] = None
    _position_key: str = ""
    _frozen_sacred: bool = False

    def __post_init__(self):
        """After construction: if positionAmt > 0, sacred fields MUST have content. If not, CRASH."""
        if abs(self.positionAmt) > 0.0001 and self.entry_price > 0:
            _missing = []
            if not self.opened_at:
                _missing.append("opened_at")
            if self.max_positionSize == 0 and self.positionAmt > 0:
                pass  # OK on first open
            # Only crash if position has been traded (has aug/red history) but fields are wiped
            if self.last_augmentation_time and self.last_augmentation_price == 0:
                _missing.append("last_augmentation_price")
            if self.last_reduction_time and self.last_reduction_price == 0:
                _missing.append("last_reduction_price")
            if _missing:
                import traceback

                stack = "".join(traceback.format_stack())
                _crash_msg = f"\n{'=' * 80}\n[POSITION_BORN_CORRUPT] {self.symbol}_{self.position_side}: positionAmt={self.positionAmt} entry={self.entry_price} but MISSING: {_missing}\nSTACK:\n{stack}\n{'=' * 80}"
                logger.critical(_crash_msg)
                with open(
                    str(config.LOG_DIR / "POSITION_ZEROED_CRASH.log"), "a"
                ) as _cf:
                    _cf.write(
                        f"{datetime.now(timezone.utc).isoformat()} {_crash_msg}\n"
                    )
        object.__setattr__(self, "_frozen_sacred", True)

    # Sacred fields: content → empty = CRASH + stack trace. positionAmt CAN go to 0 (legitimate close).
    _SACRED_DATETIME_FIELDS = frozenset(
        {"last_augmentation_time", "last_reduction_time", "opened_at", "reduced_at"}
    )
    _SACRED_FLOAT_FIELDS = frozenset({"max_positionSize", "entry_price"})
    _SACRED_STR_FIELDS = frozenset({"augment_reason", "reduction_reason"})

    def __setattr__(self, name, value):
        try:
            old = object.__getattribute__(self, name)
        except AttributeError:
            object.__setattr__(self, name, value)
            return
        try:
            frozen = object.__getattribute__(self, "_frozen_sacred")
        except AttributeError:
            frozen = False
        if not frozen:
            object.__setattr__(self, name, value)
            return
        _erased = False
        if name in Position._SACRED_DATETIME_FIELDS:
            if old is not None and isinstance(old, datetime) and value is None:
                _erased = True
        elif name in Position._SACRED_FLOAT_FIELDS:
            if (
                old is not None
                and float(old) > 0
                and (value is None or float(value) == 0)
            ):
                _erased = True
        elif name in Position._SACRED_STR_FIELDS:
            if (
                old
                and isinstance(old, str)
                and len(old) > 0
                and (not value or value == "")
            ):
                _erased = True
        if _erased:
            import traceback

            pk = getattr(self, "_position_key", "") or getattr(self, "symbol", "?")
            stack = "".join(traceback.format_stack())
            _crash_msg = f"\n{'=' * 80}\n[SACRED_FIELD_ERASED] {pk}: {name} = {old!r} -> {value!r}\nSTACK:\n{stack}\n{'=' * 80}"
            logger.critical(_crash_msg)
            with open(str(config.LOG_DIR / "POSITION_ZEROED_CRASH.log"), "a") as _cf:
                _cf.write(f"{datetime.now(timezone.utc).isoformat()} {_crash_msg}\n")
            os._exit(99)
        object.__setattr__(self, name, value)

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "Position":
        if not isinstance(data, dict):
            raise TypeError(
                f"Position.from_dict() requires a dict, got {type(data).__name__}"
            )
        data = _convert_timestamp_strings(data)  # Convert all timestamp strings first

        def safe_float(x):
            if x is None:
                return 0.0
            if isinstance(x, (int, float, Decimal)):
                return float(x)
            if isinstance(x, str):
                s = x.strip()
                if s == "":
                    return 0.0
                s = s.replace(",", "")
                try:
                    return float(Decimal(s))
                except Exception:
                    return 0.0
            if isinstance(x, dict):
                for k in ("amount", "qty", "positionAmt", "value"):
                    if k in x:
                        return safe_float(x[k])
            try:
                return float(x)
            except (TypeError, ValueError):
                return 0.0

        def safe_time(x):
            if isinstance(x, datetime):
                return x.replace(tzinfo=timezone.utc) if x.tzinfo is None else x
            if isinstance(x, str):
                try:
                    return (
                        isoparse(x)
                        if isinstance(isoparse(x), datetime)
                        else pd.to_datetime(x, utc=True).to_pydatetime()
                    )
                except (ValueError, TypeError):
                    try:
                        return pd.to_datetime(x, utc=True).to_pydatetime()
                    except (ValueError, TypeError):
                        return None
            return None

        return cls(
            symbol=str(data.get("symbol", "")),
            position_side=str(data.get("position_side", "")),
            entry_price=safe_float(data.get("entry_price")),
            mark_price=safe_float(data.get("mark_price")),
            positionAmt=safe_float(data.get("positionAmt")),
            initial_quantity=safe_float(data.get("initial_quantity")),
            gain=safe_float(data.get("gain")),
            max_gain=safe_float(data.get("max_gain")),
            prev_gain=safe_float(data.get("prev_gain")),
            max_quantity=safe_float(data.get("max_quantity")),
            last_augmentation_amount=safe_float(data.get("last_augmentation_amount")),
            last_augmentation_price=safe_float(data.get("last_augmentation_price")),
            last_augmentation_time=safe_time(data.get("last_augmentation_time")),
            last_reduction_amount=safe_float(data.get("last_reduction_amount")),
            last_reduction_price=safe_float(data.get("last_reduction_price")),
            last_reduction_time=safe_time(data.get("last_reduction_time")),
            max_positionSize=safe_float(data.get("max_positionSize")),
            opened_at=safe_time(data.get("opened_at")),
            last_updated=safe_time(data.get("last_updated")),
            last_signal=str(data.get("last_signal", "")),
            realized_pnl=safe_float(data.get("realized_pnl")),
            unrealized_pnl_USD=safe_float(data.get("unrealized_pnl_USD")),
            was_reentered=data.get("was_reentered", False),
            was_reduced=data.get("was_reduced", False),
            is_reduced=data.get("is_reduced", False),
            reduced_at=safe_time(data.get("reduced_at")),
            prev_gain_last_updated=safe_time(data.get("prev_gain_last_updated")),
            augment_reason=str(data.get("augment_reason", data.get("reason", ""))),
            reduction_reason=str(data.get("reduction_reason", data.get("reason", ""))),
            mark_price_last_updated=safe_time(data.get("mark_price_last_updated")),
        )

    def to_dict(self) -> Dict[str, Any]:
        result = asdict(self)
        for key, value in result.items():
            if isinstance(value, datetime):
                result[key] = value.strftime("%Y-%m-%dT%H:%M:%S.%fZ")
            elif value is None:
                result[key] = None
        return result


class WebSocketManager:
    def __init__(
        self,
        account_keys,
        api_key: str,
        api_secret: str,
        config,
        symbols=None,
        trade_manager=None,
    ):
        self.account_keys = (
            account_keys if isinstance(account_keys, list) else [account_keys]
        )
        self.api_key = api_key
        self.api_secret = api_secret
        self.config = config
        self.symbols = symbols
        self.trade_manager = trade_manager
        self.client = None
        self.bm = None
        self._running = True
        self.semaphore = Semaphore(
            config.EZ_MANAGE_WS_SEMAPHORE.get(current_env["env"], 140)
        )  # Use centralized rate limiting
        self.ws_managers = []
        self.positions = self.trade_manager.positions
        self.price_cache = self.trade_manager.price_cache
        self.price_update_time = self.trade_manager.price_update_time
        self.markprice_lock = DummyLock()  # Add lock for price update
        self.listen_keys = {}
        self.positions_by_account = self.trade_manager.positions_by_account
        self.time_offset = 0
        self._last_time_sync = 0.0
        self.is_primary = False
        self._mark_price_session: Optional[aiohttp.ClientSession] = None
        self._mark_price_task: Optional[asyncio.Task] = None
        self._fallback_task: Optional[asyncio.Task] = None
        self._guard_task: Optional[asyncio.Task] = None
        self._mark_price_aggregate_task: Optional[asyncio.Task] = None
        self._mark_price_guard_task: Optional[asyncio.Task] = None
        self._mark_price_stop = False
        self._fallback_interval = float(
            getattr(self.config, "PRICE_FALLBACK_INTERVAL", 1.0)
        )
        self._mark_price_guard_interval = float(
            getattr(self.config, "MARK_PRICE_GUARD_INTERVAL", 2.0)
        )
        self._mark_price_max_staleness = float(
            getattr(self.config, "MARK_PRICE_MAX_STALENESS", 2.0)
        )
        self._redis_client: Optional[Redis] = None
        self._price_cache_file_data: Dict[str, Any] = {}
        self._price_cache_file_mtime: float = 0.0
        self.positions_by_account = self.trade_manager.positions_by_account
        self.time_offset = 0
        self._last_time_sync = 0.0
        self._last_mark_price_heartbeat = 0.0
        self.position_callback_manager = PositionCallbackManager()
        try:
            _sym_path = Path(
                getattr(
                    self.config,
                    "SYMBOLS_FILE",
                    Path(self.config.BASE_PATH) / "symbols.json",
                )
            )
            _sym_list = (
                safe_json_loads(_sym_path.read_bytes()) if _sym_path.exists() else []
            )
            _sym_set = set(_sym_list) if isinstance(_sym_list, list) else set()
            self._valid_mark_symbols: set = _sym_set | {
                s.replace("USDC", "USDT") for s in _sym_set if s.endswith("USDC")
            }
        except Exception:
            self._valid_mark_symbols = set()

    async def _init_session(self) -> aiohttp.ClientSession:
        timeout = aiohttp.ClientTimeout(
            total=300, connect=30, sock_read=60, sock_connect=30
        )
        connector = aiohttp.TCPConnector(
            limit=20,
            limit_per_host=5,
            ttl_dns_cache=300,
            keepalive_timeout=60,
            enable_cleanup_closed=True,
        )
        return aiohttp.ClientSession(connector=connector, timeout=timeout)

    async def start(self):
        self.client = Client(api_key=self.api_key, api_secret=self.api_secret)
        self.sync_binance_time()
        self.session = await self._init_session()
        # User-data WS owned by ez_positions_service.WebSocketManager (canonical). Binance
        # allows ONE connection per listen_key — duplicating here kicks service's WS off and
        # leaves both thrashing (root cause of 2026-04-30 ws_reset detector trip).
        for account_key in self.account_keys:
            logger.info(
                f"[{account_key}] User-data WS skipped here; owned by ez_positions_service WebSocketManager."
            )
        if not self._mark_price_session or self._mark_price_session.closed:
            self._mark_price_session = await self._init_session()
        await self.ensure_mark_price_streams()

    def sync_binance_time(self):
        """Sync local time with Binance server time to prevent signature errors. Max once per hour."""
        current_time = time.time()
        if (
            hasattr(self, "_last_time_sync")
            and (current_time - self._last_time_sync) < 3600
        ):
            return True
        try:
            server_time_response = self.client.futures_time()
            server_time = server_time_response["serverTime"]
            local_time = int(time.time() * 1000)
            time_diff = server_time - local_time
            if abs(time_diff) > 1000:
                logger.warning(
                    f"[{','.join(self.account_keys)}] ⚠️ Significant time difference detected: {time_diff}ms. This may cause signature errors."
                )
                logger.warning(
                    f"[{','.join(self.account_keys)}] Please check system clock synchronization."
                )
            self.time_offset = time_diff
            self._last_time_sync = current_time
            return True
        except Exception as e:
            logger.error(
                f"[{','.join(self.account_keys)}] Failed to sync time with Binance: {e}"
            )
            return False

    async def user_data_websocket_loop(self, url, account_key):
        logger.debug(
            f"[{account_key}] Starting user data websocket loop for {url[:50]}..."
        )
        while self._running:
            try:
                current_listen_key = self.listen_keys.get(account_key)
                if current_listen_key and current_listen_key not in url:
                    # 2026-05-10: routed /private/ required since Binance change; /ws/{lk} silently sends 0 msgs
                    url = f"wss://fstream.binance.com/ws/{current_listen_key}"
                    logger.debug(
                        f"[{account_key}] Using refreshed listen key, new URL: {url[:50]}..."
                    )
                if self.session.closed:
                    logger.debug(
                        f"[{account_key}] Session was closed, creating new session..."
                    )
                    self.session = await self._init_session()
                logger.debug(f"[{account_key}] Attempting websocket connection...")
                async with self.session.ws_connect(
                    url, heartbeat=30, timeout=60.0
                ) as ws:
                    logger.debug(
                        f"[{account_key}] Websocket connected successfully! Waiting for messages..."
                    )
                    async for message in ws:
                        if message.type == aiohttp.WSMsgType.TEXT:
                            try:
                                data = safe_json_loads(message.data)
                                event_type = data.get("e")
                                logger.debug(
                                    f"[{account_key}] WS message received: event_type={event_type}"
                                )
                                if event_type == "ACCOUNT_UPDATE":
                                    update = data.get("a", {})
                                    payloads = update.get("P", [])
                                    pos_info = (
                                        [
                                            f"{p.get('s', 'N/A')}/{p.get('ps', 'BOTH')}"
                                            for p in payloads
                                            if p.get("s")
                                        ]
                                        if payloads
                                        else []
                                    )
                                    logger.debug(
                                        f"[{account_key}] ACCOUNT_UPDATE received from websocket, processing... symbols/sides: {pos_info if pos_info else 'none'}"
                                    )
                                    now = datetime.now(timezone.utc)
                                    event_ts = now
                                    event_ts_raw = data.get("E") or data.get(
                                        "eventTime"
                                    )
                                    if event_ts_raw:
                                        try:
                                            event_ts = ensure_tz(
                                                datetime.fromtimestamp(
                                                    event_ts_raw / 1000, tz=timezone.utc
                                                )
                                            )
                                        except Exception:
                                            event_ts = now
                                    for pos_update in payloads:
                                        symbol_raw = pos_update.get("s")
                                        if not symbol_raw:
                                            continue
                                        position_side_raw = (
                                            pos_update.get("ps") or ""
                                        ).upper()
                                        if (
                                            not position_side_raw
                                            or position_side_raw
                                            not in ("LONG", "SHORT")
                                        ):
                                            continue
                                        raw_amt_raw = safe_fetch_float(
                                            pos_update.get("pa") or "0"
                                        )
                                        entry_price_raw = safe_fetch_float(
                                            pos_update.get("ep") or "0"
                                        )
                                        unrealized_pnl_USD_raw = (
                                            safe_fetch_float(
                                                pos_update.get("up")
                                                or pos_update.get("unrealizedProfit")
                                            )
                                            if (
                                                "up" in pos_update
                                                or "unrealizedProfit" in pos_update
                                            )
                                            else None
                                        )
                                        position_key_raw = construct_position_key(
                                            account_key, symbol_raw, position_side_raw
                                        )
                                        if not position_key_raw:
                                            continue
                                        position_data = {
                                            "positionAmt": abs(raw_amt_raw),
                                            "symbol": symbol_raw,
                                            "positionSide": position_side_raw,
                                            "entryPrice": entry_price_raw,
                                            "ep": entry_price_raw,
                                            "unrealizedPnl": unrealized_pnl_USD_raw,
                                            "timestamp": event_ts,
                                        }
                                        await self.trade_manager.position_callback_manager.notify_position_update(
                                            position_key_raw, position_data
                                        )
                                        if self.trade_manager.order_execution_monitor:
                                            self.trade_manager.order_execution_monitor.mark_order_executed(
                                                position_key_raw
                                            )
                                            logger.info(f"pac1: WS: {position_data} ")
                                elif event_type == "ORDER_TRADE_UPDATE":
                                    pass  # Keep disabled if noisy/error-prone
                                elif event_type == "listenKeyExpired":
                                    logger.warning(
                                        f"[{account_key}] Listen key expired. Attempting to refresh."
                                    )
                                    await self.refresh_listen_key_and_reconnect(
                                        account_key
                                    )  # Implement this method
                                    break  # Break inner loop to force reconnect with new key
                                else:
                                    logger.debug(
                                        f"[{account_key}] WS message with unknown event_type: {event_type}"
                                    )
                            except json.JSONDecodeError:
                                logger.error(
                                    f"[{account_key}] Failed to parse user data message: {message.data}"
                                )
                            except Exception as e_msg:
                                logger.error(
                                    f"[{account_key}] Error processing WebSocket message: {e_msg}",
                                    exc_info=True,
                                )
                        elif message.type == aiohttp.WSMsgType.ERROR:
                            logger.error(
                                f"User data WebSocket error for '{account_key}': {ws.exception()}"
                            )
                            break  # Break inner loop to reconnect
                        elif message.type == aiohttp.WSMsgType.CLOSED:
                            logger.warning(
                                f"User data WebSocket closed for '{account_key}'."
                            )
                            break  # Break inner loop to reconnect
            except aiohttp.ClientConnectorError as e:
                logger.error(
                    f"[{account_key}] User data WS Connection Error: {e}. Retrying..."
                )
            except Exception as e:
                logger.error(
                    f"[{account_key}] Unexpected error in user data WebSocket loop: {e}",
                    exc_info=True,
                )
            logger.info(
                f"[{account_key}] Reconnecting user data WebSocket in 5 seconds..."
            )
            await asyncio.sleep(5)

    async def keep_listen_key_alive(self, account_key):
        """Keep the listen key alive; auto-recreate on failure with backoff."""
        backoff = 5
        while self._running:
            try:
                await asyncio.sleep(25 * 60)  # Keep alive every 25 minutes
                if not self.client or not self.listen_keys.get(account_key):
                    raise RuntimeError("listen key or client not available")
                self.client.futures_stream_keepalive(self.listen_keys[account_key])
                logger.info(f"[{account_key}] Listen key kept alive.")
                backoff = 5  # Reset backoff on success
            except asyncio.TimeoutError:
                logger.warning(
                    f"[{account_key}] Timeout keeping listen key alive, refreshing..."
                )
                await self.refresh_listen_key_and_reconnect(account_key)
                await asyncio.sleep(backoff)
                backoff = min(backoff * 2, 300)
            except Exception as e:
                logger.error(
                    f"[{account_key}] Error keeping listen key alive: {e}",
                    exc_info=True,
                )
                try:
                    await self.refresh_listen_key_and_reconnect(account_key)
                except Exception as e2:
                    logger.error(
                        f"[{account_key}] Failed to refresh listen key: {e2}",
                        exc_info=True,
                    )
                await asyncio.sleep(backoff)
                backoff = min(backoff * 2, 300)

    async def refresh_listen_key_and_reconnect(self, account_key):
        logger.warning(f"[{account_key}] Attempting to refresh listen key...")
        try:
            if self.client:
                new_listen_key = self.client.futures_stream_get_listen_key()
                old_key = self.listen_keys.get(account_key)
                self.listen_keys[account_key] = new_listen_key
                new_url = f"wss://fstream.binance.com/ws/{new_listen_key}"
                logger.debug(
                    f"[{account_key}] Listen key refreshed. Old key: {old_key[:20] if old_key else 'None'}..., New key: {new_listen_key[:20]}..."
                )
                logger.debug(f"[{account_key}] New URL: {new_url[:50]}...")
            else:
                logger.error(
                    f"[{account_key}] Cannot refresh listen key, client not available."
                )
        except Exception as e:
            logger.error(
                f"[{account_key}] Failed to refresh listen key: {e}", exc_info=True
            )

    async def mark_price_aggregate_loop(self):
        # 2026-05-10: routed /market/ path required since Binance change; /ws/!markPrice@arr silently sends 0 msgs
        url = "wss://fstream.binance.com/market/stream?streams=!markPrice@arr@1000ms"
        backoff = 5
        while self._running and not self._mark_price_stop:
            try:
                if not self._mark_price_session or self._mark_price_session.closed:
                    self._mark_price_session = await self._init_session()
                try:
                    async with self._mark_price_session.ws_connect(
                        url, heartbeat=30, timeout=60.0
                    ) as ws:
                        logger.debug(
                            "[mark_price] Connected to aggregate mark price stream"
                        )
                        backoff = 5
                        async for message in ws:
                            if not self._running or self._mark_price_stop:
                                break
                            if message.type == aiohttp.WSMsgType.TEXT:
                                await self._handle_mark_price_message(message.data)
                            elif message.type in (
                                aiohttp.WSMsgType.ERROR,
                                aiohttp.WSMsgType.CLOSED,
                            ):
                                logger.warning(
                                    "[mark_price] Websocket closed or errored, reconnecting..."
                                )
                                break
                except AttributeError:
                    logger.warning(
                        "[mark_price] Session invalid (connector None). Recreating session..."
                    )
                    self._mark_price_session = await self._init_session()
                    await asyncio.sleep(0.5)
                    continue
                if not self._mark_price_stop:
                    await asyncio.sleep(1)
            except asyncio.CancelledError:
                break
            except Exception as exc:
                logger.error(f"[mark_price] Aggregate stream error: {exc}")
                await asyncio.sleep(backoff)
                backoff = min(backoff * 2, 60)

    async def mark_price_guard_loop(self):
        await asyncio.sleep(self._mark_price_guard_interval)
        while self._running and not self._mark_price_stop:
            try:
                now = datetime.now(timezone.utc)
                stale_symbols: Set[str] = set()
                async with self.trade_manager._positions_lock:
                    for position in self.trade_manager.positions.values():
                        if not position:
                            continue
                        ts = getattr(position, "mark_price_last_updated", None)
                        if isinstance(ts, str):
                            with suppress(Exception):
                                ts = isoparse(ts)
                        if isinstance(ts, datetime) and ts.tzinfo is None:
                            ts = ts.replace(tzinfo=timezone.utc)
                        if (
                            not ts
                            or (now - ts).total_seconds()
                            > self._mark_price_max_staleness
                        ):
                            stale_symbols.add(position.symbol)
                    for account_key in config.ACCOUNT_KEYS:
                        account_positions = self.trade_manager.positions_by_account.get(
                            account_key, {}
                        )
                        if not account_positions:
                            continue
                        for position in account_positions.values():
                            if not position:
                                continue
                            ts = getattr(position, "mark_price_last_updated", None)
                            if isinstance(ts, str):
                                with suppress(Exception):
                                    ts = isoparse(ts)
                            if isinstance(ts, datetime) and ts.tzinfo is None:
                                ts = ts.replace(tzinfo=timezone.utc)
                            if (
                                not ts
                                or (now - ts).total_seconds()
                                > self._mark_price_max_staleness
                            ):
                                stale_symbols.add(position.symbol)
                for symbol in stale_symbols:
                    price, ts = await self._get_mark_price_from_redis(symbol)
                    if price:
                        await self._apply_mark_price(symbol, price, ts or now)
                if time.time() - self._last_mark_price_heartbeat > max(
                    self._mark_price_max_staleness * 5, 10
                ):
                    await self._force_mark_price_reconnect("stale mark price heartbeat")
            except asyncio.CancelledError:
                break
            except Exception as exc:
                logger.debug(f"[mark_price_guard] {exc}")
            await asyncio.sleep(self._mark_price_guard_interval)

    async def ensure_mark_price_streams(self) -> None:
        if self._mark_price_stop:
            self._mark_price_stop = False
        if not self._mark_price_session or self._mark_price_session.closed:
            self._mark_price_session = await self._init_session()
        if (
            not self._mark_price_aggregate_task
            or self._mark_price_aggregate_task.done()
        ):
            if (
                self._mark_price_aggregate_task
                and self._mark_price_aggregate_task.done()
            ):
                try:
                    self._mark_price_aggregate_task.exception()
                except Exception as exc:
                    logger.warning(f"[mark_price] aggregate task ended: {exc}")
            self._mark_price_aggregate_task = asyncio.create_task(
                self.mark_price_aggregate_loop()
            )
        if not self._mark_price_guard_task or self._mark_price_guard_task.done():
            self._mark_price_guard_task = asyncio.create_task(
                self.mark_price_guard_loop()
            )

    async def _handle_mark_price_message(self, raw: str) -> None:
        try:
            data = safe_json_loads(raw)
        except Exception:
            return
        if isinstance(data, dict) and "data" in data:
            payloads = (
                data["data"] if isinstance(data["data"], list) else [data["data"]]
            )
        elif isinstance(data, list):
            payloads = data
        else:
            payloads = [data]
        for entry in payloads:
            if not isinstance(entry, dict):
                continue
            symbol = entry.get("s") or entry.get("symbol")
            if (
                symbol
                and self._valid_mark_symbols
                and symbol.upper() not in self._valid_mark_symbols
            ):
                continue
            price_candidate = (
                entry.get("p") or entry.get("markPrice") or entry.get("price")
            )
            if not symbol or price_candidate is None:
                continue
            try:
                price = float(price_candidate)
            except (TypeError, ValueError):
                continue
            event_ts_raw = entry.get("E") or entry.get("eventTime") or entry.get("T")
            ts = None
            if isinstance(event_ts_raw, (int, float)):
                ts = ensure_tz(
                    datetime.fromtimestamp(event_ts_raw / 1000, tz=timezone.utc)
                )
            elif isinstance(event_ts_raw, str):
                with suppress(Exception):
                    ts = ensure_tz(isoparse(event_ts_raw))
            await self._apply_mark_price(symbol, price, ts)

    async def _apply_mark_price(
        self, symbol: str, price: float, timestamp: Optional[datetime]
    ) -> bool:
        if price <= 0:
            return False
        symbol = symbol.strip().upper()
        all_symbols = set()
        for sym_set in [
            getattr(self.trade_manager, "symbols_ang_long", set()),
            getattr(self.trade_manager, "symbols_inf_long", set()),
            getattr(self.trade_manager, "symbols_inf_short", set()),
            getattr(self.trade_manager, "symbols_men", set()),
            getattr(self.trade_manager, "symbols_flz", set()),
            getattr(self.trade_manager, "symbols_ang_short", set()),
            getattr(self.trade_manager, "symbols_fin", set()),
        ]:
            all_symbols.update(sym_set)
        if symbol.endswith("USDT"):
            usdc_candidate = symbol.replace("USDT", "USDC")
            norm = usdc_candidate if usdc_candidate in all_symbols else symbol
        else:
            norm = symbol
        ts = ensure_tz(timestamp or datetime.now(timezone.utc))
        updated = False
        iso_ts = ts.strftime("%Y-%m-%dT%H:%M:%S.%fZ")
        async with self.trade_manager._price_cache_lock:
            self.trade_manager.price_cache[norm] = {"price": price, "timestamp": iso_ts}
            self.trade_manager.price_update_time[norm] = ts
        async with self.trade_manager._positions_lock:
            for position_key, position in self.trade_manager.positions.items():
                if position and position.symbol == norm:
                    position.mark_price = price
                    position.mark_price_last_updated = ts
                    updated = True
            for (
                account_key,
                account_positions,
            ) in self.trade_manager.positions_by_account.items():
                for position_key, position in account_positions.items():
                    if position and position.symbol == norm:
                        position.mark_price = price
                        position.mark_price_last_updated = ts
                        updated = True
        if self.trade_manager.positions_by_account:
            service = self.trade_manager.positions_service
            async with service._positions_lock:
                for position_key, position in service.positions.items():
                    if position and position.symbol == norm:
                        position.mark_price = price
                        position.mark_price_last_updated = ts
                        updated = True
                for (
                    account_key,
                    account_positions,
                ) in service.positions_by_account.items():
                    for position_key, position in account_positions.items():
                        if position and position.symbol == norm:
                            position.mark_price = price
                            position.mark_price_last_updated = ts
                            updated = True
        self._last_mark_price_heartbeat = time.time()
        return updated

    async def _force_mark_price_reconnect(self, reason: str) -> None:
        logger.warning(f"[mark_price] forcing websocket reconnect: {reason}")
        try:
            if self._mark_price_session and not self._mark_price_session.closed:
                await self._mark_price_session.close()
        except Exception as exc:
            logger.debug(f"[mark_price] reconnect close error: {exc}")
        self._mark_price_session = None
        self._last_mark_price_heartbeat = time.time()
        await self.ensure_mark_price_streams()

    async def force_mark_price_reconnect(self, reason: str) -> None:
        await self._force_mark_price_reconnect(reason)

    async def _get_mark_price_from_redis(
        self, symbol: str
    ) -> Tuple[Optional[float], Optional[datetime]]:
        client = await self._ensure_redis_client()
        if not client:
            return (None, None)
        candidates = (
            symbol,
            symbol.replace("USDC", "USDT") if symbol.endswith("USDC") else symbol,
        )
        for candidate in candidates:
            try:
                raw = await asyncio.wait_for(
                    client.get(f"mark_price:{candidate}"), timeout=2.0
                )
                if not raw:
                    continue
                if isinstance(raw, (bytes, bytearray)):
                    raw = raw.decode()
                if raw.startswith("{"):
                    payload = json.loads(raw)
                    price = safe_fetch_float(
                        payload.get("price") or payload.get("mark_price"), 0.0
                    )
                    ts_raw = payload.get("timestamp") or payload.get("time")
                else:
                    price = safe_fetch_float(raw, 0.0)
                    ts_raw = None
                if price <= 0:
                    continue
                ts = None
                if isinstance(ts_raw, str):
                    with suppress(Exception):
                        ts = ensure_tz(isoparse(ts_raw))
                return (price, ts)
            except Exception as exc:
                logger.debug(f"[mark_price] redis error {candidate}: {exc}")
        return (None, None)

    async def _ensure_redis_client(self) -> Optional[Redis]:
        if self._redis_client:
            return self._redis_client
        try:
            self._redis_client = Redis(
                host=self.config.REDIS_HOST,
                port=self.config.REDIS_PORT,
                db=self.config.REDIS_DB,
                decode_responses=True,
                socket_timeout=1,
                socket_connect_timeout=1,
            )
        except Exception as exc:
            logger.debug(f"[mark_price] redis unavailable: {exc}")
            self._redis_client = None
        return self._redis_client

    async def stop(self):
        self._running = False
        self._mark_price_stop = True
        for task in (
            self._mark_price_aggregate_task,
            self._mark_price_guard_task,
            self._mark_price_task,
            self._fallback_task,
            self._guard_task,
        ):
            if task and not task.done():
                task.cancel()
                with suppress(asyncio.CancelledError):
                    await task
        self._mark_price_aggregate_task = None
        self._mark_price_guard_task = None
        self._mark_price_task = None
        self._fallback_task = None
        self._guard_task = None
        if self.bm:
            await self.bm.stop()  # Assuming python-binance socket manager
        if self.client:
            pass
        if self.session and not self.session.closed:
            await self.session.close()
        if self._mark_price_session and not self._mark_price_session.closed:
            await self._mark_price_session.close()
        logger.info(f"WebSocketManager for {','.join(self.account_keys)} stopped.")


async def read_json_file(filepath: str | Path) -> dict:
    try:
        filepath = Path(filepath)
        if not filepath.exists():
            return {}
        async with _global_file_write_semaphore:
            async with aiofiles.open(str(filepath), "rb") as f:
                content = await f.read()
                return safe_json_loads(content)
    except Exception as e:
        logger.debug(f"Could not read {filepath}: {e}")
        return {}


async def _atomic_write_json_impl(file_path: Union[str, Path], data: dict):
    try:
        file_path_obj = Path(file_path)
    except Exception:
        return False
    random_suffix = uuid.uuid4().hex[:8]
    temp_path_obj = file_path_obj.with_name(
        f".tmp_{random_suffix}_{file_path_obj.name}"
    )
    str_file_path = str(file_path_obj)
    str_temp_path = str(temp_path_obj)
    try:
        if not file_path_obj.parent.exists():
            file_path_obj.parent.mkdir(parents=True, exist_ok=True)
            try:
                os.chmod(str(file_path_obj.parent), 0o775)
            except Exception:
                pass
        try:
            json_bytes = json_dumps(data)
        except Exception as e:
            logger.error(f"Serialization failed for {str_file_path}: {e}")
            return False
        if isinstance(json_bytes, str):
            json_bytes = json_bytes.encode("utf-8")
        async with aiofiles.open(str_temp_path, "wb") as f:
            await f.write(json_bytes)
            await f.flush()
        await asyncio.to_thread(os.replace, str_temp_path, str_file_path)
        try:
            os.chmod(str_file_path, 0o664)
        except Exception:
            pass
        return True
    except Exception as e:
        logger.error(f"Atomic write failed for {str_file_path}: {e}")
        if Path(str_temp_path).exists():
            try:
                os.unlink(str_temp_path)
            except Exception:
                pass
        return False


def _sanitize_json_value(value: Any) -> Any:
    """Recursively sanitize JSON values to ensure no NaN/inf."""
    if isinstance(value, float):
        if math.isnan(value) or math.isinf(value):
            return 0.0
        return value
    elif isinstance(value, dict):
        return {k: _sanitize_json_value(v) for k, v in value.items()}
    elif isinstance(value, (list, tuple)):
        return [_sanitize_json_value(item) for item in value]
    return value


async def atomic_write_json(file_path: Union[str, Path], data: dict):
    clean_data = _sanitize_json_value(data)
    async with _get_file_write_semaphore():
        return await _atomic_write_json_impl(file_path, clean_data)


async def quick_price(symbol: Optional[str] = None) -> float:
    global trade_manager_global
    if not symbol:
        return 0.0
    trade_manager = trade_manager_global
    candidates = []
    now_utc = datetime.now(timezone.utc)
    if not trade_manager:
        return None
    if trade_manager:
        try:
            read_client = None
            if trade_manager.redis_manager and trade_manager.redis_manager._initialized:
                read_client = trade_manager.redis_manager.connections.get(
                    "gateway"
                ) or trade_manager.redis_manager.connections.get("local")
            if read_client:
                redis_key = f"mark_price:{symbol}"
                data = await asyncio.wait_for(read_client.get(redis_key), timeout=2.0)
                if data:
                    try:
                        p_data = safe_json_loads(data)
                        price = float(p_data["price"])
                        if price > 0:
                            ts_str = p_data.get("timestamp", "")
                            normalized_ts = (
                                _normalize_timestamp_to_z(ts_str)
                                if ts_str and isinstance(ts_str, str)
                                else ts_str
                            )
                            timestamp = safe_datetime(normalized_ts, normalized_ts)
                            if timestamp and timestamp.tzinfo is None:
                                timestamp = timestamp.replace(tzinfo=timezone.utc)
                            age = (
                                (now_utc - timestamp).total_seconds()
                                if timestamp
                                else 999999
                            )
                            if age < 12.0 and price > 0:
                                return price
                            if age < 90 and price > 0:
                                candidates.append((age, price, "Redis", timestamp))
                    except Exception:
                        pass
        except Exception:
            pass
    if trade_manager:
        if symbol in trade_manager.price_cache:
            try:
                cache_entry = trade_manager.price_cache[symbol]
                if isinstance(cache_entry, dict) and "price" in cache_entry:
                    price = float(cache_entry["price"])
                    if price > 0:
                        timestamp = safe_datetime(cache_entry.get("timestamp"), now_utc)
                        if timestamp.tzinfo is None:
                            timestamp = timestamp.replace(tzinfo=timezone.utc)
                        age = (now_utc - timestamp).total_seconds()
                        if age < 12.0 and price > 0:
                            return price
                        if age < 90 and price > 0:
                            candidates.append((age, price, "price_cache", timestamp))
            except Exception:
                pass
        if symbol in trade_manager.price_cache_2:
            try:
                cache_entry = trade_manager.price_cache_2[symbol]
                if isinstance(cache_entry, dict) and "price" in cache_entry:
                    price = float(cache_entry["price"])
                    if price > 0:
                        timestamp = safe_datetime(cache_entry.get("timestamp"), now_utc)
                        if timestamp.tzinfo is None:
                            timestamp = timestamp.replace(tzinfo=timezone.utc)
                        age = (now_utc - timestamp).total_seconds()
                        if age < 12.0 and price > 0:
                            return price
                        if age < 90 and price > 0:
                            candidates.append((age, price, "price_cache_2", timestamp))
            except Exception:
                pass
        if symbol in trade_manager.price_cache_3:
            try:
                cache_entry = trade_manager.price_cache_3[symbol]
                if isinstance(cache_entry, dict) and "price" in cache_entry:
                    price = float(cache_entry["price"])
                    if price > 0:
                        timestamp = safe_datetime(cache_entry.get("timestamp"), now_utc)
                        if timestamp.tzinfo is None:
                            timestamp = timestamp.replace(tzinfo=timezone.utc)
                        age = (now_utc - timestamp).total_seconds()
                        if age < 12.0 and price > 0:
                            return price
                        if age < 90 and price > 0:
                            candidates.append((age, price, "price_cache_3", timestamp))
            except Exception:
                pass
        managed_accounts = set(trade_manager.accounts.keys())
        for account_key, positions_dict in trade_manager.positions_by_account.items():
            if (
                account_key not in managed_accounts
                or account_key not in config.ACCOUNT_KEYS
            ):
                continue
            for position_key, position in positions_dict.items():
                if (
                    position
                    and position.symbol == symbol
                    and position.mark_price
                    and position.mark_price > 0
                ):
                    ts = getattr(position, "last_updated", None) or getattr(
                        position, "mark_price_last_updated", None
                    )
                    if isinstance(ts, str):
                        ts = isoparse(ts)
                    if isinstance(ts, datetime) and ts.tzinfo is None:
                        ts = ts.replace(tzinfo=timezone.utc)
                    age = (now_utc - ts).total_seconds() if ts else 999
                    if age < 12.0 and position.mark_price > 0:
                        return position.mark_price
                    if age < 90 and position.mark_price > 0:
                        candidates.append((age, position.mark_price, "position", ts))
                    break
        try:
            price, price_ts = await get_current_price(symbol)
            if price and price > 0:
                age = (now_utc - price_ts).total_seconds() if price_ts else 999
                if age < 12.0:
                    return price
                if age < 90:
                    candidates.append((age, price, "get_current_price", price_ts))
        except Exception:
            pass
    if candidates:
        candidates.sort(key=lambda x: x[0])
        best_age, price, best_source, best_ts = candidates[0]
        if price <= 0:
            logger.error(
                f"[quick_price] CRITICAL: Best candidate has invalid price {price} for {symbol}!"
            )
            return None
        return price
    return None


async def price(
    symbol: str, position=None, max_age: float = 2.0, withts: bool = False
) -> Union[float, Tuple[float, Optional[datetime]]]:
    """Get fresh price with strict age check (default 2s). If withts=True, returns (price, timestamp_obj)."""
    if not symbol:
        return (0.0, None) if withts else 0.0
    global trade_manager_global
    trade_manager = trade_manager_global
    now = datetime.now(timezone.utc)
    if trade_manager:
        entry = trade_manager.price_cache.get(symbol)
        if entry:
            if isinstance(entry, dict):
                price_val = safe_fetch_float(entry.get("price"), 0.0)
                ts_raw = entry.get("timestamp")
                ts = ensure_tz(safe_datetime(ts_raw)) if ts_raw else None
            else:
                price_val = safe_fetch_float(entry, 0.0)
                ts = now  # Assume fresh if direct float (rare)
            if price_val > 0 and ts and (now - ts).total_seconds() <= max_age:
                return (price_val, ts) if withts else price_val
        for cache_name in ("price_cache_2", "price_cache_3"):
            cache = getattr(trade_manager, cache_name, {}) or {}
            entry = cache.get(symbol)
            if entry:
                if isinstance(entry, dict):
                    price_val = safe_fetch_float(entry.get("price"), 0.0)
                    ts_raw = entry.get("timestamp")
                    ts = ensure_tz(safe_datetime(ts_raw)) if ts_raw else None
                    if price_val > 0 and ts and (now - ts).total_seconds() <= max_age:
                        return (price_val, ts) if withts else price_val
    if (
        trade_manager
        and trade_manager.redis_manager
        and trade_manager.redis_manager._initialized
    ):
        read_client = trade_manager.redis_manager.connections.get("local")
        if read_client:
            try:
                data = await asyncio.wait_for(
                    read_client.get(f"mark_price:{symbol}"), timeout=2.0
                )
                if data:
                    if isinstance(data, (bytes, bytearray)):
                        data = data.decode()
                    p_data = (
                        json.loads(data)
                        if isinstance(data, str) and data.startswith("{")
                        else None
                    )
                    if p_data:
                        price_val = float(p_data.get("price", 0.0))
                        if price_val > 0:
                            ts_str = p_data.get("timestamp", "")
                            ts = ensure_tz(isoparse(ts_str)) if ts_str else now
                            age = (now - ts).total_seconds()
                            if age <= max_age:
                                return (price_val, ts) if withts else price_val
                    elif not withts and data:
                        return float(data)
            except Exception:
                pass
    if not withts:
        quick = await quick_price(symbol)
        if quick and quick > 0:
            return quick
    if position:
        pos_price = safe_fetch_float(getattr(position, "mark_price", 0.0), 0.0)
        pos_updated = getattr(position, "mark_price_last_updated", None)
        if pos_price > 0 and pos_updated:
            if isinstance(pos_updated, datetime):
                if pos_updated.tzinfo is None:
                    pos_updated = pos_updated.replace(tzinfo=timezone.utc)
                if (now - pos_updated).total_seconds() <= max_age:
                    return (pos_price, pos_updated) if withts else pos_price
    robust_price, robust_ts = await get_current_price(symbol)
    if robust_price and robust_price > 0:
        return (robust_price, robust_ts) if withts else robust_price
    return (0.0, None) if withts else 0.0


def _normalize_event_type(ctx: dict) -> str:
    event_type = ctx.get("event_type")
    signal_data = ctx.get("signal_data")
    if not event_type and isinstance(signal_data, dict):
        event_type = signal_data.get("event_type")
    if event_type is None:
        return "account_update"
    if not isinstance(event_type, str):
        return str(event_type)
    return event_type or "account_update"


def _decide_action(positionAmt: float, min_qty: float) -> str:
    if min_qty <= 0:
        return "OPEN" if positionAmt <= 0 else "AUGMENT"
    return "OPEN" if abs(positionAmt) < min_qty else "AUGMENT"


@dataclass(eq=True)
class StopLevel:
    level: float
    reduction_amount: float
    position_side: str
    strategy: str = "system"
    created_at: datetime = field(default_factory=lambda: datetime.now(timezone.utc))
    updated_at: datetime = field(default_factory=lambda: datetime.now(timezone.utc))
    source: str = "service"
    order_id: Optional[str] = None
    breakeven_applied: bool = False
    binance_stop_price: Optional[float] = None
    managed_on_exchange: bool = False
    last_synced_at: Optional[datetime] = None
    augmentation_price: float = 0.0

    def to_dict(self) -> Dict[str, Any]:
        return {
            "level": float(self.level),
            "reduction_amount": float(self.reduction_amount),
            "position_side": self.position_side,
            "strategy": self.strategy,
            "created_at": ensure_tz(self.created_at).strftime("%Y-%m-%dT%H:%M:%S.%fZ"),
            "updated_at": ensure_tz(self.updated_at).strftime("%Y-%m-%dT%H:%M:%S.%fZ"),
            "source": self.source,
            "order_id": self.order_id,
            "breakeven_applied": self.breakeven_applied,
            "binance_stop_price": float(self.binance_stop_price)
            if self.binance_stop_price is not None
            else None,
            "managed_on_exchange": self.managed_on_exchange,
            "last_synced_at": ensure_tz(self.last_synced_at).strftime(
                "%Y-%m-%dT%H:%M:%S.%fZ"
            )
            if self.last_synced_at
            else None,
            "augmentation_price": float(self.augmentation_price),
        }

    @classmethod
    def from_dict(cls, payload: Dict[str, Any]) -> "StopLevel":
        parsed_created = (
            ensure_tz(isoparse(payload["created_at"]))
            if payload.get("created_at")
            else datetime.now(timezone.utc)
        )
        parsed_updated = (
            ensure_tz(isoparse(payload["updated_at"]))
            if payload.get("updated_at")
            else parsed_created
        )
        parsed_synced = (
            ensure_tz(isoparse(payload["last_synced_at"]))
            if payload.get("last_synced_at")
            else None
        )
        return cls(
            level=safe_float(payload.get("level")),
            reduction_amount=safe_float(payload.get("reduction_amount")),
            position_side=str(payload.get("position_side") or ""),
            strategy=str(payload.get("strategy", "service")),
            created_at=parsed_created,
            updated_at=parsed_updated,
            source=str(payload.get("source", "service")),
            order_id=str(payload.get("order_id") or "") or None,
            breakeven_applied=bool(payload.get("breakeven_applied", False)),
            binance_stop_price=safe_float(payload.get("binance_stop_price"))
            if payload.get("binance_stop_price") is not None
            else None,
            managed_on_exchange=bool(payload.get("managed_on_exchange", False)),
            last_synced_at=parsed_synced,
            augmentation_price=safe_float(payload.get("augmentation_price")),
        )


class SnapshotLoader:
    def __init__(self, trade_manager, data_dir):
        self.trade_manager = trade_manager
        self.data_dir = Path(data_dir)
        self.last_loaded_file = None
        self._shutdown = False
        if not hasattr(self.trade_manager, "indicators_snapshot"):
            self.trade_manager.indicators_snapshot = {}

    async def start(self):
        """Starts the background loop."""
        asyncio.create_task(self._loader_loop())

    async def _loader_loop(self):
        while not self._shutdown:
            try:
                candidates = list(self.data_dir.glob("market_data_*.json"))
                target_file = None
                if candidates:
                    candidates.sort(key=lambda p: p.name, reverse=True)
                    target_file = candidates[0]
                else:
                    static = self.data_dir / "latest_market_data.json"
                    if static.exists():
                        target_file = static
                if target_file and target_file != self.last_loaded_file:
                    async with aiofiles.open(target_file, "rb") as f:
                        content = await f.read()
                        if content:
                            data = orjson.loads(content)
                            self.trade_manager.indicators_snapshot.clear()
                            self.trade_manager.indicators_snapshot.update(data)
                            self.last_loaded_file = target_file
            except Exception as e:
                print(f"❌ Snapshot Load Error: {e}")
            await asyncio.sleep(2)


class IndicatorsBridge:
    def __init__(self, trade_manager, *, logger=None, **kwargs):
        self.trade_manager = trade_manager
        self.logger = logger or logging.getLogger("IndicatorsBridge")
        self.shared_proxy = None
        self._shutdown = False
        if not hasattr(self.trade_manager, "hot_data_cache"):
            self.trade_manager.hot_data_cache = {}
        self.cache = trade_manager.hot_data_cache

    async def initialize(self):
        self.logger.info("🚀 [BRIDGE] Starting Hot Sync (SharedMem -> HotCache)...")
        asyncio.create_task(self._maintain_connection_loop())

    async def _maintain_connection_loop(self):
        import orjson

        from ez_share_ind import get_shared_memory_client

        while not self._shutdown:
            try:
                if self.shared_proxy is None:
                    c = get_shared_memory_client()
                    if c:
                        self.shared_proxy = c.get_store()
                data_found = False
                if self.shared_proxy:
                    try:
                        hot_snapshot = self.shared_proxy.get_all()
                        if hot_snapshot:
                            self._merge_into_cache(hot_snapshot, "bridge")
                            data_found = True
                    except Exception:
                        self.shared_proxy = None
                # DEDUP_STEP6: bridge Redis fallback — authoritative: service IndicatorsBridge handles Redis fallback
                # if not data_found and hasattr(self.trade_manager, 'redis_manager'):
                #     try:
                #         client = self.trade_manager.redis_manager.connections.get("local")
                #         if client:
                #             raw = await asyncio.wait_for(client.get("latest_market_data"), timeout=2.0)
                #             if raw:
                #                 if isinstance(raw, bytes): raw = raw.decode('utf-8')
                #                 snapshot = orjson.loads(raw)
                #                 if isinstance(snapshot, dict):
                #                     self._merge_into_cache(snapshot, "redis")
                #                     data_found = True
                #     except Exception: pass
            except Exception:
                await asyncio.sleep(1)
            await asyncio.sleep(
                1.0
            )  # 1s poll — hot_data_cache updated by Redis pub/sub

    def _merge_into_cache(self, new_snapshot: Dict[str, Dict], source: str):
        target = self.trade_manager.hot_data_cache
        now = time.time()
        updated_count = 0
        for symbol, new_data in new_snapshot.items():
            if not isinstance(new_data, dict):
                continue
            existing = target.get(symbol, {})
            new_ts = float(new_data.get("_tick_ts") or new_data.get("ts") or 0)
            old_ts = float(existing.get("_hot_ts") or existing.get("ts") or 0)
            if new_ts >= old_ts:
                if symbol not in target:
                    target[symbol] = {}
                target[symbol].update(new_data)
                target[symbol]["_rcv_ts"] = now
                target[symbol]["_hot_ts"] = new_ts
                target[symbol]["_hot_source"] = source
                updated_count += 1
        if updated_count > 0:
            self.trade_manager.indicators_source_label = source
            self.trade_manager.indicators_snapshot_refresh_time = now
            self.trade_manager.indicators_timestamp = datetime.now(timezone.utc)


class RemoteStopLevelsManager:
    def __init__(self, *, logger, service_client, stop_levels_store, trade_manager):
        self.config = config
        self.logger = logger
        self.service_client = service_client
        self.stop_levels = stop_levels_store
        self.trade_manager = trade_manager
        self._managed_stop_ids: set[str] = set()

    async def manage_all_stops(self, account_key: str) -> Dict[str, List[StopLevel]]:
        return {}

    async def manage(
        self,
        *,
        account_key: str,
        symbol: str,
        position_key: str,
        position_side: str,
        position: Any,
        current_price: float,
        entry_price: Optional[float] = None,
        event: str = "sync",
        force_sync: bool = False,
    ) -> List[StopLevel]:
        return self.stop_levels.get(position_key, [])

    async def _flush_registry(self):
        return

    async def _schedule_registry_flush(self, delay: float = 15.0):
        return

    def _clear_stop(self, position_key: str, order_id: Optional[str] = None):
        registry = getattr(self.trade_manager, "managed_stop_registry", {})
        entry = registry.get(position_key)
        if not entry:
            if hasattr(self.trade_manager, "_untrack_price_band_order"):
                self.trade_manager._untrack_price_band_order(position_key, order_id)
            return
        registry.pop(position_key, None)
        if hasattr(self.trade_manager, "_untrack_price_band_order"):
            self.trade_manager._untrack_price_band_order(
                position_key, order_id or entry.get("orderId")
            )

    def _registry_key(self, position_key: str) -> str:
        return position_key

    def _ingest_payload(self, payload: Dict[str, Any]) -> Dict[str, List[StopLevel]]:
        if not isinstance(payload, dict):
            return {}
        result: Dict[str, List[StopLevel]] = {}
        for position_key, entries in payload.items():
            parsed = []
            if isinstance(entries, list):
                for entry in entries:
                    if isinstance(entry, StopLevel):
                        parsed.append(entry)
                    elif isinstance(entry, dict):
                        try:
                            parsed.append(StopLevel.from_dict(entry))
                        except Exception as exc:
                            self.logger.debug(
                                f"[stop_manager] Failed to parse stop level for {position_key}: {exc}"
                            )
        self.trade_manager._untrack_price_band_order(position_key, None)
        for level in parsed:
            order_id = getattr(level, "order_id", None)
            if order_id:
                self.trade_manager._track_price_band_order(position_key, order_id)
            self.stop_levels[position_key] = parsed
            result[position_key] = parsed
        return result


class PositionUpdateCallback:
    """Read-only buffer for websocket position updates. Provides latest position data without modifying position objects."""

    def __init__(self, trade_manager=None):
        self.callbacks: Dict[
            str, List[Callable]
        ] = {}  # position_key -> list of callback functions
        self.latest_positions: Dict[
            str, Dict[str, Any]
        ] = {}  # position_key -> latest position data buffer (READ-ONLY)
        self._lock = DummyLock()
        self.trade_manager = trade_manager
        self._pending_reloads: Dict[
            str, asyncio.Task
        ] = {}  # account_key -> pending reload task
        self._reload_delay = 0.75  # Delay before reloading after WebSocket update

    async def register_callback(self, position_key: str, callback_func: Callable):
        """Register a callback for position updates during order execution"""
        async with self._lock:
            if position_key not in self.callbacks:
                self.callbacks[position_key] = []
            self.callbacks[position_key].append(callback_func)

    async def unregister_callback(self, position_key: str, callback_func: Callable):
        """Remove callback after order completion"""
        async with self._lock:
            if position_key in self.callbacks:
                try:
                    self.callbacks[position_key].remove(callback_func)
                    if not self.callbacks[position_key]:
                        del self.callbacks[position_key]
                except ValueError:
                    pass

    async def notify_position_update(
        self, position_key: str, position_data: Dict[str, Any]
    ):
        """Notify all registered callbacks of position updates and schedule debounced position reload - READ ONLY, positions_service writes"""
        if self.trade_manager and self.trade_manager.order_execution_monitor:
            was_tracked = (
                self.trade_manager.order_execution_monitor.mark_order_executed(
                    position_key
                )
            )
            if was_tracked:
                await self.trade_manager.force_clear_execution_lock(position_key)
        if self.trade_manager:
            try:
                now_utc = datetime.now(timezone.utc)
                positionAmt = safe_fetch_float(position_data.get("positionAmt", 0), 0.0)
                position_data["positionAmt"] = positionAmt  # Ensure float type in data
                prev_position = self.trade_manager.positions.get(position_key)
                prev_amt = (
                    abs(safe_fetch_float(getattr(prev_position, "positionAmt", 0), 0.0))
                    if prev_position
                    else 0.0
                )
                amt_abs = abs(positionAmt)
                if amt_abs > prev_amt and prev_amt > 0:
                    augment_qty = amt_abs - prev_amt
                    current_price = safe_fetch_float(
                        position_data.get("mark_price") or position_data.get("price"),
                        0.0,
                    )
                    if not current_price and prev_position:
                        current_price = safe_fetch_float(
                            getattr(prev_position, "mark_price", 0), 0.0
                        )
                elif amt_abs < prev_amt and amt_abs >= 0:
                    reduce_qty = prev_amt - amt_abs
                    current_price = safe_fetch_float(
                        position_data.get("mark_price") or position_data.get("price"),
                        0.0,
                    )
                    if not current_price and prev_position:
                        current_price = safe_fetch_float(
                            getattr(prev_position, "mark_price", 0), 0.0
                        )
                    if current_price > 0:
                        reduce_value = reduce_qty * current_price
                        if hasattr(self.trade_manager, "reduction_cooldown_map"):
                            self.trade_manager.reduction_cooldown_map[position_key] = {
                                "time": now_utc,
                                "usd": reduce_value,
                            }
                            logger.warning(
                                f"[WS_COOLDOWN_SET] {position_key}: Reduction cooldown set - qty={reduce_qty:.6f}, value=${reduce_value:.2f}"
                            )
                if abs(amt_abs - prev_amt) > 0.001:
                    if (
                        hasattr(self.trade_manager, "active_maker_orders")
                        and position_key in self.trade_manager.active_maker_orders
                    ):
                        logger.warning(
                            f"[WS_ORDER_CONFIRMED] {position_key}: Position changed from {prev_amt:.6f} to {amt_abs:.6f} - clearing active order lock"
                        )
                        await self.trade_manager.clear_active_maker_order(position_key)
                        logger.debug(
                            f"[KEEP_DEDUPE_EXECUTED] {position_key}: Order executed - keeping deduplication entry"
                        )
                    exec_lock_key_buy = f"execute_now:{position_key}:BUY"
                    exec_lock_key_sell = f"execute_now:{position_key}:SELL"
                    try:
                        if self.trade_manager.redis_manager and hasattr(
                            self.trade_manager.redis_manager, "delete"
                        ):
                            await self.trade_manager.redis_manager.delete(
                                exec_lock_key_buy
                            )
                            await self.trade_manager.redis_manager.delete(
                                exec_lock_key_sell
                            )
                    except Exception as lock_err:
                        logger.debug(
                            f"[WS_LOCK_CLEAR] {position_key}: Error clearing locks: {lock_err}"
                        )
            except Exception as cooldown_err:
                logger.error(
                    f"[WS_COOLDOWN_ERROR] {position_key}: Error setting cooldown: {cooldown_err}",
                    exc_info=True,
                )
        async with self._lock:
            self.latest_positions[position_key] = position_data
            if position_key in self.callbacks:
                for callback in self.callbacks[position_key]:
                    try:
                        if asyncio.iscoroutinefunction(callback):
                            await callback(position_data)
                        else:
                            callback(position_data)
                    except Exception as e:
                        logger.error(f"Position callback error for {position_key}: {e}")
        if self.trade_manager:
            try:
                account_key = (
                    position_key.split(":")[0] if ":" in position_key else None
                )
                if account_key and account_key in self.trade_manager.accounts:
                    await self._schedule_debounced_reload(account_key)
            except Exception as e:
                logger.debug(
                    f"[POSITION_RELOAD] Error scheduling reload for {position_key}: {e}"
                )

    async def _schedule_debounced_reload(self, account_key: str):
        """Schedule a debounced position reload for the account after WebSocket update"""
        if account_key in self._pending_reloads:
            try:
                self._pending_reloads[account_key].cancel()
            except Exception:
                pass

        async def delayed_reload():
            try:
                await asyncio.sleep(self._reload_delay)
                if self.trade_manager:
                    try:
                        await self.trade_manager._load_positions_for_account(
                            account_key
                        )
                    except Exception as e:
                        logger.debug(
                            f"[POSITION_RELOAD] Error reloading positions for {account_key}: {e}"
                        )
            except asyncio.CancelledError:
                pass
            finally:
                async with self._lock:
                    if account_key in self._pending_reloads:
                        del self._pending_reloads[account_key]

        self._pending_reloads[account_key] = asyncio.create_task(delayed_reload())

    async def get_latest_position(self, position_key: str) -> Optional[Dict[str, Any]]:
        """Get the latest position data from websocket buffer (read-only reference, does not modify position objects)"""
        async with self._lock:
            return self.latest_positions.get(position_key)

    async def has_recent_update(
        self, position_key: str, max_age_seconds: float = 5.0
    ) -> bool:
        """Check if there's a recent websocket update for this position (read-only check)"""
        async with self._lock:
            if position_key not in self.latest_positions:
                return False
            update_data = self.latest_positions[position_key]
            if not update_data.get("timestamp"):
                return False
            ws_timestamp = update_data["timestamp"]
            if isinstance(ws_timestamp, str):
                from dateutil.parser import isoparse

                ws_timestamp = safe_datetime(ws_timestamp, datetime.now(timezone.utc))
            min_since_ws = (datetime.now(timezone.utc) - ws_timestamp).total_seconds()
            return min_since_ws < max_age_seconds


class OrderExecutionMonitor:
    def __init__(self, trade_manager):
        self.trade_manager = trade_manager
        self.pending_orders: Dict[
            str, Dict[str, Any]
        ] = {}  # position_key -> order_info
        self._monitor_task: Optional[asyncio.Task] = None
        self._monitor_running = False
        self.execution_timeout = 9.0
        self.logger = logging.getLogger("OrderMonitor")

    async def start(self):
        if not self._monitor_running:
            self._monitor_running = True
            self._monitor_task = asyncio.create_task(self._monitor_loop())
            self.logger.info("[OrderMonitor] Started background monitoring")

    async def stop(self):
        self._monitor_running = False
        if self._monitor_task:
            self._monitor_task.cancel()
            with suppress(asyncio.CancelledError):
                await self._monitor_task
        self.logger.info("[OrderMonitor] Stopped")

    def track_order(self, position_key: str, action: str, quantity: float, reason: str):
        """Call this immediately before submitting an order"""
        now = time.time()
        current_pos = self.trade_manager.positions.get(position_key)
        start_amt = abs(safe_float(current_pos.positionAmt)) if current_pos else 0.0
        self.pending_orders[position_key] = {
            "position_key": position_key,
            "action": action,
            "quantity": float(quantity),
            "reason": reason,
            "sent_time": now,
            "start_amt": start_amt,
        }
        self.logger.debug(
            f"[OrderMonitor] Tracking: {position_key} {action} {quantity:.4f}"
        )

    def mark_order_executed(self, position_key: str):
        """Called by WebSocket when a position update arrives"""
        if position_key in self.pending_orders:
            order = self.pending_orders[position_key]
            elapsed = time.time() - order["sent_time"]
            self.logger.info(
                f"[OrderMonitor] CONFIRMED: {position_key} {order['action']} filled in {elapsed:.2f}s"
            )
            del self.pending_orders[position_key]
            return True
        return False

    async def _monitor_loop(self):
        """Checks for stuck orders every second"""
        while self._monitor_running:
            try:
                await asyncio.sleep(1.0)
                now = time.time()
                expired_keys = []
                for key, order in list(self.pending_orders.items()):
                    if await self._check_if_actually_filled(key, order):
                        continue
                    if (now - order["sent_time"]) > self.execution_timeout:
                        self.logger.error(
                            f"[OrderMonitor] 🚨 TIMEOUT: {key} {order['action']} stuck for {self.execution_timeout}s"
                        )
                        expired_keys.append(key)
                for key in expired_keys:
                    await self._handle_stuck_order(key)
            except asyncio.CancelledError:
                break
            except Exception as e:
                self.logger.error(f"[OrderMonitor] Loop Error: {e}")
                await asyncio.sleep(5)

    async def _check_if_actually_filled(
        self, position_key: str, order_info: dict
    ) -> bool:
        """Query the position callback manager to see if we missed the update"""
        try:
            if hasattr(self.trade_manager, "position_callback_manager"):
                latest = await self.trade_manager.position_callback_manager.get_latest_position(
                    position_key
                )
                if latest:
                    current_amt = abs(safe_float(latest.get("positionAmt", 0.0)))
                    start_amt = order_info["start_amt"]
                    if abs(current_amt - start_amt) > (order_info["quantity"] * 0.5):
                        self.mark_order_executed(position_key)
                        return True
        except Exception:
            pass
        return False

    _stuck_order_counts = {}

    async def _handle_stuck_order(self, position_key: str):
        """Aggressively clear locks so the system doesn't freeze. Limits REENTRY retries."""
        if position_key in self.pending_orders:
            order = self.pending_orders[position_key]
            action = order.get("action", "")
            self._stuck_order_counts[position_key] = (
                self._stuck_order_counts.get(position_key, 0) + 1
            )
            count = self._stuck_order_counts[position_key]
            self.logger.warning(
                f"[OrderMonitor] ☢️ NUKING LOCKS for {position_key} due to stuck {action} (attempt #{count})"
            )
            await self.trade_manager.force_clear_execution_lock(position_key)
            await self.trade_manager.clear_all_cooldowns_for_position(position_key)
            async with self.trade_manager.dedupe_lock:
                self.trade_manager.order_deduplication.pop(position_key, None)
            del self.pending_orders[position_key]
            if count >= 5 and "REENTRY" in action.upper():
                self.logger.critical(
                    f"[OrderMonitor] 🛑 REENTRY_STUCK_LIMIT: {position_key} failed {count}x — setting 10min cooldown to stop loop"
                )
                await self.trade_manager.set_trade_cooldown(
                    position_key, cooldown_seconds=600
                )
                self._stuck_order_counts[position_key] = 0


# ═══ POST-TRADE FIELD VERIFICATION — COLLAPSE if reduction fields not set within 4s ═══
_recent_trade_events: Dict[
    str, Dict
] = {}  # position_key → {timestamp, action, price, qty, ...} last 4s of activity


def _verify_reduction_fields_set(
    trade_manager, position_key: str, expected_qty: float, expected_price: float
):
    try:
        pos = None
        if (
            hasattr(trade_manager, "positions")
            and position_key in trade_manager.positions
        ):
            pos = trade_manager.positions[position_key]
        if (
            not pos
            and hasattr(trade_manager, "positions_service")
            and trade_manager.positions_service
        ):
            pos = trade_manager.positions_service.positions.get(position_key)
        if not pos:
            return
        _lrt = getattr(pos, "last_reduction_time", None)
        _lra = getattr(pos, "last_reduction_amount", 0)
        _lrp = getattr(pos, "last_reduction_price", 0)
        _wr = getattr(pos, "was_reduced", False)
        _ir = getattr(pos, "is_reduced", False)
        fields_ok = _lrt is not None and _lra > 0 and _lrp > 0 and _wr and _ir
        if not fields_ok:
            import threading
            import traceback as _vtb

            _threads = [(t.name, t.ident) for t in threading.enumerate()]
            _recent = dict(list(_recent_trade_events.items())[-20:])
            _crash_msg = f"\n{'!' * 80}\n🚨🚨🚨 FIELD COLLAPSE: {position_key} — reduction fields NOT SET 4s after trade!\nExpected: qty={expected_qty:.6f} price={expected_price:.6f}\nActual: last_reduction_time={_lrt}, last_reduction_amount={_lra}, last_reduction_price={_lrp}, was_reduced={_wr}, is_reduced={_ir}\nPosition state: positionAmt={getattr(pos, 'positionAmt', '?')}, entry_price={getattr(pos, 'entry_price', '?')}, gain={getattr(pos, 'gain', '?')}, last_signal={getattr(pos, 'last_signal', '?')}\nRecent trade events (last 4s):\n"
            for pk, ev in _recent.items():
                _crash_msg += f"  {pk}: {ev}\n"
            _crash_msg += f"Active threads: {_threads}\nPID={os.getpid()}\n{'!' * 80}\n"
            logger.critical(_crash_msg)
            try:
                with open(
                    os.path.expanduser("~/logs/FIELD_COLLAPSE_CRASH.log"), "a"
                ) as _cf:
                    _cf.write(
                        f"[{datetime.now(timezone.utc).isoformat()}] {_crash_msg}\n"
                    )
            except Exception:
                pass
        else:
            logger.info(
                f"[FIELD_VERIFY_OK] {position_key}: All reduction fields confirmed set after trade."
            )
    except Exception as e:
        logger.error(f"[FIELD_VERIFY_ERROR] {position_key}: {e}")


