def calculate_htf_requirements(min_since_exit: float, htf_confirmations: list) -> bool:
    if not isinstance(htf_confirmations, list):
        return False
    if min_since_exit <= 120:
        return True
    count = len(htf_confirmations)
    if min_since_exit <= 480:
        return count >= 3
    elif min_since_exit <= 90 * 60:
        return count >= 5
    else:
        return count >= 7


def format_reason(reason_code, i, side_params):
    """Helper to create a detailed reason string for logging."""
    i = {
        key: i.get(key, default)
        for key, default in {
            "stoch_k_3m": 50,
            "stoch_k_15m": 50,
            "ha_3m": "neutral",
            "ha_15m": "neutral",
            "wt1_15m": 0,
            "wt2_15m": 0,
        }.items()
    }
    (k_3m, k_15m, ha_3m, ha_15m, wt1_15m, wt2_15m) = [i[k] for k in i]
    current_price = side_params.get("current_price", 0.0)
    timestamp = side_params.get("timestamp", "")
    return (
        f"{reason_code} "
        f"k_3m={k_3m:.1f} "
        f"k_15m={k_15m:.1f} "
        f"ha3={ha_3m} "
        f"ha15={ha_15m} "
        f"wt1_15={wt1_15m:.1f} "
        f"wt2_15={wt2_15m:.1f} "
        f"price={current_price:.4f}"
        f"ts={timestamp}"
    )


def _parse_ranking_event_type(event_type: str):
    info = {
        "timeframe": None,
        "group": None,
        "direction": None,
        "raw_direction": None,
        "signal_type": None,
    }
    if not isinstance(event_type, str):
        return info
    parts = event_type.split("_")
    if (
        len(parts) >= 3
        and parts[0] in {"winners", "losers"}
        and parts[1] == "all"
        and parts[2] in {"green", "red"}
    ):
        info["group"] = parts[0]
        info["signal_type"] = f"all_{parts[2]}"
        info["direction"] = (
            "entry"
            if (parts[0] == "winners" and parts[2] == "green")
            or (parts[0] == "losers" and parts[2] == "red")
            else "exit"
        )
        info["raw_direction"] = f"all_{parts[2]}"
        return info
    if (
        len(parts) >= 4
        and parts[0] in {"short", "long"}
        and parts[1] == "term"
        and parts[2] in {"winners", "losers"}
    ):
        info["timeframe"] = "_".join(parts[0:2])
        info["group"] = parts[2]
        raw_dir = parts[3]
        info["raw_direction"] = raw_dir
        if raw_dir in {"up", "jump"}:
            info["direction"] = "up"
        elif raw_dir in {"down", "drop"}:
            info["direction"] = "down"
    return info


def is_position_protected_by_reversed(ctx: dict, position_key: str) -> bool:
    trade_manager = ctx["trade_manager"]
    account_key, symbol, position_side = parse_position_key(position_key)
    reversed_side = "SHORT" if position_side == "LONG" else "LONG"
    reversed_key = f"{account_key}:{symbol}_{reversed_side}"
    if reversed_key in trade_manager.reversed_positions:
        reversed_position = trade_manager.positions.get(reversed_key)
        if reversed_position and reversed_position.positionAmt > 0:
            return True  # Block the action - original position is protected
    return False


async def calculate_conviction(ctx):
    """Read conviction scores from indicators pipeline instead of calculating them."""
    cfg = ctx.get("config", config)
    if not getattr(cfg, "ENABLE_CONVICTION", True):
        default_reason = ["CONVICTION_DISABLED"]
        return 0.0, default_reason
    is_long = ctx["position_side"] == "LONG"
    indicators_data = ctx.get("indicators", {})
    if is_long:
        conviction = indicators_data.get("zconviction_long", 0.0)
        reasons = indicators_data.get("zconviction_reasons_augment_long", [])
    else:
        conviction = indicators_data.get("zconviction_short", 0.0)
        reasons = indicators_data.get("zconviction_reasons_augment_short", [])
    if not isinstance(reasons, list):
        if isinstance(reasons, str):
            reasons = [reasons] if reasons else ["NO_REASONS"]
        else:
            reasons = ["NO_REASONS"]
    return float(conviction), reasons


def calculate_reduction_conviction(ctx):
    """Simplified reduction conviction - we don't use conviction for reductions."""
    cfg = ctx.get("config", config)
    if not getattr(cfg, "ENABLE_CONVICTION", True):
        return 0.0, ["CONVICTION_DISABLED"]
    is_long = ctx["position_side"] == "LONG"
    indicators_data = ctx.get("indicators", {})
    conviction = 68.0  # Not used for reductions
    reasons = ["REDUCTION_CONVICTION_NOT_USED"]
    return float(conviction), reasons


_evaluate_reentry_original = None


@timed_function("evaluate_reentry")
async def evaluate_reentry(ctx: dict) -> Optional[Signal]:
    """Compacted evaluate_reentry — 7 proven blocks with per-block switches.
    ABLATION 2026-04-16: 9 blocks tested on 11 crypto + 12 tradier symbols.
    2 blocks CUT (B01_WT_2of3: Sharpe 0.033 noise, B09_SNAPBACK: 0.022 weak).
    7 blocks KEPT with switches for sweep testing.
    Original 1177-line version in backups/before_reentry_compact_*.py"""
    config = ctx["config"]
    logger = ctx["logger"]
    position_key = ctx["position_key"]
    symbol = ctx["symbol"]
    account_key = ctx["account_key"]
    trade_manager = ctx["trade_manager"]
    position = trade_manager.positions.get(position_key)
    if not position or position.positionAmt > 0:
        return None
    # 2026-04-28: pre-flight eligibility gate — return None early if execute_now
    # would BLOCK the resulting signal (LOSING_POSITION_HARD_BLOCK / NON_TRADEABLE).
    # Saves the indicator fetch + 7 sub-block traversal cost; suppresses B12_*,
    # B15_*, B04_*, B11_*, etc reasons from spamming execute_now.
    try:
        from ez_reentry import is_reentry_eligible as _ezr_eligible

        _ok, _gw = _ezr_eligible(
            trade_manager, position_key, account_key, symbol, config
        )
        if not _ok:
            return None
    except Exception:
        pass
    is_long = ctx.get("position_side", "LONG") == "LONG"
    current_price = safe_fetch_float(
        ctx.get("current_price")
        or ctx.get("mark_price")
        or getattr(position, "mark_price", 0.0),
        0.0,
    )
    if not current_price:
        current_price = await price(symbol, position, 3)
    if current_price <= 0:
        return None
    positionAmt = safe_fetch_float(position.positionAmt, 0.0)
    position_value = abs(positionAmt) * current_price
    min_pos_size = safe_fetch_float(config.MIN_POSITION_SIZE, 55.0)
    if position_value > 2 * min_pos_size:
        return None
    i = await ii(trade_manager, symbol)
    if not i:
        return None
    re_qty = config.START_POSITION_SIZE / max(current_price, 1e-9)
    # Phase 2 vectorization: pure block logic lives in position_evaluator.py.
    # Live and v8 backtest now share one code path — sweep parity guaranteed.
    _gr_htf_min_tfs = int(getattr(config, "GOLDEN_RULE_HTF_MIN_TFS", 0))
    if _gr_htf_min_tfs > 0:
        try:
            from golden_rule_htf import score_entry_htf as _gr_score_entry

            _gr_min_ind = int(getattr(config, "GOLDEN_RULE_MIN_IND", 2))
            _gr_ok, _gr_ntfs, _gr_detail = _gr_score_entry(
                i, is_long, "crypto", _gr_htf_min_tfs, _gr_min_ind, current_price
            )
            if not _gr_ok:
                logger.debug(
                    f"[GR_HTF_BLOCK] {position_key}: {_gr_ntfs}of{_gr_htf_min_tfs}tfs {_gr_detail}"
                )
                return None
        except Exception as _gre:
            logger.warning(f"[GR_HTF] {position_key}: {_gre}")
    from position_evaluator import evaluate_reentry_core

    sig = evaluate_reentry_core(i, is_long, current_price, config, re_qty_base=re_qty)
    if sig is None:
        return None
    # Preserve live logging tag — match the block prefix in the reason.
    _block_tag = sig.reason.split("_", 1)[0]  # B15 / B04 / etc.
    _log_fn = (
        logger.warning if _block_tag in ("B15", "B04", "B11", "B02") else logger.info
    )
    _log_fn(f"[REENTRY_{_block_tag}] {position_key}: {sig.reason}")
    return Signal(
        action="REENTRY",
        reason=sig.reason,
        conviction=sig.conviction,
        quantity=sig.quantity,
    )


@timed_function("evaluate_augmentation")
async def evaluate_augmentation(ctx: dict) -> Optional[Signal]:
    """Augment winning positions using WT crossovers as primary signal, K values for timing.
    WT cross = the trigger. K value across TFs = how much runway remains before reversal."""
    position_key = ctx["position_key"]
    config, symbol, trade_manager = ctx["config"], ctx["symbol"], ctx["trade_manager"]
    position = await trade_manager.get_position(position_key)
    if not position:
        return None
    i = (
        ctx.get("indicators")
        if isinstance(ctx.get("indicators"), dict)
        else await ii(trade_manager, symbol)
    )
    if not i:
        return None
    current_price = safe_fetch_float(ctx.get("current_price", 0), 0)
    if current_price <= 0:
        current_price = await price(symbol, position)
    if not current_price or current_price <= 0:
        return None
    is_long = ctx.get("is_long", position.position_side == "LONG")
    gain = ctx.get("gain", safe_fetch_float(getattr(position, "gain", 0), 0))
    pos_amt = abs(safe_fetch_float(getattr(position, "positionAmt", 0), 0))
    position_value = pos_amt * current_price
    # DD BOUNCE: augment losing position on wt_D or wt_4h bounce with higher price + wt — fires before gain gate
    if pos_amt > 0 and gain < 0 and getattr(config, "DD_BOUNCE_ENABLED", False):
        if not hasattr(trade_manager, "_dd_bounce_state"):
            trade_manager._dd_bounce_state = {}
        _dbs = trade_manager._dd_bounce_state.get(symbol, {})
        _dd_cool_s = float(getattr(config, "DD_BOUNCE_COOLDOWN_HOURS", 4.0)) * 3600
        _dd_last_ts = float(_dbs.get("last_aug_ts", 0.0))
        if (time.time() - _dd_last_ts) >= _dd_cool_s:
            _req_hwt = getattr(config, "DD_BOUNCE_REQUIRE_HIGHER_WT", True)
            _req_hpx = getattr(config, "DD_BOUNCE_REQUIRE_HIGHER_PRICE", True)
            _last_wt = _dbs.get("last_aug_wt", (-999.0 if is_long else 999.0))
            _last_px = _dbs.get("last_aug_price", (0.0 if is_long else float("inf")))
            _triggered_tf = None
            _trigger_wt = 0.0
            if getattr(config, "DD_BOUNCE_WT_D_ENABLED", True):
                wt1_D = safe_fetch_float(i.get("wt1_D"), 0)
                wt1_D_prev = safe_fetch_float(i.get("wt1_D_prev", wt1_D), wt1_D)
                _bounce_D = (wt1_D > wt1_D_prev) if is_long else (wt1_D < wt1_D_prev)
                _hwt_D = (not _req_hwt) or (
                    (wt1_D > _last_wt) if is_long else (wt1_D < _last_wt)
                )
                _hpx_D = (not _req_hpx) or (
                    (current_price > _last_px)
                    if is_long
                    else (current_price < _last_px)
                )
                if _bounce_D and _hwt_D and _hpx_D:
                    _triggered_tf = "D"
                    _trigger_wt = wt1_D
            if _triggered_tf is None and getattr(
                config, "DD_BOUNCE_WT_4H_ENABLED", True
            ):
                wt1_4h = safe_fetch_float(i.get("wt1_4h"), 0)
                wt1_4h_prev = safe_fetch_float(i.get("wt1_4h_prev", wt1_4h), wt1_4h)
                _bounce_4h = (
                    (wt1_4h > wt1_4h_prev) if is_long else (wt1_4h < wt1_4h_prev)
                )
                _hwt_4h = (not _req_hwt) or (
                    (wt1_4h > _last_wt) if is_long else (wt1_4h < _last_wt)
                )
                _hpx_4h = (not _req_hpx) or (
                    (current_price > _last_px)
                    if is_long
                    else (current_price < _last_px)
                )
                if _bounce_4h and _hwt_4h and _hpx_4h:
                    _triggered_tf = "4h"
                    _trigger_wt = wt1_4h
            if _triggered_tf is not None:
                dd_qty = pos_amt  # add 1x to existing 1x → total 2x
                trade_manager._dd_bounce_state[symbol] = {
                    "last_aug_ts": time.time(),
                    "last_aug_wt": _trigger_wt,
                    "last_aug_price": current_price,
                    "dd_qty": dd_qty,
                }
                return Signal(
                    action="AUGMENT",
                    reason=f"DD_BOUNCE_AUG_{_triggered_tf} wt={_trigger_wt:.1f} px={current_price:.4f}>prev={_last_px:.4f} g={gain:.2f}%",
                    conviction=70.0,
                    quantity=dd_qty,
                )
    if pos_amt <= 0 or gain < 0.3:
        return None
    now = datetime.now(timezone.utc)
    aug_seconds = (
        (now - position.last_augmentation_time).total_seconds()
        if getattr(position, "last_augmentation_time", None)
        else float("inf")
    )
    if aug_seconds < 120:
        return None
    wt1_3m = safe_fetch_float(i.get("wt1_3m"), 0)
    wt2_3m = safe_fetch_float(i.get("wt2_3m"), 0)
    wt1_15m = safe_fetch_float(i.get("wt1_15m"), 0)
    wt2_15m = safe_fetch_float(i.get("wt2_15m"), 0)
    wt1_1h = safe_fetch_float(i.get("wt1_1h"), 0)
    wt2_1h = safe_fetch_float(i.get("wt2_1h"), 0)
    wt_cross_3m = i.get("wt_cross_3m", "NONE")
    wt_cross_15m = i.get("wt_cross_15m", "NONE")
    k_3m = safe_fetch_float(i.get("stoch_k_3m"), 50)
    k_15m = safe_fetch_float(i.get("stoch_k_15m"), 50)
    k_1h = safe_fetch_float(i.get("stoch_k_1h"), 50)
    k_4h = safe_fetch_float(i.get("stoch_k_4h"), 50)
    if is_long:
        wt_dir_3m = wt1_3m > wt2_3m
        wt_dir_15m = wt1_15m > wt2_15m
        wt_dir_1h = wt1_1h > wt2_1h
        wt_cross_bull_3m = wt_cross_3m == "BULL"
        wt_cross_bull_15m = wt_cross_15m == "BULL"
        k_runway = min(100 - k_3m, 100 - k_15m, 100 - k_1h) / 100.0
        k_not_exhausted = k_3m < 85 and k_15m < 85
    else:
        wt_dir_3m = wt1_3m < wt2_3m
        wt_dir_15m = wt1_15m < wt2_15m
        wt_dir_1h = wt1_1h < wt2_1h
        wt_cross_bull_3m = wt_cross_3m == "BEAR"
        wt_cross_bull_15m = wt_cross_15m == "BEAR"
        k_runway = min(k_3m, k_15m, k_1h) / 100.0
        k_not_exhausted = k_3m > 15 and k_15m > 15
    wt_tf_aligned = sum([wt_dir_3m, wt_dir_15m, wt_dir_1h])
    has_wt_cross = wt_cross_bull_3m or wt_cross_bull_15m
    min_gain = safe_fetch_float(getattr(config, "MIN_GAIN", 5.0), 5.0)
    base_qty = config.START_POSITION_SIZE / current_price
    # AUG_A: BLOWPAST (gain >= 3×min_gain, conviction 90) — highest conviction
    if getattr(config, "AUGMENT_BLOWPAST_ENABLED", True):
        if gain >= 3 * min_gain and k_not_exhausted:
            aug_qty = min(pos_amt * 0.30, base_qty * 2.0)
            return Signal(
                action="AUGMENT",
                reason=f"AUG_A_BLOWPAST_g{gain:.1f}%_wt={wt_tf_aligned}/3_k_run={k_runway:.0%}",
                conviction=90.0,
                quantity=aug_qty,
            )
    # AUG_B: WT cross + aligned 2/3 TFs (conviction 80)
    if getattr(config, "AUGMENT_WT_CROSS_ENABLED", True):
        if has_wt_cross and wt_tf_aligned >= 2 and gain >= min_gain and k_not_exhausted:
            aug_qty = base_qty * k_runway
            cross_tf = "3m" if wt_cross_bull_3m else "15m"
            return Signal(
                action="AUGMENT",
                reason=f"AUG_B_WT_CROSS_{cross_tf}_g{gain:.1f}%_wt={wt_tf_aligned}/3_k_run={k_runway:.0%}",
                conviction=80.0,
                quantity=aug_qty,
            )
    # AUG_C: WT aligned 3/3 LTF + smaller gain (conviction 70)
    if getattr(config, "AUGMENT_WT_3TF_ENABLED", True):
        if (
            wt_tf_aligned >= 3
            and wt_dir_3m
            and gain >= 0.5 * min_gain
            and k_not_exhausted
            and k_runway > 0.25
        ):
            aug_qty = base_qty * 0.5 * k_runway
            return Signal(
                action="AUGMENT",
                reason=f"AUG_C_WT_3TF_g{gain:.1f}%_k_run={k_runway:.0%}",
                conviction=70.0,
                quantity=aug_qty,
            )
    # AUG_D: HTF trend only (conviction 65) — lowest bar, most frequent
    if getattr(config, "AUGMENT_HTF_TREND_ENABLED", True):
        if gain >= min_gain and wt_dir_15m and wt_dir_1h and k_runway > 0.30:
            aug_qty = base_qty * 0.3 * k_runway
            return Signal(
                action="AUGMENT",
                reason=f"AUG_D_HTF_TREND_g{gain:.1f}%_k_run={k_runway:.0%}",
                conviction=65.0,
                quantity=aug_qty,
            )
    return None


@timed_function("evaluate_leaderboard_entry")
async def evaluate_leaderboard_entry(ctx: dict) -> Optional[Signal]:
    """Evaluate leaderboard entry signals with Redis signals + ranking data fallback"""
    event_type = ctx.get("event_type")
    signal_data = ctx.get("signal_data")
    if not event_type and signal_data:
        event_type = signal_data.get("event_type")
    if not event_type:
        event_type = "process_position"
    position = ctx.get("position")
    if not position:
        return None
    position_key = ctx["position_key"]
    config = ctx["config"]
    logger = ctx["logger"]
    is_long = ctx["position_side"] == "LONG"
    now = datetime.now(timezone.utc)
    symbol = ctx["symbol"]
    gain = ctx["gain"]
    trade_manager = ctx["trade_manager"]
    current_price = await price(ctx["symbol"], position)
    if not current_price or current_price <= 0:
        current_price, _ = await ctx["trade_manager"].get_current_price(symbol)
    i = await ii(ctx["trade_manager"], ctx["symbol"])
    if not i:
        logger.warning(
            f"[{position_key}] LEADERBOARD_ENTRY_NOT_ALLOWED: No indicator data"
        )
        return None
    # Check for Redis signals first
    if signal_data and event_type:
        logger.debug(
            f" REDIS SIGNAL RECEIVED: evaluate_leaderboard_entry processing {event_type} for {position_key}"
        )
    else:
        # Fallback: Check ranking data directly
        logger.debug(
            f" RANKING_FALLBACK: evaluate_leaderboard_entry checking ranking data directly for {position_key}"
        )
    k_15m, k_15m_prev, d_15m, k_1h, d_1h = (
        i.get("stoch_k_15m"),
        i.get("stoch_k_15m_prev") or i.get("k_15m_prev"),
        i.get("stoch_d_15m"),
        i.get("stoch_k_1h"),
        i.get("stoch_d_1h"),
    )
    k_3m, d_3m = i.get("stoch_k_3m"), i.get("stoch_d_3m")
    ha_3m, ha_15m = i.get("ha_3m"), i.get("ha_15m")
    wt1_3m, wt2_3m, wt1_15m, wt2_15m = (
        i.get("wt1_3m"),
        i.get("wt2_3m"),
        i.get("wt1_15m"),
        i.get("wt2_15m"),
    )
    sma_200_1m, dc_basis_3m, dc_basis_15m = (
        i.get("sma_200_1m"),
        i.get("dc_basis_3m"),
        i.get("dc_basis_15m"),
    )
    dc_high_3m, dc_low_3m, dc_high_3m_ant, dc_low_3m_ant = (
        i.get("dc_high_3m"),
        i.get("dc_low_3m"),
        i.get("dc_high_3m_ant"),
        i.get("dc_low_3m_ant"),
    )
    dc_high_15m, dc_low_15m, dc_high_15m_ant, dc_low_15m_ant = (
        i.get("dc_high_15m"),
        i.get("dc_low_15m"),
        i.get("dc_high_15m_ant"),
        i.get("dc_low_15m_ant"),
    )
    high_3m, low_3m, high_3m_prev, low_3m_prev = (
        i.get("high_3m"),
        i.get("low_3m"),
        i.get("high_3m_prev"),
        i.get("low_3m_prev"),
    )
    timestamp = safe_datetime(i.get("timestamp"), datetime.now(timezone.utc))
    min_position_size = max(
        config.START_POSITION_SIZE / current_price,
        1.2 * trade_manager.min_qty.get(symbol, 0.001),
    )

    if position.positionAmt > min_position_size and gain < 0.3 * config.MIN_GAIN:
        logger.info(
            f"[LEADERBOARD_ENTRY] REJECTED GAIN TOO LOW {gain}% for {position_key}"
        )
        return None

    if (
        minutes_since(position.last_reduction_time, now) < 9
        or minutes_since(position.last_augmentation_time, now) < 9
    ):
        return None

    # Check for signals - Redis only (removed slow file I/O fallback)
    detected_signals = []
    if (
        signal_data
        and event_type
        and any(s in event_type for s in ["winners", "losers"])
    ):
        detected_signals.append(event_type)
    if not detected_signals:
        return None
    is_winner_signal = any("winners" in signal for signal in detected_signals)
    is_loser_signal = any("losers" in signal for signal in detected_signals)
    if (is_long and not is_winner_signal) or (not is_long and not is_loser_signal):
        return None
    higher_highs_3m = dc_high_3m > dc_high_3m_ant and dc_low_3m > dc_low_3m_ant
    higher_highs_15m = dc_high_15m > dc_high_15m_ant and dc_low_15m > dc_low_15m_ant
    lower_lows_3m = dc_low_3m < dc_low_3m_ant and dc_high_3m < dc_high_3m_ant
    lower_lows_15m = dc_low_15m < dc_low_15m_ant and dc_high_15m < dc_high_15m_ant
    higher_high = (
        high_3m
        and high_3m_prev
        and low_3m
        and low_3m_prev
        and (high_3m or current_price) >= high_3m_prev
        and low_3m >= low_3m_prev
    )
    lower_low = (
        high_3m
        and high_3m_prev
        and low_3m
        and low_3m_prev
        and high_3m <= high_3m_prev
        and (low_3m or current_price) <= low_3m_prev
    )
    if config.TREND_GATES:
        if is_long:
            trend_gate = (
                current_price > sma_200_1m
                or current_price > dc_basis_15m
                or (higher_high and (higher_highs_3m or higher_highs_15m))
            ) and (ha_3m == "green" or ha_15m == "green")
        else:
            trend_gate = (
                current_price < sma_200_1m
                or current_price < dc_basis_15m
                or current_price < dc_basis_3m
                or (lower_low and (lower_lows_3m or lower_lows_15m))
            ) and (ha_3m == "red" or ha_15m == "red")
        if not trend_gate:
            return None
    if signal_data:
        event_type_signal = signal_data.get("event_type", "")
        if event_type_signal and any(
            s in event_type_signal for s in ["winners", "losers"]
        ):
            info = _parse_ranking_event_type(event_type_signal)
            group = info.get("group")
            direction = info.get("direction")

            # Long entry: winners improving
            if (
                is_long
                and group == "winners"
                and direction == "up"
                and ha_3m == "green"
                and wt1_3m > wt2_3m
                and wt1_15m > wt2_15m
            ):
                conviction = ctx["conviction_long"]
                reasons = ctx["conviction_long_reasons"]
                action = (
                    "OPEN" if position.positionAmt < min_position_size else "AUGMENT"
                )
                signal_type = f"SIGNAL_DRIVEN_LEADERBOARD_LONG_{action}"
                return Signal(
                    action=action,
                    reason=f"{signal_type} ({event_type_signal}) ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}| {reasons}",
                    conviction=conviction,
                )
            elif (
                not is_long
                and group == "losers"
                and direction == "down"
                and ha_3m == "red"
                and wt1_3m < wt2_3m
                and wt1_15m < wt2_15m
            ):
                conviction = i.get("zconviction_short", 0.0)
                reasons = i.get("zconviction_reasons_augment_short", [])
                action = (
                    "OPEN" if position.positionAmt < min_position_size else "AUGMENT"
                )
                signal_type = f"SIGNAL_DRIVEN_LEADERBOARD_SHORT_{action}"
                return Signal(
                    action=action,
                    reason=f"{signal_type} ({event_type_signal}) ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}| {reasons}",
                    conviction=conviction,
                )
    # Handle NEW ranking signals
    elif "WT Strong Alert" in event_type:
        # Parse the alert to determine direction
        if "ranking_points" in event_type:
            try:
                points_str = event_type.split("ranking_points ")[-1].rstrip(")")
                ranking_points = float(points_str)
                if (is_long and ranking_points > 0) or (
                    not is_long and ranking_points < 0
                ):
                    action = (
                        "OPEN"
                        if position.positionAmt < min_position_size
                        else "AUGMENT"
                    )
                    conviction = (
                        ctx["conviction_long"] if is_long else ctx["conviction_short"]
                    )
                    reasons = (
                        ctx["conviction_long_reasons"]
                        if is_long
                        else ctx["conviction_short_reasons"]
                    )
                    return Signal(
                        action=action,
                        reason=f"WT_STRONG_ALERT_{'BUY' if is_long else 'SELL'}_{action} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}| {reasons}",
                        conviction=conviction,
                    )
            except (ValueError, IndexError):
                # Fallback for any WT Strong Alert (assume positive for long, negative for short)
                if is_long:
                    action = (
                        "OPEN"
                        if position.positionAmt < min_position_size
                        else "AUGMENT"
                    )
                    conviction = ctx["conviction_long"]
                    reasons = ctx["conviction_long_reasons"]
                    return Signal(
                        action=action,
                        reason=f"WT_STRONG_ALERT_BUY_{action} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}| {reasons}",
                        conviction=conviction,
                    )
                else:
                    action = (
                        "OPEN"
                        if position.positionAmt < min_position_size
                        else "AUGMENT"
                    )
                    conviction = ctx["conviction_short"]
                    reasons = ctx["conviction_short_reasons"]
                    return Signal(
                        action=action,
                        reason=f"WT_STRONG_ALERT_SELL_{action} cts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')} | {reasons}",
                        conviction=conviction,
                    )
    elif "winners_all_green_rank" in event_type and is_long:
        if position.positionAmt < min_position_size or gain > 0.6:
            action = "OPEN" if position.positionAmt < min_position_size else "AUGMENT"
            conviction = (
                ctx["conviction_long"] * 0.8
            )  # Slightly lower conviction for all-green signals
            reasons = ctx["conviction_long_reasons"]
            return Signal(
                action=action,
                reason=f"WINNERS_ALL_GREEN_{action} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')} | {reasons}",
                conviction=conviction,
            )
    elif "losers_all_red_rank" in event_type and not is_long:
        if position.positionAmt < min_position_size or gain > 0.6:
            action = "OPEN" if position.positionAmt < min_position_size else "AUGMENT"
            conviction = (
                ctx["conviction_short"] * 0.8
            )  # Slightly lower conviction for all-red signals
            reasons = ctx["conviction_short_reasons"]
            return Signal(
                action=action,
                reason=f"LOSERS_ALL_RED_{action} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}| {reasons}",
                conviction=conviction,
            )
    elif (
        event_type in ["winners_all_green_rank_1m", "winners_all_green_rank5"]
        and is_long
    ):
        if position.positionAmt < min_position_size or gain > 0.6:
            action = "OPEN" if position.positionAmt < min_position_size else "AUGMENT"
            conviction = (
                ctx["conviction_long"] * 0.9
            )  # Higher conviction for top-ranked signals
            reasons = ctx["conviction_long_reasons"]
            return Signal(
                action=action,
                reason=f"WINNERS_TOP_RANK_{action} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')} | {reasons}",
                conviction=conviction,
            )
    elif (
        event_type in ["losers_all_red_rank_1m", "losers_all_red_rank5"] and not is_long
    ):
        if position.positionAmt < min_position_size or gain > 0.6:
            action = "OPEN" if position.positionAmt < min_position_size else "AUGMENT"
            conviction = (
                ctx["conviction_short"] * 0.9
            )  # Higher conviction for top-ranked signals
            reasons = ctx["conviction_short_reasons"]
            return Signal(
                action=action,
                reason=f"LOSERS_TOP_RANK_{action} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}| {reasons}",
                conviction=conviction,
            )
    pullback_threshold = 0.005  # 0.5%
    has_pulled_back = False

    if is_long:
        has_pulled_back = current_price < sma_200_1m * (1 + pullback_threshold)
    else:
        has_pulled_back = (
            current_price > sma_200_1m * (1 - pullback_threshold)
            or current_price < sma_200_1m * (1 - 0.05)
            or current_price < dc_basis_15m * (1 - 0.03)
        )
    if has_pulled_back:
        if is_long:
            higher_high_1h_check = (
                i.get("high_1h", 0) > i.get("high_1h_prev", 0)
                and i.get("low_1h", 0) > i.get("low_1h_prev", 0)
                if i.get("high_1h", 0) > 0
                and i.get("high_1h_prev", 0) > 0
                and i.get("low_1h", 0) > 0
                and i.get("low_1h_prev", 0) > 0
                else False
            )
            wt_ok = (
                wt1_3m > wt2_3m
                and wt1_15m > wt2_15m
                and k_15m < 80
                and k_15m > d_15m
                and (k_1h > d_1h or higher_high_1h_check)
            )
            stoch_ok = (isinstance(k_15m, (int, float)) and k_15m <= 40) and (
                not isinstance(k_3m, (int, float))
                or not isinstance(d_3m, (int, float))
                or k_3m >= d_3m
            )
        else:
            lower_low_1h_check = (
                i.get("high_1h", 0) < i.get("high_1h_prev", 0)
                and i.get("low_1h", 0) < i.get("low_1h_prev", 0)
                if i.get("high_1h", 0) > 0
                and i.get("high_1h_prev", 0) > 0
                and i.get("low_1h", 0) > 0
                and i.get("low_1h_prev", 0) > 0
                else False
            )
            wt_ok = (
                wt1_3m < wt2_3m
                and wt1_15m < wt2_15m
                and k_15m > 20
                and k_15m < d_15m
                and (k_1h < d_1h or lower_low_1h_check)
            )
            stoch_ok = (isinstance(k_15m, (int, float)) and k_15m >= 60) and (
                not isinstance(k_3m, (int, float))
                or not isinstance(d_3m, (int, float))
                or (k_3m <= d_3m and k_3m >= 55)
            )
        if wt_ok and stoch_ok:
            conviction = (
                i.get("zconviction_long", 0.0)
                if is_long
                else i.get("zconviction_short", 0.0)
            )
            reasons = (
                i.get("zconviction_reasons_augment_long", [])
                if is_long
                else i.get("zconviction_reasons_augment_short", [])
            )
            reason = f"LEADERBOARD_ENTRY_ON_PULLBACK k_15m {k_15m:.1f} d_15m {d_15m:.1f} ({event_type})"
            if config.VERBOSE:
                logger.info(
                    f"[LEADERBOARD_ENTRY] {position_key}: OPEN - Pullback entry"
                )
            return Signal(
                action="OPEN",
                reason=f"{reason} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}| {reasons}",
                conviction=conviction,
            )
        if config.VERBOSE:
            safe_k_15m = (
                round(float(k_15m), 1) if isinstance(k_15m, (int, float)) else k_15m
            )
            safe_k_3m = (
                round(float(k_3m), 1) if isinstance(k_3m, (int, float)) else k_3m
            )
            if config.VERBOSE:
                logger.info(
                    f"[LEADERBOARD_ENTRY] Pullback gating failed for {position_key}: wt_ok={wt_ok} stoch_ok={stoch_ok} k_15m={safe_k_15m} k_3m={safe_k_3m} long={is_long}"
                )

    if config.VERBOSE:
        logger.info(f"[LEADERBOARD_ENTRY] {position_key}: None - No conditions met")
    return None


@timed_function("evaluate_ranking_momentum_trade")
async def evaluate_ranking_momentum_trade(ctx: dict) -> Optional[Signal]:
    # return None
    """Evaluate ranking momentum trades with optimized logic"""
    now = datetime.now(timezone.utc)
    position_key = ctx.get("position_key")
    account_key = ctx.get("account_key")
    trade_manager = ctx.get("trade_manager")
    position = trade_manager.positions.get(position_key)
    event_type = (
        ctx.get("event_type")
        or (ctx.get("signal_data") or {}).get("event_type")
        or "process_position"
    )
    signal_data = ctx.get("signal_data")
    symbol = ctx.get("symbol")
    is_long = ctx.get("position_side") == "LONG"
    gain = ctx.get("gain", 0.0)
    logger = ctx["logger"]
    config = ctx["config"]
    logger.debug(
        f" REDIS SIGNAL RECEIVED: evaluate_ranking_momentum_trade processing {event_type} for {position_key}"
    )
    current_price = await price(symbol, position)
    if not current_price or current_price <= 0.0:
        current_price = position.mark_price
    if not current_price or current_price <= 0.0:
        return None
    i = await ii(trade_manager, symbol)
    if not i:
        logger.warning(
            f"[{position_key}] RANKING_MOMENTUM_NOT_ALLOWED: No indicator data"
        )
        return None

    def get_f(key, default=0.0):
        val = i.get(key)
        try:
            return float(val) if val is not None else default
        except (ValueError, TypeError):
            return default

    k_15m = get_f("stoch_k_15m", 50.0)
    k_1h = get_f("stoch_k_1h", 50.0)
    d_1h = get_f("stoch_d_1h", 50.0)
    k_15m_prev = get_f("stoch_k_15m_prev", get_f("k_15m_prev", 50.0))
    k_3m = get_f("stoch_k_3m", 50.0)
    d_3m = get_f("stoch_d_3m", 50.0)
    wt1_3m = get_f("wt1_3m", 0.0)
    wt2_3m = get_f("wt2_3m", 0.0)
    wt1_15m = get_f("wt1_15m", 0.0)
    wt2_15m = get_f("wt2_15m", 0.0)
    wt1_1h = get_f("wt1_1h", 0.0)
    wt2_1h = get_f("wt2_1h", 0.0)
    sma_200_1m = get_f("sma_200_1m", current_price)
    dc_basis_3m = get_f("dc_basis_3m", current_price)
    dc_basis_15m = get_f("dc_basis_15m", current_price)
    ha_3m = i.get("ha_3m", "neutral") or "neutral"
    ha_15m = i.get("ha_15m", "neutral") or "neutral"
    dc_high_3m = get_f("dc_high_3m")
    dc_low_3m = get_f("dc_low_3m")
    dc_high_3m_ant = get_f("dc_high_3m_ant")
    dc_low_3m_ant = get_f("dc_low_3m_ant")
    dc_high_15m = get_f("dc_high_15m")
    dc_low_15m = get_f("dc_low_15m")
    dc_high_15m_ant = get_f("dc_high_15m_ant")
    dc_low_15m_ant = get_f("dc_low_15m_ant")
    high_3m = get_f("high_3m")
    high_3m_prev = get_f("high_3m_prev")
    low_3m = get_f("low_3m")
    low_3m_prev = get_f("low_3m_prev")
    if sma_200_1m == 0 or dc_basis_3m == 0:
        logger.error(
            f"CRITICAL [MOMENTUM_SIGNALS] Missing required Overlay data for {symbol}"
        )
        return None
    min_position_size = max(
        config.START_POSITION_SIZE / current_price,
        1.2 * trade_manager.min_qty.get(symbol, 0.001),
    )
    if position.positionAmt > min_position_size and gain < 0.3 * config.MIN_GAIN:
        if config.VERBOSE:
            logger.info(
                f"[{position_key}] RANKING_MOMENTUM REJECTED: Gain {gain:.2f}% too low"
            )
        return None
    if position.last_reduction_time and position.last_augmentation_time:
        if (
            minutes_since(position.last_reduction_time, now) < 6
            or minutes_since(position.last_augmentation_time, now) < 6.0
        ):
            if config.VERBOSE:
                logger.info(
                    f"[RANKING_MOMENTUM_RETURN] {position_key}: Cooldown active"
                )
            return None
    # WT-primary trend check (K kept as fallback)
    _wt_bull_1h = bool(i.get("wt_bullish_1h", False))
    _wt_vel_15m = safe_fetch_float(i.get("wt_velocity_15m"), 0)
    long_trend_bad = (
        not _wt_bull_1h and _wt_vel_15m < 0 and (ha_3m == "red" or ha_15m == "red")
    ) or (wt1_3m < wt2_3m and wt1_15m < wt2_15m)
    short_trend_bad = (
        _wt_bull_1h and _wt_vel_15m > 0 and (ha_3m == "green" or ha_15m == "green")
    ) or (wt1_3m > wt2_3m and wt1_15m > wt2_15m)
    if (is_long and long_trend_bad) or (not is_long and short_trend_bad):
        logger.info(
            f"[RANKING_MOMENTUM_RETURN] {position_key}: Price not yet trending in position direction"
        )
        return None
    account_signals = {
        "inf": [
            "short_term_winners_up_rank",
            "short_term_winners_down_rank",
            "short_term_losers_jump_rank",
            "short_term_losers_drop_rank",
            "WT Strong Alert",
        ],
        "ang": [
            "long_term_winners_up_rank",
            "long_term_winners_down_rank",
            "WT Strong Alert",
            "long_term_losers_jump_rank",
            "long_term_losers_drop_rank",
            "short_term_winners_up_rank",
            "short_term_winners_down_rank",
            "short_term_losers_jump_rank",
            "short_term_losers_drop_rank",
        ],
        "flz": [
            "short_term_winners_up_rank",
            "short_term_winners_down_rank",
            "short_term_losers_jump_rank",
            "short_term_losers_drop_rank",
            "long_term_winners_up_rank",
            "long_term_winners_down_rank",
            "long_term_losers_jump_rank",
            "long_term_losers_drop_rank",
            "WT Strong Alert",
        ],
        "men": [
            "short_term_winners_up_rank",
            "short_term_winners_down_rank",
            "short_term_losers_jump_rank",
            "short_term_losers_drop_rank",
            "long_term_winners_up_rank",
            "long_term_winners_down_rank",
            "long_term_losers_jump_rank",
            "long_term_losers_drop_rank",
            "WT Strong Alert",
        ],
        "fin": [
            "short_term_winners_up_rank",
            "short_term_winners_down_rank",
            "short_term_losers_jump_rank",
            "short_term_losers_drop_rank",
            "long_term_winners_up_rank",
            "long_term_winners_down_rank",
            "long_term_losers_jump_rank",
            "long_term_losers_drop_rank",
            "WT Strong Alert",
        ],
    }
    if account_key not in account_signals or not any(
        signal in event_type for signal in account_signals[account_key]
    ):
        return None
    try:
        rank = int(event_type.split("rank")[-1])
        if rank > 30:
            return None
    except (ValueError, IndexError):
        rank = 0
    timeframes_data = [
        ("3m", wt1_3m, wt2_3m),
        ("15m", wt1_15m, wt2_15m),
        ("1h", wt1_1h, wt2_1h),
    ]
    wt_aligned_count = sum(
        1
        for _, wt1, wt2 in timeframes_data
        if (is_long and wt1 > wt2) or (not is_long and wt1 < wt2)
    )
    if wt_aligned_count < 2:
        logger.debug(
            f"[RANKING_MOMENTUM_RETURN] {position_key}: WT alignment too weak ({wt_aligned_count}/3)"
        )
        return None
    higher_high = (
        high_3m > 0
        and high_3m_prev > 0
        and low_3m > 0
        and low_3m_prev > 0
        and high_3m >= high_3m_prev
        and low_3m >= low_3m_prev
    )
    lower_low = (
        high_3m > 0
        and high_3m_prev > 0
        and low_3m > 0
        and low_3m_prev > 0
        and high_3m <= high_3m_prev
        and low_3m <= low_3m_prev
    )
    structure_ok = (
        is_long and (higher_high or (k_3m > d_3m and ha_3m == "green"))
    ) or (not is_long and (lower_low or (k_3m < d_3m and ha_3m == "red")))
    if not structure_ok:
        logger.debug(
            f"[RANKING_MOMENTUM_RETURN] {position_key}: No structure confirmation"
        )
        return None
    action = "OPEN" if position.positionAmt < min_position_size else "AUGMENT"
    conviction = (
        ctx.get("conviction_long", 25.0)
        if is_long
        else ctx.get("conviction_short", 25.0)
    )
    conviction = float(conviction) * (0.8 + 0.1 * wt_aligned_count)
    reasons = ctx.get(
        "conviction_long_reasons" if is_long else "conviction_short_reasons", []
    )
    reason = f"RANKING_MOMENTUM_{action}_WT{wt_aligned_count}/3_rank{rank} ({event_type}) ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')} | {reasons}"
    logger.info(
        f"[RANKING_MOMENTUM] {position_key}: {action} conviction={conviction:.1f} wt_aligned={wt_aligned_count}/3 rank={rank}"
    )
    return Signal(action=action, reason=reason, conviction=conviction)


