def _apply_sentiment_boost(reasons, sentiment_boost_factor):
    """Apply sentiment boost to reasons list"""
    if isinstance(reasons, list):
        reasons = reasons.copy()
    else:
        reasons = [str(reasons)]
    if sentiment_boost_factor > 1.0:
        reasons.append(f"SENTIMENT_BOOST_{sentiment_boost_factor:.1f}x")
    return reasons


@timed_function("evaluate_technical_indicator_signals")
async def evaluate_technical_indicator_signals(ctx: dict) -> Optional[Signal]:
    trade_manager = ctx.get("trade_manager")
    if not trade_manager:
        return None
    position_key = ctx["position_key"]
    position = trade_manager.positions.get(position_key)
    if not position:
        return None
    i = (
        ctx.get("indicators")
        if isinstance(ctx.get("indicators"), dict)
        else await ii(ctx["trade_manager"], ctx["symbol"])
    )
    if not _check_timestamp_3m_freshness(i, max_age_minutes=8.0):
        return None
    is_long = ctx.get("position_side") == "LONG"
    current_price = ctx.get("current_price", 0.0)
    if not current_price or current_price <= 0:
        current_price = await price(ctx["symbol"], position)
    if not current_price or current_price <= 0:
        return None
    # RZ_BREAKOUT early path: bb_pct_b_1h in band just outside extreme zone → entry without alignment gates.
    # Band: LONG fires when bb_pctb in [rz_bot, rz_bot+band] (just exited oversold zone).
    # SHORT fires when bb_pctb in [rz_top-band, rz_top]. Defaults False — enable via config.py once sweep validates.
    if getattr(trade_manager.config, "RZ_BREAKOUT_ENTRY_ENABLED", False):
        _rz_bb = float(i.get("bb_pct_b_1h", 0.5) or 0.5)
        _rz_top = float(getattr(trade_manager.config, "RZ_TOP_BB_THRESHOLD", 0.85))
        _rz_bot = float(getattr(trade_manager.config, "RZ_BOT_BB_THRESHOLD", 0.15))
        _rz_band = float(getattr(trade_manager.config, "RZ_BREAKOUT_BAND", 0.05))
        _rz_break_fire = (is_long and _rz_bot <= _rz_bb <= _rz_bot + _rz_band) or (
            not is_long and _rz_top - _rz_band <= _rz_bb <= _rz_top
        )
        if _rz_break_fire:
            _rz_sym = ctx.get("symbol")
            _rz_min_qty = (
                float((trade_manager.min_qty or {}).get(_rz_sym, 0.0))
                if hasattr(trade_manager, "min_qty")
                and isinstance(getattr(trade_manager, "min_qty", None), dict)
                else 0.0
            )
            _rz_pos_amt = float(getattr(position, "positionAmt", 0.0) or 0.0)
            _rz_action = _decide_action(_rz_pos_amt, _rz_min_qty)
            logger.info(
                f"[RZ_BREAKOUT] {ctx['position_key']}: bb_pctb_1h={_rz_bb:.2f} action={_rz_action}"
            )
            return Signal(
                action=_rz_action,
                reason=f"RZ_BREAKOUT_{'L' if is_long else 'S'}_bb={_rz_bb:.2f}",
                conviction=70.0,
            )
    # ═══════════════════════════════════════════════════════════════════════════
    # 🚩 GR_HTF_DIRECT_ENTRY — 2026-05-12 USER MANDATE (crypto)
    # Direct entry signal: Score = n_tfs_aligned × GOLDEN_RULE_MIN_IND.
    # Fires BEFORE alignment gates — independent of existing WT/DC/trading-policy path.
    # If score >= GR_HTF_DIRECT_ENTRY_SCORE_MIN and position is flat → OPEN.
    # If score >= GR_HTF_DIRECT_ENTRY_DOUBLE_SCORE → double size (2×START_POSITION_SIZE).
    # Reason: GR_HTF_DIRECT_ENTRY_{score}_{detail}
    # ROLLBACK: set GR_HTF_DIRECT_ENTRY_ENABLED=False in config.py.
    # ═══════════════════════════════════════════════════════════════════════════
    _tm_cfg_grde = getattr(trade_manager, "config", config)
    if bool(getattr(_tm_cfg_grde, "GR_HTF_DIRECT_ENTRY_ENABLED", True)):
        try:
            from golden_rule_htf import score_entry_htf as _gr_htf_de_fn

            _grde_min_ind = int(getattr(_tm_cfg_grde, "GOLDEN_RULE_MIN_IND", 1))
            _grde_min_tfs = int(getattr(_tm_cfg_grde, "GOLDEN_RULE_HTF_MIN_TFS", 1))
            _grde_pass, _grde_n_tfs, _grde_detail = _gr_htf_de_fn(
                i,
                is_long,
                "crypto",
                min_tfs=_grde_min_tfs,
                min_ind=_grde_min_ind,
                current_price=current_price,
            )
            _grde_score = float(_grde_n_tfs) * float(_grde_min_ind)
            _grde_score_min = float(
                getattr(_tm_cfg_grde, "GR_HTF_DIRECT_ENTRY_SCORE_MIN", 12.0)
            )
            _grde_double = float(
                getattr(_tm_cfg_grde, "GR_HTF_DIRECT_ENTRY_DOUBLE_SCORE", 18.0)
            )
            if _grde_score >= _grde_score_min:
                _grde_sps = float(getattr(_tm_cfg_grde, "START_POSITION_SIZE", 200))
                _grde_mult = 2.0 if _grde_score >= _grde_double else 1.0
                _grde_pos_amt = float(getattr(position, "positionAmt", 0.0) or 0.0)
                _grde_min_qty = (
                    float((trade_manager.min_qty or {}).get(symbol, 0.0))
                    if hasattr(trade_manager, "min_qty")
                    and isinstance(getattr(trade_manager, "min_qty", None), dict)
                    else 0.0
                )
                _grde_action = _decide_action(_grde_pos_amt, _grde_min_qty)
                _grde_reason = (
                    f"GR_HTF_DIRECT_ENTRY_{_grde_score:.0f}_{_grde_detail[:60]}"
                )
                logger.warning(
                    f"[GR_HTF_DIRECT_ENTRY] {position_key}: score={_grde_score:.0f} (tfs={_grde_n_tfs}×ind={_grde_min_ind}) >= {_grde_score_min:.0f} mult={_grde_mult:.0f}x action={_grde_action}"
                )
                return Signal(
                    action=_grde_action, reason=_grde_reason, conviction=_grde_score
                )
        except Exception as _grde_err:
            logger.warning(f"[GR_HTF_DIRECT_ENTRY_ERR] {position_key}: {_grde_err}")
    # ═══ END GR_HTF_DIRECT_ENTRY ═══
    k_1m = float(i.get("stoch_k_1m", 50))
    d_1m = float(i.get("stoch_d_1m", 50))
    k_3m = float(i.get("stoch_k_3m", 50))
    d_3m = float(i.get("stoch_d_3m", 50))
    k_15m = float(i.get("stoch_k_15m", 50))
    d_15m = float(i.get("stoch_d_15m", 50))
    k_1h = float(i.get("stoch_k_1h", 50))
    d_1h = float(i.get("stoch_d_1h", 50))
    k_4h = float(i.get("stoch_k_4h", 50))
    d_4h = float(i.get("stoch_d_4h", 50))
    k_D = float(i.get("stoch_k_D", 50))
    d_D = float(i.get("stoch_d_D", 50))
    ha_D = i.get("ha_D", "neutral")
    _tp_aligned, _tp_align_reason = trading_policy.check_entry_alignment(i, is_long)
    if not _tp_aligned:
        return None
    _tp_htf_ok, _tp_htf_reason = trading_policy.check_htf_trend_aligned(
        i, current_price, is_long
    )
    if not _tp_htf_ok:
        return None
    _tp_trigger_ok, _tp_trigger_reason = trading_policy.check_entry_trigger(i, is_long)
    if not _tp_trigger_ok:
        logger.debug(f"[ENTRY_TRIGGER_BLOCK] {position_key}: {_tp_trigger_reason}")
        return None

    signal_data = ctx.get("signal_data") or {}
    detected: List[str] = []

    event_hint = signal_data.get("event_type")
    if isinstance(event_hint, str) and event_hint:
        detected.append(event_hint)
    for key in (
        "stoch_crossover_3m",
        "stoch_crossover_15m",
        "wt_crossover_15m",
        "dc_basis_crossover_15m",
    ):
        if signal_data.get(key):
            detected.append(key)
    if not detected:
        for key in (
            "stoch_crossover_3m",
            "stoch_crossover_15m",
            "wt_crossover_15m",
            "dc_basis_crossover_15m",
        ):
            if i.get(key):
                detected.append(key)
        ha_val = i.get("ha_15m")
        if ha_val == ("green" if is_long else "red"):
            detected.append(f"ha_{ha_val}_15m")
    if not detected:
        return None

    def _supportive(sig: str) -> bool:
        if is_long:
            return any(term in sig for term in ("crossover", "BUY", "ha_green"))
        return any(term in sig for term in ("crossunder", "SELL", "ha_red"))

    positives = [sig for sig in detected if _supportive(sig)]
    if not positives:
        return None
    min_qty = 0.0
    symbol = ctx.get("symbol")
    if hasattr(trade_manager, "min_qty") and isinstance(trade_manager.min_qty, dict):
        min_qty = safe_fetch_float(trade_manager.min_qty.get(symbol), 0.0)
    positionAmt = safe_fetch_float(getattr(position, "positionAmt", 0.0), 0.0)
    action = _decide_action(positionAmt, min_qty)
    conviction_key = "conviction_long" if is_long else "conviction_short"
    conviction = safe_fetch_float(ctx.get(conviction_key), 25.0)
    reasons_key = "conviction_long_reasons" if is_long else "conviction_short_reasons"
    reasons = ctx.get(reasons_key) or []
    reason_parts = [f"TECH_SIGNAL_{positives[0]}"]
    if reasons:
        reason_parts.append(", ".join(str(r) for r in reasons if r))
    # 2026-04-27 — additive entry-engine boost (default OFF; user controls activation).
    # Engines NEVER block existing entries — only ADD score. Wrapped to never raise.
    _tm_cfg = getattr(trade_manager, "config", None)
    if _tm_cfg is not None and getattr(_tm_cfg, "LIVE_ENTRY_ENGINE_ENABLED", False):
        _ee_score_max = 0.0
        _ee_reasons = []
        _ee_side = "LONG" if is_long else "SHORT"
        for _ee_name, _ee_fn, _ee_flag in (
            ("wt", _ee_should_fire_wt_entry, "LIVE_ENTRY_ENGINE_WT_ENABLED"),
            ("stoch", _ee_should_fire_stoch_entry, "LIVE_ENTRY_ENGINE_STOCH_ENABLED"),
            ("dc", _ee_should_fire_dc_entry, "LIVE_ENTRY_ENGINE_DC_ENABLED"),
            ("htf", _ee_should_fire_htf_entry, "LIVE_ENTRY_ENGINE_HTF_ENABLED"),
            ("stdev_macro", _ee_should_fire_stdev_macro_entry, "LIVE_ENTRY_ENGINE_STDEV_MACRO_ENABLED"),
        ):
            if not getattr(_tm_cfg, _ee_flag, False):
                continue
            if _ee_fn is None:
                continue
            try:
                _fire, _why, _sc = _ee_fn(symbol, i, _ee_side)
                if _fire and _sc >= float(
                    getattr(_tm_cfg, "LIVE_ENTRY_ENGINE_MIN_SCORE", 0.6)
                ):
                    _ee_score_max = max(_ee_score_max, _sc)
                    _ee_reasons.append(f"{_ee_name}={_sc:.2f}")
            except Exception:
                pass  # never let engine error block entry
        if _ee_score_max > 0:
            _ee_boost = float(getattr(_tm_cfg, "LIVE_ENTRY_ENGINE_BOOST_SCORE", 8.0))
            conviction = conviction + (_ee_boost * _ee_score_max)
            reason_parts.append(f"+ENGINES({','.join(_ee_reasons)})")
    reason = " | ".join(part for part in reason_parts if part)
    _pts_result = await _process_technical_signals(
        ctx,
        event_hint or "process_position",
        is_long,
        "15m",
        k_15m,
        d_15m,
        current_price,
        trade_manager.config.MIN_POSITION_SIZE / current_price,
        True,
        1.0,
    )
    if (
        _pts_result
        and hasattr(_pts_result, "action")
        and _pts_result.action != "NO_ACTION"
    ):
        return _pts_result
    return Signal(action=action, reason=reason, conviction=conviction)


