async def monitor_stale_augmentations(
    trade_manager: MultiAccountTradeManager,
    order_queue: OrderQueue,
    threshold: float = None,
):
    await asyncio.sleep(25)
    config = getattr(trade_manager, "config", None)
    stale_threshold = threshold or float(
        getattr(config, "AUGMENTATION_STALE_THRESHOLD", 300.0)
    )
    while True:
        try:
            now_ts = time.time()
            stale_entries = []
            positions_by_account = (
                getattr(trade_manager, "positions_by_account", {})
                if isinstance(getattr(trade_manager, "positions_by_account", {}), dict)
                else {}
            )
            allowed_accounts = (
                set(getattr(config, "ACCOUNT_KEYS", [])) if config else set()
            )
            managed_accounts = allowed_accounts.intersection(
                set(trade_manager.accounts.keys())
                if hasattr(trade_manager, "accounts")
                else set()
            )
            managed_accounts = {
                acc for acc in managed_accounts if acc not in ["fin", "men"]
            }
            tradeable_keys = await trade_manager.load_tradeable()
            for account_key, positions_dict in positions_by_account.items():
                if account_key not in managed_accounts:
                    continue
                if not positions_dict:
                    continue
                for position_key, position in positions_dict.items():
                    if not position:
                        continue
                    if position_key in trade_manager.processing_keys:
                        continue
                    try:
                        positionAmt = abs(float(getattr(position, "positionAmt", 0.0)))
                    except (TypeError, ValueError):
                        positionAmt = 0.0
                    if positionAmt <= 0.0:
                        trade_manager.position_last_processed.pop(position_key, None)
                        continue
                    if position_key not in tradeable_keys:
                        continue
                    last_ts = trade_manager.position_last_processed.get(
                        position_key, 0.0
                    )
                    if last_ts <= 0.0:
                        trade_manager.position_last_processed[position_key] = now_ts
                        continue
                    elapsed = now_ts - last_ts
                    if elapsed >= stale_threshold:
                        trade_manager.position_last_processed[position_key] = now_ts
                        stale_entries.append((account_key, position_key))
            if stale_entries:
                logger.warning(
                    f"[AUGMENT_MONITOR] Dispatching {len(stale_entries)} stale positions (> {stale_threshold:.0f}s)"
                )
                tasks = [
                    asyncio.create_task(
                        process_position(
                            account_key,
                            position_key,
                            order_queue,
                            trade_manager,
                            event_type="stale_monitor",
                            force=True,
                        )
                    )
                    for account_key, position_key in stale_entries
                ]
                results = await asyncio.gather(*tasks, return_exceptions=True)
                for idx, result in enumerate(results):
                    if isinstance(result, Exception):
                        account_key, position_key = stale_entries[idx]
                        logger.error(
                            f"[AUGMENT_MONITOR] Task failed for {position_key} ({account_key}): {result}"
                        )
                        logger.debug(traceback.format_exc())
                reentry_data_dict = (
                    trade_manager.service.reentry_data
                    if trade_manager.service
                    else getattr(trade_manager, "reentry_data", {})
                )
                if (
                    reentry_data_dict
                    and isinstance(reentry_data_dict, dict)
                    and bool(getattr(config, "EZ_REENTRY_INLINE_ENABLED", True))
                    and bool(
                        getattr(config, "EZ_REENTRY_INLINE_EVAL2_DIRECT_ENABLED", True)
                    )
                ):
                    filtered_keys = _filter_position_keys(
                        trade_manager, list(reentry_data_dict.keys())
                    )
                    if filtered_keys:
                        filtered_reentry_data = {
                            position_key: reentry_data_dict[position_key]
                            for position_key in filtered_keys
                            if position_key in reentry_data_dict
                        }
                        original_reentry_data = trade_manager.reentry_data
                        try:
                            trade_manager.reentry_data = filtered_reentry_data
                            await evaluate_reentry_2(trade_manager)
                        finally:
                            trade_manager.reentry_data = original_reentry_data
            await asyncio.sleep(15)
        except asyncio.CancelledError:
            break
        except Exception as exc:
            logger.error(f"[AUGMENT_MONITOR] Error: {exc}")
            logger.debug(traceback.format_exc())
            await asyncio.sleep(20)


