@timed_function("process_position")
async def process_position(
    account_key: Optional[str] = None,
    position_key: Optional[str] = None,
    order_queue: OrderQueue = None,
    trade_manager: MultiAccountTradeManager = None,
    event_type=None,
    signal_data=None,
    queue_len=None,
    force: bool = False,
):
    # 2026-05-08 USER MANDATE: filter NON_TRADEABLE + ALREADY_AUGMENTED at the FIRST LINE
    # so we don't waste 12s of compute on positions that will be rejected at the end anyway.
    # Cheap O(1) checks before anything else.
    if not position_key or not trade_manager:
        return
    try:
        if (
            hasattr(trade_manager, "tradeable_keys")
            and trade_manager.tradeable_keys
            and position_key not in trade_manager.tradeable_keys
        ):
            return
        _pp_pos = (
            trade_manager.positions.get(position_key)
            if hasattr(trade_manager, "positions")
            else None
        )
        if _pp_pos is not None:
            _pp_amt = abs(safe_fetch_float(getattr(_pp_pos, "positionAmt", 0), 0))
            if _pp_amt > 0:
                _pp_gain = safe_fetch_float(getattr(_pp_pos, "gain", 0), 0)
                _pp_min_gain = float(
                    getattr(
                        getattr(trade_manager, "config", None) or config,
                        "MIN_GAIN",
                        3.0,
                    )
                )
                if _pp_gain < 0.5 * _pp_min_gain and (event_type or "").startswith(
                    ("queue_processor", "process_position", "reentry")
                ):
                    return
    except Exception:
        pass
    logger.debug(f"[[PP] 🚨 {position_key}] entering")
    current_account.set(account_key)
    config = getattr(trade_manager, "config", None)
    allowed_accounts = set(getattr(config, "ACCOUNT_KEYS", [])) if config else set()
    trade_manager_accounts = (
        set(trade_manager.accounts.keys())
        if hasattr(trade_manager, "accounts") and trade_manager.accounts
        else set()
    )
    managed_accounts = (
        allowed_accounts.intersection(trade_manager_accounts)
        if allowed_accounts
        else trade_manager_accounts
    )
    tradeable_keys = await trade_manager.load_tradeable()
    if position_key not in tradeable_keys:
        return
    if (
        account_key not in managed_accounts
        and account_key not in trade_manager_accounts
    ):
        logger.debug(
            f"[process_position] SKIPPING: account '{account_key}' not in managed accounts {list(managed_accounts)} for {position_key}"
        )
        return
    try:
        await symbol_tracker.track_stage(
            position_key, "PROCESS_POSITION_ENTERED", f"event={event_type}"
        )
    except Exception as e:
        logger.warning(f"[{position_key}] Error tracking stage: {e}")
    overall_t0 = time.perf_counter()
    now_ts = time.time()
    last_queued_ts = trade_manager.recently_queued_signals.get(position_key)
    if last_queued_ts and not force and (now_ts - last_queued_ts) < 2.0:
        try:
            await symbol_tracker.track_completion(
                position_key, f"NO_ACTION:COOLDOWN_ACTIVE"
            )
        except Exception as e:
            logger.warning(f"[{position_key}] Error tracking completion: {e}")
        return f"{EvalStatus.NO_ACTION}:COOLDOWN_ACTIVE"
    if position_key in trade_manager.processing_keys:
        try:
            await symbol_tracker.track_completion(
                position_key, f"NO_ACTION:ALREADY_PROCESSING"
            )
        except Exception as e:
            logger.warning(f"[{position_key}] Error tracking completion: {e}")
        return f"{EvalStatus.NO_ACTION}:ALREADY_PROCESSING"
    trade_manager.processing_keys.add(position_key)
    process_position_enter_count[position_key] = (
        process_position_enter_count.get(position_key, 0) + 1
    )
    count = process_position_enter_count[position_key]
    if count % 10 == 1:
        logger.info(f"[PPPPProcess_position] {position_key} count={count}")
    ready_event = getattr(trade_manager, "positions_ready_event", None)
    if isinstance(ready_event, asyncio.Event) and not ready_event.is_set():
        try:
            await asyncio.wait_for(ready_event.wait(), timeout=3.0)
        except asyncio.TimeoutError:
            logger.debug(
                f"[{position_key}] positions_ready_event timed out; continuing with file fallback"
            )
    now = datetime.now(timezone.utc)
    ak, symbol, position_side = parse_position_key(position_key)
    if not account_key or account_key != ak:
        account_key = ak
    # BACKTEST_CHANGE_46: skip blacklisted symbols (negative Sharpe in matrix)
    _blacklist = getattr(config, "BLACKLIST_SYMBOLS", []) if config else []
    if symbol in _blacklist:
        trade_manager.processing_keys.discard(position_key)
        return f"{EvalStatus.NO_ACTION}:BLACKLISTED_{symbol}"
    position = await trade_manager.get_position(position_key)
    # USER 2026-05-18: shared ii() cache for this process_position cycle.
    # Was 4× Redis stampede (lines below: WZG / R3 / R3_HTF_FLIP / GR_HTF_DIRECT_EXIT
    # each called `await ii(trade_manager, symbol)` independently). With 50+ positions ×
    # 4 calls per cycle = 200+ Redis hits per evaluation cycle — proven cause of GR
    # backtest engine timeouts at 90 min in v4/v5/v6 sweeps. Lazy-init: only fetches on
    # first GR gate that fires, reuses for all subsequent gates in the same cycle.
    _pp_shared_ind: Optional[dict] = None
    # 🤖 AGENT advisory short-circuit (supervisor override, all 5 crypto accounts)
    # Hook fires after position fetch so we have all needed context. inf runs SCALP_V3 too —
    # this hook runs first; a force_close advisory wins over a SCALP_V3 hold.
    if account_key in ("fin", "ang", "inf", "flz", "men"):
        try:
            import fin_advisory_consumer as _ag_adv

            _ag_obj = _ag_adv.check(account_key, symbol, position_side, "process")
            if _ag_obj:
                _ag_tag = account_key.upper()
                _ag_action = _ag_obj.get("action")
                _ag_reason = (_ag_obj.get("reason") or "")[:60]
                _ag_pos_amt = (
                    abs(safe_float(getattr(position, "positionAmt", 0)))
                    if position
                    else 0.0
                )
                if _ag_action == "force_close" and _ag_pos_amt > 0:
                    _ag_gain = (
                        safe_float(getattr(position, "gain", 0)) if position else 0.0
                    )
                    if _ag_gain < 0:
                        logger.warning(
                            f"🚫 {_ag_tag}_AGENT_FORCE_CLOSE_DENIED_LOSS {position_key}: gain={_ag_gain:.2f}% — never close at loss; downgrading to hedge"
                        )
                        _ag_action = "force_hedge"
                    else:
                        _ag_side = "SELL" if position_side == "LONG" else "BUY"
                        _ag_adv.log_application(
                            account_key,
                            symbol,
                            position_side,
                            "process",
                            "force_close",
                            _ag_obj,
                        )
                        logger.info(
                            f"🤖 {_ag_tag}_AGENT_FORCE_CLOSE {position_key} (profit gain={_ag_gain:.2f}%): {_ag_reason}"
                        )
                        await trade_manager.execute_now(
                            position_key=position_key,
                            account_key=account_key,
                            symbol=symbol,
                            original_positionAmt=_ag_pos_amt,
                            side=_ag_side,
                            position_side=position_side,
                            quantity=_ag_pos_amt,
                            reason=f"{_ag_tag}_AGENT_FORCE_CLOSE({_ag_reason})",
                            is_full_close=True,
                            action="CLOSE",
                        )
                        trade_manager.processing_keys.discard(position_key)
                        return f"{EvalStatus.ACTION_TAKEN}:{_ag_tag}_AGENT_FORCE_CLOSE"
                if _ag_action == "force_hedge" and _ag_pos_amt > 0:
                    _ag_adv.log_application(
                        account_key,
                        symbol,
                        position_side,
                        "process",
                        "force_hedge",
                        _ag_obj,
                    )
                    _he = getattr(trade_manager, "hedge_engine", None)
                    if _he is None:
                        logger.error(
                            f"🤖 {_ag_tag}_AGENT_FORCE_HEDGE_NO_ENGINE {position_key}: no hedge_engine — falling through to scripted"
                        )
                    else:
                        _ag_mark = (
                            safe_float(getattr(position, "mark_price", 0))
                            if position
                            else 0.0
                        )
                        if _ag_mark <= 0:
                            _ag_mark, _ = await get_current_price(symbol)
                            _ag_mark = float(_ag_mark) if _ag_mark else 0.0
                        logger.warning(
                            f"🤖 {_ag_tag}_AGENT_FORCE_HEDGE {position_key} qty={_ag_pos_amt} mark={_ag_mark}: {_ag_reason}"
                        )
                        try:
                            _ag_h_result = await _he.execute_same_symbol_hedge(
                                account_key,
                                position,
                                symbol,
                                position_side,
                                _ag_pos_amt,
                                _ag_mark,
                            )
                        except Exception as _ag_h_e:
                            logger.error(
                                f"🤖 {_ag_tag}_AGENT_FORCE_HEDGE_ERR {position_key}: {type(_ag_h_e).__name__}: {_ag_h_e}"
                            )
                            _ag_h_result = False
                        trade_manager.processing_keys.discard(position_key)
                        if _ag_h_result:
                            return (
                                f"{EvalStatus.ACTION_TAKEN}:{_ag_tag}_AGENT_FORCE_HEDGE"
                            )
                        return (
                            f"{EvalStatus.NO_ACTION}:{_ag_tag}_AGENT_FORCE_HEDGE_FAILED"
                        )
                if _ag_action == "hold" and _ag_pos_amt > 0:
                    _ag_adv.log_application(
                        account_key, symbol, position_side, "process", "hold", _ag_obj
                    )
                    logger.info(f"🤖 {_ag_tag}_AGENT_HOLD {position_key}: {_ag_reason}")
                    trade_manager.processing_keys.discard(position_key)
                    return f"{EvalStatus.NO_ACTION}:{_ag_tag}_AGENT_HOLD"
                if _ag_action == "force_open" and _ag_pos_amt == 0:
                    _ag_size_usd = float(_ag_obj.get("size_override_usd") or 0)
                    _ag_price, _ = await get_current_price(symbol)
                    _ag_price = float(_ag_price) if _ag_price else 0.0
                    if _ag_size_usd > 0 and _ag_price > 0:
                        _ag_qty = max(_ag_size_usd / _ag_price, 0.0)
                        _ag_side = "BUY" if position_side == "LONG" else "SELL"
                        _ag_adv.log_application(
                            account_key,
                            symbol,
                            position_side,
                            "process",
                            "force_open",
                            _ag_obj,
                        )
                        logger.info(
                            f"🤖 {_ag_tag}_AGENT_FORCE_OPEN {position_key} size=${_ag_size_usd:.0f} qty={_ag_qty:.4f}: {_ag_reason}"
                        )
                        await trade_manager.execute_now(
                            position_key=position_key,
                            account_key=account_key,
                            symbol=symbol,
                            original_positionAmt=0,
                            side=_ag_side,
                            position_side=position_side,
                            quantity=_ag_qty,
                            reason=f"{_ag_tag}_AGENT_FORCE_OPEN({_ag_reason})",
                            action="OPEN",
                        )
                        trade_manager.processing_keys.discard(position_key)
                        return f"{EvalStatus.ACTION_TAKEN}:{_ag_tag}_AGENT_FORCE_OPEN"
                if _ag_action == "block_entry" and _ag_pos_amt == 0:
                    _ag_adv.log_application(
                        account_key,
                        symbol,
                        position_side,
                        "process",
                        "block_entry",
                        _ag_obj,
                    )
                    logger.info(
                        f"🤖 {_ag_tag}_AGENT_BLOCK_ENTRY {position_key}: {_ag_reason}"
                    )
                    trade_manager.processing_keys.discard(position_key)
                    return f"{EvalStatus.NO_ACTION}:{_ag_tag}_AGENT_BLOCK_ENTRY"
        except Exception as _ag_err:
            logger.warning(
                f"[AGENT] advisory check failed for {position_key}: {_ag_err}"
            )
    if position and abs(safe_float(getattr(position, "positionAmt", 0))) == 0:
        trade_manager.processing_keys.discard(position_key)
        return f"{EvalStatus.NO_ACTION}:ZERO_AMT"
    current_price, price_ts = await price(symbol, position, withts=True)
    if not current_price or current_price <= 0:
        current_price, price_ts = await get_current_price(symbol)
    if not current_price or current_price <= 0:
        try:
            from utils import get_current_price as utils_get_price

            current_price, price_ts = await utils_get_price(symbol)
        except Exception:
            pass
    if not current_price or current_price <= 0:
        current_price = (
            safe_fetch_float(getattr(position, "mark_price", 0.0), 0.0)
            if position
            else 0.0
        )
        price_ts = (
            getattr(position, "mark_price_last_updated", None) if position else None
        )
    if not current_price or current_price <= 0:
        logger.error(
            f"[process_position_enter] {position_key}: CRITICAL - no valid current_price after all attempts"
        )
        return f"{EvalStatus.NO_ACTION}:NO_PRICE"
    # ═══════════════════════════════════════════════════════════════════════════
    # R1 — DC_LOW4_3M EMERGENCY CLOSE (USER 2026-05-09).
    # Fixed stop price set at open/augment time (dc_low4_3m LONG / dc_high4_3m SHORT).
    # No time window — fires whenever current_price breaches the recorded stop level.
    # Bypasses NO_LOSS / hedge / MTF. Desktop alert + JSONL log naming the entry signal.
    # ═══════════════════════════════════════════════════════════════════════════
    # 2026-05-18 per-sym overlay
    if (
        position
        and abs(safe_float(getattr(position, "positionAmt", 0))) > 0
        and bool(_psym_get(symbol, position_side, "R1_DC_LOW4_3M_EMERGENCY_ENABLED", True))
    ):
        try:
            _r1_stop = float(getattr(position, "r1_stop_price", 0.0) or 0.0)
            # 2026-05-18 BUG FIX (USER AUTHORIZED): r1_stop_price only set at 3 of 11
            # open sites — QUICK_OPEN_STRONG / QUICK_HEDGE_PROTECT / GOLDEN_RULE /
            # DAEMON_PRICE_CROSS_REENTRY / GUARANTEED_REENTRY / QUICK_SCALP_V3 skipped it.
            # Lazy-set fallback mirrors tradier_manage.py:1892-1898 so R1 fires for every
            # open position by reading live dc_low4_3m / dc_high4_3m.
            if _r1_stop <= 0:
                _r1_live_key = "dc_low4_3m" if (position_side == "LONG") else "dc_high4_3m"
                if _pp_shared_ind is None:
                    _pp_shared_ind = await ii(trade_manager, symbol) or {}
                _r1_stop_live = safe_fetch_float(_pp_shared_ind.get(_r1_live_key), 0.0)
                if _r1_stop_live > 0:
                    _r1_stop = _r1_stop_live
                    position.r1_stop_price = _r1_stop_live
                    logger.info(f"[R1_STOP_LAZY_SET] {position_key}: r1_stop_price not set — initialised from live {_r1_live_key}={_r1_stop_live:.6f}")
            _r1_age_min = 0.0
            _r1_opened = getattr(position, "opened_at", None)
            if isinstance(_r1_opened, datetime):
                _r1_age_min = (
                    datetime.now(timezone.utc) - _r1_opened
                ).total_seconds() / 60.0
            if _r1_stop > 0:
                _r1_is_long = position_side == "LONG"
                _r1_breached = (_r1_is_long and current_price <= _r1_stop) or (
                    (not _r1_is_long) and current_price >= _r1_stop
                )
                if _r1_breached:
                    _r1_amt = abs(safe_float(getattr(position, "positionAmt", 0)))
                    _r1_close_side = "SELL" if _r1_is_long else "BUY"
                    _r1_gain = safe_fetch_float(getattr(position, "gain", 0), 0)
                    _r1_entry_sig = (
                        getattr(position, "last_signal", "")
                        or getattr(position, "open_reason", "")
                        or "?"
                    )
                    _r1_entry_ts = str(getattr(position, "opened_at", ""))[:19]
                    logger.error(
                        f"⛔ [R1_DC_LOW4_3M_EMERGENCY] {position_key}: g={_r1_gain:.2f}% age={_r1_age_min:.1f}m price={current_price:.6f} {'<=' if _r1_is_long else '>='} r1_stop={_r1_stop:.6f} entry={_r1_entry_sig[:40]} → CLOSE"
                    )
                    # 2026-05-10 USER MANDATE: action-first. Try CLOSE; alert ONLY if it
                    # fails for an unexplained reason. Min-notional / qty=0 / blacklist /
                    # already-closed are valid silent failures.
                    _r1_failed = False
                    _r1_err_str = None
                    try:
                        _r1_result = await trade_manager.execute_now(
                            position_key=position_key,
                            account_key=account_key,
                            symbol=symbol,
                            original_positionAmt=_r1_amt,
                            side=_r1_close_side,
                            position_side=position_side,
                            quantity=_r1_amt,
                            old_price=current_price,
                            unique_id=f"R1_DC_LOW4_3M_{int(time.time())}",
                            reason=f"R1_DC_LOW4_3M_EMERGENCY_g{_r1_gain:.2f}_age{_r1_age_min:.1f}m_entry_{str(_r1_entry_sig)[:30]}",
                            is_full_close=True,
                            action="CLOSE",
                        )
                        if isinstance(_r1_result, str) and (
                            "BLOCK" in _r1_result.upper()
                            or "SKIP" in _r1_result.upper()
                            or "REJECT" in _r1_result.upper()
                        ):
                            _r1_failed = True
                            _r1_err_str = _r1_result
                    except Exception as _r1_err:
                        _r1_failed = True
                        _r1_err_str = repr(_r1_err)
                    if not _r1_failed:
                        trade_manager.processing_keys.discard(position_key)
                        return (
                            f"{EvalStatus.ACTION_TAKEN}:R1_DC_LOW4_3M_EMERGENCY_CLOSED"
                        )
                    try:
                        import ez_alert

                        _r1_should = ez_alert.should_alert_for_failure(_r1_err_str)
                    except Exception:
                        _r1_should = True
                    if _r1_should:
                        logger.critical(
                            f"☢️ [R1_CLOSE_AGENT_BUG] {position_key}: close failed with no valid reason: {_r1_err_str}"
                        )
                        try:
                            import ez_alert

                            ez_alert.alert_bad_exit(
                                account=account_key,
                                position_key=position_key,
                                gain=_r1_gain,
                                reason=f"R1_CLOSE_DID_NOT_EXECUTE_NO_VALID_REASON_err={str(_r1_err_str)[:80]}",
                                entry_signal=str(_r1_entry_sig),
                                entry_ts=_r1_entry_ts,
                                current_price=current_price,
                            )
                        except Exception:
                            pass
                    else:
                        logger.warning(
                            f"[R1_CLOSE_VALID_SKIP] {position_key}: close suppressed for valid reason: {_r1_err_str}"
                        )
        except Exception as _r1_outer:
            logger.debug(f"[R1_DC_LOW4_3M] {position_key} probe err: {_r1_outer}")
    # ═══════════════════════════════════════════════════════════════════════════
    # R1b — DAEMON_REENTRY_STALE EXIT (2026-05-15 USER).
    # When a DAEMON_PRICE_CROSS_REENTRY position's premise fails — price crosses
    # back ABOVE exit_price for SHORT (or BELOW for LONG) — close immediately.
    # The exit_price is parsed from the position's augment_reason string.
    # Bypasses NOLOSS gate via DAEMON_REENTRY_STALE_EXIT bypass reason.
    # ═══════════════════════════════════════════════════════════════════════════
    if (
        position
        and abs(safe_float(getattr(position, "positionAmt", 0))) > 0
        and bool(getattr(config, "DAEMON_REENTRY_STALE_EXIT_ENABLED", True))
    ):
        try:
            import re as _re_r1b
            _r1b_blob = (
                str(getattr(position, "augment_reason", "") or "")
                + " "
                + str(getattr(position, "last_signal", "") or "")
            ).upper()
            if "DAEMON_PRICE_CROSS_REENTRY" in _r1b_blob:
                _r1b_m = _re_r1b.search(r"EXIT(\d+\.\d+)", _r1b_blob)
                if _r1b_m:
                    _r1b_exit_px = float(_r1b_m.group(1))
                    _r1b_is_long = position_side == "LONG"
                    _r1b_stale = (not _r1b_is_long and current_price > _r1b_exit_px) or (
                        _r1b_is_long and current_price < _r1b_exit_px
                    )
                    if _r1b_stale:
                        _r1b_amt = abs(safe_float(getattr(position, "positionAmt", 0)))
                        _r1b_gain = safe_fetch_float(getattr(position, "gain", 0), 0)
                        _r1b_close_side = "BUY" if not _r1b_is_long else "SELL"
                        logger.error(
                            f"⛔ [R1b_DAEMON_REENTRY_STALE] {position_key}: g={_r1b_gain:.2f}% price={current_price:.6f} {'>' if not _r1b_is_long else '<'} exit_px={_r1b_exit_px:.6f} — reentry premise failed, closing"
                        )
                        _r1b_result = await trade_manager.execute_now(
                            position_key=position_key,
                            account_key=account_key,
                            symbol=symbol,
                            original_positionAmt=_r1b_amt,
                            side=_r1b_close_side,
                            position_side=position_side,
                            quantity=_r1b_amt,
                            old_price=current_price,
                            unique_id=f"R1b_DAEMON_STALE_{int(time.time())}",
                            reason=f"DAEMON_REENTRY_STALE_EXIT_g{_r1b_gain:.2f}_exit_px_{_r1b_exit_px:.6f}_cur_{current_price:.6f}",
                            is_full_close=True,
                            action="CLOSE",
                        )
                        if isinstance(_r1b_result, str) and not any(
                            x in _r1b_result.upper() for x in ("BLOCK", "SKIP", "REJECT")
                        ):
                            trade_manager.processing_keys.discard(position_key)
                            return f"{EvalStatus.ACTION_TAKEN}:R1b_DAEMON_REENTRY_STALE_CLOSED"
        except Exception as _r1b_outer:
            logger.debug(f"[R1b_DAEMON_REENTRY_STALE] {position_key} probe err: {_r1b_outer}")
    # ═══════════════════════════════════════════════════════════════════════════
    # R1c — FROZEN_ACT_STOP (USER 2026-05-18) — replaces RIDICULOUS_LOSS late-fire.
    # At first per-bar check after open, freeze the activation-TF dc level on the
    # position. Subsequent bars: if price crosses frozen level AND in loss → CLOSE.
    # Plus an absolute floor (-10% crypto / -8% stocks) caps gap-down catastrophes.
    # Bypass reasons FROZEN_ACT_STOP_* are in UNIVERSAL_NOLOSS_GATE_BYPASS_REASONS.
    # ═══════════════════════════════════════════════════════════════════════════
    if (
        position
        and abs(safe_float(getattr(position, "positionAmt", 0))) > 0
        and bool(getattr(config, "FROZEN_ACTIVATION_STOP_ENABLED", True))
    ):
        try:
            _fa_tf = str(getattr(config, "FROZEN_ACTIVATION_TF", "4h"))
            _fa_floor_pct = float(getattr(config, "FROZEN_ABSOLUTE_FLOOR_PCT_CRYPTO", -10.0))
            _fa_is_long = position_side == "LONG"
            _fa_gain = safe_fetch_float(getattr(position, "gain", 0), 0)
            # Lazy freeze: read current bar's dc level on first encounter, stash on position
            _fa_frozen = getattr(position, "_frozen_dc_act", None)
            if _fa_frozen is None:
                if _pp_shared_ind is None:
                    _pp_shared_ind = await ii(trade_manager, symbol) or {}
                _fa_ind = _pp_shared_ind if _pp_shared_ind else None
                if _fa_ind:
                    _fa_field = f"dc_low_{_fa_tf}" if _fa_is_long else f"dc_high_{_fa_tf}"
                    _fa_frozen_raw = _fa_ind.get(_fa_field)
                    if _fa_frozen_raw not in (None, 0, 0.0):
                        try:
                            _fa_frozen = float(_fa_frozen_raw)
                            setattr(position, "_frozen_dc_act", _fa_frozen)
                        except (TypeError, ValueError):
                            _fa_frozen = None
            # Stop condition 1: absolute floor (always active — catches gap-downs)
            _fa_floor_hit = _fa_gain <= _fa_floor_pct
            # Stop condition 2: frozen-level breach AND in loss
            _fa_breach = False
            if _fa_frozen is not None:
                _fa_breach = (
                    (_fa_is_long and current_price < _fa_frozen)
                    or (not _fa_is_long and current_price > _fa_frozen)
                ) and _fa_gain < 0
            if _fa_floor_hit or _fa_breach:
                _fa_amt = abs(safe_float(getattr(position, "positionAmt", 0)))
                _fa_close_side = "SELL" if _fa_is_long else "BUY"
                _fa_reason_tag = "FROZEN_ACT_STOP_ABSOLUTE_FLOOR" if _fa_floor_hit else "FROZEN_ACT_STOP_FROZEN_BREACH"
                _fa_reason = (
                    f"{_fa_reason_tag}_g{_fa_gain:.2f}%_floor{_fa_floor_pct:.1f}%"
                    if _fa_floor_hit
                    else f"{_fa_reason_tag}_g{_fa_gain:.2f}%_frozen{_fa_tf}={_fa_frozen}_cur={current_price}"
                )
                logger.critical(
                    f"⛔ [{_fa_reason_tag}] {position_key}: g={_fa_gain:.2f}% frozen_{_fa_tf}={_fa_frozen} cur={current_price:.6f} {'<' if _fa_is_long else '>'}={_fa_frozen} floor={_fa_floor_pct:.1f}% → CLOSE"
                )
                try:
                    _fa_result = await trade_manager.execute_now(
                        position_key=position_key,
                        account_key=account_key,
                        symbol=symbol,
                        original_positionAmt=_fa_amt,
                        side=_fa_close_side,
                        position_side=position_side,
                        quantity=_fa_amt,
                        old_price=current_price,
                        unique_id=f"{_fa_reason_tag}_{int(time.time())}",
                        reason=_fa_reason,
                        is_full_close=True,
                        action="CLOSE",
                    )
                    if isinstance(_fa_result, str) and not any(
                        x in _fa_result.upper() for x in ("BLOCK", "SKIP", "REJECT")
                    ):
                        trade_manager.processing_keys.discard(position_key)
                        return f"{EvalStatus.ACTION_TAKEN}:{_fa_reason_tag}_CLOSED"
                except Exception as _fa_exec_err:
                    logger.warning(f"[FROZEN_ACT_STOP_EXEC_ERR] {position_key}: {_fa_exec_err}")
        except Exception as _fa_outer:
            logger.debug(f"[FROZEN_ACT_STOP] {position_key} probe err: {_fa_outer}")
    # ═══════════════════════════════════════════════════════════════════════════
    # R2 — WT_VEL_SLOW near-breakeven exit (USER 2026-05-08, tightened 2026-05-09).
    # Trigger (per TF in R2_TF_LIST):
    #   floor <= gain < band  (default 0.01 .. 0.50 — "approaching 0 from above"), AND
    #   wt_velocity_<TF> opposes position, AND
    #   ( |vel| < |vel_prev| * WT_VEL_DECEL_RATIO  (DYNAMIC slowdown — not fixed)
    #     OR (legacy) |vel| ≤ WT_15M_VEL_NEAR_ZERO_THRESHOLD when WT_VEL_USE_DECEL_RATIO_ONLY=False )
    # Closes at current price (≥ floor → positive net of commissions).
    # Tradier mirrors with R2_TF_LIST=('1h','4h','D') per user 2026-05-09.
    # ═══════════════════════════════════════════════════════════════════════════
    if (
        position
        and abs(safe_float(getattr(position, "positionAmt", 0))) > 0
        and bool(getattr(config, "WT_15M_VEL_SLOW_AT_ZERO_GAIN_ENABLED", True))
    ):
        try:
            _wzg_gain = safe_fetch_float(getattr(position, "gain", 0), 0)
            _wzg_max_gain = safe_fetch_float(getattr(position, "max_gain", 0), 0)
            _wzg_peak_min = float(getattr(config, "R2_PEAK_MIN_PCT", 0.5))
            # 2026-05-18 per-sym overlay
            _wzg_band = float(_psym_get(symbol, position_side, "WT_15M_VEL_SLOW_GAIN_BAND_PCT", 0.10))
            _wzg_floor = float(_psym_get(symbol, position_side, "WT_15M_VEL_SLOW_GAIN_FLOOR_PCT", 0.01))
            _wzg_near_zero = float(
                _psym_get(symbol, position_side, "WT_15M_VEL_NEAR_ZERO_THRESHOLD", 0.1)
            )
            _wzg_decel_ratio = float(_psym_get(symbol, position_side, "WT_VEL_DECEL_RATIO", 0.5))
            _wzg_decel_only = bool(_psym_get(symbol, position_side, "WT_VEL_USE_DECEL_RATIO_ONLY", True))
            _wzg_tfs = tuple(_psym_get(symbol, position_side, "R2_TF_LIST", ("15m",)) or ("15m",))
            # PEAK-THEN-COLLAPSE: must have peaked ≥ R2_PEAK_MIN_PCT AND now
            # be back inside [floor, band]. From-open-tiny-profit positions
            # don't fire here — R1 (DC4 newborn window) handles those.
            if _wzg_max_gain >= _wzg_peak_min and _wzg_floor <= _wzg_gain < _wzg_band:
                if _pp_shared_ind is None:
                    _pp_shared_ind = await ii(trade_manager, symbol) or {}
                _wzg_ind = _pp_shared_ind if _pp_shared_ind else None
                if _wzg_ind:
                    _wzg_is_long = position_side == "LONG"
                    _wzg_fired_tf = None
                    _wzg_vel = 0.0
                    _wzg_vel_prev = 0.0
                    _wzg_tag = ""
                    for _wzg_tf in _wzg_tfs:
                        _v = safe_fetch_float(_wzg_ind.get(f"wt_velocity_{_wzg_tf}"), 0)
                        # 2026-05-18 BUG FIX (USER AUTHORIZED): wt_velocity_*_prev never
                        # exists in NPZ or live indicators. Derive from wt_acceleration_{tf}
                        # per the documented pattern at ez_positions_quick.py:1782-1788
                        # (accel = velocity - velocity_prev ⇒ velocity_prev = v - a).
                        # Pre-fix this fell back to _v itself → decel ratio always False → R2 dead.
                        _a = safe_fetch_float(_wzg_ind.get(f"wt_acceleration_{_wzg_tf}"), 0)
                        _vp = _v - _a
                        _against = (_wzg_is_long and _v < 0) or (
                            (not _wzg_is_long) and _v > 0
                        )
                        _decel = (
                            abs(_v) < abs(_vp) * _wzg_decel_ratio and abs(_vp) > 1e-6
                        )
                        _dying = (not _wzg_decel_only) and abs(_v) <= _wzg_near_zero
                        if _against and (_decel or _dying):
                            _wzg_fired_tf, _wzg_vel, _wzg_vel_prev = _wzg_tf, _v, _vp
                            _wzg_tag = "DECEL" if _decel else "DYING"
                            break
                    if _wzg_fired_tf:
                        _wzg_amt = abs(safe_float(getattr(position, "positionAmt", 0)))
                        _wzg_close_side = "SELL" if _wzg_is_long else "BUY"
                        logger.error(
                            f"⛔ [R2_WT_VEL_SLOW] {position_key}: peak={_wzg_max_gain:.2f}% (≥{_wzg_peak_min}%) collapsed→g={_wzg_gain:.3f}% in [{_wzg_floor},{_wzg_band}], wt_vel_{_wzg_fired_tf}={_wzg_vel:.3f} (prev={_wzg_vel_prev:.3f}) AGAINST+{_wzg_tag} ratio={_wzg_decel_ratio} → CLOSE"
                        )
                        try:
                            await trade_manager.execute_now(
                                position_key=position_key,
                                account_key=account_key,
                                symbol=symbol,
                                original_positionAmt=_wzg_amt,
                                side=_wzg_close_side,
                                position_side=position_side,
                                quantity=_wzg_amt,
                                old_price=current_price,
                                unique_id=f"R2_WT_VEL_SLOW_{int(time.time())}",
                                reason=f"R2_WT_VEL_SLOW_{_wzg_tag}_{_wzg_fired_tf}_g{_wzg_gain:.3f}%_vel{_wzg_vel:.3f}vs{_wzg_vel_prev:.3f}",
                                is_full_close=True,
                                action="CLOSE",
                            )
                            trade_manager.processing_keys.discard(position_key)
                            return f"{EvalStatus.ACTION_TAKEN}:R2_WT_VEL_SLOW_CLOSED_{_wzg_fired_tf}"
                        except Exception as _wzg_err:
                            logger.error(
                                f"⛔ [R2_WT_VEL_SLOW_ERR] {position_key}: {_wzg_err}"
                            )
        except Exception as _wzg_outer:
            logger.debug(f"[R2_WT_VEL_SLOW] {position_key} probe err: {_wzg_outer}")
    # ═══════════════════════════════════════════════════════════════════════════
    # R3 — HEDGE_INVARIANT loss-bypass dump (USER 2026-05-09).
    # If wt1_3m AND wt1_1h are AGAINST the position AND gain<0 AND no hedge
    # exists AND no hedge is pending → DUMP. Skips NO_LOSS, MTF, cooldowns.
    # Fires desktop alert so the root cause (why hedge engine didn't fire) can
    # be investigated. Hedge presence: active_hedges with hedge_for==position_key.
    # Pending: Redis 'hedge_pending:<key>' (60s TTL set when hedge setup begins).
    # ═══════════════════════════════════════════════════════════════════════════
    if (
        position
        and abs(safe_float(getattr(position, "positionAmt", 0))) > 0 and position.gain > 0
        and bool(getattr(config, "R3_HEDGE_INVARIANT_DUMP_ENABLED", True))
    ):
        try:
            _r3_gain = safe_fetch_float(getattr(position, "gain", 0), 0)
            _r3_gain_max = float(getattr(config, "R3_GAIN_MAX_PCT", 0.0))
            if _r3_gain < _r3_gain_max and _r3_gain > 0:
                if _pp_shared_ind is None:
                    _pp_shared_ind = await ii(trade_manager, symbol) or {}
                _r3_ind = _pp_shared_ind if _pp_shared_ind else None
                if _r3_ind:
                    _r3_w1_3m = safe_fetch_float(_r3_ind.get("wt1_3m"), 0)
                    _r3_w2_3m = safe_fetch_float(_r3_ind.get("wt2_3m"), 0)
                    _r3_w1_1h = safe_fetch_float(_r3_ind.get("wt1_1h"), 0)
                    _r3_w2_1h = safe_fetch_float(_r3_ind.get("wt2_1h"), 0)
                    _r3_is_long = position_side == "LONG"
                    _r3_3m_against = (_r3_is_long and _r3_w1_3m < _r3_w2_3m) or (
                        (not _r3_is_long) and _r3_w1_3m > _r3_w2_3m
                    )
                    _r3_1h_against = (_r3_is_long and _r3_w1_1h < _r3_w2_1h) or (
                        (not _r3_is_long) and _r3_w1_1h > _r3_w2_1h
                    )
                    if _r3_3m_against and _r3_1h_against:
                        # Hedge present?
                        _r3_has_hedge = False
                        try:
                            _r3_tracker = getattr(
                                trade_manager, "tracker_manager", None
                            )
                            _r3_active_hedges = (
                                list(getattr(_r3_tracker, "active_hedges", []) or [])
                                if _r3_tracker
                                else []
                            )
                            for _h in _r3_active_hedges:
                                if not isinstance(_h, dict):
                                    continue
                                if (
                                    _h.get("hedge_for") == position_key
                                    and _h.get("account") == account_key
                                ):
                                    _r3_has_hedge = True
                                    break
                                if (
                                    _h.get("losing_position_key") == position_key
                                    and _h.get("account") == account_key
                                ):
                                    _r3_has_hedge = True
                                    break
                        except Exception:
                            _r3_has_hedge = False
                        # 2026-05-09: opposite-side same-symbol position with material qty acts as hedge.
                        # The active_hedges list misses untagged positions (manual entries, legacy). If
                        # an opposite-side position covers ≥50% of losing notional, treat as hedged.
                        if not _r3_has_hedge:
                            try:
                                _r3_opp_side = "SHORT" if _r3_is_long else "LONG"
                                _r3_opp_key = f"{account_key}:{symbol}_{_r3_opp_side}"
                                _r3_pos_dict = (
                                    trade_manager.tracker_manager.positions_service.positions_by_account.get(
                                        account_key, {}
                                    )
                                    if hasattr(
                                        trade_manager.tracker_manager,
                                        "positions_service",
                                    )
                                    and trade_manager.tracker_manager.positions_service
                                    else {}
                                )
                                _r3_opp_pos = _r3_pos_dict.get(_r3_opp_key)
                                _r3_opp_amt = (
                                    abs(
                                        safe_float(
                                            getattr(_r3_opp_pos, "positionAmt", 0)
                                        )
                                    )
                                    if _r3_opp_pos
                                    else 0.0
                                )
                                _r3_opp_mark = (
                                    safe_fetch_float(
                                        getattr(_r3_opp_pos, "mark_price", 0), 0
                                    )
                                    if _r3_opp_pos
                                    else 0.0
                                )
                                _r3_self_amt = abs(
                                    safe_float(getattr(position, "positionAmt", 0))
                                )
                                _r3_self_mark = safe_fetch_float(
                                    getattr(position, "mark_price", current_price),
                                    current_price,
                                )
                                if (
                                    _r3_opp_amt * _r3_opp_mark
                                    >= 0.5 * _r3_self_amt * _r3_self_mark
                                    and _r3_self_amt * _r3_self_mark > 0
                                ):
                                    _r3_has_hedge = True
                                    if int(now_ts) % 60 == 0:
                                        logger.info(
                                            f"[R3_OPP_SIDE_COUNTED_AS_HEDGE] {position_key}: opp={_r3_opp_key} amt={_r3_opp_amt:.4f} notional=${_r3_opp_amt * _r3_opp_mark:.2f} ≥ 50% of loser ${_r3_self_amt * _r3_self_mark:.2f}"
                                        )
                            except Exception:
                                pass
                        # Hedge being started? (Redis lock 'hedge_pending:<key>' 60s TTL)
                        _r3_pending = False
                        try:
                            if not _r3_has_hedge and getattr(
                                trade_manager, "redis_manager", None
                            ):
                                _r3_pending = bool(
                                    await trade_manager.redis_manager.get(
                                        f"hedge_pending:{position_key}"
                                    )
                                )
                        except Exception:
                            _r3_pending = False
                        if not (_r3_has_hedge or _r3_pending):
                            _r3_amt = abs(
                                safe_float(getattr(position, "positionAmt", 0))
                            )
                            _r3_close_side = "SELL" if _r3_is_long else "BUY"
                            _r3_entry_sig = (
                                getattr(position, "last_signal", "")
                                or getattr(position, "open_reason", "")
                                or "?"
                            )
                            _r3_entry_ts = str(getattr(position, "opened_at", ""))[:19]
                            # 2026-05-09: action-first — TRY HEDGE before dumping.
                            _r3_hedge_ok = False
                            _r3_hedge_err = None
                            _r3_he = getattr(trade_manager, "hedge_engine", None)
                            if _r3_he is not None:
                                try:
                                    _r3_hedge_result = (
                                        await _r3_he.execute_same_symbol_hedge(
                                            account_key=account_key,
                                            origin_position=position,
                                            symbol=symbol,
                                            origin_side=position_side,
                                            qty=_r3_amt,
                                            current_price=current_price,
                                        )
                                    )
                                    _r3_hedge_ok = bool(_r3_hedge_result)
                                    if not _r3_hedge_ok:
                                        _r3_hedge_err = (
                                            f"hedge_engine_returned={_r3_hedge_result}"
                                        )
                                except Exception as _r3_he_err:
                                    _r3_hedge_err = repr(_r3_he_err)
                            else:
                                _r3_hedge_err = "no_hedge_engine"
                            if _r3_hedge_ok:
                                logger.warning(
                                    f"🛡️ [R3_HEDGE_OPENED] {position_key}: gain={_r3_gain:.2f}% — hedge fired by R3 directly (no dump, no alert)"
                                )
                                trade_manager.processing_keys.discard(position_key)
                                return f"{EvalStatus.ACTION_TAKEN}:R3_HEDGE_OPENED"
                            # Hedge didn't open — try CLOSE as fallback. Reason carries HEDGE_FAILED
                            # token so it bypasses UNIVERSAL_NOLOSS_GATE per config.py:1083.
                            logger.warning(
                                f"⚠️ [R3_HEDGE_REFUSED] {position_key}: hedge_engine refused: {_r3_hedge_err} — falling through to close"
                            )
                            _r3_close_failed = False
                            _r3_close_err = None
                            try:
                                _r3_close_result = await trade_manager.execute_now(
                                    position_key=position_key,
                                    account_key=account_key,
                                    symbol=symbol,
                                    original_positionAmt=_r3_amt,
                                    side=_r3_close_side,
                                    position_side=position_side,
                                    quantity=_r3_amt,
                                    old_price=current_price,
                                    unique_id=f"R3_HEDGE_INVARIANT_{int(time.time())}",
                                    reason=f"HEDGE_FAILED_R3_INVARIANT_DUMP_g{_r3_gain:.2f}_wt3m+1h_against_hedge_err={str(_r3_hedge_err)[:40]}",
                                    is_full_close=True,
                                    action="CLOSE",
                                )
                                if isinstance(_r3_close_result, str) and (
                                    "BLOCK" in _r3_close_result.upper()
                                    or "SKIP" in _r3_close_result.upper()
                                    or "REJECT" in _r3_close_result.upper()
                                ):
                                    _r3_close_failed = True
                                    _r3_close_err = _r3_close_result
                            except Exception as _r3_err:
                                _r3_close_failed = True
                                _r3_close_err = repr(_r3_err)
                            if not _r3_close_failed:
                                logger.critical(
                                    f"☢️ [R3_HEDGE_INVARIANT_DUMPED] {position_key}: gain={_r3_gain:.2f}% — hedge refused, dump executed (HEDGE_FAILED bypass)"
                                )
                                trade_manager.processing_keys.discard(position_key)
                                return f"{EvalStatus.ACTION_TAKEN}:R3_HEDGE_INVARIANT_DUMPED"
                            # BOTH hedge AND close failed. Alert ONLY if neither failure has a valid reason.
                            try:
                                import ez_alert
                                _r3_alert_hedge = ez_alert.should_alert_for_failure(
                                    _r3_hedge_err
                                )
                                _r3_alert_close = ez_alert.should_alert_for_failure(
                                    _r3_close_err
                                )
                            except Exception:
                                _r3_alert_hedge = True
                                _r3_alert_close = True
                            if _r3_alert_hedge or _r3_alert_close:
                                logger.critical(
                                    f"☢️ [R3_AGENT_BUG] {position_key}: hedge AND close both failed with no valid reason. hedge_err={_r3_hedge_err} close_err={_r3_close_err}"
                                )
                                try:
                                    import ez_alert

                                    ez_alert.alert_bad_exit(
                                        account=account_key,
                                        position_key=position_key,
                                        gain=_r3_gain,
                                        reason=f"R3_HEDGE_AND_CLOSE_BOTH_FAILED_NO_VALID_REASON_h={str(_r3_hedge_err)[:40]}_c={str(_r3_close_err)[:40]}",
                                        entry_signal=str(_r3_entry_sig),
                                        entry_ts=_r3_entry_ts,
                                        current_price=current_price,
                                    )
                                except Exception:
                                    pass
                            else:
                                logger.warning(
                                    f"[R3_BOTH_VALID_SKIP] {position_key}: both hedge+close suppressed for valid reasons. hedge={_r3_hedge_err} close={_r3_close_err}"
                                )
        except Exception as _r3_outer:
            logger.debug(f"[R3_HEDGE_INVARIANT] {position_key} probe err: {_r3_outer}")
    # ═══════════════════════════════════════════════════════════════════════════
    # R3_HTF_FLIP — Daily-close + parallel 4h structural exit (USER 2026-05-17).
    # Source: data/research_20260516/PLAN.md §3.6. Addresses 44% stuck-open / 49
    # RIDICULOUS_HOLD time-caps observed in 30d Rule A scoring.
    #   LONG closes when:
    #     Daily tier: (current_price < dc_basis_D) OR (wt1_D < wt2_D AND wt1_W < wt2_W)
    #     4h tier:    (current_price < ema_20_4h - atr_4h) AND wt1_4h < wt2_4h
    #   SHORT mirror.
    # Reasons R3_HTF_FLIP / R3_HTF_FLIP_4H are in UNIVERSAL_NOLOSS_GATE_BYPASS_REASONS.
    # ROLLBACK: R3_HTF_FLIP_EXIT_ENABLED=False (and/or _4H_TIER_ENABLED=False) in config.py.
    # ═══════════════════════════════════════════════════════════════════════════
    # 2026-05-18 per-sym overlay
    if (
        position
        and abs(safe_float(getattr(position, "positionAmt", 0))) > 0
        and bool(_psym_get(symbol, position_side, "R3_HTF_FLIP_EXIT_ENABLED", False))
    ):
        try:
            if _pp_shared_ind is None:
                _pp_shared_ind = await ii(trade_manager, symbol) or {}
            _r3hf_ind = _pp_shared_ind if _pp_shared_ind else None
        except Exception:
            _r3hf_ind = None
        if _r3hf_ind:
            try:
                _r3hf_is_long = position_side == "LONG"
                _r3hf_w1_D = safe_fetch_float(_r3hf_ind.get("wt1_D"), 0)
                _r3hf_w2_D = safe_fetch_float(_r3hf_ind.get("wt2_D"), 0)
                _r3hf_w1_W = safe_fetch_float(_r3hf_ind.get("wt1_W"), 0)
                _r3hf_w2_W = safe_fetch_float(_r3hf_ind.get("wt2_W"), 0)
                _r3hf_dc_basis_D = safe_fetch_float(_r3hf_ind.get("dc_basis_D"), 0)
                _r3hf_atr_4h = safe_fetch_float(_r3hf_ind.get("atr_4h"), 0)
                _r3hf_ema_20_4h = safe_fetch_float(_r3hf_ind.get("ema_20_4h"), 0)
                _r3hf_w1_4h = safe_fetch_float(_r3hf_ind.get("wt1_4h"), 0)
                _r3hf_w2_4h = safe_fetch_float(_r3hf_ind.get("wt2_4h"), 0)
                _r3hf_fire = False
                _r3hf_tier = None
                _r3hf_detail = ""
                if _r3hf_dc_basis_D > 0:
                    _r3hf_dc_break = (_r3hf_is_long and current_price < _r3hf_dc_basis_D) or ((not _r3hf_is_long) and current_price > _r3hf_dc_basis_D)
                    _r3hf_wt_flip = (_r3hf_is_long and _r3hf_w1_D < _r3hf_w2_D and _r3hf_w1_W < _r3hf_w2_W) or ((not _r3hf_is_long) and _r3hf_w1_D > _r3hf_w2_D and _r3hf_w1_W > _r3hf_w2_W)
                    if _r3hf_dc_break or _r3hf_wt_flip:
                        _r3hf_fire = True
                        _r3hf_tier = "DAILY"
                        _r3hf_detail = f"dc_break={_r3hf_dc_break}_wt_flip={_r3hf_wt_flip}_px={current_price:.6f}_dcBD={_r3hf_dc_basis_D:.6f}_w1D={_r3hf_w1_D:.2f}_w2D={_r3hf_w2_D:.2f}_w1W={_r3hf_w1_W:.2f}_w2W={_r3hf_w2_W:.2f}"
                if (not _r3hf_fire) and bool(_psym_get(symbol, position_side, "R3_HTF_FLIP_4H_TIER_ENABLED", False)):
                    if _r3hf_ema_20_4h > 0 and _r3hf_atr_4h > 0:
                        _r3hf_4h_break_long = _r3hf_is_long and current_price < (_r3hf_ema_20_4h - _r3hf_atr_4h) and _r3hf_w1_4h < _r3hf_w2_4h
                        _r3hf_4h_break_short = (not _r3hf_is_long) and current_price > (_r3hf_ema_20_4h + _r3hf_atr_4h) and _r3hf_w1_4h > _r3hf_w2_4h
                        if _r3hf_4h_break_long or _r3hf_4h_break_short:
                            _r3hf_fire = True
                            _r3hf_tier = "4H"
                            _r3hf_detail = f"px={current_price:.6f}_ema4h={_r3hf_ema_20_4h:.6f}_atr4h={_r3hf_atr_4h:.6f}_w1_4h={_r3hf_w1_4h:.2f}_w2_4h={_r3hf_w2_4h:.2f}"
                if _r3hf_fire:
                    _r3hf_amt = abs(safe_float(getattr(position, "positionAmt", 0)))
                    _r3hf_close_side = "SELL" if _r3hf_is_long else "BUY"
                    _r3hf_gain = safe_fetch_float(getattr(position, "gain", 0), 0)
                    _r3hf_reason_tag = "R3_HTF_FLIP" if _r3hf_tier == "DAILY" else "R3_HTF_FLIP_4H"
                    logger.error(
                        f"⛔ [{_r3hf_reason_tag}] {position_key}: tier={_r3hf_tier} gain={_r3hf_gain:.2f}% {_r3hf_detail} → CLOSE"
                    )
                    try:
                        await trade_manager.execute_now(
                            position_key=position_key,
                            account_key=account_key,
                            symbol=symbol,
                            original_positionAmt=_r3hf_amt,
                            side=_r3hf_close_side,
                            position_side=position_side,
                            quantity=_r3hf_amt,
                            old_price=current_price,
                            unique_id=f"{_r3hf_reason_tag}_{int(time.time())}",
                            reason=f"{_r3hf_reason_tag}_{_r3hf_tier}_g{_r3hf_gain:.2f}%_{_r3hf_detail[:80]}",
                            is_full_close=True,
                            action="CLOSE",
                        )
                        trade_manager.processing_keys.discard(position_key)
                        return f"{EvalStatus.ACTION_TAKEN}:{_r3hf_reason_tag}_CLOSED_{_r3hf_tier}"
                    except Exception as _r3hf_exec_err:
                        logger.error(
                            f"⛔ [R3_HTF_FLIP_EXEC_ERR] {position_key}: {_r3hf_exec_err}"
                        )
            except Exception as _r3hf_outer:
                logger.warning(
                    f"[R3_HTF_FLIP_ERR] {position_key}: {_r3hf_outer}"
                )
    # ═══ END R3_HTF_FLIP ═══
    # ═══════════════════════════════════════════════════════════════════════════
    # MTF COMPOUND EXIT — Path A Phase 1 wiring 2026-05-19 (USER MANDATE)
    # Source: vec_paths/mtf_armed_entries.py:127-235 + data/_diagnostic/protection_stack_2026051*.md.
    # Replacement protection stack for HEDGE_MODE + DC_LOW_4 emergency. 5 triggers, ANY fires CLOSE:
    #   1. MTF_ATR_TRAIL: ATR trail hit (HARD, ratchets from entry, MTF_ATR_TRAIL_TF/MULT knobs)
    #   2. MTF_DC_REJECT: price was outside dc_high/low_TF and re-crossed back
    #   3. MTF_BB_REJECT: BB tag-fail within MTF_BB_REJECT_EXIT_LOOKBACK bars
    #   4. MTF_GR_WT_EXIT: GR HTF exit gate (opposite-side score) AND wt1/wt2 cross against (BOTH required)
    # Master switch MTF_EXIT_USE_COMPOUND defaults False → entire block is inert.
    # Bypasses NOLOSS: close reasons MTF_ATR_TRAIL/MTF_DC_REJECT/MTF_BB_REJECT/MTF_GR_WT_EXIT
    # are in config.UNIVERSAL_NOLOSS_GATE_BYPASS_REASONS (added 2026-05-19).
    # Per-position trail state lives in trade_manager.mtf_compound_exit_state[position_key].
    # Fires AFTER R3_HTF_FLIP (so structural exits preempt) and BEFORE GR_HTF_DIRECT_EXIT.
    # ROLLBACK: set MTF_EXIT_USE_COMPOUND=False (already default) → block becomes inert.
    # ═══════════════════════════════════════════════════════════════════════════
    # ─── USER 2026-05-20: MTF compound exit applies ONLY to positions opened
    #     AFTER MTF_EXIT_MIN_OPEN_TS. Default 0 → resolves to trade_manager
    #     startup time so currently-open positions ride legacy exits, only
    #     future opens get MTF-managed. Prevents restart-cascade closing
    #     existing trades. Resolved once per call below as `_mtfce_min_ts_gate`.
    _mtfce_min_ts_gate = float(_psym_get(symbol, position_side, "MTF_EXIT_MIN_OPEN_TS", 0.0)) if position else 0.0
    if _mtfce_min_ts_gate <= 0:
        if not hasattr(trade_manager, "_mtfce_startup_ts"):
            trade_manager._mtfce_startup_ts = time.time()
        _mtfce_min_ts_gate = trade_manager._mtfce_startup_ts
    _mtfce_pos_open_ts_gate = float(getattr(position, "opened_at", 0) or 0) if position else 0.0
    if (
        position
        and abs(safe_float(getattr(position, "positionAmt", 0))) > 0
        and bool(_psym_get(symbol, position_side, "MTF_EXIT_USE_COMPOUND", False))
        and _mtfce_pos_open_ts_gate >= _mtfce_min_ts_gate
    ):
        try:
            if not hasattr(trade_manager, "mtf_compound_exit_state"):
                trade_manager.mtf_compound_exit_state = {}
            _mtfce_state = trade_manager.mtf_compound_exit_state.get(position_key, {"trail": 0.0, "ever_outside_dc": False, "bb_tag_bars": []})
            if _pp_shared_ind is None:
                _pp_shared_ind = await ii(trade_manager, symbol) or {}
            _mtfce_ind = _pp_shared_ind if _pp_shared_ind else None
        except Exception:
            _mtfce_ind = None
        if _mtfce_ind:
            try:
                _mtfce_is_long = position_side == "LONG"
                _mtfce_entry = safe_fetch_float(getattr(position, "entry_price", 0), 0)
                _mtfce_fire = False
                _mtfce_reason = ""
                _mtfce_atr_tf = str(_psym_get(symbol, position_side, "MTF_ATR_TRAIL_TF", "15m"))
                _mtfce_dc_tf = str(_psym_get(symbol, position_side, "MTF_DC_REJECT_EXIT_TF", "15m"))
                _mtfce_bb_tf = str(_psym_get(symbol, position_side, "MTF_BB_REJECT_EXIT_TF", "15m"))
                _mtfce_wt_tf = str(_psym_get(symbol, position_side, "MTF_WT_CROSS_EXIT_TF", "15m"))
                _mtfce_atr_mult = float(_psym_get(symbol, position_side, "MTF_ATR_TRAIL_MULT", 2.5))
                _mtfce_bb_lb = int(_psym_get(symbol, position_side, "MTF_BB_REJECT_EXIT_LOOKBACK", 5))
                # ─── 1. MTF_ATR_TRAIL ────────────────────────────────────────────
                if bool(_psym_get(symbol, position_side, "MTF_ATR_TRAIL_ENABLED", False)):
                    _mtfce_atr = safe_fetch_float(_mtfce_ind.get(f"atr_{_mtfce_atr_tf}"), 0)
                    if _mtfce_atr > 0 and _mtfce_entry > 0 and current_price > 0:
                        if _mtfce_is_long:
                            _mtfce_cand = max(_mtfce_entry - _mtfce_atr_mult * _mtfce_atr, current_price - _mtfce_atr_mult * _mtfce_atr)
                            _mtfce_state["trail"] = max(_mtfce_state.get("trail", 0.0), _mtfce_cand) if _mtfce_state.get("trail", 0.0) > 0 else _mtfce_cand
                            if _mtfce_state["trail"] > 0 and current_price < _mtfce_state["trail"]:
                                _mtfce_fire = True
                                _mtfce_reason = f"MTF_ATR_TRAIL_{_mtfce_atr_tf}_x{_mtfce_atr_mult}_lvl{_mtfce_state['trail']:.6f}"
                        else:
                            _mtfce_cand = min(_mtfce_entry + _mtfce_atr_mult * _mtfce_atr, current_price + _mtfce_atr_mult * _mtfce_atr)
                            _mtfce_state["trail"] = min(_mtfce_state.get("trail", 0.0), _mtfce_cand) if _mtfce_state.get("trail", 0.0) > 0 else _mtfce_cand
                            if _mtfce_state["trail"] > 0 and current_price > _mtfce_state["trail"]:
                                _mtfce_fire = True
                                _mtfce_reason = f"MTF_ATR_TRAIL_{_mtfce_atr_tf}_x{_mtfce_atr_mult}_lvl{_mtfce_state['trail']:.6f}"
                # ─── 2. MTF_DC_REJECT ────────────────────────────────────────────
                if (not _mtfce_fire) and bool(_psym_get(symbol, position_side, "MTF_DC_REJECT_EXIT_ENABLED", False)):
                    if _mtfce_is_long:
                        _mtfce_band = safe_fetch_float(_mtfce_ind.get(f"dc_high_{_mtfce_dc_tf}"), 0)
                        if _mtfce_band > 0:
                            if current_price > _mtfce_band:
                                _mtfce_state["ever_outside_dc"] = True
                            elif _mtfce_state.get("ever_outside_dc", False) and current_price < _mtfce_band:
                                _mtfce_fire = True
                                _mtfce_reason = f"MTF_DC_REJECT_{_mtfce_dc_tf}_px{current_price:.6f}"
                    else:
                        _mtfce_band = safe_fetch_float(_mtfce_ind.get(f"dc_low_{_mtfce_dc_tf}"), 0)
                        if _mtfce_band > 0:
                            if current_price < _mtfce_band:
                                _mtfce_state["ever_outside_dc"] = True
                            elif _mtfce_state.get("ever_outside_dc", False) and current_price > _mtfce_band:
                                _mtfce_fire = True
                                _mtfce_reason = f"MTF_DC_REJECT_{_mtfce_dc_tf}_px{current_price:.6f}"
                # ─── 3. MTF_BB_REJECT ────────────────────────────────────────────
                if (not _mtfce_fire) and bool(_psym_get(symbol, position_side, "MTF_BB_REJECT_EXIT_ENABLED", False)):
                    _mtfce_bbu = safe_fetch_float(_mtfce_ind.get(f"bb_upper_{_mtfce_bb_tf}"), 0)
                    _mtfce_bbl = safe_fetch_float(_mtfce_ind.get(f"bb_lower_{_mtfce_bb_tf}"), 0)
                    _mtfce_high = safe_fetch_float(_mtfce_ind.get(f"high_{_mtfce_bb_tf}"), current_price)
                    _mtfce_low = safe_fetch_float(_mtfce_ind.get(f"low_{_mtfce_bb_tf}"), current_price)
                    if _mtfce_is_long and _mtfce_bbu > 0:
                        _mtfce_tag_now = _mtfce_high >= _mtfce_bbu - 1e-9
                        _mtfce_fail_now = (_mtfce_high < _mtfce_bbu) and _mtfce_high > 0
                    elif (not _mtfce_is_long) and _mtfce_bbl > 0:
                        _mtfce_tag_now = _mtfce_low <= _mtfce_bbl + 1e-9 and _mtfce_low > 0
                        _mtfce_fail_now = (_mtfce_low > _mtfce_bbl) and _mtfce_low > 0
                    else:
                        _mtfce_tag_now = False
                        _mtfce_fail_now = False
                    _mtfce_tag_bars = list(_mtfce_state.get("bb_tag_bars", []))
                    _mtfce_now_s = int(time.time())
                    if _mtfce_tag_now:
                        _mtfce_tag_bars.append(_mtfce_now_s)
                    # Trim older than lookback (60s × lookback bars approximation)
                    _mtfce_cutoff_s = _mtfce_now_s - _mtfce_bb_lb * 60
                    _mtfce_tag_bars = [b for b in _mtfce_tag_bars if b >= _mtfce_cutoff_s]
                    _mtfce_state["bb_tag_bars"] = _mtfce_tag_bars
                    if _mtfce_fail_now and len(_mtfce_tag_bars) > 0:
                        _mtfce_fire = True
                        _mtfce_reason = f"MTF_BB_REJECT_{_mtfce_bb_tf}"
                # ─── 4. MTF_GR_WT_EXIT (GR HTF exit gate AND WT cross against — BOTH) ─
                if (not _mtfce_fire) and bool(_psym_get(symbol, position_side, "MTF_GR_EXIT_GATE_ENABLED", False)):
                    _mtfce_wt1 = safe_fetch_float(_mtfce_ind.get(f"wt1_{_mtfce_wt_tf}"), 0)
                    _mtfce_wt2 = safe_fetch_float(_mtfce_ind.get(f"wt2_{_mtfce_wt_tf}"), 0)
                    _mtfce_wt_against = (_mtfce_is_long and _mtfce_wt1 < _mtfce_wt2) or ((not _mtfce_is_long) and _mtfce_wt1 > _mtfce_wt2)
                    if _mtfce_wt_against and bool(_psym_get(symbol, position_side, "MTF_WT_CROSS_EXIT_ENABLED", False)):
                        # GR HTF exit gate: opposite-side bullish/bearish across MIN_TFS HTFs
                        _mtfce_gr_min_tfs = int(_psym_get(symbol, position_side, "MTF_GR_EXIT_MIN_TFS", 3))
                        _mtfce_gr_count = 0
                        for _gtf in ("15m", "1h", "4h", "D"):
                            _gw1 = safe_fetch_float(_mtfce_ind.get(f"wt1_{_gtf}"), 0)
                            _gw2 = safe_fetch_float(_mtfce_ind.get(f"wt2_{_gtf}"), 0)
                            if _mtfce_is_long and _gw1 < _gw2 and _gw1 != 0:
                                _mtfce_gr_count += 1
                            elif (not _mtfce_is_long) and _gw1 > _gw2 and _gw1 != 0:
                                _mtfce_gr_count += 1
                        if _mtfce_gr_count >= _mtfce_gr_min_tfs:
                            _mtfce_fire = True
                            _mtfce_reason = f"MTF_GR_WT_EXIT_{_mtfce_wt_tf}_grTFs={_mtfce_gr_count}"
                # Persist state regardless of fire
                trade_manager.mtf_compound_exit_state[position_key] = _mtfce_state
                if _mtfce_fire:
                    _mtfce_amt = abs(safe_float(getattr(position, "positionAmt", 0)))
                    _mtfce_close_side = "SELL" if _mtfce_is_long else "BUY"
                    _mtfce_gain = safe_fetch_float(getattr(position, "gain", 0), 0)
                    logger.error(
                        f"⛔ [{_mtfce_reason[:18]}] {position_key}: gain={_mtfce_gain:.2f}% px={current_price:.6f} entry={_mtfce_entry:.6f} → CLOSE"
                    )
                    try:
                        await trade_manager.execute_now(
                            position_key=position_key,
                            account_key=account_key,
                            symbol=symbol,
                            original_positionAmt=_mtfce_amt,
                            side=_mtfce_close_side,
                            position_side=position_side,
                            quantity=_mtfce_amt,
                            old_price=current_price,
                            unique_id=f"{_mtfce_reason[:18]}_{int(time.time())}",
                            reason=f"{_mtfce_reason}_g{_mtfce_gain:.2f}%",
                            is_full_close=True,
                            action="CLOSE",
                        )
                        trade_manager.processing_keys.discard(position_key)
                        trade_manager.mtf_compound_exit_state.pop(position_key, None)
                        return f"{EvalStatus.ACTION_TAKEN}:{_mtfce_reason[:18]}_CLOSED"
                    except Exception as _mtfce_exec_err:
                        logger.error(
                            f"⛔ [MTF_COMPOUND_EXIT_EXEC_ERR] {position_key}: {_mtfce_exec_err}"
                        )
            except Exception as _mtfce_outer:
                logger.warning(
                    f"[MTF_COMPOUND_EXIT_ERR] {position_key}: {_mtfce_outer}"
                )
    # ═══ END MTF COMPOUND EXIT ═══
    # ═══════════════════════════════════════════════════════════════════════════
    # 🚩 GR_HTF_DIRECT_EXIT — 2026-05-12 USER MANDATE (crypto)
    # Direct exit signal: if opposite-direction GR_HTF score >= GR_HTF_DIRECT_EXIT_SCORE → CLOSE.
    # Bypass UNIVERSAL_NOLOSS_GATE: reason contains 'GR_HTF_DIRECT_EXIT' (per config.py bypass list).
    # Fires BEFORE ALL_TF_AGAINST_CLOSE — sanctioned technical loss-exit path per CLAUDE.md.
    # ROLLBACK: set GR_HTF_DIRECT_EXIT_ENABLED=False in config.py.
    # ═══════════════════════════════════════════════════════════════════════════
    if (
        position
        and abs(safe_float(getattr(position, "positionAmt", 0))) > 0
        and bool(getattr(config, "GR_HTF_DIRECT_EXIT_ENABLED", True))
    ):
        try:
            if _pp_shared_ind is None:
                _pp_shared_ind = await ii(trade_manager, symbol) or {}
            _grde_exit_ind = _pp_shared_ind if _pp_shared_ind else None
        except Exception:
            _grde_exit_ind = None
        if _grde_exit_ind:
            try:
                from golden_rule_htf import score_entry_htf as _gr_htf_exit_fn

                _grde_exit_is_long = position_side == "LONG"
                _grde_exit_min_ind = int(getattr(config, "GOLDEN_RULE_MIN_IND", 1))
                _grde_exit_min_tfs = int(getattr(config, "GOLDEN_RULE_HTF_MIN_TFS", 1))
                # Score opposite-direction alignment to determine exit signal
                _grde_exit_pass, _grde_exit_n_tfs, _grde_exit_detail = _gr_htf_exit_fn(
                    _grde_exit_ind,
                    not _grde_exit_is_long,
                    "crypto",
                    min_tfs=_grde_exit_min_tfs,
                    min_ind=_grde_exit_min_ind,
                    current_price=current_price,
                )
                _grde_exit_score = float(_grde_exit_n_tfs) * float(_grde_exit_min_ind)
                _grde_exit_score_min = float(
                    getattr(config, "GR_HTF_DIRECT_EXIT_SCORE", 18.0)
                )
                if _grde_exit_score >= _grde_exit_score_min:
                    _grde_exit_amt = abs(
                        safe_float(getattr(position, "positionAmt", 0))
                    )
                    _grde_exit_side = "SELL" if _grde_exit_is_long else "BUY"
                    _grde_exit_gain = safe_fetch_float(getattr(position, "gain", 0), 0)
                    logger.critical(
                        f"⛔ [GR_HTF_DIRECT_EXIT] {position_key}: opp_score={_grde_exit_score:.0f} (tfs={_grde_exit_n_tfs}×ind={_grde_exit_min_ind}) >= {_grde_exit_score_min:.0f} gain={_grde_exit_gain:.2f}% — CLOSE (bypasses NOLOSS)"
                    )
                    try:
                        await trade_manager.execute_now(
                            position_key=position_key,
                            account_key=account_key,
                            symbol=symbol,
                            original_positionAmt=_grde_exit_amt,
                            side=_grde_exit_side,
                            position_side=position_side,
                            quantity=_grde_exit_amt,
                            old_price=current_price,
                            unique_id=f"GR_HTF_DIRECT_EXIT_{int(time.time())}",
                            reason=f"GR_HTF_DIRECT_EXIT_{_grde_exit_score:.0f}_g{_grde_exit_gain:.2f}%_{_grde_exit_detail[:50]}",
                            is_full_close=True,
                            action="CLOSE",
                        )
                        trade_manager.processing_keys.discard(position_key)
                        return f"{EvalStatus.ACTION_TAKEN}:GR_HTF_DIRECT_EXIT_CLOSED"
                    except Exception as _grde_exit_err:
                        logger.error(
                            f"⛔ [GR_HTF_DIRECT_EXIT_EXEC_ERR] {position_key}: {_grde_exit_err}"
                        )
                else:
                    logger.debug(
                        f"[GR_HTF_DIRECT_EXIT_MISS] {position_key}: opp_score={_grde_exit_score:.0f} < {_grde_exit_score_min:.0f}"
                    )
            except Exception as _grde_exit_outer:
                logger.warning(
                    f"[GR_HTF_DIRECT_EXIT_ERR] {position_key}: {_grde_exit_outer}"
                )
    # ═══ END GR_HTF_DIRECT_EXIT ═══
    # ═══════════════════════════════════════════════════════════════════════════
    # ALL_TF_AGAINST_CLOSE — USER 2026-05-06 mandate (strongest signal):
    # If ALL TFs (3m/15m/1h/4h/D) agree against the trade direction → CLOSE primary IMMEDIATELY.
    # The hedge (if open) becomes the new main trade — leave it running on the winning side.
    # No %-gate, no underwater requirement. Same-side full-TF disagreement = trade is dead.
    # ═══════════════════════════════════════════════════════════════════════════
    if (
        position
        and abs(safe_float(getattr(position, "positionAmt", 0))) > 0
        and bool(getattr(config, "ALL_TF_AGAINST_CLOSE_ENABLED", True))
    ):
        _at_cd_dict = trade_manager.__dict__.setdefault("_all_tf_against_cooldown", {})
        _at_cd_sec = float(getattr(config, "ALL_TF_AGAINST_CLOSE_COOLDOWN_SEC", 30.0))
        _at_recent = (now_ts - _at_cd_dict.get(position_key, 0)) < _at_cd_sec
        if not _at_recent:
            try:
                _at_ind = await ii(trade_manager, symbol)
            except Exception:
                _at_ind = {}
            if _at_ind:
                _at_w1_3m = safe_fetch_float(_at_ind.get("wt1_3m"), 0)
                _at_w2_3m = safe_fetch_float(_at_ind.get("wt2_3m"), 0)
                _at_w1_15m = safe_fetch_float(_at_ind.get("wt1_15m"), 0)
                _at_w2_15m = safe_fetch_float(_at_ind.get("wt2_15m"), 0)
                _at_w1_1h = safe_fetch_float(_at_ind.get("wt1_1h"), 0)
                _at_w2_1h = safe_fetch_float(_at_ind.get("wt2_1h"), 0)
                _at_w1_4h = safe_fetch_float(_at_ind.get("wt1_4h"), 0)
                _at_w2_4h = safe_fetch_float(_at_ind.get("wt2_4h"), 0)
                _at_w1_D = safe_fetch_float(_at_ind.get("wt1_D"), 0)
                _at_w2_D = safe_fetch_float(_at_ind.get("wt2_D"), 0)
                _at_is_long = position_side == "LONG"
                # 2026-05-09 sweep-exposure: count TFs against; require >= ALL_TF_AGAINST_CLOSE_MIN_TFS.
                # Default 5 = legacy "all 5 TFs against". Set to 3 or 4 to fire on 3-of-5 / 4-of-5.
                if _at_is_long:
                    _at_count = (
                        int(_at_w1_3m < _at_w2_3m)
                        + int(_at_w1_15m < _at_w2_15m)
                        + int(_at_w1_1h < _at_w2_1h)
                        + int(_at_w1_4h < _at_w2_4h)
                        + int(_at_w1_D < _at_w2_D)
                    )
                else:
                    _at_count = (
                        int(_at_w1_3m > _at_w2_3m)
                        + int(_at_w1_15m > _at_w2_15m)
                        + int(_at_w1_1h > _at_w2_1h)
                        + int(_at_w1_4h > _at_w2_4h)
                        + int(_at_w1_D > _at_w2_D)
                    )
                _at_min_tfs = int(getattr(config, "ALL_TF_AGAINST_CLOSE_MIN_TFS", 5))
                _at_against = _at_count >= _at_min_tfs
                if _at_against:
                    _at_pos_amt = abs(safe_float(getattr(position, "positionAmt", 0)))
                    _at_close_side = "SELL" if _at_is_long else "BUY"
                    _at_cd_dict[position_key] = now_ts
                    logger.error(
                        f"⛔ [ALL_TF_AGAINST_CLOSE] {position_key}: ALL TFs against — "
                        f"3m({_at_w1_3m:.1f}/{_at_w2_3m:.1f}) 15m({_at_w1_15m:.1f}/{_at_w2_15m:.1f}) "
                        f"1h({_at_w1_1h:.1f}/{_at_w2_1h:.1f}) 4h({_at_w1_4h:.1f}/{_at_w2_4h:.1f}) "
                        f"D({_at_w1_D:.1f}/{_at_w2_D:.1f}) → CLOSE primary, hedge becomes main"
                    )
                    try:
                        await trade_manager.execute_now(
                            position_key=position_key,
                            account_key=account_key,
                            symbol=symbol,
                            original_positionAmt=_at_pos_amt,
                            side=_at_close_side,
                            position_side=position_side,
                            quantity=_at_pos_amt,
                            old_price=current_price,
                            unique_id=f"ALL_TF_AGAINST_{int(time.time())}",
                            reason=f"ALL_TF_AGAINST_CLOSE_3m{_at_w1_3m:.0f}_15m{_at_w1_15m:.0f}_1h{_at_w1_1h:.0f}_4h{_at_w1_4h:.0f}_D{_at_w1_D:.0f}",
                            is_full_close=True,
                            action="CLOSE",
                        )
                        # Hedge auto-becomes main: when primary closes via execute_now, the hedge
                        # record stays in tracker.active_hedges but its losing_position_key is now
                        # closed. The hedge keeps running on the winning side as the main exposure.
                        # No explicit "promote hedge to main" action needed — it's already the only
                        # remaining position on the symbol after primary close.
                        trade_manager.processing_keys.discard(position_key)
                        return f"{EvalStatus.ACTION_TAKEN}:ALL_TF_AGAINST_CLOSED_HEDGE_PROMOTED"
                    except Exception as _at_err:
                        logger.error(
                            f"⛔ [ALL_TF_AGAINST_CLOSE_ERR] {position_key}: {_at_err}"
                        )
    # ═══════════════════════════════════════════════════════════════════════════
    # WT15M_AGAINST_FORCE_HEDGE — USER 2026-05-06 mandate (highest priority safety):
    # If wt1_15m is against the trade direction → fire hedge IMMEDIATELY, no matter what.
    # No %-gate, no underwater requirement, no cooldown beyond a 30s per-position dedup.
    # When hedge can't fire OR already exists with bleed continuing, fall through to close.
    # Fires BEFORE RIDICULOUS_HOLD / DC_BB_D_BREAK / UNDERWATER guards.
    # ═══════════════════════════════════════════════════════════════════════════
    if (
        position
        and abs(safe_float(getattr(position, "positionAmt", 0))) > 0
        and bool(getattr(config, "WT15M_AGAINST_FORCE_HEDGE_ENABLED", True))
    ):
        _w15_cd_dict = trade_manager.__dict__.setdefault(
            "_wt15m_force_hedge_cooldown", {}
        )
        _w15_cd_sec = float(
            getattr(config, "WT15M_AGAINST_FORCE_HEDGE_COOLDOWN_SEC", 30.0)
        )
        _w15_recent = (now_ts - _w15_cd_dict.get(position_key, 0)) < _w15_cd_sec
        if not _w15_recent:
            try:
                _w15_ind = await ii(trade_manager, symbol)
            except Exception:
                _w15_ind = {}
            if _w15_ind:
                _w15_w1 = safe_fetch_float(_w15_ind.get("wt1_15m"), 0)
                _w15_w2 = safe_fetch_float(_w15_ind.get("wt2_15m"), 0)
                if _w15_w1 != 0 or _w15_w2 != 0:
                    _w15_is_long = position_side == "LONG"
                    _w15_against = (
                        (_w15_w1 < _w15_w2) if _w15_is_long else (_w15_w1 > _w15_w2)
                    )
                    if _w15_against:
                        _w15_tm = getattr(trade_manager, "tracker_manager", None)
                        _w15_inflight = getattr(
                            getattr(trade_manager, "hedge_engine", None),
                            "_hedge_same_in_flight",
                            set(),
                        )
                        _w15_active = (
                            bool(_w15_tm)
                            and any(
                                (
                                    h.get("losing_position_key") == position_key
                                    or h.get("hedge_for") == position_key
                                )
                                for h in (_w15_tm.active_hedges or [])
                            )
                        ) or (position_key in _w15_inflight)
                        _w15_pos_amt = abs(
                            safe_float(getattr(position, "positionAmt", 0))
                        )
                        _w15_cd_dict[position_key] = now_ts
                        if not _w15_active:
                            logger.error(
                                f"🛡️ [WT15M_AGAINST_FORCE_HEDGE] {position_key}: wt1_15m={_w15_w1:.1f} {'<' if _w15_is_long else '>'} wt2_15m={_w15_w2:.1f} → FIRING HEDGE (no matter what)"
                            )
                            try:
                                _w15_he = getattr(trade_manager, "hedge_engine", None)
                                if _w15_he is not None:
                                    await _w15_he.execute_same_symbol_hedge(
                                        account_key,
                                        position,
                                        symbol,
                                        position_side,
                                        _w15_pos_amt,
                                        current_price,
                                    )
                                    trade_manager.processing_keys.discard(position_key)
                                    return f"{EvalStatus.ACTION_TAKEN}:WT15M_AGAINST_HEDGE_FIRED"
                            except Exception as _w15_err:
                                logger.error(
                                    f"🛡️ [WT15M_AGAINST_FORCE_HEDGE_ERR] {position_key}: {_w15_err} — falling to force-close"
                                )
                        else:
                            # 2026-05-06 ZECUSDC: skip force-close on parabolic — 15m WT will repeatedly
                            # diverge from price during a strong trend; let it ride instead of whipsawing.
                            _w15_skip = False
                            if bool(
                                getattr(config, "PARABOLIC_PROTECTION_ENABLED", True)
                            ):
                                _pp_r4w = safe_fetch_float(
                                    _w15_ind.get("rsi_4h", 50), 50
                                )
                                _pp_r1w = safe_fetch_float(
                                    _w15_ind.get("rsi_1h", 50), 50
                                )
                                _pp_bb4w = safe_fetch_float(
                                    _w15_ind.get("bb_pct_b_4h", 0.5), 0.5
                                )
                                _pp_up_w = (
                                    _pp_r4w
                                    >= float(
                                        getattr(config, "PARABOLIC_RSI_4H_MIN", 70.0)
                                    )
                                    and _pp_r1w
                                    >= float(
                                        getattr(config, "PARABOLIC_RSI_1H_MIN", 65.0)
                                    )
                                    and _pp_bb4w
                                    >= float(
                                        getattr(
                                            config, "PARABOLIC_BB_PCT_B_4H_MIN", 0.90
                                        )
                                    )
                                )
                                _pp_dn_w = (
                                    _pp_r4w
                                    <= float(
                                        getattr(config, "PARABOLIC_RSI_4H_MAX", 30.0)
                                    )
                                    and _pp_r1w
                                    <= float(
                                        getattr(config, "PARABOLIC_RSI_1H_MAX", 35.0)
                                    )
                                    and _pp_bb4w
                                    <= float(
                                        getattr(
                                            config, "PARABOLIC_BB_PCT_B_4H_MAX", 0.10
                                        )
                                    )
                                )
                                if (_w15_is_long and _pp_up_w) or (
                                    (not _w15_is_long) and _pp_dn_w
                                ):
                                    _w15_skip = True
                                    logger.warning(
                                        f"🌟 [WT15M_FORCE_CLOSE_PARABOLIC_BYPASS] {position_key}: "
                                        f"rsi_4h={_pp_r4w:.1f} rsi_1h={_pp_r1w:.1f} bb%B_4h={_pp_bb4w:.2f} → skip force-close, let trend run"
                                    )
                            if not _w15_skip:
                                # Hedge already on but bleed continues + wt1_15m against → force close primary
                                _w15_side_close = "SELL" if _w15_is_long else "BUY"
                                logger.error(
                                    f"🛡️ [WT15M_AGAINST_FORCE_CLOSE] {position_key}: wt1_15m={_w15_w1:.1f}/{_w15_w2:.1f} against + hedge active → FORCE CLOSE"
                                )
                                try:
                                    await trade_manager.execute_now(
                                        position_key=position_key,
                                        account_key=account_key,
                                        symbol=symbol,
                                        original_positionAmt=_w15_pos_amt,
                                        side=_w15_side_close,
                                        position_side=position_side,
                                        quantity=_w15_pos_amt,
                                        old_price=current_price,
                                        unique_id=f"WT15M_FORCE_{int(time.time())}",
                                        reason=f"WT15M_AGAINST_FORCE_CLOSE_w1{_w15_w1:.1f}_w2{_w15_w2:.1f}",
                                        is_full_close=True,
                                        action="CLOSE",
                                    )
                                    trade_manager.processing_keys.discard(position_key)
                                    return f"{EvalStatus.ACTION_TAKEN}:WT15M_AGAINST_FORCE_CLOSED"
                                except Exception as _w15_cl_err:
                                    logger.error(
                                        f"🛡️ [WT15M_AGAINST_FORCE_CLOSE_ERR] {position_key}: {_w15_cl_err}"
                                    )
    # ═══════════════════════════════════════════════════════════════════════════
    # RIDICULOUS_HOLD_GUARD — User 2026-05-05 mandate (LUNC -65% incident on ang):
    # Catastrophic-loss safety net. Even with hedging, positions can bleed unbounded
    # when hedges keep getting closed (HEDGE_BANDAID_OFF) while shorts run unbounded.
    # Absolute fail-safe — fires BEFORE everything else:
    #   gain ≤ RIDICULOUS_LOSS_PCT (-15% default) → force close regardless of hedge state
    #   underwater longer than RIDICULOUS_HOLD_HOURS (48h) → force close
    # ═══════════════════════════════════════════════════════════════════════════
    if (
        position
        and abs(safe_float(getattr(position, "positionAmt", 0))) > 0
        and bool(getattr(config, "RIDICULOUS_HOLD_GUARD_ENABLED", True))
    ):
        _rh_gain = safe_fetch_float(getattr(position, "gain", 0), 0)
        _rh_loss_cap = float(getattr(config, "RIDICULOUS_LOSS_PCT", -15.0))
        _rh_hold_hours = float(getattr(config, "RIDICULOUS_HOLD_HOURS", 48.0))
        _rh_force = False
        _rh_why = ""
        if _rh_gain <= _rh_loss_cap:
            _rh_force = True
            _rh_why = f"RIDICULOUS_LOSS_g{_rh_gain:.2f}%_cap{_rh_loss_cap:.1f}%"
        else:
            # USER 2026-05-11: HOLD-cap path now requires gain >= 0 (clean-up stale winners only).
            # Was previously firing on `_rh_gain < 0` after 48h, closing losers at -12/-15% — that path
            # is OUTSIDE the 3 sanctioned loss-exit paths (R1 / R2 / HEDGE_FAILED) and was the #1 cause
            # of forced losses (64.1% of 18,363 closes in 24h on 2026-05-11).
            _rh_require_nonneg = bool(
                getattr(config, "RIDICULOUS_HOLD_REQUIRE_GAIN_NONNEG", True)
            )
            _rh_gain_ok_for_hold = (
                (_rh_gain >= 0.0) if _rh_require_nonneg else (_rh_gain < 0.0)
            )
            if _rh_gain_ok_for_hold:
                _rh_opened = getattr(position, "opened_at", None)
                if _rh_opened:
                    try:
                        _rh_dt = (
                            isoparse(_rh_opened)
                            if isinstance(_rh_opened, str)
                            else _rh_opened
                        )
                        if hasattr(_rh_dt, "tzinfo") and _rh_dt.tzinfo is None:
                            _rh_dt = _rh_dt.replace(tzinfo=timezone.utc)
                        _rh_age_h = (
                            (now - _rh_dt).total_seconds() / 3600.0
                            if hasattr(_rh_dt, "tzinfo")
                            else 0
                        )
                        if _rh_age_h > _rh_hold_hours:
                            _rh_force = True
                            _rh_why = f"RIDICULOUS_HOLD_age{_rh_age_h:.1f}h_cap{_rh_hold_hours:.0f}h_g{_rh_gain:.2f}%_nonneg"
                    except Exception:
                        pass
        if _rh_force:
            _rh_pos_amt = abs(safe_float(getattr(position, "positionAmt", 0)))
            _rh_side = "SELL" if position_side == "LONG" else "BUY"
            logger.error(
                f"🛑 [RIDICULOUS_HOLD_GUARD] {position_key}: {_rh_why} → FORCE CLOSE (regardless of hedge state)"
            )
            try:
                await trade_manager.execute_now(
                    position_key=position_key,
                    account_key=account_key,
                    symbol=symbol,
                    original_positionAmt=_rh_pos_amt,
                    side=_rh_side,
                    position_side=position_side,
                    quantity=_rh_pos_amt,
                    old_price=current_price,
                    unique_id=f"RIDICULOUS_HOLD_{int(time.time())}",
                    reason=_rh_why,
                    is_full_close=True,
                    action="CLOSE",
                )
                trade_manager.processing_keys.discard(position_key)
                return f"{EvalStatus.ACTION_TAKEN}:RIDICULOUS_HOLD_GUARD_CLOSED"
            except Exception as _rh_err:
                logger.error(
                    f"🛑 [RIDICULOUS_HOLD_CLOSE_ERR] {position_key}: {_rh_err}"
                )
    # ═══════════════════════════════════════════════════════════════════════════
    # DC_BB_D_BREAK_REVERSE — USER 2026-05-06 mandate (1000LUNC -18% incident):
    # When Daily DC or BB band BREAKS or CROSSES BACK:
    #   close > dc_high_D_prev OR close > bb_upper_D_prev → break-UP → close SHORT, open LONG
    #   close < dc_low_D_prev  OR close < bb_lower_D_prev → break-DN → close LONG, open SHORT
    # CROSS-BACK reversal (user 2026-05-06 follow-up): track last break direction+level.
    # If last_break='UP' AND close drops back below that level → reverse again (close LONG, open SHORT).
    # ═══════════════════════════════════════════════════════════════════════════
    # 2026-05-18 per-sym overlay
    if (
        position
        and abs(safe_float(getattr(position, "positionAmt", 0))) > 0
        and bool(_psym_get(symbol, position_side, "DC_BB_D_BREAK_REVERSE_ENABLED", True))
    ):
        try:
            _db_ind = await ii(trade_manager, symbol)
        except Exception:
            _db_ind = {}
        if _db_ind:
            _db_close = (
                safe_fetch_float(_db_ind.get("close"), current_price) or current_price
            )
            _db_dc_hi_d = safe_fetch_float(
                _db_ind.get("dc_high_D_prev", _db_ind.get("dc_high_D")), 0
            )
            _db_dc_lo_d = safe_fetch_float(
                _db_ind.get("dc_low_D_prev", _db_ind.get("dc_low_D")), 0
            )
            _db_bb_up_d = safe_fetch_float(_db_ind.get("bb_upper_D"), 0)
            _db_bb_lo_d = safe_fetch_float(_db_ind.get("bb_lower_D"), 0)
            _db_is_long = position_side == "LONG"
            _db_break_up = (_db_dc_hi_d > 0 and _db_close > _db_dc_hi_d) or (
                _db_bb_up_d > 0 and _db_close > _db_bb_up_d
            )
            _db_break_dn = (_db_dc_lo_d > 0 and _db_close < _db_dc_lo_d) or (
                _db_bb_lo_d > 0 and _db_close < _db_bb_lo_d
            )
            # Per-symbol break-state tracking (cross-back detection)
            _db_state = trade_manager.__dict__.setdefault("_dc_bb_d_break_state", {})
            _db_sym_st = _db_state.get(
                symbol, {"last_dir": None, "last_level": 0.0, "last_band": ""}
            )
            _db_cross_back_to_short = False
            _db_cross_back_to_long = False
            if _db_break_up:
                # Update state: last broken UP through this level — record timestamp for 72h continuation window
                _db_lvl = (
                    _db_dc_hi_d
                    if (_db_dc_hi_d > 0 and _db_close > _db_dc_hi_d)
                    else _db_bb_up_d
                )
                _db_band_now = (
                    "DC" if (_db_dc_hi_d > 0 and _db_close > _db_dc_hi_d) else "BB"
                )
                _db_prev_up_ts = _db_sym_st.get("last_up_ts", 0)
                _db_state[symbol] = {
                    "last_dir": "UP",
                    "last_level": _db_lvl,
                    "last_band": _db_band_now,
                    "last_up_ts": _db_prev_up_ts if _db_prev_up_ts > 0 else time.time(),
                    "last_dn_ts": _db_sym_st.get("last_dn_ts", 0),
                }
            elif _db_break_dn:
                _db_lvl = (
                    _db_dc_lo_d
                    if (_db_dc_lo_d > 0 and _db_close < _db_dc_lo_d)
                    else _db_bb_lo_d
                )
                _db_band_now = (
                    "DC" if (_db_dc_lo_d > 0 and _db_close < _db_dc_lo_d) else "BB"
                )
                _db_prev_dn_ts = _db_sym_st.get("last_dn_ts", 0)
                _db_state[symbol] = {
                    "last_dir": "DOWN",
                    "last_level": _db_lvl,
                    "last_band": _db_band_now,
                    "last_up_ts": _db_sym_st.get("last_up_ts", 0),
                    "last_dn_ts": _db_prev_dn_ts if _db_prev_dn_ts > 0 else time.time(),
                }
            else:
                # No fresh break — check cross-back of last-known break level
                # 2026-05-07: hysteresis (DC_BB_CROSSBACK_HYSTERESIS_PCT) prevents hair-trigger flips
                # on tiny consolidations; BB_BREAKOUT_CONT suppresses crossback within 72h of breakout
                _db_hyst = (
                    float(getattr(config, "DC_BB_CROSSBACK_HYSTERESIS_PCT", 2.0))
                    / 100.0
                )
                _db_cont_hrs = float(getattr(config, "BB_BREAKOUT_CONT_HOURS", 72.0))
                _db_cont_on = bool(getattr(config, "BB_BREAKOUT_CONT_ENABLED", True))
                if (
                    _db_sym_st.get("last_dir") == "UP"
                    and _db_sym_st.get("last_level", 0) > 0
                ):
                    _db_cross_level = _db_sym_st["last_level"] * (1.0 - _db_hyst)
                    if _db_close < _db_cross_level:
                        _db_last_up_ts = _db_sym_st.get("last_up_ts", 0)
                        _db_elapsed_h = (
                            (time.time() - _db_last_up_ts) / 3600.0
                            if _db_last_up_ts > 0
                            else 999.0
                        )
                        if (
                            _db_cont_on
                            and _db_last_up_ts > 0
                            and _db_elapsed_h < _db_cont_hrs
                        ):
                            logger.warning(
                                f"🏄 [BB_BREAKOUT_CONT] {position_key}: {_db_elapsed_h:.1f}h/{_db_cont_hrs:.0f}h window → suppressing CROSSBACK_TO_SHORT px={_db_close:.2f} level={_db_sym_st['last_level']:.2f} hyst={_db_hyst * 100:.0f}%"
                            )
                        else:
                            _db_cross_back_to_short = (
                                True  # was UP, now back down → flip to SHORT
                            )
                            _db_state[symbol] = {
                                "last_dir": "DOWN",
                                "last_level": _db_sym_st["last_level"],
                                "last_band": _db_sym_st.get("last_band", "DC"),
                                "last_up_ts": _db_sym_st.get("last_up_ts", 0),
                                "last_dn_ts": time.time(),
                            }
                elif (
                    _db_sym_st.get("last_dir") == "DOWN"
                    and _db_sym_st.get("last_level", 0) > 0
                ):
                    _db_cross_level = _db_sym_st["last_level"] * (1.0 + _db_hyst)
                    if _db_close > _db_cross_level:
                        _db_last_dn_ts = _db_sym_st.get("last_dn_ts", 0)
                        _db_elapsed_h = (
                            (time.time() - _db_last_dn_ts) / 3600.0
                            if _db_last_dn_ts > 0
                            else 999.0
                        )
                        if (
                            _db_cont_on
                            and _db_last_dn_ts > 0
                            and _db_elapsed_h < _db_cont_hrs
                        ):
                            logger.warning(
                                f"🏄 [BB_BREAKOUT_CONT] {position_key}: {_db_elapsed_h:.1f}h/{_db_cont_hrs:.0f}h window → suppressing CROSSBACK_TO_LONG px={_db_close:.2f} level={_db_sym_st['last_level']:.2f}"
                            )
                        else:
                            _db_cross_back_to_long = (
                                True  # was DOWN, now back up → flip to LONG
                            )
                            _db_state[symbol] = {
                                "last_dir": "UP",
                                "last_level": _db_sym_st["last_level"],
                                "last_band": _db_sym_st.get("last_band", "DC"),
                                "last_up_ts": time.time(),
                                "last_dn_ts": _db_sym_st.get("last_dn_ts", 0),
                            }
            # Determine if position is on WRONG side
            #   SHORT during break-UP or cross-back-to-LONG → wrong (should be LONG)
            #   LONG during break-DOWN or cross-back-to-SHORT → wrong (should be SHORT)
            _db_should_be_long = _db_break_up or _db_cross_back_to_long
            _db_should_be_short = _db_break_dn or _db_cross_back_to_short
            _db_wrong = (_db_is_long and _db_should_be_short) or (
                (not _db_is_long) and _db_should_be_long
            )
            # 2026-05-06 ZECUSDC missed-trend incident: don't fight a parabolic move with daily-band cross-back exits.
            # On extreme overbought (LONG) or extreme oversold (SHORT), let the trend run.
            if _db_wrong and bool(
                getattr(config, "PARABOLIC_PROTECTION_ENABLED", True)
            ):
                _pp_r4 = safe_fetch_float(_db_ind.get("rsi_4h", 50), 50)
                _pp_r1 = safe_fetch_float(_db_ind.get("rsi_1h", 50), 50)
                _pp_bb4 = safe_fetch_float(_db_ind.get("bb_pct_b_4h", 0.5), 0.5)
                _pp_up = (
                    _pp_r4 >= float(getattr(config, "PARABOLIC_RSI_4H_MIN", 70.0))
                    and _pp_r1 >= float(getattr(config, "PARABOLIC_RSI_1H_MIN", 65.0))
                    and _pp_bb4
                    >= float(getattr(config, "PARABOLIC_BB_PCT_B_4H_MIN", 0.90))
                )
                _pp_dn = (
                    _pp_r4 <= float(getattr(config, "PARABOLIC_RSI_4H_MAX", 30.0))
                    and _pp_r1 <= float(getattr(config, "PARABOLIC_RSI_1H_MAX", 35.0))
                    and _pp_bb4
                    <= float(getattr(config, "PARABOLIC_BB_PCT_B_4H_MAX", 0.10))
                )
                if (_db_is_long and _pp_up) or ((not _db_is_long) and _pp_dn):
                    logger.warning(
                        f"🌟 [DC_BB_D_BREAK_PARABOLIC_BYPASS] {position_key}: "
                        f"rsi_4h={_pp_r4:.1f} rsi_1h={_pp_r1:.1f} bb_pct_b_4h={_pp_bb4:.2f} "
                        f"→ skipping cross-back close on parabolic {'UP' if _db_is_long else 'DOWN'}trend, let it ride"
                    )
                    _db_wrong = False
            if _db_wrong:
                _db_pos_amt = abs(safe_float(getattr(position, "positionAmt", 0)))
                _db_close_side = "SELL" if _db_is_long else "BUY"
                _db_open_pos_side = "SHORT" if _db_is_long else "LONG"
                _db_open_side = "SELL" if _db_open_pos_side == "SHORT" else "BUY"
                if _db_break_up:
                    _db_event = "BREAK_UP"
                elif _db_break_dn:
                    _db_event = "BREAK_DOWN"
                elif _db_cross_back_to_long:
                    _db_event = "CROSSBACK_TO_LONG"
                elif _db_cross_back_to_short:
                    _db_event = "CROSSBACK_TO_SHORT"
                else:
                    _db_event = "UNKNOWN"
                _db_band = _db_state.get(symbol, {}).get("last_band", "DC")
                logger.error(
                    f"🔄 [DC_BB_D_BREAK_REVERSE] {position_key}: {_db_event} (band={_db_band}) "
                    f"close={_db_close:.6f} dc_hi_D={_db_dc_hi_d:.6f} dc_lo_D={_db_dc_lo_d:.6f} bb_up_D={_db_bb_up_d:.6f} bb_lo_D={_db_bb_lo_d:.6f} "
                    f"→ CLOSE wrong {position_side} + signal opposite"
                )
                try:
                    # 1. Close the wrong-side position
                    await trade_manager.execute_now(
                        position_key=position_key,
                        account_key=account_key,
                        symbol=symbol,
                        original_positionAmt=_db_pos_amt,
                        side=_db_close_side,
                        position_side=position_side,
                        quantity=_db_pos_amt,
                        old_price=current_price,
                        unique_id=f"DC_BB_D_BREAK_{int(time.time())}",
                        reason=f"DC_BB_D_BREAK_REVERSE_close_{_db_band}_{_db_event}",
                        is_full_close=True,
                        action="CLOSE",
                    )
                    # 2. Open opposite side (small foothold — let normal augment scale up).
                    # base_min_qty is defined LATER in process_position; compute inline.
                    _db_base_min_qty = (
                        trade_manager.min_qty.get(symbol, 0.0001)
                        if hasattr(trade_manager, "min_qty")
                        else 0.0001
                    )
                    _db_min_pos_qty = max(
                        config.MIN_POSITION_SIZE / current_price, _db_base_min_qty * 1.2
                    )
                    _db_open_qty = _db_min_pos_qty
                    _db_open_pk = f"{account_key}:{symbol}_{_db_open_pos_side}"
                    await trade_manager.execute_now(
                        position_key=_db_open_pk,
                        account_key=account_key,
                        symbol=symbol,
                        original_positionAmt=0.0,
                        side=_db_open_side,
                        position_side=_db_open_pos_side,
                        quantity=_db_open_qty,
                        old_price=current_price,
                        unique_id=f"DC_BB_D_BREAK_OPEN_{int(time.time())}",
                        reason=f"DC_BB_D_BREAK_REVERSE_open_{_db_band}_{_db_event}",
                        is_full_close=False,
                        action="OPEN",
                    )
                    trade_manager.processing_keys.discard(position_key)
                    return f"{EvalStatus.ACTION_TAKEN}:DC_BB_D_BREAK_REVERSED"
                except Exception as _db_err:
                    logger.error(
                        f"🔄 [DC_BB_D_BREAK_REVERSE_ERR] {position_key}: {_db_err}"
                    )
    # ═══════════════════════════════════════════════════════════════════════════
    # UNDERWATER_HEDGE_OR_CLOSE — User 2026-05-05 mandate (loss prevention):
    # If position pnl<0 AND wt1_3m flipped against trade AND no active hedge → fire hedge.
    # If hedge already active → close primary IMMEDIATELY (don't let it bleed further).
    # Signal-driven (wt1_3m flip), not %-based — so this is NOT a fixed-% stop loss.
    # Replicated in backtest_v8_engine + ez_positions_quick for sandbox parity.
    # ═══════════════════════════════════════════════════════════════════════════
    _uh_cd_dict = trade_manager.__dict__.setdefault("_underwater_safety_cooldown", {})
    _uh_cd_sec = float(getattr(config, "UNDERWATER_HEDGE_OR_CLOSE_COOLDOWN_SEC", 60.0))
    _uh_recent = (now_ts - _uh_cd_dict.get(position_key, 0)) < _uh_cd_sec
    if (
        not _uh_recent
        and position
        and abs(safe_float(getattr(position, "positionAmt", 0))) > 0
        and bool(getattr(config, "UNDERWATER_HEDGE_OR_CLOSE_ENABLED", True))
    ):
        _uh_gain = safe_fetch_float(getattr(position, "gain", 0), 0)
        if _uh_gain < 0:
            try:
                _uh_ind = await ii(trade_manager, symbol)
            except Exception:
                _uh_ind = {}
            if _uh_ind:
                _uh_w1_15m = safe_fetch_float(_uh_ind.get("wt1_15m"), 0)
                _uh_w2_15m = safe_fetch_float(_uh_ind.get("wt2_15m"), 0)
                _uh_is_long = position_side == "LONG"
                _uh_against_15m = (
                    (_uh_w1_15m < _uh_w2_15m)
                    if _uh_is_long
                    else (_uh_w1_15m > _uh_w2_15m)
                )
                _uh_thr = float(
                    getattr(config, "MANDATORY_HEDGE_GAIN_THRESHOLD_PCT", -0.5)
                )
                # Hedge-fire: gain < -0.5% AND wt1_15m against (HEDGE_BANDAID_BACKTEST winner).
                # Force-close: hedge already active AND 2/4 HTF (15m/1h/4h/D) agree WT against.
                # NEVER close on wt1_3m alone — 3m is too noisy; HTF agreement required.
                if _uh_against_15m and (_uh_w1_15m != 0 or _uh_w2_15m != 0):
                    _uh_tm = getattr(trade_manager, "tracker_manager", None)
                    _he_inflight = getattr(
                        getattr(trade_manager, "hedge_engine", None),
                        "_hedge_same_in_flight",
                        set(),
                    )
                    _uh_active = (
                        bool(_uh_tm)
                        and any(
                            (
                                h.get("losing_position_key") == position_key
                                or h.get("hedge_for") == position_key
                            )
                            for h in (_uh_tm.active_hedges or [])
                        )
                    ) or (position_key in _he_inflight)
                    _uh_pos_amt = abs(safe_float(getattr(position, "positionAmt", 0)))
                    _uh_cd_dict[position_key] = (
                        now_ts  # mark fired (cooldown for next 60s)
                    )
                    if not _uh_active and _uh_gain < _uh_thr:
                        logger.warning(
                            f"⚠️ [UNDERWATER_HEDGE_FIRE] {position_key}: gain={_uh_gain:.2f}% wt1_15m={_uh_w1_15m:.1f} {'<' if _uh_is_long else '>'} wt2_15m={_uh_w2_15m:.1f} → FIRING HEDGE"
                        )
                        try:
                            _he = getattr(trade_manager, "hedge_engine", None)
                            if _he is not None:
                                await _he.execute_same_symbol_hedge(
                                    account_key,
                                    position,
                                    symbol,
                                    position_side,
                                    _uh_pos_amt,
                                    current_price,
                                )
                                trade_manager.processing_keys.discard(position_key)
                                return (
                                    f"{EvalStatus.ACTION_TAKEN}:UNDERWATER_HEDGE_FIRED"
                                )
                            else:
                                logger.error(
                                    f"⚠️ [UNDERWATER_HEDGE_NO_ENGINE] {position_key}: no hedge_engine — falling through to close"
                                )
                                _uh_force_close = True
                        except Exception as _uh_he_err:
                            logger.error(
                                f"⚠️ [UNDERWATER_HEDGE_FIRE_ERR] {position_key}: {type(_uh_he_err).__name__}: {_uh_he_err} — falling through to close"
                            )
                            _uh_force_close = True
                    elif _uh_active:
                        # Hedge covers. Only force-close origin if ≥2 of 4 HTF (15m/1h/4h/D) agree WT against.
                        # USDC maker bypass: reenter is zero-fee maker, so 3m signal alone is acceptable.
                        _uh_htf_pairs = [
                            ("wt1_15m", "wt2_15m"),
                            ("wt1_1h", "wt2_1h"),
                            ("wt1_4h", "wt2_4h"),
                            ("wt1_D", "wt2_D"),
                        ]
                        _uh_htf_count = 0
                        for _uhh1_k, _uhh2_k in _uh_htf_pairs:
                            _uhh1 = safe_fetch_float(_uh_ind.get(_uhh1_k), 0)
                            _uhh2 = safe_fetch_float(_uh_ind.get(_uhh2_k), 0)
                            if _uhh1 == 0 and _uhh2 == 0:
                                continue
                            if (_uh_is_long and _uhh1 < _uhh2) or (
                                not _uh_is_long and _uhh1 > _uhh2
                            ):
                                _uh_htf_count += 1
                        _uh_htf_req = int(
                            getattr(
                                config,
                                "UNDERWATER_HEDGE_OR_CLOSE_HTF_CLOSE_REQUIRED",
                                2,
                            )
                        )
                        _uh_usdc_bypass = (
                            symbol.endswith("USDC")
                            and bool(
                                getattr(config, "MICRO_SCALP_USDC_MAKER_ENABLED", False)
                            )
                            and bool(
                                getattr(
                                    config, "UNDERWATER_HOC_USDC_MAKER_BYPASS", True
                                )
                            )
                        )
                        if _uh_usdc_bypass or _uh_htf_count >= _uh_htf_req:
                            _uh_force_close = True
                            logger.warning(
                                f"⚠️ [UNDERWATER_HEDGED_FORCE_CLOSE] {position_key}: gain={_uh_gain:.2f}% wt1_15m={_uh_w1_15m:.1f}/{_uh_w2_15m:.1f} hedge active {'USDC_MAKER_BYPASS' if _uh_usdc_bypass else f'HTF {_uh_htf_count}/4 >= {_uh_htf_req}'} → FORCE CLOSE"
                            )
                        else:
                            logger.info(
                                f"[UNDERWATER_HEDGED_HOLD] {position_key}: gain={_uh_gain:.2f}% wt1_15m against but {_uh_htf_count}/4 HTF agree (need {_uh_htf_req}) — holding, hedge covers"
                            )
                    if locals().get("_uh_force_close"):
                        _uh_side = "SELL" if position_side == "LONG" else "BUY"
                        try:
                            await trade_manager.execute_now(
                                position_key=position_key,
                                account_key=account_key,
                                symbol=symbol,
                                original_positionAmt=_uh_pos_amt,
                                side=_uh_side,
                                position_side=position_side,
                                quantity=_uh_pos_amt,
                                old_price=current_price,
                                unique_id=f"UNDERWATER_HOC_{int(time.time())}",
                                reason=f"UNDERWATER_HEDGE_OR_CLOSE_wt15m{_uh_w1_15m:.1f}vs{_uh_w2_15m:.1f}_g{_uh_gain:.2f}%",
                                is_full_close=True,
                                action="CLOSE",
                            )
                            trade_manager.processing_keys.discard(position_key)
                            return f"{EvalStatus.ACTION_TAKEN}:UNDERWATER_HEDGE_OR_CLOSE_CLOSED"
                        except Exception as _uh_cl_err:
                            logger.error(
                                f"⚠️ [UNDERWATER_FORCE_CLOSE_ERR] {position_key}: {_uh_cl_err}"
                            )
    # 2026-04-27 — WIRE evaluate_reentry (was dead code at line 16593, never called).
    # 683 reentry mentions / 0 executions today across 5 crypto accounts. The compact 7-block
    # function (B15/B04/B11/B02/B12/B14/B10) is ablation-tested and returns Signal(action='REENTRY').
    # Gated by EVAL_REENTRY_ENABLED (default True). Per user: "Test the difference (huge functions
    # so augments backtest times by up to 50% but if it works it works)".
    # Function self-gates on position_value <= 2*MIN_POSITION_SIZE so it only fires for fresh-flat or
    # partially-reduced positions. NO_DOUBLE_OPEN guard naturally allows because execute_now
    # reclassifies REENTRY → OPEN (positionAmt=0) or AUGMENT (positionAmt>min_pos).
    if (
        bool(getattr(config, "EVAL_REENTRY_ENABLED", True))
        and bool(getattr(config, "EZ_REENTRY_INLINE_ENABLED", True))
        and bool(getattr(config, "EZ_REENTRY_INLINE_EVAL2_DIRECT_ENABLED", True))
    ):
        try:
            _re_ctx = {
                "config": config,
                "logger": logger,
                "position_key": position_key,
                "symbol": symbol,
                "account_key": account_key,
                "trade_manager": trade_manager,
                "position_side": position_side,
                "current_price": current_price,
                "mark_price": current_price,
            }
            _re_signal = await evaluate_reentry(_re_ctx)
            if _re_signal and getattr(_re_signal, "action", None) == "REENTRY":
                _re_qty = float(getattr(_re_signal, "quantity", 0) or 0)
                _re_reason = getattr(_re_signal, "reason", "EVAL_REENTRY_FIRED")
                if _re_qty > 0:
                    _re_side = "BUY" if position_side == "LONG" else "SELL"
                    logger.warning(
                        f"[EVAL_REENTRY_FIRED] {position_key}: {_re_reason} qty={_re_qty:.6f}"
                    )
                    await trade_manager.execute_now(
                        position_key=position_key,
                        account_key=account_key,
                        symbol=symbol,
                        original_positionAmt=0.0,
                        side=_re_side,
                        position_side=position_side,
                        quantity=_re_qty,
                        old_price=current_price,
                        unique_id=f"EVAL_REENTRY_{int(time.time())}",
                        reason=_re_reason,
                        is_full_close=False,
                        action="REENTRY",
                    )
                    trade_manager.processing_keys.discard(position_key)
                    return f"{EvalStatus.NO_ACTION}:EVAL_REENTRY_QUEUED"
        except Exception as _re_e:
            logger.warning(
                f"[EVAL_REENTRY_ERR] {position_key}: {type(_re_e).__name__}: {_re_e}"
            )
    age_pr = -1
    if price_ts:
        if isinstance(price_ts, datetime):
            if price_ts.tzinfo is None:
                price_ts = price_ts.replace(tzinfo=timezone.utc)
            age_pr = (now - price_ts).total_seconds()
    base_min_qty = trade_manager.min_qty.get(symbol, 0.0001)
    pos_min_qty = max(config.MIN_POSITION_SIZE / current_price, base_min_qty * 1.2)
    last_augmentation_time = (
        getattr(position, "last_augmentation_time", None)
        if hasattr(position, "last_augmentation_time")
        else None
    )
    if isinstance(last_augmentation_time, str):
        try:
            parsed = isoparse(last_augmentation_time)
            last_augmentation_time = (
                parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)
            )
        except Exception:
            last_augmentation_time = None
    min_since_aug = (
        (now - last_augmentation_time).total_seconds() / 60.0
        if last_augmentation_time
        else 999999.0
    )
    try:
        ak, symbol, position_side = parse_position_key(position_key)
        # ═══ 2026-04-26 HEDGE_CLOSE PRE-GATE — runs BEFORE symbol_allowed/leaderboard ═══
        # Hedges may sit on symbols not in tradeable_keys (cross-symbol elected hedges) or
        # outside the leaderboard. Without this pre-gate, process_position returns
        # SYMBOL_NOT_ALLOWED and the wt_3m+wt_1h close never fires for those hedges.
        # Detection: position.is_hedge attribute OR membership in tracker_manager.active_hedges.
        try:
            _hg_pos = (
                position
                if (
                    position
                    and abs(safe_fetch_float(getattr(position, "positionAmt", 0), 0))
                    > 0
                )
                else None
            )
            if _hg_pos is None:
                _hg_pos = await trade_manager.get_position(position_key)
            _hg_amt = (
                abs(safe_fetch_float(getattr(_hg_pos, "positionAmt", 0), 0))
                if _hg_pos
                else 0
            )
            if _hg_pos and _hg_amt > 0:
                _is_hedge_attr = bool(getattr(_hg_pos, "is_hedge", False))
                _is_hedge_tracker = False
                _hedge_for_tracker = None
                try:
                    for _h in getattr(tracker_manager, "active_hedges", None) or []:
                        if (
                            isinstance(_h, dict)
                            and _h.get("position_key") == position_key
                        ):
                            _is_hedge_tracker = True
                            _hedge_for_tracker = _h.get(
                                "losing_position_key"
                            ) or _h.get("hedge_for")
                            break
                except Exception:
                    pass
                if _is_hedge_attr or _is_hedge_tracker:
                    _hg_i = await ii(trade_manager, symbol)
                    if _hg_i:
                        _hg_long = position_key.endswith("_LONG")
                        # 2026-04-27 USER ABSOLUTE: gain/mark_price/positionAmt MUST NEVER be stale.
                        # If service data is older than LIVE_POSITION_FRESHNESS_MAX_SEC, FORCE-REFRESH from
                        # fallback sources (positions_service.fetch_positions = Binance API), then re-fetch position.
                        # NEVER bail on staleness — positions data is the LIFELINE.
                        _max_age = float(
                            getattr(config, "LIVE_POSITION_FRESHNESS_MAX_SEC", 3.0)
                        )
                        _now_epoch = time.time()

                        def _hg_age_of(_pos, _field):
                            _raw = getattr(_pos, _field, None)
                            if _raw is None:
                                return 9999.0
                            try:
                                _dt = isoparse(_raw) if isinstance(_raw, str) else _raw
                                if hasattr(_dt, "timestamp"):
                                    return _now_epoch - _dt.timestamp()
                            except Exception:
                                pass
                            return 9999.0

                        _hg_pos_age = _hg_age_of(_hg_pos, "last_updated")
                        _hg_mp_age = _hg_age_of(_hg_pos, "mark_price_last_updated")
                        if max(_hg_pos_age, _hg_mp_age) > _max_age:
                            logger.warning(
                                f"⏰ [HEDGE_FRESHNESS_REFRESH] {position_key}: pos_age={_hg_pos_age:.1f}s mp_age={_hg_mp_age:.1f}s > {_max_age}s — FORCE-REFRESHING from API"
                            )
                            try:
                                _ps = getattr(trade_manager, "positions_service", None)
                                if _ps and hasattr(_ps, "fetch_positions"):
                                    await asyncio.wait_for(
                                        _ps.fetch_positions(account_key), timeout=8.0
                                    )
                                _hg_pos = (
                                    await trade_manager.get_position(position_key)
                                    or _hg_pos
                                )
                                _hg_pos_age = _hg_age_of(_hg_pos, "last_updated")
                                _hg_mp_age = _hg_age_of(
                                    _hg_pos, "mark_price_last_updated"
                                )
                                logger.warning(
                                    f"⏰ [HEDGE_FRESHNESS_REFRESHED] {position_key}: post-refresh pos_age={_hg_pos_age:.1f}s mp_age={_hg_mp_age:.1f}s"
                                )
                            except Exception as _rf_e:
                                logger.error(
                                    f"⏰ [HEDGE_FRESHNESS_REFRESH_ERR] {position_key}: {type(_rf_e).__name__}: {_rf_e} — proceeding with last-known data (logged for diagnostic)"
                                )
                            # Even if refresh failed, proceed using current_price for real_gain calc — the recompute below already uses current_price (live), so the close decision is based on live price not stale gain field.
                        # 2026-04-27 (C98USDT incident): position.gain field is sometimes stale relative to live current_price.
                        # Recompute REAL gain from entry_price + current_price NOW so the NOLOSS gate doesn't trust stale +0.55% when actual is -1.27%.
                        _hg_entry_px = safe_fetch_float(
                            getattr(_hg_pos, "entry_price", 0), 0
                        )
                        _hg_stale_gain = safe_fetch_float(
                            getattr(_hg_pos, "gain", 0), 0
                        )
                        if _hg_entry_px > 0 and current_price > 0:
                            if _hg_long:
                                _hg_real_gain = (
                                    (current_price - _hg_entry_px) / _hg_entry_px
                                ) * 100.0
                            else:
                                _hg_real_gain = (
                                    (_hg_entry_px - current_price) / _hg_entry_px
                                ) * 100.0
                        else:
                            _hg_real_gain = _hg_stale_gain
                        # Use the WORSE of stale-gain and real-gain so we never close at a hidden loss.
                        _hg_gain = min(_hg_stale_gain, _hg_real_gain)
                        # ═══ 2026-04-30 USER ABSOLUTE: wt_15m flip closes hedge FIRST, NO P/L gate ═══
                        # User: "CLOSE the hedge when wt_15m goes against it. Same as last 500 years."
                        # The 3m+1h NOLOSS_HOLD check below RETURNS early from process_position when
                        # hedge is at a loss — stopping all subsequent close logic (including the
                        # BANDAID_OFF block in ez_positions_quick.monitor_and_manage_hedges, which is
                        # in a separate loop). Hoist the wt_15m close check ABOVE the 3m+1h block so
                        # losing hedges with wt_15m flipped against them DO close.
                        if getattr(config, "HEDGE_BANDAID_OFF_ENABLED", False):
                            _hg_losing_pk = (
                                _hedge_for_tracker
                                or getattr(_hg_pos, "hedge_for", None)
                                or position_key
                            )
                            try:
                                _, _hg_losing_sym, _hg_losing_side = (
                                    _hg_losing_pk.split(":")[0],
                                    _hg_losing_pk.split(":")[1].rsplit("_", 1)[0],
                                    _hg_losing_pk.rsplit("_", 1)[1],
                                )
                            except Exception:
                                _hg_losing_sym = symbol
                                _hg_losing_side = "SHORT" if _hg_long else "LONG"
                            _hg_losing_is_long = _hg_losing_side == "LONG"
                            # Same-symbol hedge: 15m WT is in _hg_i. Cross-symbol: would need separate fetch.
                            _hg_w1_15m = safe_fetch_float(_hg_i.get("wt1_15m"), 0)
                            _hg_w2_15m = safe_fetch_float(_hg_i.get("wt2_15m"), 0)
                            _hg_w1_3m = safe_fetch_float(_hg_i.get("wt1_3m"), 0)
                            _hg_w2_3m = safe_fetch_float(_hg_i.get("wt2_3m"), 0)
                            _hg_favors_origin = (
                                _hg_losing_is_long and _hg_w1_15m > _hg_w2_15m
                            ) or (not _hg_losing_is_long and _hg_w1_15m < _hg_w2_15m)
                            # User 2026-05-05: do NOT nuke the hedge while wt_3m STILL agrees with
                            # the hedge AND origin still in loss — this is the rule that prevented
                            # 1000LUNCUSDT from re-bleeding when its hedge got killed at 0.16% gain.
                            _hg_3m_with_hedge = (
                                _hg_losing_is_long and _hg_w1_3m < _hg_w2_3m
                            ) or (not _hg_losing_is_long and _hg_w1_3m > _hg_w2_3m)
                            try:
                                _hg_origin_pos = (
                                    trade_manager.positions.get(_hg_losing_pk)
                                    if hasattr(trade_manager, "positions")
                                    else None
                                )
                                _hg_origin_g = (
                                    safe_fetch_float(
                                        getattr(_hg_origin_pos, "gain", 0), 0
                                    )
                                    if _hg_origin_pos
                                    else 0.0
                                )
                            except Exception:
                                _hg_origin_g = 0.0
                            _hg_origin_in_loss = _hg_origin_g < float(
                                getattr(config, "BANDAID_OFF_LOSER_RECOVER_PCT", -0.25)
                            )
                            _hg_require_3m_flip = bool(
                                getattr(
                                    config, "HEDGE_BANDAID_OFF_REQUIRE_WT_3M_FLIP", True
                                )
                            )
                            if (
                                _hg_require_3m_flip
                                and _hg_3m_with_hedge
                                and _hg_origin_in_loss
                                and (_hg_w1_3m != 0 or _hg_w2_3m != 0)
                            ):
                                logger.info(
                                    f"🛡️ [HEDGE_BANDAID_OFF_FIRST_PRE_BLOCKED] {position_key}: wt_15m flipped ({_hg_w1_15m:.1f}/{_hg_w2_15m:.1f}) BUT wt_3m still with hedge ({_hg_w1_3m:.1f}/{_hg_w2_3m:.1f}) AND origin still losing g={_hg_origin_g:.2f}% — HOLDING."
                                )
                                _hg_favors_origin = False
                            if _hg_favors_origin and (
                                _hg_w1_15m != 0 or _hg_w2_15m != 0
                            ):
                                _hg_ord_side_first = "SELL" if _hg_long else "BUY"
                                _hg_pos_side_first = "LONG" if _hg_long else "SHORT"
                                logger.warning(
                                    f"🩹 [HEDGE_BANDAID_OFF_FIRST_PRE] {position_key}: 15m WT favors origin {_hg_losing_pk} (wt1={_hg_w1_15m:.1f} wt2={_hg_w2_15m:.1f} {'BULL' if _hg_losing_is_long else 'BEAR'}). Hedge gain={_hg_gain:.2f}%. NUKING (NO P/L gate, hoisted above 3m+1h NOLOSS_HOLD)."
                                )
                                try:
                                    await trade_manager.execute_now(
                                        position_key,
                                        account_key,
                                        symbol,
                                        _hg_amt,
                                        _hg_ord_side_first,
                                        _hg_pos_side_first,
                                        _hg_amt,
                                        current_price,
                                        f"HEDGE_BANDAID_OFF_FIRST_{int(time.time())}",
                                        f"HEDGE_BANDAID_OFF_FIRST_PRE_wt15m_{_hg_w1_15m:.1f}vs{_hg_w2_15m:.1f}_hgain{_hg_gain:.2f}%",
                                        True,
                                        "CLOSE",
                                        is_hedge=True,
                                        hedge_for=_hg_losing_pk,
                                    )
                                finally:
                                    trade_manager.processing_keys.discard(position_key)
                                return f"{EvalStatus.NO_ACTION}:HEDGE_BANDAID_OFF_FIRST_PRE"
                        _hg_decision = _hd.should_close_hedge_wt3m1h(
                            _hg_i, _hg_long, _hg_gain, config
                        )
                        if _hg_decision is not None:
                            _hg_w13 = _hg_decision["wt"]["wt1_3m"]
                            _hg_w23 = _hg_decision["wt"]["wt2_3m"]
                            _hg_w11 = _hg_decision["wt"]["wt1_1h"]
                            _hg_w21 = _hg_decision["wt"]["wt2_1h"]
                            _hg_ord_side = "SELL" if _hg_long else "BUY"
                            _hg_pos_side = "LONG" if _hg_long else "SHORT"
                            _hg_hedge_for = (
                                getattr(_hg_pos, "hedge_for", None)
                                or _hedge_for_tracker
                                or position_key
                            )
                            if not _hg_decision["fire"]:
                                logger.warning(
                                    f"🛡️ [HEDGE_CLOSE_WT3M1H_PRE_GATE_NOLOSS_HOLD] {position_key}: wt_3m={_hg_w13:.1f}/{_hg_w23:.1f} AND wt_1h={_hg_w11:.1f}/{_hg_w21:.1f} against {_hg_pos_side} hedge but min(stale={_hg_stale_gain:.2f}%, real={_hg_real_gain:.2f}%)={_hg_gain:.2f}% < 0 — STRICT_NO_LOSS, holding hedge."
                                )
                                return f"{EvalStatus.NO_ACTION}:HEDGE_CLOSE_WT3M1H_PRE_GATE_NOLOSS_HOLD"
                            logger.critical(
                                f"🛑 [HEDGE_CLOSE_WT3M1H_PRE_GATE] {position_key}: wt_3m={_hg_w13:.1f}/{_hg_w23:.1f} AND wt_1h={_hg_w11:.1f}/{_hg_w21:.1f} against {_hg_pos_side} hedge — pre-gate close (stale_gain={_hg_stale_gain:.2f}% real_gain={_hg_real_gain:.2f}%, attr={_is_hedge_attr}, tracker={_is_hedge_tracker})."
                            )
                            try:
                                await trade_manager.execute_now(
                                    position_key,
                                    account_key,
                                    symbol,
                                    _hg_amt,
                                    _hg_ord_side,
                                    _hg_pos_side,
                                    _hg_amt,
                                    current_price,
                                    f"HEDGE_WT3M1H_PRE_{int(time.time())}",
                                    f"HEDGE_CLOSE_WT3M1H_PRE_GATE_3m={_hg_w13:.1f}/{_hg_w23:.1f}_1h={_hg_w11:.1f}/{_hg_w21:.1f}_gain={_hg_gain:.2f}%",
                                    True,
                                    "CLOSE",
                                    is_hedge=True,
                                    hedge_for=_hg_hedge_for,
                                )
                            finally:
                                trade_manager.processing_keys.discard(position_key)
                            return f"{EvalStatus.NO_ACTION}:HEDGE_CLOSE_WT3M1H_PRE_GATE"
        except Exception as _hge:
            logger.debug(
                f"[HEDGE_CLOSE_WT3M1H_PRE_GATE] {position_key}: pre-gate check failed: {_hge}"
            )
        if not force and not trade_manager.is_symbol_allowed(
            account_key, symbol, position_key
        ):
            logger.info(
                f"[{position_key}] process_position REJECTED: Symbol not allowed (force={force})"
            )
            return f"{EvalStatus.NO_ACTION}:SYMBOL_NOT_ALLOWED"
        if (
            not force
            and getattr(trade_manager.config, "LEADERBOARD_FILTER", True)
            and not _check_leaderboard_allowed(
                trade_manager, symbol, position_side, account_key, position_key
            )
        ):
            logger.info(
                f"[{position_key}] process_position REJECTED: Not in leaderboard (force={force})"
            )
            return f"{EvalStatus.NO_ACTION}:NOT_IN_LEADERBOARD"
        indicator_guard_ctx = {
            "trade_manager": trade_manager,
            "symbol": symbol,
            "logger": logger,
            "position_key": position_key,
            "account_key": account_key,
            "config": config,
        }
        i = await ii(trade_manager, symbol)
        if not i:
            logger.warning(
                f"[{position_key}] No indicator data available for {symbol} - skipping position processing"
            )
            try:
                await symbol_tracker.track_completion(
                    position_key, "NO_ACTION:NO_INDICATOR_DATA"
                )
            except Exception as e:
                logger.warning(f"[{position_key}] Error tracking completion: {e}")
            return f"{EvalStatus.NO_ACTION}:NO_INDICATOR_DATA"
        (
            sma_200_1m,
            ha_3m,
            ha_15m,
            k_3m,
            k_3m_prev,
            d_3m,
            atr_3m,
            atr_3m_prev,
            k_15m,
            d_15m,
            k_15m_prev,
            k_1h,
            d_1h,
            k_1h_prev,
            k_4h,
            d_4h,
            k_4h_prev,
            t_up_3m,
            t_up_15m,
            timestamp_3m,
            wt1_3m,
            wt2_3m,
            low_3m,
            low_3m_prev,
            high_3m,
            high_3m_prev,
            dc_low_15m,
            dc_low_1h,
            dc_low_4h,
            dc_high_15m,
            dc_high_1h,
            dc_high_4h,
        ) = (
            i.get("sma_200_1m", 0.0),
            i.get("ha_3m", "neutral"),
            i.get("ha_15m", "neutral"),
            i.get("stoch_k_3m", 50.0),
            i.get("k_3m_prev", 50.0),
            i.get("stoch_d_3m", 50.0),
            i.get("atr_3m", 0.0),
            i.get("atr_3m_prev", 0.0),
            i.get("stoch_k_15m", 50.0),
            i.get("stoch_d_15m", 50.0),
            i.get("stoch_k_15m_prev", 50.0),
            i.get("stoch_k_1h", 50.0),
            i.get("stoch_d_1h", 50.0),
            i.get("stoch_k_1h_prev", 50.0),
            i.get("stoch_k_4h", 50.0),
            i.get("stoch_d_4h", 50.0),
            i.get("stoch_k_4h_prev", 50.0),
            i.get("t_up_3m", False),
            i.get("t_up_15m", True),
            i.get("timestamp_3m"),
            i.get("wt1_3m", 0.0),
            i.get("wt2_3m", 0.0),
            i.get("low_3m", 0.0),
            i.get("low_3m_prev", 0.0),
            i.get("high_3m", 0.0),
            i.get("high_3m_prev", 0.0),
            i.get("dc_low_15m", 0.0),
            i.get("dc_low_1h", 0.0),
            i.get("dc_low_4h", 0.0),
            i.get("dc_high_15m", 0.0),
            i.get("dc_high_1h", 0.0),
            i.get("dc_high_4h", 0.0),
        )
        (
            stoch_k_1m,
            stoch_d_1m,
            stoch_k_3m,
            stoch_d_3m,
            stoch_k_15m,
            stoch_d_15m,
            timestamp_1m,
            timestamp_3m,
            timestamp_15m,
        ) = (
            i.get("stoch_k_1m"),
            i.get("stoch_d_1m"),
            i.get("stoch_k_3m"),
            i.get("stoch_d_3m"),
            i.get("stoch_k_15m"),
            i.get("stoch_d_15m"),
            i.get("timestamp_1m"),
            i.get("timestamp_3m"),
            i.get("timestamp_15m"),
        )
        dc_high4_3m = safe_fetch_float(i.get("dc_high4_3m"), 0.0)
        dc_low4_3m = safe_fetch_float(i.get("dc_low4_3m"), 0.0)
        dc_high_3m = safe_fetch_float(i.get("dc_high_3m"), 0.0)
        dc_low_3m = safe_fetch_float(i.get("dc_low_3m"), 0.0)
        dc_basis_15m = safe_fetch_float(i.get("dc_basis_15m"), 0.0)
        k_1m = safe_fetch_float(stoch_k_1m, 50.0)
        k_1m_prev = safe_fetch_float(i.get("k_1m_prev"), 50.0)
        d_1m = safe_fetch_float(stoch_d_1m, 50.0)
        stoch_k_3m = k_3m
        stoch_d_3m = d_3m
        stoch_k_15m = k_15m
        stoch_d_15m = d_15m

        def get_age(ts_val, ref_now):
            dt = safe_datetime(ts_val)
            return (ref_now - dt).total_seconds() if dt else -1

        age_1m = get_age(timestamp_1m, now)
        age_3m = get_age(timestamp_3m, now)
        age_15m = get_age(timestamp_15m, now)
        is_active_position = False
        position = await trade_manager.get_position(position_key)
        if position:
            amt = abs(safe_fetch_float(getattr(position, "positionAmt", 0.0), 0.0))
            if amt > pos_min_qty:
                is_active_position = True
        if not is_active_position:
            pass  # Entry gates moved to rate() and evaluate functions — process_position must reach ALL evaluators
        logger.info(
            f"👂👂{position_key} {current_price}: k_1m:{stoch_k_1m}, d_1m:{stoch_d_1m}, k_3m:{stoch_k_3m}, d_3m:{stoch_d_3m}, k_15m:{stoch_k_15m}, d_15m:{stoch_d_15m}, age_1m:{age_1m}, age_3m:{age_3m},age_15m:{age_15m}, age_pr:{age_pr}"
        )
        # ═══ 2026-04-26 USER RULE — MICRO_SCALP_USDC_MAKER ═══
        # USDC-only, maker-only micro-scalper. Closes at gain >= MICRO_SCALP_GAIN_THRESHOLD AND gain < prev_gain
        # (first deceleration past threshold). On flat-after-close, reopens when price re-crosses exit_price.
        # NO webhook fallback — if place_maker_order doesn't fill, just retry next cycle.
        # USDC pairs have zero maker fees on Binance Futures, so 0.02% gross == 0.02% net.
        if (
            bool(getattr(config, "MICRO_SCALP_USDC_MAKER_ENABLED", True))
            and symbol.endswith("USDC")
            and account_key
            in (getattr(config, "MICRO_SCALP_USDC_ACCOUNTS", None) or ["inf"])
        ):
            try:
                _ms_state_dict = getattr(trade_manager, "_micro_scalp_state", None)
                if _ms_state_dict is None:
                    trade_manager._micro_scalp_state = {}
                    _ms_state_dict = trade_manager._micro_scalp_state
                _ms_st = _ms_state_dict.get(position_key, {})
                _ms_pos_amt = (
                    abs(safe_fetch_float(getattr(position, "positionAmt", 0.0), 0.0))
                    if position
                    else 0.0
                )
                _ms_threshold = float(
                    getattr(config, "MICRO_SCALP_GAIN_THRESHOLD_PCT", 0.02)
                )
                _ms_long = position_key.endswith("_LONG")
                # CLOSE branch — active position, gain past threshold AND first decel
                if _ms_pos_amt > pos_min_qty and current_price > 0:
                    _ms_gain = safe_fetch_float(getattr(position, "gain", 0), 0)
                    _ms_prev = float(_ms_st.get("prev_gain", _ms_gain))
                    if _ms_gain >= _ms_threshold and _ms_gain < _ms_prev:
                        _ms_close_side = "SELL" if _ms_long else "BUY"
                        _ms_uid = f"MS_USDC_CLOSE_{int(time.time() * 1000)}"
                        _ms_reason = f"MICRO_SCALP_USDC_CLOSE_g{_ms_gain:.3f}%_prev{_ms_prev:.3f}%"
                        logger.critical(
                            f"⚡ [MICRO_SCALP_USDC_CLOSE] {position_key}: gain={_ms_gain:.3f}% < prev={_ms_prev:.3f}% (threshold={_ms_threshold}%) — execute_now close"
                        )
                        _ms_result = await trade_manager.execute_now(
                            position_key,
                            account_key,
                            symbol,
                            _ms_pos_amt,
                            _ms_close_side,
                            position_side,
                            _ms_pos_amt,
                            current_price,
                            _ms_uid,
                            _ms_reason,
                            True,
                            "QUICK_CLOSE",
                        )
                        _ms_ok = "SUCCESS" in str(_ms_result or "").upper()
                        _ms_filled = _ms_pos_amt if _ms_ok else 0.0
                        if _ms_ok:
                            logger.critical(
                                f"✅ [MICRO_SCALP_USDC_CLOSED] {position_key}: filled qty={_ms_filled} at ${current_price:.6f}. Pending reopen on price re-cross of exit."
                            )
                            _ms_state_dict[position_key] = {
                                "prev_gain": 0.0,
                                "exit_price": current_price,
                                "reopen_pending": True,
                                "original_side": position_side,
                                "original_qty": _ms_pos_amt,
                            }
                            trade_manager.processing_keys.discard(position_key)
                            return f"{EvalStatus.ACTION_TAKEN}:MICRO_SCALP_USDC_CLOSE"
                        else:
                            logger.warning(
                                f"⏸️ [MICRO_SCALP_USDC_CLOSE_RETRY] {position_key}: maker did not fill (ok={_ms_ok} filled={_ms_filled}). NO webhook fallback — will retry next cycle."
                            )
                    # Track prev_gain regardless of fire — for next-cycle decel detection
                    _ms_st_new = dict(_ms_st)
                    _ms_st_new["prev_gain"] = _ms_gain
                    _ms_state_dict[position_key] = _ms_st_new
                # REOPEN branch — flat position, prior close pending, price re-crossed exit
                elif (
                    _ms_pos_amt <= pos_min_qty
                    and _ms_st.get("reopen_pending", False)
                    and current_price > 0
                ):
                    _ms_exit_px = float(_ms_st.get("exit_price", 0) or 0)
                    _ms_orig_side = str(_ms_st.get("original_side", "") or "")
                    _ms_orig_qty = float(_ms_st.get("original_qty", 0) or 0)
                    if _ms_exit_px > 0 and _ms_orig_qty > 0:
                        _ms_orig_long = _ms_orig_side == "LONG"
                        _ms_crossed = (
                            _ms_orig_long and current_price <= _ms_exit_px
                        ) or ((not _ms_orig_long) and current_price >= _ms_exit_px)
                        if _ms_crossed:
                            _ms_open_side = "BUY" if _ms_orig_long else "SELL"
                            _ms_uid = f"MS_USDC_REOPEN_{int(time.time() * 1000)}"
                            _ms_reason = f"MICRO_SCALP_USDC_REOPEN_exit{_ms_exit_px:.6f}_now{current_price:.6f}"
                            logger.critical(
                                f"⚡ [MICRO_SCALP_USDC_REOPEN] {position_key}: price {current_price:.6f} re-crossed exit {_ms_exit_px:.6f} ({_ms_orig_side}) — execute_now open qty={_ms_orig_qty:.6f}"
                            )
                            _ms_result = await trade_manager.execute_now(
                                position_key,
                                account_key,
                                symbol,
                                0.0,
                                _ms_open_side,
                                _ms_orig_side,
                                _ms_orig_qty,
                                current_price,
                                _ms_uid,
                                _ms_reason,
                                False,
                                "OPEN",
                            )
                            _ms_ok = "SUCCESS" in str(_ms_result or "").upper()
                            _ms_filled = _ms_orig_qty if _ms_ok else 0.0
                            if _ms_ok:
                                logger.critical(
                                    f"✅ [MICRO_SCALP_USDC_REOPENED] {position_key}: filled qty={_ms_filled} at ${current_price:.6f}"
                                )
                                _ms_state_dict[position_key] = {
                                    "prev_gain": 0.0,
                                    "exit_price": 0.0,
                                    "reopen_pending": False,
                                    "original_side": "",
                                    "original_qty": 0.0,
                                }
                                trade_manager.processing_keys.discard(position_key)
                                return (
                                    f"{EvalStatus.ACTION_TAKEN}:MICRO_SCALP_USDC_REOPEN"
                                )
                            else:
                                logger.warning(
                                    f"⏸️ [MICRO_SCALP_USDC_REOPEN_RETRY] {position_key}: maker did not fill (ok={_ms_ok} filled={_ms_filled}). NO webhook fallback — will retry next cycle."
                                )
            except Exception as _ms_e:
                logger.warning(
                    f"[MICRO_SCALP_USDC_ERR] {position_key}: {type(_ms_e).__name__}: {_ms_e}"
                )
        # ═══ 2026-04-21 HEDGE_CLOSE_WT3M1H_ABS SAFETY NET IN process_position ═══
        # User rule (feedback_hedge_wt3m_close_absolute.md + 2026-04-21 complaint): hedge MUST close
        # when wt_3m AND wt_1h BOTH go against. NO P/L gate. Primary path lives in ez_positions_quick
        # monitor_hedge_health_loop (line ~4837) scanning active_hedges. If a hedge is orphaned/missing
        # from active_hedges, that primary path never fires. This redundant check runs per-position via
        # process_position on ANY position flagged is_hedge=True — guarantees the close fires even
        # when tracker state is corrupted.
        try:
            _pp_is_hedge = (
                bool(getattr(position, "is_hedge", False)) if position else False
            )
            if _pp_is_hedge and is_active_position:
                _pp_long = position_key.endswith("_LONG")
                # 2026-04-27 USER ABSOLUTE: NEVER act on stale data, NEVER bail. Force-refresh from API.
                _pp_max_age = float(
                    getattr(config, "LIVE_POSITION_FRESHNESS_MAX_SEC", 3.0)
                )
                _pp_now = time.time()

                def _pp_age_of(_pos, _field):
                    _raw = getattr(_pos, _field, None)
                    if _raw is None:
                        return 9999.0
                    try:
                        _dt = isoparse(_raw) if isinstance(_raw, str) else _raw
                        if hasattr(_dt, "timestamp"):
                            return _pp_now - _dt.timestamp()
                    except Exception:
                        pass
                    return 9999.0

                _pp_pos_age = _pp_age_of(position, "last_updated")
                _pp_mp_age = _pp_age_of(position, "mark_price_last_updated")
                if max(_pp_pos_age, _pp_mp_age) > _pp_max_age:
                    logger.warning(
                        f"⏰ [HEDGE_FRESHNESS_REFRESH_PP] {position_key}: pos_age={_pp_pos_age:.1f}s mp_age={_pp_mp_age:.1f}s > {_pp_max_age}s — FORCE-REFRESHING from API"
                    )
                    try:
                        _ps = getattr(trade_manager, "positions_service", None)
                        if _ps and hasattr(_ps, "fetch_positions"):
                            await asyncio.wait_for(
                                _ps.fetch_positions(account_key), timeout=8.0
                            )
                        position = (
                            await trade_manager.get_position(position_key) or position
                        )
                        logger.warning(
                            f"⏰ [HEDGE_FRESHNESS_REFRESHED_PP] {position_key}: post-refresh pos_age={_pp_age_of(position, 'last_updated'):.1f}s"
                        )
                    except Exception as _rf_e:
                        logger.error(
                            f"⏰ [HEDGE_FRESHNESS_REFRESH_ERR_PP] {position_key}: {type(_rf_e).__name__}: {_rf_e} — proceeding with last-known data + live current_price (real_gain recompute is authoritative)"
                        )
                # 2026-04-27 (C98USDT): same stale-gain fix — recompute real_gain at decision time, use min(stale, real).
                _pp_stale_gain = safe_fetch_float(getattr(position, "gain", 0), 0)
                _pp_entry_px = safe_fetch_float(getattr(position, "entry_price", 0), 0)
                if _pp_entry_px > 0 and current_price > 0:
                    if _pp_long:
                        _pp_real_gain = (
                            (current_price - _pp_entry_px) / _pp_entry_px
                        ) * 100.0
                    else:
                        _pp_real_gain = (
                            (_pp_entry_px - current_price) / _pp_entry_px
                        ) * 100.0
                else:
                    _pp_real_gain = _pp_stale_gain
                _pp_gain = min(_pp_stale_gain, _pp_real_gain)
                _pp_decision = _hd.should_close_hedge_wt3m1h(
                    i, _pp_long, _pp_gain, config
                )
                if _pp_decision is not None:
                    _pp_w13 = _pp_decision["wt"]["wt1_3m"]
                    _pp_w23 = _pp_decision["wt"]["wt2_3m"]
                    _pp_w11 = _pp_decision["wt"]["wt1_1h"]
                    _pp_w21 = _pp_decision["wt"]["wt2_1h"]
                    _pp_amt = abs(
                        safe_fetch_float(getattr(position, "positionAmt", 0), 0)
                    )
                    _pp_ord_side = "SELL" if _pp_long else "BUY"
                    _pp_pos_side = "LONG" if _pp_long else "SHORT"
                    _pp_hedge_for = getattr(position, "hedge_for", None) or position_key
                    if not _pp_decision["fire"]:
                        logger.warning(
                            f"🛡️ [HEDGE_CLOSE_WT3M1H_PP_ABS_NOLOSS_HOLD] {position_key}: wt_3m={_pp_w13:.1f}/{_pp_w23:.1f} AND wt_1h={_pp_w11:.1f}/{_pp_w21:.1f} against {_pp_pos_side} hedge but gain={_pp_gain:.2f}% < 0 — STRICT_NO_LOSS, holding hedge."
                        )
                        return f"{EvalStatus.NO_ACTION}:HEDGE_CLOSE_WT3M1H_PP_ABS_NOLOSS_HOLD"
                    logger.critical(
                        f"🛑 [HEDGE_CLOSE_WT3M1H_PP_ABS] {position_key}: wt_3m={_pp_w13:.1f}/{_pp_w23:.1f} AND wt_1h={_pp_w11:.1f}/{_pp_w21:.1f} against {_pp_pos_side} hedge — safety-net close (gain={_pp_gain:.2f}%)."
                    )
                    try:
                        await trade_manager.execute_now(
                            position_key,
                            account_key,
                            symbol,
                            _pp_amt,
                            _pp_ord_side,
                            _pp_pos_side,
                            _pp_amt,
                            current_price,
                            f"HEDGE_WT3M1H_PP_{int(time.time())}",
                            f"HEDGE_CLOSE_WT3M1H_PP_ABS_3m={_pp_w13:.1f}/{_pp_w23:.1f}_1h={_pp_w11:.1f}/{_pp_w21:.1f}_gain={_pp_gain:.2f}%",
                            True,
                            "CLOSE",
                            is_hedge=True,
                            hedge_for=_pp_hedge_for,
                        )
                    finally:
                        trade_manager.processing_keys.discard(position_key)
                    return f"{EvalStatus.NO_ACTION}:HEDGE_CLOSE_WT3M1H_PP_ABS"
        except Exception as _pphe:
            logger.debug(
                f"[HEDGE_CLOSE_WT3M1H_PP_ABS] {position_key}: check failed: {_pphe}"
            )
        base_ctx = {
            "trade_manager": trade_manager,
            "symbol": symbol,
            "logger": logger,
            "position_key": position_key,
        }
        snapshot = trade_manager.indicators_snapshot.get(symbol, {})
        (
            is_data_fresh,
            freshness_reason,
            data_fresh_for_augment,
        ) = await _validate_indicator_data_freshness(
            i, symbol, position_key, logger, trade_manager
        )
        if not is_data_fresh:
            logger.warning(
                f"[{position_key}] DATA_FRESHNESS: {freshness_reason} - blocking augment, allowing reduction only ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}"
            )
            try:
                await symbol_tracker.track_completion(
                    position_key, f"NO_ACTION:DATA_NOT_FRESH_{freshness_reason}"
                )
            except Exception as e:
                logger.warning(f"[{position_key}] Error tracking completion: {e}")
        is_long = position_side == "LONG"
        # ==================================================================
        # SCALP_V2 ISOLATION — V2-tagged positions skip ALL main exit logic.
        # V2 exits are handled exclusively by ez_positions_quick (htf_breakout_scalper).
        # Without this, main exits (WT_4H_VEL, hedges, profit takes) trample V2 positions
        # → V8 showed -0.30 Sharpe. Added 2026-04-16.
        # ==================================================================
        if (
            is_active_position
            and getattr(config, "SCALP_V2_ISOLATE", False)
            and getattr(config, "SCALP_MODE", False)
        ):
            _v2_reason = str(
                getattr(position, "augment_reason", "")
                or getattr(position, "reason", "")
                or ""
            )
            if _v2_reason.startswith("SCALP_V2_OPEN_"):
                trade_manager.processing_keys.discard(position_key)
                return f"{EvalStatus.NO_ACTION}:SCALP_V2_ISOLATED"
        # ==================================================================
        # SHARPE-TRIPLE 2026-04-16 — TIER A+D ENHANCEMENTS (all switch-gated, default OFF)
        # Implementations: strategy_enhancements.py. See data/sweep_tiers.json.
        # Order matters: asymmetric stop (fastest exit) → progressive lock → pyramid.
        # ==================================================================
        if (
            is_active_position
            and position
            and abs(safe_fetch_float(getattr(position, "positionAmt", 0), 0))
            > pos_min_qty
        ):
            try:
                import strategy_enhancements as _sx

                _pg = safe_fetch_float(getattr(position, "gain", 0), 0)
                _oa = safe_datetime(getattr(position, "opened_at", None))
                _age = (
                    (now - _oa).total_seconds()
                    if isinstance(_oa, datetime) and isinstance(now, datetime)
                    else 9999
                )
                # TIER A #1: Asymmetric stops (tight losers, wide winners)
                _asym_exit, _asym_reason = _sx.check_asymmetric_stop(
                    config, i, current_price, _pg, _age, is_long
                )
                if _asym_exit:
                    logger.warning(f"[ASYMMETRIC_STOP] {position_key}: {_asym_reason}")
                    result = await queue_trade_action(
                        order_queue,
                        trade_manager,
                        position_key,
                        "QUICK_CLOSE",
                        _asym_reason,
                        0.93,
                    )
                    if result:
                        trade_manager.processing_keys.discard(position_key)
                        _sx.clear_progressive_lock(position_key)
                        _sx.clear_pyramid_state(position_key)
                        return f"{EvalStatus.ACTION_TAKEN}:ASYMMETRIC_STOP"
                # TIER A #2: Progressive profit lock (25% reduce at each tier)
                _plock, _frac, _plock_reason = _sx.check_progressive_lock(
                    config, position_key, _pg
                )
                if _plock and _frac > 0:
                    _plock_qty = (
                        abs(safe_fetch_float(getattr(position, "positionAmt", 0), 0))
                        * _frac
                    )
                    logger.warning(
                        f"[PROGRESSIVE_LOCK] {position_key}: {_plock_reason}"
                    )
                    result = await queue_trade_action(
                        order_queue,
                        trade_manager,
                        position_key,
                        "REDUCE",
                        _plock_reason,
                        0.85,
                        override_qty=_plock_qty,
                    )
                    if result:
                        return f"{EvalStatus.ACTION_TAKEN}:PROGRESSIVE_LOCK"
                # TIER D #9: Pyramid into structural strength (once per position)
                _pyr, _pyr_mult, _pyr_reason = _sx.check_pyramid_signal(
                    config, position_key, i, _pg, is_long
                )
                if _pyr and _pyr_mult > 0:
                    _pyr_qty = (
                        abs(safe_fetch_float(getattr(position, "positionAmt", 0), 0))
                        * _pyr_mult
                    )
                    logger.warning(f"[PYRAMID] {position_key}: {_pyr_reason}")
                    _pyr_side = "BUY" if is_long else "SELL"
                    result = await trade_manager.execute_now(
                        position_key,
                        account_key,
                        symbol,
                        abs(position.positionAmt),
                        _pyr_side,
                        position_side,
                        _pyr_qty,
                        current_price,
                        f"PYR_{int(time.time())}",
                        _pyr_reason,
                        False,
                        "AUGMENT",
                    )
                    if result and "SUCCESS" in str(result):
                        return f"{EvalStatus.ACTION_TAKEN}:PYRAMID"
            except Exception as _sx_err:
                logger.debug(f"[STRATEGY_ENHANCEMENTS] {position_key}: {_sx_err}")
        # ==================================================================
        # 2026-04-28 USER RULE: GUARANTEED_REENTRY positions get a tight stop.
        # If a position was opened/augmented via GUARANTEED_REENTRY and quickly reverses,
        # cut at TIGHT_STOP_PCT before it bleeds further. Bypasses commission floor (controlled bleed).
        # The strict-confirmation gate above prevents most bad reentries; this is the safety net for the rest.
        # ==================================================================
        if (
            bool(getattr(config, "GUARANTEED_REENTRY_TIGHT_STOP_ENABLED", True))
            and is_active_position
            and position
            and abs(safe_fetch_float(getattr(position, "positionAmt", 0), 0))
            > pos_min_qty
        ):
            _gr_signal_blob = (
                str(getattr(position, "last_signal", ""))
                + " "
                + str(getattr(position, "augment_reason", ""))
                + " "
                + str(getattr(position, "reduction_reason", ""))
            ).upper()
            if "GUARANTEED_REENTRY" in _gr_signal_blob:
                _gr_stop_pct = -abs(
                    float(getattr(config, "GUARANTEED_REENTRY_TIGHT_STOP_PCT", 0.5))
                )
                _gr_pp_g = safe_fetch_float(getattr(position, "gain", 0), 0)
                _gr_oa_raw = getattr(position, "opened_at", None) or getattr(
                    position, "last_augmentation_time", None
                )
                if isinstance(_gr_oa_raw, (int, float)):
                    _gr_oa_raw = (
                        datetime.fromtimestamp(_gr_oa_raw, tz=timezone.utc)
                        if _gr_oa_raw > 0
                        else None
                    )
                _gr_oa_dt = safe_datetime(_gr_oa_raw) if _gr_oa_raw else None
                _gr_age_s = (
                    (now - _gr_oa_dt).total_seconds()
                    if isinstance(_gr_oa_dt, datetime) and isinstance(now, datetime)
                    else 9999
                )
                _gr_min_age = float(
                    getattr(config, "GUARANTEED_REENTRY_TIGHT_STOP_MIN_AGE_S", 60.0)
                )
                _gr_max_age = float(
                    getattr(config, "GUARANTEED_REENTRY_TIGHT_STOP_MAX_AGE_S", 1800.0)
                )
                if _gr_min_age <= _gr_age_s <= _gr_max_age and _gr_pp_g <= _gr_stop_pct:
                    logger.critical(
                        f"🛑[GR_TIGHT_STOP] {position_key}: GUARANTEED_REENTRY position gain={_gr_pp_g:.2f}% <= stop {_gr_stop_pct:.2f}% (age={_gr_age_s:.0f}s) — closing tight-stop, bypasses commission floor"
                    )
                    result = await queue_trade_action(
                        order_queue,
                        trade_manager,
                        position_key,
                        "QUICK_CLOSE",
                        f"GR_TIGHT_STOP_g{_gr_pp_g:.2f}%_age{_gr_age_s:.0f}s_pos_was_GUARANTEED_REENTRY",
                        0.95,
                    )
                    if result:
                        trade_manager.processing_keys.discard(position_key)
                        return f"{EvalStatus.ACTION_TAKEN}:GR_TIGHT_STOP"
        # ==================================================================
        # #1 RULE: EXIT ON 4H WT VELOCITY SLOWDOWN — MANDATORY REENTRY
        # V5 WT Pure backtest 2026-03-31: 4h velocity = +$10,074 (WINNER)
        # 1h cross = -$15k (too fast), D = breakeven (too slow), 4h = sweet spot
        # Old 3m/15m/1h cross was -$9,133 (30% WR) — REPLACED
        # 2026-04-19 FIX: SHORT condition was wt1_4h>wt2_4h (cross-only, no velocity threshold)
        # → caused 409 closes at 14% WR in backtest. Now uses velocity symmetry with LONG.
        # ==================================================================
        if (
            getattr(config, "WT_4H_VEL_EXIT_ENABLED", True)
            and is_active_position
            and position
            and abs(safe_fetch_float(getattr(position, "positionAmt", 0), 0))
            > pos_min_qty
        ):
            _wt_vel_4h = safe_fetch_float(i.get("wt_velocity_4h", 0), 0)
            _wt1_4h = safe_fetch_float(i.get("wt1_4h", 0), 0)
            _wt2_4h = safe_fetch_float(i.get("wt2_4h", 0), 0)
            _4h_against = False
            if is_long:
                _4h_against = _wt_vel_4h < getattr(
                    config, "WT_4H_VEL_EXIT_LONG_VEL_MIN", -2.0
                )
            else:
                _4h_against = _wt_vel_4h > getattr(
                    config, "WT_4H_VEL_EXIT_SHORT_VEL_MIN", 2.0
                )
            _oa_raw = getattr(position, "opened_at", None)
            if isinstance(_oa_raw, (int, float)):
                _oa_raw = (
                    datetime.fromtimestamp(_oa_raw, tz=timezone.utc)
                    if _oa_raw > 0
                    else None
                )
            _oa_dt = safe_datetime(_oa_raw) if _oa_raw else None
            _pos_age_s = (
                (now - _oa_dt).total_seconds()
                if isinstance(_oa_dt, datetime) and isinstance(now, datetime)
                else 9999
            )
            _pp_g = safe_fetch_float(getattr(position, "gain", 0), 0)
            # 2026-04-28 USER RULE: WT_4H_VEL_EXIT may only fire on profitable positions AND when stoch K is in extreme zone
            # against position direction. Old gate fired at any gain → drove API3USDT_SHORT bleed -374% across 89 closes today.
            _wtve_req_profit = bool(
                getattr(config, "WT_4H_VEL_EXIT_REQUIRE_PROFIT", True)
            )
            _wtve_req_kx = bool(
                getattr(config, "WT_4H_VEL_EXIT_REQUIRE_K_EXTREME", True)
            )
            _wtve_kx_hi = float(getattr(config, "WT_4H_VEL_EXIT_K_EXTREME_HIGH", 80.0))
            _wtve_kx_lo = float(getattr(config, "WT_4H_VEL_EXIT_K_EXTREME_LOW", 20.0))
            # 2026-04-28 user: commission-aware floor — close must net positive after fees + slippage.
            _wtve_comm_buf = float(getattr(config, "COMMISSION_BUFFER_PCT", 0.10))
            _profit_ok = (_pp_g >= _wtve_comm_buf) if _wtve_req_profit else True
            _k_3m = safe_fetch_float(i.get("stoch_k_3m", 50.0), 50.0)
            _k_15m = safe_fetch_float(i.get("stoch_k_15m", 50.0), 50.0)
            if _wtve_req_kx:
                if is_long:
                    _kx_ok = (_k_3m >= _wtve_kx_hi) or (_k_15m >= _wtve_kx_hi)
                else:
                    _kx_ok = (_k_3m <= _wtve_kx_lo) or (_k_15m <= _wtve_kx_lo)
            else:
                _kx_ok = True
            if _4h_against and _pos_age_s > 360 and _profit_ok and _kx_ok:
                logger.warning(
                    f"[WT_4H_VEL_EXIT] {position_key}: vel_4h={_wt_vel_4h:.1f} wt1/2={_wt1_4h:.1f}/{_wt2_4h:.1f} g={_pp_g:.2f}% k_3m={_k_3m:.0f} k_15m={_k_15m:.0f} → MANDATORY_REENTRY"
                )
                result = await queue_trade_action(
                    order_queue,
                    trade_manager,
                    position_key,
                    "QUICK_CLOSE",
                    f"WT_4H_VEL_EXIT_vel={_wt_vel_4h:.1f}_g={_pp_g:.2f}%_k3m={_k_3m:.0f}_k15m={_k_15m:.0f}_MANDATORY_REENTRY",
                    0.95,
                )
                if result:
                    trade_manager.processing_keys.discard(position_key)
                    return f"{EvalStatus.ACTION_TAKEN}:WT_4H_VEL_EXIT"
            elif _4h_against and _pos_age_s > 360:
                logger.info(
                    f"🛡️[WT_4H_VEL_EXIT_BLOCKED] {position_key}: vel_4h={_wt_vel_4h:.1f} g={_pp_g:.2f}% k_3m={_k_3m:.0f} k_15m={_k_15m:.0f} profit_ok={_profit_ok} kx_ok={_kx_ok} — holding"
                )
        # ==================================================================
        # DC_HOPELESS_EXIT — close if entry_price is now outside dc_4h channel
        # LONG: entry_price > dc_high_4h → bought above the channel ceiling, structure failed
        # SHORT: entry_price < dc_low_4h → sold below the channel floor, structure failed
        # Technical structure break exit — not a % stop. Bypasses NOLOSS gate intentionally.
        # 2026-04-19: approved by user as part of indicator-audit exit framework
        # ==================================================================
        if (
            getattr(config, "DC_HOPELESS_EXIT_ENABLED", True)
            and is_active_position
            and position
            and abs(safe_fetch_float(getattr(position, "positionAmt", 0), 0))
            > pos_min_qty
        ):
            _dc_high_4h = safe_fetch_float(i.get("dc_high_4h", 0), 0)
            _dc_low_4h = safe_fetch_float(i.get("dc_low_4h", 0), 0)
            _entry_px = safe_fetch_float(getattr(position, "entry_price", 0), 0)
            if _dc_high_4h > 0 and _dc_low_4h > 0 and _entry_px > 0:
                _oa_raw2 = getattr(position, "opened_at", None)
                if isinstance(_oa_raw2, (int, float)):
                    _oa_raw2 = (
                        datetime.fromtimestamp(_oa_raw2, tz=timezone.utc)
                        if _oa_raw2 > 0
                        else None
                    )
                _oa_dt2 = safe_datetime(_oa_raw2) if _oa_raw2 else None
                _age2 = (
                    (now - _oa_dt2).total_seconds()
                    if isinstance(_oa_dt2, datetime) and isinstance(now, datetime)
                    else 0
                )
                _min_age = getattr(config, "DC_HOPELESS_EXIT_MIN_AGE_S", 900)
                _hopeless = False
                if is_long and _entry_px > _dc_high_4h:
                    _hopeless = True
                elif not is_long and _entry_px < _dc_low_4h:
                    _hopeless = True
                if _hopeless and _age2 > _min_age:
                    _pp_g2 = safe_fetch_float(getattr(position, "gain", 0), 0)
                    logger.warning(
                        f"[DC_HOPELESS_EXIT] {position_key}: entry={_entry_px:.4f} dc=[{_dc_low_4h:.4f},{_dc_high_4h:.4f}] g={_pp_g2:.2f}% age={_age2:.0f}s → CLOSE"
                    )
                    result = await queue_trade_action(
                        order_queue,
                        trade_manager,
                        position_key,
                        "QUICK_CLOSE",
                        f"DC_HOPELESS_entry={_entry_px:.4f}_dc=[{_dc_low_4h:.4f},{_dc_high_4h:.4f}]",
                        0.95,
                    )
                    if result:
                        trade_manager.processing_keys.discard(position_key)
                        return f"{EvalStatus.ACTION_TAKEN}:DC_HOPELESS_EXIT"
        # ==================================================================
        # WT_EXHAUST_EXIT — close when 4h WT momentum exhausted against position
        # EXHAUST_UP on 4h + (1h or 15m) = top confirmed → close LONG
        # EXHAUST_DOWN on 4h + (1h or 15m) = bottom confirmed → close SHORT
        # 2026-04-19: wt_momentum_state_* decoded to string by IndicatorStore in backtest
        # ==================================================================
        if (
            getattr(config, "WT_EXHAUST_EXIT_ENABLED", True)
            and is_active_position
            and position
            and abs(safe_fetch_float(getattr(position, "positionAmt", 0), 0))
            > pos_min_qty
        ):
            _mom_4h = str(i.get("wt_momentum_state_4h", "") or "").upper()
            _mom_1h = str(i.get("wt_momentum_state_1h", "") or "").upper()
            _mom_15m = str(i.get("wt_momentum_state_15m", "") or "").upper()
            _ex_exit = False
            if (
                is_long
                and _mom_4h == "EXHAUST_UP"
                and (_mom_1h == "EXHAUST_UP" or _mom_15m == "EXHAUST_UP")
            ):
                _ex_exit = True
            elif (
                not is_long
                and _mom_4h == "EXHAUST_DOWN"
                and (_mom_1h == "EXHAUST_DOWN" or _mom_15m == "EXHAUST_DOWN")
            ):
                _ex_exit = True
            if _ex_exit:
                _ex_g = safe_fetch_float(getattr(position, "gain", 0), 0)
                _req_gain = getattr(config, "WT_EXHAUST_EXIT_REQUIRE_GAIN", False)
                _ex_min_gain = float(getattr(config, "WT_EXHAUST_EXIT_MIN_GAIN_PCT", 0.0))
                if (not _req_gain or _ex_g > 0) and _ex_g >= _ex_min_gain:
                    logger.warning(
                        f"[WT_EXHAUST_EXIT] {position_key}: 4h={_mom_4h} 1h={_mom_1h} 15m={_mom_15m} g={_ex_g:.2f}%"
                    )
                    result = await queue_trade_action(
                        order_queue,
                        trade_manager,
                        position_key,
                        "QUICK_CLOSE",
                        f"WT_EXHAUST_mom4h={_mom_4h}_1h={_mom_1h}_g={_ex_g:.2f}%",
                        0.95,
                    )
                    if result:
                        trade_manager.processing_keys.discard(position_key)
                        return f"{EvalStatus.ACTION_TAKEN}:WT_EXHAUST_EXIT"
        # ==================================================================
        # WT_PERCENTILE_EXIT — close when D + 4h both overbought (LONG) or oversold (SHORT)
        # wt_percentile_D=97 in example = daily WT at 97th percentile = extreme OB
        # 2026-04-19: percentile fields confirmed float32 in NPZ
        # ==================================================================
        if (
            getattr(config, "WT_PERCENTILE_EXIT_ENABLED", True)
            and is_active_position
            and position
            and abs(safe_fetch_float(getattr(position, "positionAmt", 0), 0))
            > pos_min_qty
        ):
            _pct_D = safe_fetch_float(i.get("wt_percentile_D", 50), 50)
            _pct_4h = safe_fetch_float(i.get("wt_percentile_4h", 50), 50)
            _pct_exit = False
            if (
                is_long
                and _pct_D > getattr(config, "WT_PERCENTILE_EXIT_OB_D", 90)
                and _pct_4h > getattr(config, "WT_PERCENTILE_EXIT_OB_4H", 75)
            ):
                _pct_exit = True
            elif (
                not is_long
                and _pct_D < getattr(config, "WT_PERCENTILE_EXIT_OS_D", 10)
                and _pct_4h < getattr(config, "WT_PERCENTILE_EXIT_OS_4H", 25)
            ):
                _pct_exit = True
            if _pct_exit:
                _pct_g = safe_fetch_float(getattr(position, "gain", 0), 0)
                logger.warning(
                    f"[WT_PERCENTILE_EXIT] {position_key}: pct_D={_pct_D:.0f} pct_4h={_pct_4h:.0f} g={_pct_g:.2f}%"
                )
                result = await queue_trade_action(
                    order_queue,
                    trade_manager,
                    position_key,
                    "QUICK_CLOSE",
                    f"WT_PERCENTILE_pctD={_pct_D:.0f}_4h={_pct_4h:.0f}_g={_pct_g:.2f}%",
                    0.95,
                )
                if result:
                    trade_manager.processing_keys.discard(position_key)
                    return f"{EvalStatus.ACTION_TAKEN}:WT_PERCENTILE_EXIT"
        # E-1 WT_EXIT_USE_DELTA (2026-04-19 default OFF) — exit when wt_composite_delta crosses threshold against position.
        # Fires alongside existing exits. LONG exits when delta < -THR, SHORT when delta > +THR.
        if (
            bool(getattr(config, "E_1_WT_EXIT_USE_DELTA_ENABLED", False))
            and is_active_position
            and position
            and abs(safe_fetch_float(getattr(position, "positionAmt", 0), 0))
            > pos_min_qty
        ):
            _e1_delta = safe_fetch_float(i.get("wt_composite_delta"), None)
            _e1_thr = float(getattr(config, "E_1_EXIT_DELTA_THR", 50.0))
            if _e1_delta is not None:
                _e1_fire = (is_long and _e1_delta < -_e1_thr) or (
                    (not is_long) and _e1_delta > _e1_thr
                )
                if _e1_fire:
                    _e1_g = safe_fetch_float(getattr(position, "gain", 0), 0)
                    logger.warning(
                        f"[E_1_WT_DELTA_EXIT] {position_key}: delta={_e1_delta:+.0f} thr={_e1_thr:.0f} g={_e1_g:.2f}%"
                    )
                    result = await queue_trade_action(
                        order_queue,
                        trade_manager,
                        position_key,
                        "QUICK_CLOSE",
                        f"E_1_WT_DELTA_EXIT_delta={_e1_delta:+.0f}_thr={_e1_thr:.0f}_g={_e1_g:.2f}%",
                        0.95,
                    )
                    if result:
                        trade_manager.processing_keys.discard(position_key)
                        return f"{EvalStatus.ACTION_TAKEN}:E_1_WT_DELTA_EXIT"
        # E-3 USE_WT_STRUCTURE_EXIT (2026-04-19 default OFF, mode=0) — exit on wt_structure HH/HL label reversal.
        # Modes: 0=off, 1=shadow (log only, no action), 2=on (live exit). LONG exits on LH/LL on ≥2 HTFs.
        _e3_mode = int(getattr(config, "E_3_USE_WT_STRUCTURE_EXIT_MODE", 0))
        if (
            _e3_mode > 0
            and is_active_position
            and position
            and abs(safe_fetch_float(getattr(position, "positionAmt", 0), 0))
            > pos_min_qty
        ):
            _e3_against = 0
            _e3_tfs = []
            for _tf in ("15m", "1h", "4h"):
                _struct = str(i.get(f"wt_structure_{_tf}", "") or "").upper()
                if is_long and _struct in ("LH", "LL"):
                    _e3_against += 1
                    _e3_tfs.append(f"{_tf}={_struct}")
                elif (not is_long) and _struct in ("HH", "HL"):
                    _e3_against += 1
                    _e3_tfs.append(f"{_tf}={_struct}")
            if _e3_against >= 2:
                _e3_g = safe_fetch_float(getattr(position, "gain", 0), 0)
                if _e3_mode == 1:
                    logger.info(
                        f"[E_3_STRUCTURE_EXIT_SHADOW] {position_key}: {_e3_against}TF against {_e3_tfs} g={_e3_g:.2f}% — would exit (shadow mode)"
                    )
                elif _e3_mode == 2:
                    logger.warning(
                        f"[E_3_STRUCTURE_EXIT] {position_key}: {_e3_against}TF against {_e3_tfs} g={_e3_g:.2f}%"
                    )
                    result = await queue_trade_action(
                        order_queue,
                        trade_manager,
                        position_key,
                        "QUICK_CLOSE",
                        f"E_3_STRUCTURE_EXIT_{_e3_against}TF_g={_e3_g:.2f}%",
                        0.95,
                    )
                    if result:
                        trade_manager.processing_keys.discard(position_key)
                        return f"{EvalStatus.ACTION_TAKEN}:E_3_STRUCTURE_EXIT"
        if is_active_position and position and config.MANAGE_REDUCE:
            _pp_gain = safe_fetch_float(getattr(position, "gain", 0.0), 0.0)
            _pp_prev_gain = safe_fetch_float(getattr(position, "prev_gain", 0.0), 0.0)
            _pp_entry = safe_fetch_float(getattr(position, "entry_price", 0.0), 0.0)
            # RULE #6: HEDGE CLEANUP — 2026-04-17 OVERHAUL
            # User rule: hedges close on wt1_3m flip REGARDLESS of P/L (STRICT_NO_LOSS does not apply to hedges).
            # On close, position_key is removed from tradeable_keys so nothing reopens it automatically.
            # Reopen is handled by scan_and_hedge_losers when the loser is still in loss AND wt1_15m flips against again.
            # Switches: HEDGE_EXIT_BYPASS_NOLOSS (default True), HEDGE_CLOSE_REMOVE_FROM_TRADEABLE (default True).
            if (
                hasattr(trade_manager, "tracker_manager")
                and trade_manager.tracker_manager
            ):
                # ⚠️ GROUND TRUTH CHECK FIRST — position.is_hedge is the authoritative source.
                # If position.is_hedge is explicitly False, this is a MAIN position.
                # active_hedges records are stale data and CANNOT override the position's own attribute.
                # History: 7 incidents of main positions closed at loss because stale active_hedges
                # record survived the VETO (tradeable_keys missing the position_key).
                # Fix: check position.is_hedge BEFORE touching active_hedges at all.
                _r6_pos_is_hedge_attr = False
                _r6_pos_hedge_for_attr = None
                _r6_reason_says_hedge = False
                try:
                    _r6_pos_is_hedge_attr = bool(getattr(position, "is_hedge", False))
                    _r6_pos_hedge_for_attr = getattr(position, "hedge_for", None)
                    # 2026-04-25 FIX — account drain: R6 was purging REAL hedges because
                    # position.is_hedge boolean was False while augment_reason clearly said HEDGE.
                    # Hedges opened via execute_same_symbol_hedge → persist_hedge_record adds to
                    # active_hedges but does NOT set position.is_hedge=True on the Position object.
                    # Result: every monitor cycle purged the active_hedges entry → hedge-close loop
                    # had empty list → hedges never closed → MOVR -$3, dozens of pairs dragging.
                    # Fix: reason string is authoritative; trust it.
                    _r6_reason = str(
                        getattr(position, "augment_reason", "") or ""
                    ).upper()
                    for _hm in (
                        "HEDGE_PROTECT_",
                        "HEDGE_ELECTED_",
                        "QUICK_HEDGE_",
                        "HEDGE_SAME_",
                    ):
                        if _hm in _r6_reason:
                            _r6_reason_says_hedge = True
                            break
                except Exception:
                    pass
                if not _r6_pos_is_hedge_attr and not _r6_reason_says_hedge:
                    # Position object says NOT a hedge AND reason doesn't say hedge — safe to purge stale record
                    _r6_stale = any(
                        h.get("position_key") == position_key
                        for h in trade_manager.tracker_manager.active_hedges
                    )
                    if _r6_stale:
                        logger.critical(
                            f"[HEDGE_CLEANUP_R6_GROUND_TRUTH_VETO] {position_key}: position.is_hedge=False AND reason not hedge — PURGING stale active_hedges record, skipping R6. Main position."
                        )
                        try:
                            async with trade_manager.tracker_manager._hedges_lock:
                                trade_manager.tracker_manager.active_hedges = [
                                    h
                                    for h in trade_manager.tracker_manager.active_hedges
                                    if h.get("position_key") != position_key
                                ]
                        except Exception:
                            pass
                    _r6_is_hedge = False
                elif not _r6_pos_is_hedge_attr and _r6_reason_says_hedge:
                    # Flag missing but reason says HEDGE — trust reason. DO NOT PURGE.
                    # Heal the Position object so future cycles agree.
                    try:
                        position.is_hedge = True  # best-effort heal
                    except Exception:
                        pass
                    logger.warning(
                        f"🩹 [R6_HEDGE_FLAG_HEAL] {position_key}: reason says HEDGE but is_hedge flag was False — healed to True, keeping active_hedges record"
                    )
                    _r6_is_hedge = any(
                        h.get("position_key") == position_key
                        for h in trade_manager.tracker_manager.active_hedges
                    )
                else:
                    _r6_is_hedge = any(
                        h.get("position_key") == position_key
                        for h in trade_manager.tracker_manager.active_hedges
                    )
                    # SYMBOLS DIRECTION LIST VETO — primary source of truth for main positions.
                    # tradeable_keys is NOT used here: it is polluted with temp hedge keys added
                    # at hedge-open time and removed at close. symbols_{acct}_long/short are
                    # the hand-curated lists that define what is a real main position.
                    # 2026-04-25 FIX — same-symbol hedges (e.g. ENJUSDT_SHORT hedging ENJUSDT_LONG)
                    # were always purged because the hedge side IS in the symbols direction list
                    # for normal trading. Only fire this veto when pos.is_hedge attr is False
                    # (i.e., we got here via active_hedges-only fallback, not an authoritative flag).
                    if _r6_is_hedge and not _r6_pos_is_hedge_attr:
                        _r6_long_syms = (
                            getattr(trade_manager, f"symbols_{account_key}_long", None)
                            or set()
                        )
                        _r6_flat_syms = (
                            getattr(trade_manager, f"symbols_{account_key}", None)
                            or set()
                        )
                        _r6_short_syms = (
                            getattr(trade_manager, f"symbols_{account_key}_short", None)
                            or set()
                        )
                        if account_key in ("flz", "men", "fin"):
                            _r6_long_syms = _r6_long_syms | _r6_flat_syms
                        _r6_is_main = (is_long and symbol in _r6_long_syms) or (
                            not is_long and symbol in _r6_short_syms
                        )
                        if _r6_is_main:
                            logger.warning(
                                f"[HEDGE_CLEANUP_R6_VETO] {position_key}: symbol in direction list (symbols_{account_key}_{'long' if is_long else 'short'}) AND pos.is_hedge=False — main position, purging stale active_hedges record, skipping R6"
                            )
                            try:
                                async with trade_manager.tracker_manager._hedges_lock:
                                    trade_manager.tracker_manager.active_hedges = [
                                        h
                                        for h in trade_manager.tracker_manager.active_hedges
                                        if h.get("position_key") != position_key
                                    ]
                            except Exception:
                                pass
                            _r6_is_hedge = False
                    if not _r6_is_hedge:
                        try:
                            _r6_ec = (
                                trade_manager.tracker_manager.exit_candidates.get(
                                    position_key, {}
                                )
                                or {}
                            )
                            if (
                                _r6_ec.get("is_hedge")
                                or _r6_ec.get("hedge_for")
                                or "HEDGE" in str(_r6_ec.get("last_reason", "")).upper()
                            ):
                                _r6_is_hedge = True
                        except Exception:
                            pass
                if _r6_is_hedge:
                    _r6_wt1_3m = safe_fetch_float(i.get("wt1_3m", 0), 0.0)
                    _r6_wt2_3m = safe_fetch_float(i.get("wt2_3m", 0), 0.0)
                    _r6_wt1_15m = safe_fetch_float(i.get("wt1_15m", 0), 0.0)
                    _r6_wt2_15m = safe_fetch_float(i.get("wt2_15m", 0), 0.0)
                    _r6_wt1_1h = safe_fetch_float(i.get("wt1_1h", 0), 0.0)
                    _r6_wt2_1h = safe_fetch_float(i.get("wt2_1h", 0), 0.0)
                    _r6_wt_wrong_3m = (is_long and _r6_wt1_3m < _r6_wt2_3m) or (
                        not is_long and _r6_wt1_3m > _r6_wt2_3m
                    )
                    _r6_wt_wrong_15m = (is_long and _r6_wt1_15m < _r6_wt2_15m) or (
                        not is_long and _r6_wt1_15m > _r6_wt2_15m
                    )
                    _r6_wt_wrong_1h = (is_long and _r6_wt1_1h < _r6_wt2_1h) or (
                        not is_long and _r6_wt1_1h > _r6_wt2_1h
                    )
                    _r6_wt_all_wrong = (
                        _r6_wt_wrong_3m and _r6_wt_wrong_15m and _r6_wt_wrong_1h
                    )
                    _r6_main_pk = next(
                        (
                            h.get("losing_position_key", "")
                            for h in trade_manager.tracker_manager.active_hedges
                            if h.get("position_key") == position_key
                        ),
                        None,
                    )
                    _r6_main_pos = (
                        trade_manager.positions.get(_r6_main_pk)
                        if _r6_main_pk
                        else None
                    )
                    _r6_main_gone = (
                        not _r6_main_pos
                        or abs(
                            safe_fetch_float(getattr(_r6_main_pos, "positionAmt", 0), 0)
                        )
                        < 0.0001
                    )
                    _r6_main_gain = (
                        safe_fetch_float(getattr(_r6_main_pos, "gain", 0), 0)
                        if _r6_main_pos and not _r6_main_gone
                        else None
                    )
                    # 2026-04-28 user: "make sure commissions are included in the sell before loss"
                    # main_recovered must be ABOVE commission buffer, not just >= 0.
                    _r6_comm_buf = float(getattr(config, "COMMISSION_BUFFER_PCT", 0.10))
                    _r6_main_recovered = _r6_main_gone or (
                        _r6_main_gain is not None and _r6_main_gain >= _r6_comm_buf
                    )
                    _r6_main_gain_str = (
                        f"{_r6_main_gain:.2f}" if _r6_main_gain is not None else "gone"
                    )
                    _r6_bypass = bool(getattr(config, "HEDGE_EXIT_BYPASS_NOLOSS", True))
                    _r6_wt_flip_trigger = (
                        (_r6_wt_wrong_3m and _r6_wt_wrong_1h)
                        if _r6_bypass
                        else _r6_wt_all_wrong
                    )
                    _r6_should_close = _r6_wt_flip_trigger or _r6_main_recovered
                    # ⚠️ NOLOSS GATE — DO NOT DISABLE WITHOUT EXPLICIT USER PERMISSION
                    # 2026-04-28 user: include commissions. Hedge close at gain < COMMISSION_BUFFER_PCT
                    # is a NET LOSS after entry+exit fees. Block until gain covers fees.
                    if _r6_should_close and _pp_gain < _r6_comm_buf:
                        _r6_entry = safe_fetch_float(
                            getattr(position, "entry_price", 0), 0
                        )
                        logger.critical(
                            f"[HEDGE_CLEANUP_R6_COMMISSION_BLOCK] {position_key}: gain={_pp_gain:.2f}% < {_r6_comm_buf:.2f}% commission buffer — close would be NET LOSS after fees. Holding until commissions covered. ⚠️ DO NOT REMOVE"
                        )
                        try:
                            async with trade_manager.tracker_manager._hedges_lock:
                                trade_manager.tracker_manager.active_hedges = [
                                    h
                                    for h in trade_manager.tracker_manager.active_hedges
                                    if h.get("position_key") != position_key
                                ]
                        except Exception:
                            pass
                        _r6_should_close = False
                    if _r6_should_close:
                        _r6_amt = abs(
                            safe_fetch_float(getattr(position, "positionAmt", 0.0), 0.0)
                        )
                        if _r6_amt > pos_min_qty:
                            _r6_close_reason = (
                                "main_recovered"
                                if _r6_main_recovered
                                else (
                                    "wt3m_and_1h_flip_bypass_noloss"
                                    if _r6_bypass
                                    else "all_tf_wt_against_hedge"
                                )
                            )
                            _r6_reason = f"HEDGE_CLEANUP_R6_{_r6_close_reason}_gain={_pp_gain:.2f}_main={_r6_main_gain_str}_wt3m={_r6_wt1_3m:.1f}/{_r6_wt2_3m:.1f}_wt15m={_r6_wt1_15m:.1f}/{_r6_wt2_15m:.1f}"
                            logger.warning(
                                f"[HEDGE_CLEANUP_R6] {position_key}: hedge gain={_pp_gain:.2f}% {_r6_close_reason} → CLOSING HEDGE"
                            )
                            _r6_side = "SELL" if is_long else "BUY"
                            _r6_uid = f"HEDGE_CLEANUP_R6_{int(time.time())}_{uuid.uuid4().hex[:6].upper()}"
                            _r6_res = await trade_manager.execute_now(
                                position_key,
                                account_key,
                                symbol,
                                _r6_amt,
                                _r6_side,
                                position_side,
                                _r6_amt,
                                current_price,
                                _r6_uid,
                                _r6_reason,
                                True,
                                "QUICK_CLOSE",
                                is_hedge=True,
                                hedge_for=position_key,
                            )
                            if _r6_res and "SUCCESS" in str(_r6_res):
                                logger.warning(
                                    f"[HEDGE_CLEANUP_R6_OK] {position_key}: Hedge closed. {_r6_res}"
                                )
                                try:
                                    async with (
                                        trade_manager.tracker_manager._hedges_lock
                                    ):
                                        trade_manager.tracker_manager.active_hedges = [
                                            h
                                            for h in trade_manager.tracker_manager.active_hedges
                                            if h.get("position_key") != position_key
                                        ]
                                except Exception:
                                    pass
                                # NEVER discard from tradeable_keys here — R6 can only close real hedges
                                # (position.is_hedge=True) and real hedges are temp-added at hedge-open time.
                                # Discarding here was the root cause of ang:BTCUSDC_LONG disappearing from
                                # tradeable_keys and blocking reentry permanently. Removed 2026-04-19.
                                if _r6_close_reason != "main_recovered":
                                    _r6_loser_pk = _r6_main_pk or position_key
                                    _rds_cd_key = f"wt_same_hedge_cd:{_r6_loser_pk}"
                                    _rds_day_key = f"wt_same_hedge_daily:{account_key}:{symbol}:{datetime.now(timezone.utc).strftime('%Y%m%d')}"
                                    try:
                                        if trade_manager.redis_manager:
                                            await trade_manager.redis_manager.delete(
                                                _rds_cd_key
                                            )
                                            await trade_manager.redis_manager.delete(
                                                _rds_day_key
                                            )
                                            logger.warning(
                                                f"[HEDGE_CLEANUP_R6_RESET_CAP] {position_key}: wt_flip close — cleared daily cap + cooldown so loser {_r6_loser_pk} can re-hedge on next WT flip"
                                            )
                                    except Exception:
                                        pass
                                return f"{EvalStatus.ACTION_TAKEN}:HEDGE_CLEANUP_R6"
                    else:
                        logger.debug(
                            f"[HEDGE_CLEANUP_R6_HOLD] {position_key}: hedge gain={_pp_gain:.2f}% wt3m_wrong={_r6_wt_wrong_3m} main={_r6_main_gain_str}%. Holding."
                        )
            # ═══ 2026-04-18 USER RULE — WRONG_SIDE_ABS_KILL ═══
            # "Going COMPLETELY against any curve = SUICIDE mission. Kill completely."
            # Closes position when ALL of the following are against the position side:
            #   wt1_3m, wt1_15m, wt1_1h, wt1_4h, wt1_D (5 WT TFs) AND stoch_k_3m/15m/1h (3 stoch TFs)
            # That's 8-of-8 simultaneous against-signals — rare, decisive, bypasses STRICT_NO_LOSS.
            # Grace period: position must be older than WRONG_SIDE_MIN_AGE_MIN (default 30 min).
            # Skip hedges — HEDGE_CLEANUP_R6 above handles them with its own wt1_3m rule.
            if getattr(config, "WRONG_SIDE_ABS_KILL_ENABLED", True):
                _ws_is_hedge = False
                try:
                    _ws_is_hedge = bool(getattr(position, "is_hedge", False))
                    if (
                        not _ws_is_hedge
                        and hasattr(trade_manager, "tracker_manager")
                        and trade_manager.tracker_manager
                    ):
                        _ws_is_hedge = any(
                            h.get("position_key") == position_key
                            for h in trade_manager.tracker_manager.active_hedges
                        )
                except Exception:
                    pass
                if not _ws_is_hedge:
                    _ws_age_min = 999999.0
                    try:
                        _ws_opened = getattr(position, "opened_at", None) or getattr(
                            position, "last_augmentation_time", None
                        )
                        if _ws_opened:
                            if isinstance(_ws_opened, (int, float)):
                                _ws_age_min = (time.time() - float(_ws_opened)) / 60.0
                            else:
                                _ws_dt = (
                                    isoparse(str(_ws_opened))
                                    if not isinstance(_ws_opened, datetime)
                                    else _ws_opened
                                )
                                if _ws_dt.tzinfo is None:
                                    _ws_dt = _ws_dt.replace(tzinfo=timezone.utc)
                                _ws_age_min = (
                                    datetime.now(timezone.utc) - _ws_dt
                                ).total_seconds() / 60.0
                    except Exception:
                        _ws_age_min = 999999.0
                    _ws_min_age = float(getattr(config, "WRONG_SIDE_MIN_AGE_MIN", 30.0))
                    if _ws_age_min >= _ws_min_age:
                        _ws_wt_against = 0
                        for _wtf in ("3m", "15m", "1h", "4h", "D"):
                            _wt1 = safe_fetch_float(i.get(f"wt1_{_wtf}"), 0)
                            _wt2 = safe_fetch_float(i.get(f"wt2_{_wtf}"), 0)
                            if _wt1 == 0 and _wt2 == 0:
                                continue
                            if (is_long and _wt1 < _wt2) or (
                                (not is_long) and _wt1 > _wt2
                            ):
                                _ws_wt_against += 1
                        _ws_k_against = 0
                        for _ktf in ("3m", "15m", "1h"):
                            _k = safe_fetch_float(i.get(f"stoch_k_{_ktf}"), 50)
                            _d = safe_fetch_float(i.get(f"stoch_d_{_ktf}"), 50)
                            if (is_long and _k < _d) or ((not is_long) and _k > _d):
                                _ws_k_against += 1
                        _ws_wt_req = int(
                            getattr(config, "WRONG_SIDE_WT_TFS_REQUIRED", 5)
                        )
                        _ws_k_req = int(getattr(config, "WRONG_SIDE_K_TFS_REQUIRED", 3))
                        if _ws_wt_against >= _ws_wt_req and _ws_k_against >= _ws_k_req:
                            _ws_amt = abs(
                                safe_fetch_float(
                                    getattr(position, "positionAmt", 0.0), 0.0
                                )
                            )
                            if _ws_amt > pos_min_qty:
                                _ws_reason = f"WRONG_SIDE_ABS_KILL_wt={_ws_wt_against}/{_ws_wt_req}_k={_ws_k_against}/{_ws_k_req}_age={_ws_age_min:.0f}min_gain={_pp_gain:.2f}%"
                                logger.critical(
                                    f"🗡️ [WRONG_SIDE_ABS_KILL] {position_key}: {'LONG' if is_long else 'SHORT'} completely against curve — {_ws_wt_against}/{len(('3m', '15m', '1h', '4h', 'D'))} WT + {_ws_k_against}/3 K against, age={_ws_age_min:.0f}min, gain={_pp_gain:.2f}%. Bypassing STRICT_NO_LOSS per user rule."
                                )
                                _ws_res = await queue_trade_action(
                                    order_queue,
                                    trade_manager,
                                    position_key,
                                    "QUICK_CLOSE",
                                    _ws_reason,
                                    0.98,
                                )
                                if _ws_res:
                                    trade_manager.processing_keys.discard(position_key)
                                    return (
                                        f"{EvalStatus.ACTION_TAKEN}:WRONG_SIDE_ABS_KILL"
                                    )
            # DELTA EXIT — speed decay / combined_wt_stoch (V2 sweep: Sharpe 0.575, WR 78.5%)
            # 2026-04-10 BUGFIX: was passing (symbol, i) WITHOUT position_state, so the
            # entire exit block in wt_dc_delta.py was SKIPPED (gated on `if position_state`).
            # Now construct position_state so speed_dead/decel/peak_decay/opposing/tf_lost/MFI
            # exits actually fire.
            # RECONNECT 2026-04-14 — rz: RZ_EXIT_ENABLED master gate (delegated to delta_tracker.cfg.rz_exit_enabled)
            _rz_exit_enabled = bool(getattr(config, "RZ_EXIT_ENABLED", True))
            if (
                trade_manager.delta_tracker
                and getattr(config, "DELTA_EXIT_ENABLED", True)
                and _rz_exit_enabled
            ):
                _de_pos_amt = abs(
                    safe_fetch_float(getattr(position, "positionAmt", 0), 0)
                )
                _de_entry_px = (
                    safe_fetch_float(getattr(position, "entry_price", 0), 0)
                    or current_price
                )
                _de_n_entries = int(
                    safe_fetch_float(getattr(position, "n_entries", 1), 1) or 1
                )
                _de_pos_state = (
                    {
                        "side": "LONG" if is_long else "SHORT",
                        "n_entries": _de_n_entries,
                        "last_entry_price": _de_entry_px,
                    }
                    if _de_pos_amt > 0
                    else None
                )
                _d_sig = trade_manager.delta_tracker.update(symbol, i, _de_pos_state)
                if _d_sig and (
                    (is_long and _d_sig.exit_long)
                    or (not is_long and _d_sig.exit_short)
                ):
                    # DELTA_EXIT is sacred (user rule) — HTF slowdown gate lives IN wt_dc_delta.py
                    # and vetoes _d_sig.exit_long/short if only LTF noise fires. If exit reaches
                    # here, HTF has confirmed the slowdown → fire exit.
                    _d_reason = f"DELTA_EXIT_speed_decay_tfs_lost={getattr(_d_sig, 'tf_lost', '?')}_gain={_pp_gain:.2f}%"
                    logger.warning(f"[DELTA_EXIT] {position_key}: {_d_reason}")
                    _d_side = "SELL" if is_long else "BUY"
                    _d_amt = abs(
                        safe_fetch_float(getattr(position, "positionAmt", 0.0), 0.0)
                    )
                    if _d_amt > pos_min_qty:
                        result = await queue_trade_action(
                            order_queue,
                            trade_manager,
                            position_key,
                            "QUICK_CLOSE",
                            f"DELTA_EXIT_{_d_reason}_MANDATORY_REENTRY",
                            0.95,
                        )
                        if result:
                            return f"{EvalStatus.ACTION_TAKEN}:DELTA_EXIT"
            _pp_noloss, _pp_noloss_reason = (
                (False, "")
                if getattr(config, "ABLATION_DISABLE_CHECK_NOLOSS", False)
                else trading_policy.check_no_loss_exit(
                    i, current_price, _pp_entry, is_long, _pp_gain, _pp_prev_gain
                )
            )
            if _pp_noloss:
                _nle_opp_side = "SHORT" if is_long else "LONG"
                _nle_opp_key = f"{account_key}:{symbol}_{_nle_opp_side}"
                _nle_opp_pos = trade_manager.positions.get(_nle_opp_key)
                _nle_opp_in_loss = (
                    _nle_opp_pos
                    and abs(
                        safe_fetch_float(getattr(_nle_opp_pos, "positionAmt", 0), 0)
                    )
                    > 0
                    and safe_fetch_float(getattr(_nle_opp_pos, "gain", 0), 0) < 0.0
                )
                if _nle_opp_in_loss:
                    logger.warning(
                        f"⚡ [NO_LOSS_EXIT_BLOCKED] {position_key}: {_pp_noloss_reason} — BUT opposite {_nle_opp_key} in loss ({getattr(_nle_opp_pos, 'gain', 0):.2f}%), this IS the hedge, keeping it"
                    )
                else:
                    logger.warning(
                        f"⚡ [NO_LOSS_EXIT] {position_key}: {_pp_noloss_reason}"
                    )
                    side_reduce = "SELL" if is_long else "BUY"
                    pos_amt = abs(
                        safe_fetch_float(getattr(position, "positionAmt", 0.0), 0.0)
                    )
                    if pos_amt > pos_min_qty:
                        result = await queue_trade_action(
                            order_queue,
                            trade_manager,
                            position_key,
                            "QUICK_CLOSE",
                            f"NO_LOSS_EXIT_{_pp_noloss_reason}",
                            0.95,
                        )
                        if result:
                            return f"{EvalStatus.ACTION_TAKEN}:NO_LOSS_EXIT"
            # WT_3M_EXIT KILLED 2026-03-30: Single-TF exit bypassed the 2/3 system. The 2/3 WT exit at line ~19463 handles this correctly.
            _wt1_3m_exit = safe_fetch_float(i.get("wt1_3m", 0), 0.0)
            _wt2_3m_exit = safe_fetch_float(i.get("wt2_3m", 0), 0.0)
            _wt1_1h_exit = safe_fetch_float(i.get("wt1_1h", 0), 0.0)
            _wt2_1h_exit = safe_fetch_float(i.get("wt2_1h", 0), 0.0)
            _wt3m_against = (is_long and _wt1_3m_exit < _wt2_3m_exit) or (
                not is_long and _wt1_3m_exit > _wt2_3m_exit
            )
            _wt1h_against_sh = (is_long and _wt1_1h_exit < _wt2_1h_exit) or (
                not is_long and _wt1_1h_exit > _wt2_1h_exit
            )
            # RULE #3: WT_15M_SAME_HEDGE
            # Requires: 3m AND 1h WT against, gain < -0.5% (genuine loser only — not momentary dips to 0)
            if (
                getattr(config, "WT_15M_SAME_HEDGE_ENABLED", False)
                and _wt3m_against
                and _wt1h_against_sh
                and _pp_gain < -0.5
            ):
                # ═══ 2026-04-16 EXISTENCE GATES RUN FIRST ═══
                # Before reading any indicator or checking any cooldown, refuse to do ANYTHING
                # if (a) a hedge position already exists, (b) an open order for the hedge is
                # already on the exchange, (c) tracker_manager already records an active hedge
                # for this losing position, or (d) a preflight intent lock was taken within 60s.
                # User directive 2026-04-16: "NEVER send anything anywhere unless no other hedge exists".
                _hedge_side = "SHORT" if is_long else "LONG"
                _hedge_pk = f"{account_key}:{symbol}_{_hedge_side}"
                _skip_hedge = False
                _skip_reason = ""
                # (a) hedge position already exists (force-fresh read, positions_service is WS source of truth)
                _hedge_pos_pre = await trade_manager.get_position(
                    _hedge_pk, max_age_s=5.0
                )
                _hedge_existing_pre = (
                    abs(safe_fetch_float(getattr(_hedge_pos_pre, "positionAmt", 0), 0))
                    if _hedge_pos_pre
                    else 0
                )
                if _hedge_existing_pre > 0:
                    _skip_hedge = True
                    _skip_reason = f"HEDGE_ALREADY_OPEN_amt={_hedge_existing_pre:.6f}"
                # (b) pending open orders on hedge side
                if not _skip_hedge:
                    try:
                        _open_orders_fn = getattr(
                            trade_manager, "get_open_orders", None
                        ) or getattr(trade_manager, "fetch_open_orders", None)
                        if _open_orders_fn:
                            _oo = await _open_orders_fn(account_key, symbol)
                            _h_order_side_pre = (
                                "SELL" if _hedge_side == "SHORT" else "BUY"
                            )
                            if _oo:
                                for _o in _oo:
                                    _o_side = (
                                        _o.get("side")
                                        if isinstance(_o, dict)
                                        else getattr(_o, "side", "")
                                    ) or ""
                                    _o_ps = (
                                        _o.get("positionSide")
                                        if isinstance(_o, dict)
                                        else getattr(_o, "positionSide", "")
                                    ) or ""
                                    if (
                                        _o_side.upper() == _h_order_side_pre
                                        and _o_ps.upper() == _hedge_side
                                    ):
                                        _skip_hedge = True
                                        _skip_reason = f"HEDGE_OPEN_ORDER_PENDING_{_o_side}_{_o_ps}"
                                        break
                    except Exception as _oo_e:
                        logger.debug(
                            f"[WT_15M_SAME_HEDGE_OO_CHECK] {_hedge_pk}: {_oo_e}"
                        )
                # (c) tracker_manager already tracks an active hedge for this losing pk
                if (
                    not _skip_hedge
                    and hasattr(trade_manager, "tracker_manager")
                    and trade_manager.tracker_manager
                ):
                    if any(
                        h.get("losing_position_key") == position_key
                        or h.get("position_key") == _hedge_pk
                        for h in trade_manager.tracker_manager.active_hedges
                    ):
                        _skip_hedge = True
                        _skip_reason = "TRACKER_ALREADY_HEDGED"
                # (d) preflight intent lock
                if not _skip_hedge:
                    _pf_h = max(
                        _recent_opens.get(_hedge_pk, 0), _AUGMENT_LOCK.get(_hedge_pk, 0)
                    )
                    if _pf_h > 0 and (time.time() - _pf_h) < 60:
                        _skip_hedge = True
                        _skip_reason = (
                            f"HEDGE_PREFLIGHT_INFLIGHT_{time.time() - _pf_h:.1f}s"
                        )
                if _skip_hedge:
                    logger.debug(
                        f"[WT_15M_SAME_HEDGE_SKIP_EXIST] {position_key}→{_hedge_pk}: {_skip_reason} — not evaluating WT/cooldown"
                    )
                else:
                    _wt1_15m_h = safe_fetch_float(i.get("wt1_15m", 0), 0.0)
                    _wt2_15m_h = safe_fetch_float(i.get("wt2_15m", 0), 0.0)
                    _wt15_against = (is_long and _wt1_15m_h < _wt2_15m_h) or (
                        not is_long and _wt1_15m_h > _wt2_15m_h
                    )
                    if _wt15_against:
                        # Fresh cross gate: 15m WT cross must have happened within last 5 bars (75 min).
                        # Replaced broken wt_cross_prev_value heuristic (compared current wt to penultimate
                        # cross level — fired across nearly entire WT range, useless as a recency gate).
                        _wt15_cross_bars_ago = int(
                            safe_fetch_float(i.get("wt_cross_bars_ago_15m", 999), 999)
                        )
                        _wt15_cross_dir = str(i.get("wt_cross_15m", "")).upper()
                        _expected_cross = "BEAR" if is_long else "BULL"
                        _wt15_fresh_cross = (
                            _wt15_cross_bars_ago <= 5
                            and _wt15_cross_dir == _expected_cross
                        )
                        if _wt15_fresh_cross:
                            _he_wt = getattr(trade_manager, "hedge_engine", None)
                            # ═══ 2026-04-16 REDIS-BACKED COOLDOWN + DAILY CAP ═══
                            # In-memory _hedge_completed is wiped on every ez_manage restart → 300s cooldown
                            # is lost → 45× runs on BAT/DOT/ATOM. Persist to Redis + per-symbol daily cap.
                            _rds_cooldown_key = f"wt_same_hedge_cd:{position_key}"
                            _rds_daily_key = f"wt_same_hedge_daily:{account_key}:{symbol}:{datetime.now(timezone.utc).strftime('%Y%m%d')}"
                            _hc_ts_wt = (
                                _he_wt._hedge_completed.get(position_key, 0)
                                if _he_wt
                                else 0
                            )
                            _rds_ts_raw = None
                            try:
                                if trade_manager.redis_manager:
                                    _rds_ts_raw = await trade_manager.redis_manager.get(
                                        _rds_cooldown_key
                                    )
                            except Exception as _rds_e:
                                logger.debug(
                                    f"[WT_15M_SAME_HEDGE_REDIS_GET] {position_key}: {_rds_e}"
                                )
                            _rds_ts = float(_rds_ts_raw) if _rds_ts_raw else 0
                            _hc_ts_final = max(_hc_ts_wt, _rds_ts)
                            _daily_count = 0
                            try:
                                if trade_manager.redis_manager:
                                    _dc_raw = await trade_manager.redis_manager.get(
                                        _rds_daily_key
                                    )
                                    _daily_count = int(_dc_raw) if _dc_raw else 0
                            except Exception as _rds_e:
                                logger.debug(
                                    f"[WT_15M_SAME_HEDGE_DAILY_GET] {position_key}: {_rds_e}"
                                )
                            _daily_cap = int(
                                getattr(config, "WT_15M_SAME_HEDGE_DAILY_CAP", 2)
                            )
                            _rds_cooldown = int(
                                getattr(config, "WT_15M_SAME_HEDGE_COOLDOWN_SEC", 1800)
                            )
                            if _daily_count >= _daily_cap:
                                logger.warning(
                                    f"[WT_15M_SAME_HEDGE_DAILY_CAP] {position_key}: {_daily_count}/{_daily_cap} hedges today — BLOCKED"
                                )
                            elif (time.time() - _hc_ts_final) < _rds_cooldown:
                                logger.debug(
                                    f"[WT_15M_SAME_HEDGE_COOLDOWN] {position_key}: hedge opened {int(time.time() - _hc_ts_final)}s ago (<{_rds_cooldown}s, Redis-backed), skipping duplicate"
                                )
                            else:
                                _h_qty = abs(
                                    safe_fetch_float(
                                        getattr(position, "positionAmt", 0.0), 0.0
                                    )
                                )
                                logger.warning(
                                    f"[WT_15M_SAME_HEDGE] {position_key}: wt1_15m={_wt1_15m_h:.1f} {'<' if is_long else '>'} wt2_15m={_wt2_15m_h:.1f} fresh_cross={_wt15_cross_bars_ago}bars/{_wt15_cross_dir} wt1h={_wt1_1h_exit:.1f}/wt2h={_wt2_1h_exit:.1f} gain={_pp_gain:.2f}% → HEDGING via hedge_engine.execute_same_symbol_hedge"
                                )
                                _now_ts_h = time.time()
                                if _he_wt:
                                    _he_wt._hedge_completed[position_key] = _now_ts_h
                                try:
                                    if trade_manager.redis_manager:
                                        await trade_manager.redis_manager.set(
                                            _rds_cooldown_key,
                                            str(_now_ts_h),
                                            ex=_rds_cooldown + 60,
                                        )
                                        await trade_manager.redis_manager.set(
                                            _rds_daily_key,
                                            str(_daily_count + 1),
                                            ex=86400 + 3600,
                                        )
                                except Exception as _rds_e:
                                    logger.debug(
                                        f"[WT_15M_SAME_HEDGE_REDIS_SET] {position_key}: {_rds_e}"
                                    )
                                # 2026-04-18 FIX (user directive "WT_15M_SAME_HEDGE is THE PLAGUE"):
                                # Route through HedgeEngine.execute_same_symbol_hedge so hedges inherit
                                # tradeable_keys temp-add (ez_positions_quick.py:5735) + existence checks
                                # + nuke_hedge_key on close. Previously called execute_now directly and
                                # hit NON_TRADEABLE_HARD_BLOCK every time. HedgeEngine also applies its
                                # own HEDGE_COMPLETED_LOCKOUT as an extra safety.
                                _h_result = False
                                if _he_wt:
                                    try:
                                        _h_result = (
                                            await _he_wt.execute_same_symbol_hedge(
                                                account_key,
                                                position,
                                                symbol,
                                                position_side,
                                                _h_qty,
                                                current_price,
                                            )
                                        )
                                    except Exception as _he_e:
                                        logger.error(
                                            f"[WT_15M_SAME_HEDGE_ENGINE_ERR] {_hedge_pk}: {type(_he_e).__name__}: {_he_e}"
                                        )
                                        _h_result = False
                                else:
                                    logger.error(
                                        f"[WT_15M_SAME_HEDGE_NO_ENGINE] {position_key}: no hedge_engine available — ABORT"
                                    )
                                if _h_result:
                                    logger.warning(
                                        f"[WT_15M_SAME_HEDGE_OK] {_hedge_pk}: opened via hedge_engine to hedge {position_key}"
                                    )
                                else:
                                    if _he_wt:
                                        _he_wt._hedge_completed.pop(position_key, None)
                                    try:
                                        if trade_manager.redis_manager:
                                            await trade_manager.redis_manager.delete(
                                                _rds_cooldown_key
                                            )
                                    except Exception:
                                        pass
                                    logger.warning(
                                        f"[WT_15M_SAME_HEDGE_FAIL] {_hedge_pk}: hedge_engine returned False — cooldown/daily-count cleared"
                                    )
            # MANDATORY_HEDGE: gain < -0.5% AND wt1_15m against → MUST have a hedge.
            # Condition: wt1_15m alone (not 3m+15m). Backtest winner: -0.5% / wt_15m (HEDGE_BANDAID_BACKTEST Sharpe 1.24).
            # Skips if: position is itself a hedge, hedge already exists, tracker records hedge, Redis cooldown active.
            _mh_gain_thr = float(
                getattr(config, "MANDATORY_HEDGE_GAIN_THRESHOLD_PCT", -0.5)
            )
            if (
                not bool(getattr(position, "is_hedge", False))
                and _pp_gain < _mh_gain_thr
            ):
                _mh_wt1_15m = safe_fetch_float(i.get("wt1_15m", 0), 0.0)
                _mh_wt2_15m = safe_fetch_float(i.get("wt2_15m", 0), 0.0)
                _mh_wt15m_against = (is_long and _mh_wt1_15m < _mh_wt2_15m) or (
                    not is_long and _mh_wt1_15m > _mh_wt2_15m
                )
                if _mh_wt15m_against:
                    _mh_hedge_side = "SHORT" if is_long else "LONG"
                    _mh_hedge_pk = f"{account_key}:{symbol}_{_mh_hedge_side}"
                    _mh_hedge_pos = await trade_manager.get_position(
                        _mh_hedge_pk, max_age_s=5.0
                    )
                    _mh_hedge_amt = (
                        abs(
                            safe_fetch_float(
                                getattr(_mh_hedge_pos, "positionAmt", 0), 0
                            )
                        )
                        if _mh_hedge_pos
                        else 0
                    )
                    _mh_tracker_hedged = False
                    if (
                        hasattr(trade_manager, "tracker_manager")
                        and trade_manager.tracker_manager
                    ):
                        _mh_tracker_hedged = any(
                            h.get("losing_position_key") == position_key
                            or h.get("position_key") == _mh_hedge_pk
                            for h in trade_manager.tracker_manager.active_hedges
                        )
                    if _mh_hedge_amt > 0 or _mh_tracker_hedged:
                        logger.debug(
                            f"[MANDATORY_HEDGE_EXISTS] {position_key}: hedge present (amt={_mh_hedge_amt:.6f} tracker={_mh_tracker_hedged}) — skip"
                        )
                    else:
                        _mh_cd_key = f"mandatory_hedge_cd:{position_key}"
                        _mh_last = 0.0
                        try:
                            if trade_manager.redis_manager:
                                _mh_raw = await trade_manager.redis_manager.get(
                                    _mh_cd_key
                                )
                                _mh_last = float(_mh_raw) if _mh_raw else 0.0
                        except Exception:
                            pass
                        _mh_cooldown = int(
                            getattr(config, "MANDATORY_HEDGE_COOLDOWN_SEC", 900)
                        )
                        if (time.time() - _mh_last) < _mh_cooldown:
                            logger.debug(
                                f"[MANDATORY_HEDGE_COOLDOWN] {position_key}: {int(time.time() - _mh_last)}s ago < {_mh_cooldown}s"
                            )
                        else:
                            _mh_he = getattr(trade_manager, "hedge_engine", None)
                            _mh_qty = abs(
                                safe_fetch_float(
                                    getattr(position, "positionAmt", 0.0), 0.0
                                )
                            )
                            logger.critical(
                                f"🛡️ [MANDATORY_HEDGE] {position_key}: gain={_pp_gain:.2f}% < {_mh_gain_thr}% wt1_15m against — firing hedge qty={_mh_qty:.6f}"
                            )
                            _mh_ts = time.time()
                            try:
                                if trade_manager.redis_manager:
                                    await trade_manager.redis_manager.set(
                                        _mh_cd_key, str(_mh_ts), ex=_mh_cooldown + 60
                                    )
                            except Exception:
                                pass
                            _mh_result = False
                            if _mh_he:
                                try:
                                    _mh_result = await _mh_he.execute_same_symbol_hedge(
                                        account_key,
                                        position,
                                        symbol,
                                        position_side,
                                        _mh_qty,
                                        current_price,
                                    )
                                except Exception as _mh_e:
                                    logger.error(
                                        f"[MANDATORY_HEDGE_ERR] {_mh_hedge_pk}: {type(_mh_e).__name__}: {_mh_e}"
                                    )
                            else:
                                logger.error(
                                    f"[MANDATORY_HEDGE_NO_ENGINE] {position_key}: no hedge_engine available"
                                )
                            if _mh_result:
                                logger.critical(
                                    f"✅ [MANDATORY_HEDGE_OK] {_mh_hedge_pk}: hedge opened for {position_key}"
                                )
                            else:
                                try:
                                    if trade_manager.redis_manager:
                                        await trade_manager.redis_manager.delete(
                                            _mh_cd_key
                                        )
                                except Exception:
                                    pass
                                logger.warning(
                                    f"[MANDATORY_HEDGE_FAIL] {_mh_hedge_pk}: hedge_engine returned False — cooldown cleared"
                                )
            if _pp_gain > 0.1:
                _pp_hold, _pp_hold_reason = trading_policy.check_winner_momentum(
                    i, is_long
                )
                if _pp_hold:
                    return f"{EvalStatus.NO_ACTION}:WINNER_MOM_HOLD_{_pp_hold_reason}"
            # SATOSHIT TRADE PROTECTION — skip all non-Satoshit exit mechanisms for Satoshit-opened trades
            if getattr(config, "SATOSHIT_PROTECT_TRADES", False) and getattr(
                config, "SATOSHIT_ENABLED", False
            ):
                from ez_satoshit import is_satoshit_trade

                if is_satoshit_trade(position):
                    logger.debug(
                        f"[SATOSHIT_PROTECT] {position_key}: Satoshit trade — skipping standard exit mechanisms, only SATOSHIT_EXIT allowed"
                    )
                    # Jump directly to Satoshit exit check (already wired below), skip STOCH_CROSS/HOLD_BARS/etc
                    _sat_skip_standard_exits = True
                else:
                    _sat_skip_standard_exits = False
            else:
                _sat_skip_standard_exits = False
            # STOCH_CROSS_3M_EXIT REMOVED 2026-04-10 — stoch is way lagging vs DELTA/WT.
            # DELTA→WT priority means stoch should NEVER reach the position. If DELTA fires
            # properly, this function returns earlier. Code path eliminated to remove noise.
            # === PARTIAL_PROFIT_LOCK v2 (2026-04-21) — replaces SATOSHIT_PARTIAL_EXIT 70%.
            # Webhook routing: URL2 is ALWAYS 50% close (Finandy config); URL is 100% close.
            # Step 1 (+0.5%): fire url_2 webhook (Finandy closes 50%); stop_level = entry × (1 ± BE_buffer%).
            #                 maker-first preferred. After this: stop is at break-even + tiny buffer so
            #                 position always closes BEFORE hitting breakeven.
            # Step 2 (+0.75%): upgrade stop_level up to first_exit_price (0.5%-gain level) — locks 0.5%
            #                  scalp gain on the remaining 50%.
            # Step 3 (price ≤ stop_level for long / ≥ for short): close remainder via url (100% of
            #                                                     remaining = 50% of original).
            # User 2026-05-05: PPL_v2 is fine BUT NEVER FOR HEDGES. A hedge is detected
            # by ANY of: is_hedge flag, augment_reason hedge tag, presence in
            # tracker.active_hedges, OR being a de-facto hedge (same-symbol opposite-side
            # in deep loss > OPPOSITE_LOSER_DEEP_LOSS_PCT). Hedges must ride with the
            # rally to offset the losing leg — PPL's BE+0.02% stop closes them at
            # +0.05% which is the exact pattern that bled out 1000LUNCUSDT.
            _ppl_is_hedge = bool(getattr(position, "is_hedge", False))
            if not _ppl_is_hedge:
                _ppl_aug_reason_up = str(
                    getattr(position, "augment_reason", "") or ""
                ).upper()
                if any(
                    _m in _ppl_aug_reason_up
                    for _m in (
                        "HEDGE_PROTECT_",
                        "HEDGE_ELECTED_",
                        "QUICK_HEDGE_",
                        "HEDGE_SAME_",
                        "HEDGE_OPEN",
                        "BANDAID",
                    )
                ):
                    _ppl_is_hedge = True
            if not _ppl_is_hedge:
                try:
                    if (
                        hasattr(trade_manager, "tracker_manager")
                        and trade_manager.tracker_manager
                    ):
                        for _h in (
                            getattr(
                                trade_manager.tracker_manager, "active_hedges", None
                            )
                            or []
                        ):
                            if (
                                _h.get("position_key") == position_key
                                or _h.get("hedge_position_key") == position_key
                            ):
                                _ppl_is_hedge = True
                                break
                except Exception:
                    pass
            if not _ppl_is_hedge:
                try:
                    _ppl_other_pk = (
                        position_key[: -len("_LONG")] + "_SHORT"
                        if is_long
                        else position_key[: -len("_SHORT")] + "_LONG"
                    )
                    _ppl_other_pos = (
                        trade_manager.positions.get(_ppl_other_pk)
                        if hasattr(trade_manager, "positions")
                        else None
                    )
                    if _ppl_other_pos:
                        _ppl_other_amt = abs(
                            safe_fetch_float(
                                getattr(_ppl_other_pos, "positionAmt", 0), 0
                            )
                        )
                        _ppl_other_g = safe_fetch_float(
                            getattr(_ppl_other_pos, "gain", 0), 0
                        )
                        _ppl_dl_pct = float(
                            getattr(config, "OPPOSITE_LOSER_DEEP_LOSS_PCT", -5.0)
                        )
                        if _ppl_other_amt > 0.0001 and _ppl_other_g < _ppl_dl_pct:
                            _ppl_is_hedge = True
                except Exception:
                    pass
            # 2026-05-18 per-sym overlay
            if (
                _psym_get(symbol, position_side, "PARTIAL_PROFIT_LOCK_ENABLED", False)
                and account_key in getattr(config, "PARTIAL_PROFIT_LOCK_ACCOUNTS", [])
                and not _sat_skip_standard_exits
                and not _ppl_is_hedge
            ):
                _ppl_min_gain = float(
                    _psym_get(symbol, position_side, "PARTIAL_PROFIT_LOCK_GAIN_PCT", 0.5)
                )
                _ppl_arm_gain = float(
                    _psym_get(symbol, position_side, "PARTIAL_PROFIT_LOCK_ARM_GAIN_PCT", 0.75)
                )
                _ppl_be_buffer = float(
                    _psym_get(symbol, position_side, "PARTIAL_PROFIT_LOCK_BE_BUFFER_PCT", 0.02)
                )
                _ppl_frac = float(_psym_get(symbol, position_side, "PARTIAL_PROFIT_LOCK_FRAC", 0.5))
                _ppl_use_maker = bool(
                    getattr(config, "PARTIAL_PROFIT_LOCK_USE_MAKER", True)
                )
                if not hasattr(trade_manager, "partial_profit_lock_state"):
                    trade_manager.partial_profit_lock_state = {}
                _ppl_state = trade_manager.partial_profit_lock_state.get(
                    position_key, {}
                )
                _ppl_fired = _ppl_state.get("fired", False)
                _ppl_first_exit_px = float(_ppl_state.get("first_exit_price", 0.0))
                _ppl_stop_level = float(_ppl_state.get("stop_level", 0.0))
                _ppl_stop_upgraded = _ppl_state.get("stop_upgraded", False)
                _ppl_pos_amt = abs(
                    safe_fetch_float(getattr(position, "positionAmt", 0.0), 0.0)
                )
                _ppl_entry_px = safe_fetch_float(
                    getattr(position, "entry_price", 0.0), 0.0
                )
                _ppl_close_side = "SELL" if is_long else "BUY"
                if (
                    not _ppl_fired
                    and _pp_gain >= _ppl_min_gain
                    and _ppl_pos_amt > pos_min_qty
                    and _ppl_entry_px > 0
                ):
                    _ppl_reduce_qty = _ppl_pos_amt * _ppl_frac
                    _ppl_keep_qty = _ppl_pos_amt - _ppl_reduce_qty
                    if _ppl_reduce_qty > pos_min_qty and _ppl_keep_qty > pos_min_qty:
                        _ppl_be_stop = (
                            _ppl_entry_px * (1.0 + _ppl_be_buffer / 100.0)
                            if is_long
                            else _ppl_entry_px * (1.0 - _ppl_be_buffer / 100.0)
                        )
                        _ppl_uid = f"PPL_TP_{position_key}_{int(time.time())}"
                        _ppl_reason = f"PPL_TP_gain{_pp_gain:.2f}_URL2_50pct"
                        logger.warning(
                            f"[PARTIAL_PROFIT_LOCK_TP] {position_key}: gain={_pp_gain:.2f}% ≥ {_ppl_min_gain}% — firing URL2 (Finandy 50%) + BE stop @ {_ppl_be_stop:.6f} (entry={_ppl_entry_px:.6f}, buffer={_ppl_be_buffer}%)"
                        )
                        _ppl_result = await trade_manager.execute_now(
                            position_key,
                            account_key,
                            symbol,
                            _ppl_pos_amt,
                            _ppl_close_side,
                            position_side,
                            _ppl_reduce_qty,
                            current_price,
                            _ppl_uid,
                            _ppl_reason,
                            False,
                            "QUICK_REDUCE",
                            url_variant="2",
                        )
                        _ppl_ok = "SUCCESS" in str(_ppl_result or "").upper()
                        if _ppl_ok:
                            _ppl_eff_entry = (
                                _ppl_entry_px
                                * (1.0 - _ppl_frac * (1.0 + _pp_gain / 100.0))
                                / (1.0 - _ppl_frac)
                                if is_long
                                else _ppl_entry_px
                                * (1.0 - _ppl_frac * (1.0 - _pp_gain / 100.0))
                                / (1.0 - _ppl_frac)
                            )
                            trade_manager.partial_profit_lock_state[position_key] = {
                                "fired": True,
                                "first_exit_price": current_price,
                                "stop_level": _ppl_be_stop,
                                "stop_upgraded": False,
                                "effective_entry": _ppl_eff_entry,
                            }
                            logger.info(
                                f"[PPL_EFF_ENTRY] {position_key}: entry={_ppl_entry_px:.6f} → effective_entry={_ppl_eff_entry:.6f} (gain_locked={_pp_gain:.4f}%, frac={_ppl_frac})"
                            )
                            return f"{EvalStatus.ACTION_TAKEN}:PPL_TP_URL2"
                if (
                    _ppl_fired
                    and not _ppl_stop_upgraded
                    and _pp_gain >= _ppl_arm_gain
                    and _ppl_first_exit_px > 0
                ):
                    trade_manager.partial_profit_lock_state[position_key] = {
                        **_ppl_state,
                        "stop_level": _ppl_first_exit_px,
                        "stop_upgraded": True,
                    }
                    logger.warning(
                        f"[PPL_STOP_UPGRADED] {position_key}: gain={_pp_gain:.2f}% ≥ {_ppl_arm_gain}% — stop upgraded BE→first_exit {_ppl_first_exit_px:.6f} (locks +0.5% scalp)"
                    )
                if _ppl_fired and _ppl_stop_level > 0 and _ppl_pos_amt > pos_min_qty:
                    _sl_hit = (is_long and current_price <= _ppl_stop_level) or (
                        not is_long and current_price >= _ppl_stop_level
                    )
                    if _sl_hit:
                        _ppl_sl_uid = f"PPL_SL_{position_key}_{int(time.time())}"
                        _ppl_sl_reason = f"PPL_SL_{'upgraded' if _ppl_stop_upgraded else 'BE'}_px{current_price:.6f}_stop{_ppl_stop_level:.6f}"
                        logger.warning(
                            f"[PARTIAL_PROFIT_LOCK_SL_HIT] {position_key}: price={current_price:.6f} hit stop={_ppl_stop_level:.6f} ({'upgraded-0.5pct' if _ppl_stop_upgraded else 'BE+buffer'}) — firing URL (100% remainder)"
                        )
                        _sl_result = await trade_manager.execute_now(
                            position_key,
                            account_key,
                            symbol,
                            _ppl_pos_amt,
                            _ppl_close_side,
                            position_side,
                            _ppl_pos_amt,
                            current_price,
                            _ppl_sl_uid,
                            _ppl_sl_reason,
                            True,
                            "QUICK_CLOSE",
                        )
                        _sl_ok = "SUCCESS" in str(_sl_result or "").upper()
                        if _sl_ok:
                            trade_manager.partial_profit_lock_state.pop(
                                position_key, None
                            )
                            return f"{EvalStatus.ACTION_TAKEN}:PPL_SL_CLOSE"
            # SATOSHIT EXIT — partial close via maker order (like Satoshit: take 70% profit, keep 30% runner)
            if (
                getattr(config, "SATOSHIT_EXIT_ENABLED", False)
                and getattr(config, "SATOSHIT_ENABLED", False)
                and account_key in getattr(config, "SATOSHIT_ACCOUNTS", [])
                and _pp_gain > getattr(config, "NOLOSS_MIN_PROFIT_PCT", 0.50)
            ):
                from ez_satoshit import satoshit_exit_check

                _sat_exit, _sat_reason = satoshit_exit_check(
                    i, is_long, config, position_key=position_key
                )
                if _sat_exit:
                    _sat_amt = abs(
                        safe_fetch_float(getattr(position, "positionAmt", 0.0), 0.0)
                    )
                    _sat_partial_pct = getattr(
                        config, "SATOSHIT_EXIT_PARTIAL_PCT", 0.70
                    )
                    _sat_reduce_qty = _sat_amt * _sat_partial_pct
                    _sat_keep_qty = _sat_amt - _sat_reduce_qty
                    if _sat_reduce_qty > pos_min_qty and _sat_keep_qty > pos_min_qty:
                        _sat_side = "SELL" if is_long else "BUY"
                        _sat_unique = (
                            f"SATOSHIT_PARTIAL_{position_key}_{int(time.time())}"
                        )
                        if True:
                            logger.warning(
                                f"[SATOSHIT_PARTIAL_EXIT] {position_key}: {_sat_reason} gain={_pp_gain:.2f}% — routing through execute_now partial close {_sat_partial_pct * 100:.0f}%"
                            )
                            from ez_satoshit import record_satoshit_exit

                            record_satoshit_exit(
                                position_key, "LONG" if is_long else "SHORT", _pp_gain
                            )
                            _sat_result = await trade_manager.execute_now(
                                position_key,
                                account_key,
                                symbol,
                                _sat_amt,
                                _sat_side,
                                position_side,
                                _sat_reduce_qty,
                                current_price,
                                _sat_unique,
                                f"SATOSHIT_EXIT_{_sat_reason}_gain{_pp_gain:.2f}_partial{_sat_partial_pct * 100:.0f}pct",
                                False,
                                "QUICK_REDUCE",
                            )
                            if "SUCCESS" in str(_sat_result or "").upper():
                                logger.warning(
                                    f"[SATOSHIT_PARTIAL_EXIT_OK] {position_key}: execute_now success — runner {_sat_keep_qty:.6f} still riding"
                                )
                                return (
                                    f"{EvalStatus.ACTION_TAKEN}:SATOSHIT_PARTIAL_EXIT"
                                )
                            else:
                                logger.warning(
                                    f"[SATOSHIT_PARTIAL_EXIT_FAILED] {position_key}: execute_now={str(_sat_result or '')[:60]} — not retrying"
                                )
                        else:
                            result = await queue_trade_action(
                                order_queue,
                                trade_manager,
                                position_key,
                                "REDUCE",
                                f"SATOSHIT_EXIT_{_sat_reason}_gain{_pp_gain:.2f}",
                                0.70,
                                override_qty=_sat_reduce_qty,
                            )
                            if result:
                                return f"{EvalStatus.ACTION_TAKEN}:SATOSHIT_EXIT"
            # BACKTEST_CHANGE_15: OPTIMAL_HOLD_BARS — time-based exit when position held too long while in profit
            # BACKTEST_CHANGE_108: Only fire if gain >= NOLOSS_MIN_PROFIT_PCT
            _noloss_min_ohb = getattr(config, "NOLOSS_MIN_PROFIT_PCT", 0.50)
            if (
                not _sat_skip_standard_exits
                and _pp_gain > max(config.GAIN_THRESHOLD_LOW, _noloss_min_ohb)
                and config.TF_FOCUS == "3m"
            ):
                _ohb_max_secs = getattr(config, "OPTIMAL_HOLD_BARS_3M", 21) * 180
                _ohb_opened = getattr(position, "opened_at", None) or getattr(
                    position, "last_augmentation_time", None
                )
                if _ohb_opened:
                    _ohb_age = (
                        (now - _ohb_opened).total_seconds()
                        if isinstance(_ohb_opened, datetime)
                        else 0
                    )
                    if _ohb_age > _ohb_max_secs:
                        _ohb_amt = abs(
                            safe_fetch_float(getattr(position, "positionAmt", 0.0), 0.0)
                        )
                        if _ohb_amt > pos_min_qty:
                            logger.warning(
                                f"[HOLD_BARS_EXIT] {position_key}: held {_ohb_age:.0f}s > {_ohb_max_secs}s ({getattr(config, 'OPTIMAL_HOLD_BARS_3M', 21)} bars) gain={_pp_gain:.2f}%"
                            )
                            result = await queue_trade_action(
                                order_queue,
                                trade_manager,
                                position_key,
                                "QUICK_CLOSE",
                                f"HOLD_BARS_EXIT_{_ohb_age:.0f}s_gain{_pp_gain:.2f}",
                                0.85,
                            )
                            if result:
                                return f"{EvalStatus.ACTION_TAKEN}:HOLD_BARS_EXIT"
            # BACKTEST_CHANGE_12: CYCLE_TP_TIERED — staged take-profit at multiple levels
            # BACKTEST_CHANGE_108: Only fire tiers above NOLOSS_MIN_PROFIT_PCT
            _noloss_min_tpt = getattr(config, "NOLOSS_MIN_PROFIT_PCT", 0.50)
            if (
                not _sat_skip_standard_exits
                and getattr(config, "CYCLE_TP_TIERED_ENABLED", False)
                and _pp_gain > max(0.05, _noloss_min_tpt)
            ):
                _tpt_levels = getattr(
                    config,
                    "CYCLE_TP_TIERED_LEVELS",
                    [0.0015, 0.003, 0.005, 0.007, 0.010, 0.015, 0.020, 0.030],
                )
                _tpt_frac = getattr(config, "CYCLE_TP_TIERED_FRAC", 0.25)
                _tpt_hit = _tiered_tp_hit.get(position_key, set())
                _tpt_gain_frac = _pp_gain / 100.0
                _tpt_fired = False
                for _tpt_idx, _tpt_level in enumerate(_tpt_levels):
                    if _tpt_idx in _tpt_hit:
                        continue
                    if _tpt_gain_frac >= _tpt_level:
                        _tpt_amt = abs(
                            safe_fetch_float(getattr(position, "positionAmt", 0.0), 0.0)
                        )
                        _tpt_reduce_qty = _tpt_amt * _tpt_frac
                        if _tpt_reduce_qty > pos_min_qty:
                            _tpt_hit.add(_tpt_idx)
                            _tiered_tp_hit[position_key] = _tpt_hit
                            logger.warning(
                                f"[TIERED_TP] {position_key}: Tier {_tpt_idx} hit (gain={_pp_gain:.2f}% >= {_tpt_level * 100:.2f}%) reducing {_tpt_frac * 100:.0f}% = {_tpt_reduce_qty:.6f}"
                            )
                            result = await queue_trade_action(
                                order_queue,
                                trade_manager,
                                position_key,
                                "REDUCE",
                                f"CYCLE_TP_TIERED_T{_tpt_idx}_{_tpt_level * 100:.2f}pct_gain{_pp_gain:.2f}",
                                0.80,
                                override_qty=_tpt_reduce_qty,
                            )
                            if result:
                                _tpt_fired = True
                                break
                if _tpt_fired:
                    return f"{EvalStatus.ACTION_TAKEN}:TIERED_TP"
        triggered_stop = None
        stop_levels = (
            trade_manager.stop_levels.get(position_key, [])
            if isinstance(trade_manager.stop_levels, dict)
            else []
        )
        if stop_levels:
            if is_long:
                candidates = [
                    lvl
                    for lvl in stop_levels
                    if isinstance(lvl, StopLevel)
                    and current_price <= safe_float(getattr(lvl, "level", 0.0))
                ]
                if candidates:
                    triggered_stop = max(
                        candidates,
                        key=lambda lvl: safe_float(getattr(lvl, "level", 0.0)),
                    )
            else:
                candidates = [
                    lvl
                    for lvl in stop_levels
                    if isinstance(lvl, StopLevel)
                    and current_price >= safe_float(getattr(lvl, "level", 0.0))
                ]
                if candidates:
                    triggered_stop = min(
                        candidates,
                        key=lambda lvl: safe_float(getattr(lvl, "level", 0.0)),
                    )
        now_secs = time.time()
        if triggered_stop and config.MANAGE_REDUCE:
            breach_started = trade_manager.stop_breach_tracker.get(position_key)
            if breach_started is None:
                trade_manager.stop_breach_tracker[position_key] = now_secs
            else:
                breach_elapsed = now_secs - breach_started
                fallback_delay = float(getattr(config, "STOP_FALLBACK_DELAY", 120.0))
                if breach_elapsed >= fallback_delay:
                    trade_manager.stop_breach_tracker.pop(position_key, None)
                    pos_amt = abs(
                        safe_float(getattr(position, "positionAmt", 0.0), 0.0)
                    )
                    reduction_qty = safe_float(
                        getattr(triggered_stop, "reduction_amount", 0.0)
                    )
                    if reduction_qty <= 0.0 or reduction_qty > pos_amt:
                        reduction_qty = max(0.0, pos_amt - pos_min_qty)
                    else:
                        reduction_qty = min(
                            reduction_qty, max(0.0, pos_amt - pos_min_qty)
                        )
                    if (
                        reduction_qty > pos_min_qty
                        and current_price > 0
                        and config.MANAGE_REDUCE
                    ):
                        side_reduce = "SELL" if is_long else "BUY"
                        unique_id = f"STOP_FALLBACK_{int(now_secs)}_{uuid.uuid4().hex[:6].upper()}"
                        result = await trade_manager.execute_now(
                            position_key,
                            account_key,
                            symbol,
                            pos_amt,
                            side_reduce,
                            position_side,
                            reduction_qty,
                            current_price,
                            unique_id,
                            "STOP_LEVEL_FALLBACK",
                            False,
                            "REDUCE",
                        )
                        if result and "SUCCESS" in result:
                            logger.warning(
                                f"[STOP_FALLBACK] {position_key}: Reduced qty={reduction_qty:.6f} stop={safe_float(getattr(triggered_stop, 'level', 0.0)):.6f} result={result} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}"
                            )
                            return f"{EvalStatus.ACTION_TAKEN}:STOP_LEVEL_FALLBACK"
                        logger.error(
                            f"[STOP_FALLBACK] {position_key}: Reduction failed result={result}"
                        )
                        return f"{EvalStatus.EXECUTION_FAILED}:STOP_LEVEL_FALLBACK"
        else:
            trade_manager.stop_breach_tracker.pop(position_key, None)
        side_params = {
            "op_increase": operator.gt,
            "op_decrease": operator.lt,
            "op_gtoe": operator.ge,
            "good_ha": "green",
            "bad_ha": "red",
            "webhook_increase": "BUY",
            "webhook_decrease": "SELL",
            "stoch_extreme": 80,
            "price_level_15m": "low_15m",
            "dc_break_level_15m": "dc_low4_15m",
            "price_level_3m": "low_3m",
            "dc_break_level_3m": "dc_low4_3m",
            "reverse_cooldown": timedelta(minutes=6),
            "close_rev_cooldown": timedelta(minutes=9),
            "wt_signal_decrease": "SELL",
            "stoch_cross_decrease": "stoch_crossunder_15m",
        }
        if not is_long:
            side_params.update(
                {
                    "op_increase": operator.lt,
                    "op_decrease": operator.gt,
                    "op_gtoe": operator.le,
                    "good_ha": "red",
                    "bad_ha": "green",
                    "stoch_extreme": 20,
                    "price_level_15m": "high_15m",
                    "dc_break_level_15m": "dc_high4_15m",
                    "price_level_3m": "high_3m",
                    "dc_break_level_3m": "dc_high4_3m",
                    "close_rev_cooldown": timedelta(minutes=6),
                    "wt_signal_decrease": "BUY",
                    "stoch_cross_decrease": "stoch_crossover_15m",
                }
            )
        position = await trade_manager.get_position(position_key)
        if not position:
            position = trade_manager.positions_by_account.get(account_key, {}).get(
                position_key
            )
        if not position:
            logger.warning(
                f"[{position_key}] CRITICAL6: Position object vanished during processing - Aborting evaluation."
            )
            return f"{EvalStatus.NO_ACTION}:POSITION_LOST_RACE_CONDITION"
        effective_gain = (
            position.gain
            if position.positionAmt != 0
            else max(position.max_gain, position.prev_gain, position.realized_pnl, 0.0)
        )
        reentry_data = None
        reentry_data_dict = (
            getattr(trade_manager, "reentry_data", {})
            if isinstance(getattr(trade_manager, "reentry_data", {}), dict)
            else {}
        )
        reentry_data = (
            reentry_data_dict.get(position_key)
            if isinstance(reentry_data_dict, dict)
            and isinstance(reentry_data_dict.get(position_key), dict)
            else None
        )
        if not isinstance(reentry_data, dict):
            base_store = (
                getattr(trade_manager, "reentry_data", {})
                if isinstance(getattr(trade_manager, "reentry_data", {}), dict)
                else {}
            )
            candidate = base_store.get(position_key)
            reentry_data = (
                {
                    "reentry_level": safe_float(candidate.get("reentry_level", 0.0)),
                    "amount": safe_float(candidate.get("reentry_amount", 0.0)),
                    "timestamp": safe_datetime(candidate.get("timestamp")),
                    "reason": str(candidate.get("reason", "")),
                }
                if isinstance(candidate, dict)
                else None
            )
        reentry_amount_planned = 0.0
        reentry_amount_planned = (
            float(reentry_data.get("reentry_amount", 0.0) or 0.0)
            if isinstance(reentry_data, dict)
            else 0.0
        )
        if not isinstance(reentry_data, dict):
            reentry_data = {}
        conv_long = i.get("zconviction_long") or i.get("zconviction_augment_long", 0.0)
        conv_short = i.get("zconviction_short") or i.get(
            "zconviction_augment_short", 0.0
        )
        ctx = {
            **base_ctx,
            "now": datetime.now(timezone.utc),
            "account_key": account_key,
            "position": position,
            "event_type": event_type,
            "signal_data": signal_data,
            "position_side": position_side,
            "is_long": is_long,
            "current_price": current_price,
            "gain": effective_gain,
            "positionAmt": position.positionAmt,
            "indicators": i,
            "indicators_snapshot": snapshot,
            "conviction_long": float(conv_long or 0),
            "conviction_short": float(conv_short or 0),
            "conviction_long_reasons": i.get("zconviction_reasons_augment_long", []),
            "conviction_short_reasons": i.get("zconviction_reasons_augment_short", []),
            "config": config,
            "side_params": side_params,
            "force_fresh": True,
            "effective_last_augmentation_time": get_most_recent_timestamp(
                safe_datetime(position.last_augmentation_time)
            ),
            "data_fresh_for_augment": data_fresh_for_augment,
            "reentry_data": reentry_data,
            "reentry_planned_qty": reentry_amount_planned,
        }
        position_value = abs(float(position.positionAmt)) * current_price
        allowed = trade_manager.is_symbol_allowed(account_key, symbol)
        if not allowed:
            if not position or float(position.positionAmt) <= 0.0:
                return f"{EvalStatus.NO_ACTION}:SYMBOL_NOT_ALLOWED_ZERO_POSITION"
        close_3m_prev = safe_fetch_float(
            i.get("close_3m_prev", 0.0), 0.0
        ) or safe_fetch_float(i.get("ha_close_3m_prev", 0.0), 0.0)
        dc_basis_3m = safe_fetch_float(i.get("dc_basis_3m", 0.0), 0.0)
        higher_high = (
            high_3m
            and high_3m_prev
            and low_3m
            and low_3m_prev
            and (high_3m or current_price) >= high_3m_prev
            and low_3m >= low_3m_prev
        )
        lower_low = (
            high_3m
            and high_3m_prev
            and low_3m
            and low_3m_prev
            and high_3m <= high_3m_prev
            and (low_3m or current_price) <= low_3m_prev
        )
        signal_seq = (
            event_type
            if isinstance(event_type, (list, tuple, set))
            else ([event_type] if event_type else [])
        )
        signal_lookup = {str(tag) for tag in signal_seq if tag}
        stoch_crossunder_hit = "stoch_crossunder" in signal_lookup
        stoch_crossover_hit = "stoch_crossover" in signal_lookup
        action_from_signal = (
            (
                signal_data.get("action")
                if signal_data and isinstance(signal_data, dict)
                else ""
            )
            or ""
        ).upper()
        entry_price_check = safe_fetch_float(getattr(position, "entry_price", 0.0), 0.0)
        current_gain = (
            calculate_gain(position_side, current_price, entry_price_check)
            if entry_price_check > 0
            else safe_fetch_float(getattr(position, "gain", 0.0), 0.0)
        )
        _recently_reduced = False
        _lrt = safe_datetime(getattr(position, "last_reduction_time", None))
        if (
            _lrt
            and (now - _lrt).total_seconds() < 600
            and abs(float(position.positionAmt)) * current_price
            < 1.5 * config.START_POSITION_SIZE
        ):
            _recently_reduced = True
            logger.info(
                f"[REENTRY_BYPASS] {position_key}: Recently reduced ({(now - _lrt).total_seconds():.0f}s ago), small position (${abs(float(position.positionAmt)) * current_price:.0f}) — skipping stops, going to eval_funcs"
            )
        fell_through_floor = (
            is_long and dc_low_15m > 0 and current_price < dc_low_15m
        ) or (not is_long and dc_high_15m > 0 and current_price > dc_high_15m)
        if fell_through_floor and current_gain < 0.0:
            if is_strict_no_loss_account(config, account_key) and not getattr(
                config, "DELTA_ENGINE_ENABLED", False
            ):
                logger.info(
                    f"🛑 [DC15M_FORCE_EXIT_BLOCKED] {position_key} breaking floor ({current_gain:.2f}%) but NO_LOSS rule active — holding. L/S ratio will hedge."
                )
            else:
                logger.info(
                    f"🚨 [DC15M_FORCE_EXIT] {position_key} breaking floor ({current_gain:.2f}%). Delta engine active — technical exit allowed."
                )
                return await trade_manager.execute_now(
                    position_key,
                    account_key,
                    symbol,
                    position.positionAmt,
                    ("SELL" if is_long else "BUY"),
                    position_side,
                    position.positionAmt,
                    current_price,
                    f"DC15M_FORCE_EXIT_{int(time.time())}",
                    "DELTA_EXIT_DC15M_FLOOR_BREAK",
                    True,
                    "CLOSE",
                )

        long_stop = (
            is_long
            and position.positionAmt > 0
            and (
                k_15m < d_15m
                or k_3m < d_3m
                or ha_15m == "red"
                or not t_up_3m
                or (k_15m > 80 and wt1_3m < wt2_3m)
                or current_price <= min(low_3m, dc_low_15m)
                or stoch_crossunder_hit
                or "winners_down" in signal_lookup
            )
        )
        short_stop = (
            not is_long
            and position.positionAmt > 0
            and (
                k_15m > d_15m
                or k_3m > d_3m
                or ha_15m == "green"
                or (k_15m < 20 and wt1_3m > wt2_3m)
                or current_price >= max(high_3m, dc_high_15m)
                or stoch_crossover_hit
                or "losers_up" in signal_lookup
            )
        )

        # # --- ALIGNMENT-BASED QUICK TP: exit at intermediate tops BEFORE gains evaporate ---
        # try:
        #     import json as _json
        #     with open('/home/niels/binance/data/alignment_scores.json') as _ef:
        #         _exit_data = _json.load(_ef)
        #     _sym_exit = _exit_data.get(symbol, {})
        #     _exit_signal = _sym_exit.get('exit_long', False) if is_long else _sym_exit.get('exit_short', False)
        #     # Quick TP: if alignment says EXIT and we have ANY gain > 0.10%, take it NOW
        #     # 60s cooldown to prevent retry loop if order fill unconfirmed
        #     if not hasattr(trade_manager, '_alignment_tp_cooldown'):
        #         trade_manager._alignment_tp_cooldown = {}
        #     _tp_last = trade_manager._alignment_tp_cooldown.get(position_key, 0)
        #     if _exit_signal and current_gain > 0.10 and (time.time() - _tp_last) > 60:
        #         trade_manager._alignment_tp_cooldown[position_key] = time.time()
        #         logger.info(f"💰 [ALIGNMENT_TP] {position_key} at {current_gain:.2f}% gain. Alignment exit signal. Taking profit.")
        #         return await trade_manager.execute_now(position_key, account_key, symbol, position.positionAmt, ('SELL' if is_long else 'BUY'), position_side, position.positionAmt, current_price, f"ALIGNMENT_TP_{int(time.time())}", "ALIGNMENT_TP_EXIT", True, 'CLOSE')
        # except Exception:
        #     pass
        # --- GAIN-TIERED PROFIT HARVEST --- (tiered: bigger winners need stronger confirmation)
        _is_trend_acct_m = account_key in getattr(
            trade_manager.config, "TREND_ACCOUNTS", []
        )
        if current_gain > 2.0 and not _is_trend_acct_m and not _recently_reduced:
            _k_1h = safe_fetch_float(i.get("stoch_k_1h", i.get("k_1h")), 50.0)
            _d_1h = safe_fetch_float(i.get("stoch_d_1h", i.get("d_1h")), 50.0)
            _ha_1h = i.get("ha_1h", i.get("ha_color_1h", ""))
            if current_gain >= 10.0:
                _htf_long_exit = (
                    is_long and _k_1h < _d_1h and str(_ha_1h).lower() == "red"
                )
                _htf_short_exit = (
                    not is_long and _k_1h > _d_1h and str(_ha_1h).lower() == "green"
                )
                _harvest_ok = _htf_long_exit or _htf_short_exit
                _tier = "BIG_WINNER_HTF"
            elif current_gain >= 5.0:
                _med_long_exit = is_long and ha_15m == "red" and k_15m < d_15m
                _med_short_exit = not is_long and ha_15m == "green" and k_15m > d_15m
                _harvest_ok = _med_long_exit or _med_short_exit
                _tier = "MED_WINNER_15M"
            else:
                _harvest_ok = False
                _tier = "HOLD"
            if _harvest_ok:
                logger.info(
                    f"💰 [IN_GAIN_TREND_EXIT] {position_key} at {current_gain:.2f}% gain. Tier={_tier}. Harvesting profit."
                )
                return await trade_manager.execute_now(
                    position_key,
                    account_key,
                    symbol,
                    position.positionAmt,
                    ("SELL" if is_long else "BUY"),
                    position_side,
                    position.positionAmt,
                    current_price,
                    f"PROFIT_HARVEST_{int(time.time())}",
                    "IN_GAIN_TREND_EXIT",
                    True,
                    "CLOSE",
                )
            elif current_gain >= 5.0:
                logger.info(
                    f"🛡️ [WINNER_HOLD] {position_key} at {current_gain:.2f}% gain. Tier={_tier} HTF not confirmed — HOLDING."
                )

        # --- DC BASIS PROFIT EXIT (LAST RESORT PRE-EMPTION) ---
        basis_crossed = (
            is_long and dc_basis_15m > 0 and current_price < dc_basis_15m
        ) or (not is_long and dc_basis_15m > 0 and current_price > dc_basis_15m)
        if (
            current_gain > 3.0
            and basis_crossed
            and not _is_trend_acct_m
            and not _recently_reduced
        ):
            logger.info(
                f"⚖️ [DC_BASIS_PROFIT_EXIT] {position_key} at {current_gain:.2f}% gain. Price crossed basis. Exiting before floor hit."
            )
            return await trade_manager.execute_now(
                position_key,
                account_key,
                symbol,
                position.positionAmt,
                ("SELL" if is_long else "BUY"),
                position_side,
                position.positionAmt,
                current_price,
                f"BASIS_PROFIT_EXIT_{int(time.time())}",
                "DC_BASIS_PROFIT_EXIT",
                True,
                "CLOSE",
            )

        # --- IMMEDIATE WRONG WAY PROTECTION --- BACKTEST_CHANGE_114: DISABLED — #2 PnL destroyer. Tight stops kill trades that recover.
        opened_at_dt = (
            safe_datetime(getattr(position, "last_augmentation_time", None))
            if hasattr(position, "last_augmentation_time")
            and position.last_augmentation_time
            else None
        )
        position_age_seconds = (
            (now - opened_at_dt).total_seconds() if opened_at_dt else float("inf")
        )
        if (
            getattr(config, "IMMEDIATE_WRONG_WAY_ENABLED", False)
            and position_age_seconds < 120
            and current_gain < -0.12
        ):
            logger.critical(
                f"🛑 [IMMEDIATE_WRONG_WAY] {position_key} went WRONG IMMEDIATELY. Age: {position_age_seconds:.1f}s, Gain: {current_gain:.2f}%. Indicators: ha15={i.get('ha_15m')}, k15={i.get('stoch_k_15m', 0):.1f}, event={event_type}. CLOSING AND REPORTING."
            )
            return await trade_manager.execute_now(
                position_key,
                account_key,
                symbol,
                position.positionAmt,
                ("SELL" if is_long else "BUY"),
                position_side,
                position.positionAmt,
                current_price,
                f"WRONG_WAY_KILL_{int(time.time())}",
                "IMMEDIATE_WRONG_WAY_EXIT",
                True,
                "CLOSE",
            )

        if (
            not config.HEDGE_MODE
            and not _recently_reduced
            and (current_gain <= 1.0 and getattr(position, "max_gain", 0.0) > 3.0)
        ):
            # PROTECT HEDGE: if opposite side of SAME SYMBOL is in loss, this IS the hedge — do NOT close
            _opp_side = "SHORT" if is_long else "LONG"
            _opp_key = f"{account_key}:{symbol}_{_opp_side}"
            _opp_pos = trade_manager.positions.get(_opp_key)
            _opp_in_loss = (
                _opp_pos
                and abs(safe_fetch_float(getattr(_opp_pos, "positionAmt", 0), 0)) > 0
                and safe_fetch_float(getattr(_opp_pos, "gain", 0), 0) < 0.0
            )
            if _opp_in_loss:
                logger.warning(
                    f"[BREAK_EVEN_GUARD_SKIP] {position_key}: peak {position.max_gain:.2f}% → {current_gain:.2f}% BUT opposite {_opp_key} is in loss ({getattr(_opp_pos, 'gain', 0):.2f}%) — this IS the hedge, keeping it"
                )
            elif current_gain > safe_fetch_float(
                getattr(position, "_prev_gain_beg", current_gain), current_gain
            ):
                position._prev_gain_beg = current_gain
                logger.debug(
                    f"[BREAK_EVEN_GUARD_HOLD] {position_key}: gain still rising ({current_gain:.2f}%), waiting for turn"
                )
            else:
                position._prev_gain_beg = current_gain
                logger.info(
                    f"[BREAK_EVEN_GUARD] {position_key} peak {position.max_gain:.2f}% drop to {current_gain:.2f}%. Closing + scheduling 120% reentry."
                )
                _re_qty = abs(position.positionAmt) * 1.2
                trade_manager.reentry_data[position_key] = {
                    "reentry_level": current_price,
                    "reentry_amount": _re_qty,
                    "timestamp": datetime.now(timezone.utc).strftime(
                        "%Y-%m-%dT%H:%M:%S.%fZ"
                    ),
                    "reason": "BREAK_EVEN_GUARD_120PCT_REENTRY",
                }
                return await trade_manager.execute_now(
                    position_key,
                    account_key,
                    symbol,
                    position.positionAmt,
                    ("SELL" if is_long else "BUY"),
                    position_side,
                    position.positionAmt,
                    current_price,
                    f"BREAK_EVEN_GUARD_{int(time.time())}",
                    "BREAK_EVEN_GUARD_EXIT",
                    True,
                    "CLOSE",
                )
        price_below_dc_low_3m_long = (
            is_long and dc_low_3m > 0 and current_price < dc_low_3m
        )
        price_above_dc_high_3m_short = (
            not is_long and dc_high_3m > 0 and current_price > dc_high_3m
        )
        if (
            (price_below_dc_low_3m_long or price_above_dc_high_3m_short)
            and position.positionAmt > pos_min_qty
            and not config.HEDGE_MODE
            and not _recently_reduced
        ):
            if _check_loss_protection(position, position_key):
                logger.debug(
                    f"[LOSS_PROTECTION] {position_key}: not_allowed DC_BASIS_3M_REDUCE - gain={current_gain:.3f}%"
                )
            elif config.MANAGE_REDUCE:
                last_reduction_time = getattr(position, "last_reduction_time", None)
                reduction_cooldown_ok = (
                    not last_reduction_time
                    or (now - last_reduction_time).total_seconds()
                    >= config.REDUCTION_COOLDOWN_SECONDS
                )
                if reduction_cooldown_ok:
                    side = "SELL" if is_long else "BUY"
                    unique_id = generate_unique_id(
                        position_key, side, "DC_BASIS_3M_REDUCE"
                    )
                    reduce_qty = max(
                        0.0, abs(float(position.positionAmt)) - pos_min_qty
                    )
                    if reduce_qty > pos_min_qty:
                        logger.warning(
                            f"[DC_3M_REDUCE] {position_key}: Price {'below' if is_long else 'above'} dc_basis_3m (price={current_price:.6f} dc_basis_3m={dc_basis_3m:.6f}) - Reducing to pos_min_qty"
                        )
                        logger.info(
                            f"[execute_trade_action][{account_key}] 'REDUCE' {position_key} {current_price:.6f} PROCESS_POSITION REDUCE"
                        )
                        result = await trade_manager.execute_now(
                            position_key,
                            account_key,
                            symbol,
                            position.positionAmt,
                            side,
                            position_side,
                            reduce_qty,
                            current_price,
                            unique_id,
                            f"DC_BASIS_3M_REDUCE: price_{'below' if is_long else 'above'}_dc_basis_3m",
                            True,
                            "REDUCE",
                        )
                        if result and "SUCCESS" in result:
                            logger.warning(
                                f"[DC_3M_REDUCE] {position_key}: Successfully reduced to pos_min_qty (qty={reduce_qty:.6f})"
                            )
                            return f"{EvalStatus.ACTION_TAKEN}:DC_BASIS_3M_REDUCE"
                        elif result:
                            logger.warning(
                                f"[DC_BASIS_3M_REDUCE] {position_key}: Reduction queued/executing: {result}"
                            )
                else:
                    logger.debug(
                        f"[DC_BASIS_3M_REDUCE] {position_key}: Skipped - reduction cooldown active"
                    )
        opened_at_dt = (
            safe_datetime(getattr(position, "last_augmentation_time", None))
            if hasattr(position, "last_augmentation_time")
            and position.last_augmentation_time
            else None
        )
        position_age_seconds = (
            (now - opened_at_dt).total_seconds() if opened_at_dt else float("inf")
        )
        position_age_minutes = position_age_seconds / 60.0
        is_old_enough_stop = position_age_minutes > 6.0
        has_crossunder_signal_stop = False
        if i:
            stoch_crossunder_3m = i.get("stoch_crossunder_3m", False) or False
            stoch_crossunder_15m = i.get("stoch_crossunder_15m", False) or False
            dc_basis_crossunder_3m = i.get("dc_basis_crossunder_3m", False) or False
            wt_crossunder_3m = i.get("wt_crossunder_3m", False) or False
            stoch_crossover_3m = i.get("stoch_crossover_3m", False) or False
            stoch_crossover_15m = i.get("stoch_crossover_15m", False) or False
            dc_basis_crossover_3m = i.get("dc_basis_crossover_3m", False) or False
            wt_crossover_3m = i.get("wt_crossover_3m", False) or False
            has_crossunder_signal_stop = (
                is_long
                and (
                    stoch_crossunder_3m
                    or stoch_crossunder_15m
                    or dc_basis_crossunder_3m
                    or wt_crossunder_3m
                )
            ) or (
                not is_long
                and (
                    stoch_crossover_3m
                    or stoch_crossover_15m
                    or dc_basis_crossover_3m
                    or wt_crossover_3m
                )
            )
        about_to_be_in_loss_stop = current_gain < 0.1
        position = await trade_manager.get_position(position_key)
        _rpk_rh = position_key.split(":", 1)[1] if ":" in position_key else position_key
        _reduce_huge_thresh = config.get_symbol_setting(
            account_key, _rpk_rh, "REDUCE_HUGE_LOSS_THRESHOLD"
        )
        # BACKTEST_CHANGE_113: Block STOP_MAJOR_LOSS entirely — #1 PnL destroyer (-125k%). L/S ratio IS the hedge.
        if (
            not getattr(config, "STOP_MAJOR_LOSS_BLOCK_ENABLED", True)
            and (long_stop or short_stop)
            and config.MANAGE_REDUCE
            and not _recently_reduced
            and (current_gain < _reduce_huge_thresh or current_gain > 0.5)
            and min_since_aug > 12.0
            and (
                has_crossunder_signal_stop
                or (is_old_enough_stop and about_to_be_in_loss_stop)
                and position.positionAmt > 1.5 * pos_min_qty / current_price
            )
        ):
            if _check_loss_protection(position, position_key):
                logger.debug(
                    f"[LOSS_PROTECTION] {position_key}: not_allowed STOP_MAJOR_LOSS_REDUCE Allowing anyway- gain={current_gain:.3f}%"
                )
                return
            side = "SELL" if is_long else "BUY"
            if (is_long and side != "SELL") or (not is_long and side != "BUY"):
                logger.error(
                    f"[CRITICAL_SIDE_MISMATCH] {position_key}: side={side} does NOT match position_side={position_side} (is_long={is_long})! BLOCKING ORDER!"
                )
                return f"CRITICAL_SIDE_MISMATCH_{side}_{position_side}"
            if is_strict_no_loss_account(config, account_key):
                return f"{EvalStatus.NO_ACTION}:MAJOR_LOSS_BLOCKED_STRICT_NO_LOSS"
            unique_id = generate_unique_id(position_key, side, "STOP_MAJOR_LOSS_REDUCE")
            close_qty = max(
                0.0, abs(float(position.positionAmt)) - pos_min_qty
            )  # Always leave pos_min_qty
            if is_hedge_account(config, account_key) and current_gain < 0.35:
                logger.warning(
                    f"[HEDGE_MODE_BLOCK] {position_key}: Blocking STOP_MAJOR_LOSS_REDUCE - position gain < 0.35% (gain={current_gain:.2f}%) when HEDGE_MODE=True"
                )
                if (
                    hasattr(trade_manager, "hedge_engine")
                    and trade_manager.hedge_engine
                    and current_price
                    and current_price > 0
                ):
                    positionAmt_stop = abs(
                        safe_fetch_float(getattr(position, "positionAmt", 0.0), 0.0)
                    )
                    if (
                        hasattr(trade_manager, "tracker_manager")
                        and trade_manager.tracker_manager
                    ):
                        async with trade_manager.tracker_manager._hedges_lock:
                            active_hedge_stop = None
                            for hedge in trade_manager.tracker_manager.active_hedges:
                                if (
                                    hedge.get("account") == account_key
                                    and hedge.get("losing_position_key") == position_key
                                ):
                                    active_hedge_stop = hedge
                                    break
                        if active_hedge_stop:
                            logger.info(
                                f"🛡️ [HEDGE_CHECK] Hedge already exists for {position_key}"
                            )
                        else:
                            logger.warning(
                                f"🛡️ [HEDGE_NEEDED] No hedge found for {position_key}, placing dual hedge immediately"
                            )
                            losing_value_usd_stop = positionAmt_stop * current_price
                            hedge_result_stop = (
                                await trade_manager.hedge_engine.execute_dual_hedge(
                                    account_key=account_key,
                                    losing_position_key=position_key,
                                    losing_symbol=symbol,
                                    losing_side=position_side,
                                    losing_value_usd=losing_value_usd_stop,
                                    dry_run=False,
                                )
                            )
                            if hedge_result_stop.get("overall_status") in [
                                "success",
                                "partial",
                            ]:
                                logger.info(
                                    f" [HEDGE_PLACED] Dual hedge created for {position_key}"
                                )
                                return f"HEDGE_MODE_BLOCK_STOP_MAJOR_LOSS_REDUCE"
                            else:
                                if current_gain < _reduce_huge_thresh:
                                    logger.error(
                                        f"🛑 [SUICIDE_PREVENTION] Hedge failed! BLOCKING REDUCE because loss is {current_gain:.2f}%. We will NOT suicide."
                                    )
                                    return "HEDGE_FAILED_BLOCKED_SUICIDE"
                                logger.warning(
                                    f"⚠️ [HEDGE_FAILED] Could not create dual hedge for {position_key}: {hedge_result_stop}"
                                )
            result = await trade_manager.execute_now(
                position_key,
                account_key,
                symbol,
                position.positionAmt,
                side,
                position_side,
                close_qty,
                current_price,
                unique_id,
                f"REDUCE_HUGE_LOSS: {current_gain:.2f}% loss with indicators against",
                True,
                "REDUCE",
            )
            if "SUCCESS" in result:
                logger.info(
                    f"[🚨 REDUCE_HUGE_LOSS] {position_key}: Reduced position to pos_min_qty with {current_gain:.2f}% loss"
                )
                return f"{EvalStatus.ACTION_TAKEN}:REDUCE_HUGE_LOSS"
        position = await trade_manager.get_position(position_key)
        if (
            (long_stop or short_stop) and config.MANAGE_REDUCE and not _recently_reduced
        ):  # KILL LARGE POSITIONS to 2*START_POSITION_SIZE
            if is_strict_no_loss_account(config, account_key):
                return f"{EvalStatus.NO_ACTION}:STOP_KILL_BLOCKED_STRICT_NO_LOSS"
            if (
                not position
                or not hasattr(position, "positionAmt")
                or abs(float(position.positionAmt))
                <= 0.5 * config.START_POSITION_SIZE / current_price
            ):
                return
            opened_at = getattr(position, "opened_at", None)
            time_since_entry = minutes_since(opened_at) if opened_at else 999999
            should_stop_kill = False
            if (
                getattr(config, "LOSS_EXIT_STOP_FUNCTIONS_KILL_ENABLED", False)
                and current_gain < -5.0
                and position.positionAmt
                > 5 * config.START_POSITION_SIZE / current_price
            ):
                should_stop_kill = True
                logger.info(
                    f"[{position_key}] ${position.positionAmt * current_price} STOP_FUNCTIONS_KILL allowed: gain={current_gain:.2f}% < -0.7%"
                )
            elif time_since_entry >= 5.0:
                if is_long and k_3m is not None and d_3m is not None and k_3m < d_3m:
                    should_stop_kill = True
                    logger.info(
                        f"[{position_key}] ${position.positionAmt * current_price} STOP_FUNCTIONS_KILL allowed: time_since_entry={time_since_entry:.1f}min >= 5min, k_3m={(k_3m or 0.0):.1f} < d_3m={(d_3m or 0.0):.1f}"
                    )
                elif (
                    not is_long
                    and k_3m is not None
                    and d_3m is not None
                    and k_3m > d_3m
                ):
                    should_stop_kill = True
                    logger.info(
                        f"[{position_key}] ${position.positionAmt * current_price} STOP_FUNCTIONS_KILL allowed: "
                        f"time_since_entry={time_since_entry:.1f}min >= 5min, "
                        f"k_1m={(safe_fetch_float(k_1m) or 0.0):.1f} > d_1m={(safe_fetch_float(d_1m) or 0.0):.1f} "
                        f"k_3m={(safe_fetch_float(k_3m) or 0.0):.1f} > d_3m={(safe_fetch_float(d_3m) or 0.0):.1f} "
                        f"k_15m={(safe_fetch_float(k_15m) or 0.0):.1f} > d_15m={(safe_fetch_float(d_15m) or 0.0):.1f} "
                        f"gain {current_gain}"
                    )
                else:
                    logger.info(
                        f"[{position_key}] ${position.positionAmt * current_price} STOP_FUNCTIONS_KILL not allowed: "
                        f"time_since_entry={time_since_entry:.1f}min < 3min or gain={current_gain:.2f}% | "
                        f"k_1m={(safe_fetch_float(k_1m) or 0.0):.1f} > d_1m={(safe_fetch_float(d_1m) or 0.0):.1f} "
                        f"k_3m={(safe_fetch_float(k_3m) or 0.0):.1f} > d_3m={(safe_fetch_float(d_3m) or 0.0):.1f} "
                        f"k_15m={(safe_fetch_float(k_15m) or 0.0):.1f} > d_15m={(safe_fetch_float(d_15m) or 0.0):.1f}"
                    )
            if should_stop_kill:
                if is_hedge_account(config, account_key) and current_gain < 0.17:
                    # FIX 2026-04-03: Check how long position has been unhedged. If hedge keeps failing AND position
                    # is bleeding beyond -15%, allow STOP_FUNCTIONS_KILL through (partial size reduction only).
                    if not hasattr(trade_manager, "_hmb_unhedged_ts"):
                        trade_manager._hmb_unhedged_ts = {}
                    _hmb_has_hedge = (
                        hasattr(trade_manager, "tracker_manager")
                        and trade_manager.tracker_manager
                        and any(
                            h.get("losing_position_key") == position_key
                            for h in trade_manager.tracker_manager.active_hedges
                        )
                    )
                    if not _hmb_has_hedge:
                        if position_key not in trade_manager._hmb_unhedged_ts:
                            trade_manager._hmb_unhedged_ts[position_key] = time.time()
                        _hmb_wait_min = (
                            time.time() - trade_manager._hmb_unhedged_ts[position_key]
                        ) / 60.0
                    else:
                        trade_manager._hmb_unhedged_ts.pop(position_key, None)
                        _hmb_wait_min = 0
                    _hmb_escape = (
                        getattr(
                            config, "LOSS_EXIT_HEDGE_MODE_BLOCK_ESCAPE_ENABLED", False
                        )
                        and not _hmb_has_hedge
                        and current_gain < -15.0
                        and _hmb_wait_min > 30.0
                    )
                    if _hmb_escape:
                        logger.critical(
                            f"[HEDGE_MODE_BLOCK_ESCAPE] {position_key}: gain={current_gain:.2f}% unhedged for {_hmb_wait_min:.0f}min. Hedge failed repeatedly. Allowing partial reduction to slow bleeding."
                        )
                    else:
                        logger.warning(
                            f"[HEDGE_MODE_BLOCK] {position_key}: Blocking STOP_FUNCTIONS_KILL - position gain < 0.17% (gain={current_gain:.2f}%) when HEDGE_MODE=True"
                        )
                        if (
                            hasattr(trade_manager, "hedge_engine")
                            and trade_manager.hedge_engine
                            and current_price
                            and current_price > 0
                        ):
                            positionAmt_kill = abs(
                                safe_fetch_float(
                                    getattr(position, "positionAmt", 0.0), 0.0
                                )
                            )
                            if account_key in ["flz"]:
                                hedge_side_kill = "SHORT" if is_long else "LONG"
                                hedge_key_kill = construct_position_key(
                                    account_key, symbol, hedge_side_kill
                                )
                                existing_hedge_kill = (
                                    trade_manager.positions_by_account.get(
                                        account_key, {}
                                    ).get(hedge_key_kill)
                                )
                                if (
                                    existing_hedge_kill
                                    and abs(
                                        safe_fetch_float(
                                            existing_hedge_kill.positionAmt, 0.0
                                        )
                                    )
                                    > 0
                                ):
                                    logger.info(
                                        f"🛡️ [HEDGE_CHECK] Hedge already exists for {position_key} at {hedge_key_kill}"
                                    )
                                else:
                                    logger.warning(
                                        f"🛡️ [HEDGE_NEEDED] No hedge found for {position_key}, placing same-symbol hedge immediately"
                                    )
                                    await trade_manager.hedge_engine.execute_same_symbol_hedge(
                                        account_key,
                                        position,
                                        symbol,
                                        position_side,
                                        positionAmt_kill,
                                        current_price,
                                    )
                            else:
                                losing_value_usd_kill = positionAmt_kill * current_price
                                await trade_manager.hedge_engine.execute_dual_hedge(
                                    account_key=account_key,
                                    losing_position_key=position_key,
                                    losing_symbol=symbol,
                                    losing_side=position_side,
                                    losing_value_usd=losing_value_usd_kill,
                                    dry_run=False,
                                )
                        return f"HEDGE_MODE_BLOCK_STOP_FUNCTIONS_KILL"
                side = "SELL" if is_long else "BUY"
                if (is_long and side != "SELL") or (not is_long and side != "BUY"):
                    logger.error(
                        f"[CRITICAL_SIDE_MISMATCH] {position_key}: side={side} does NOT match position_side={position_side} (is_long={is_long})! BLOCKING ORDER!"
                    )
                    return f"CRITICAL_SIDE_MISMATCH_{side}_{position_side}"
                unique_id = generate_unique_id(
                    position_key, side, "STOP_FUNCTIONS_KILL"
                )
                logger.info(
                    f"[STOP_FUNCTIONS_KILL] {position_key}: side={side} position_side={position_side} is_long={is_long}"
                )
                if (
                    position.positionAmt
                    > 3 * config.START_POSITION_SIZE / current_price
                    and position.gain > 0.4
                    and config.MANAGE_REDUCE
                ):
                    reduce_qty_kill1 = max(
                        0.0,
                        min(
                            position.positionAmt
                            - 2 * config.START_POSITION_SIZE / current_price,
                            position.positionAmt - pos_min_qty,
                            position.positionAmt * 0.99,
                        ),
                    )
                    if reduce_qty_kill1 > 0 and reduce_qty_kill1 < position.positionAmt:
                        reason = f"STOP_FUNCTIONS_KILL_1 time_since_entry={time_since_entry}min >= 3min, k_1m={k_1m} > d_1m={d_1m} k_3m={k_3m} > d_3m={d_3m} k_15m={k_15m} > d_15m={d_15m} gain {current_gain}"
                        await trade_manager.execute_now(
                            position_key,
                            account_key,
                            symbol,
                            position.positionAmt,
                            side,
                            position_side,
                            reduce_qty_kill1,
                            current_price,
                            unique_id,
                            reason,
                            False,
                            "REDUCE",
                        )
                elif (
                    position.positionAmt
                    > 2 * config.START_POSITION_SIZE / current_price
                    and position.gain < 0.4
                    and position_age_minutes > 18
                    and config.MANAGE_REDUCE
                ):
                    reduce_qty_kill2 = max(
                        0.0,
                        min(
                            position.positionAmt - pos_min_qty,
                            position.positionAmt * 0.99,
                        ),
                    )
                    if (
                        reduce_qty_kill2 > 0
                        and reduce_qty_kill2 < position.positionAmt
                        and config.MANAGE_REDUCE
                    ):
                        reason = f"STOP_FUNCTIONS_KILL_2 time_since_entry={time_since_entry}min >= 3min, k_1m={k_1m:} > d_1m={d_1m} k_3m={k_3m} > d_3m={d_3m} k_15m={k_15m} > d_15m={d_15m:} gain {current_gain}"
                        await trade_manager.execute_now(
                            position_key,
                            account_key,
                            symbol,
                            position.positionAmt,
                            side,
                            position_side,
                            reduce_qty_kill2,
                            current_price,
                            unique_id,
                            reason,
                            False,
                            "REDUCE",
                        )
                logger.info(
                    f"[{position_key}] STOP_FUNCTIONS_KILL REJECTED: Position would be stopped out immediately (gain={current_gain:.2f}%)"
                )
                return f"{EvalStatus.NO_ACTION}:STOP_PROTECTION_ACTIVE"
        # --- MANDATORY PROFIT TAKE (MOMENTUM EXHAUSTION) ---
        if current_gain > 0.5 and not _recently_reduced:
            tp_reason = ""
            tp_price = current_price
            if is_long and k_15m > 95 and k_15m < k_15m_prev:
                tp_reason = f"PROFIT_TP_EXHAUSTION_k15:{k_15m:.1f}"
            elif not is_long and k_15m < 5 and k_15m > k_15m_prev:
                tp_reason = f"PROFIT_TP_EXHAUSTION_k15:{k_15m:.1f}"
            elif (
                is_long
                and k_15m > 95
                and low_3m > 0
                and low_3m_prev > 0
                and low_3m < low_3m_prev
            ):
                tp_reason = f"OB_LOWER_LOW_k15:{k_15m:.1f}_lo3:{low_3m:.2f}<prev:{low_3m_prev:.2f}"
                tp_price = close_3m_prev if close_3m_prev > 0 else current_price
            elif (
                is_long
                and k_3m > 60
                and k_3m < k_3m_prev
                and (k_15m > 95 or k_1h > 85)
                and low_3m > 0
                and low_3m_prev > 0
                and low_3m < low_3m_prev
            ):
                tp_reason = f"K3M_BOUNCE_TURN_L_k3:{k_3m:.1f}<prev:{k_3m_prev:.1f}_k15:{k_15m:.1f}_k1h:{k_1h:.1f}_lo3:{low_3m:.2f}<prev:{low_3m_prev:.2f}"
                tp_price = close_3m_prev if close_3m_prev > 0 else current_price
            elif is_long and low_3m_prev > 0 and current_price < low_3m_prev:
                cliff = dc_low_3m > 0 and current_price < dc_low_3m and k_3m < 30
                tp_price = (
                    current_price
                    if cliff
                    else (close_3m_prev if close_3m_prev > 0 else current_price)
                )
                tp_reason = f"HARD_DROP_BELOW_PREV_LOW:{current_price:.2f}<lo3prev:{low_3m_prev:.2f}{'_CLIFF_dc' if cliff else '_BOUNCE_WAIT'}"
            elif (
                not is_long
                and k_15m < 5
                and low_3m > 0
                and low_3m_prev > 0
                and low_3m > low_3m_prev
            ):
                tp_reason = f"OS_HIGHER_LOW_k15:{k_15m:.1f}_lo3:{low_3m:.2f}>prev:{low_3m_prev:.2f}"
                tp_price = close_3m_prev if close_3m_prev > 0 else current_price
            elif (
                not is_long
                and k_3m < 40
                and k_3m > k_3m_prev
                and (k_15m < 5 or k_1h < 15)
                and high_3m > 0
                and high_3m_prev > 0
                and high_3m > high_3m_prev
            ):
                tp_reason = f"K3M_BOUNCE_TURN_S_k3:{k_3m:.1f}>prev:{k_3m_prev:.1f}_k15:{k_15m:.1f}_k1h:{k_1h:.1f}_hi3:{high_3m:.2f}>prev:{high_3m_prev:.2f}"
                tp_price = close_3m_prev if close_3m_prev > 0 else current_price
            elif not is_long and high_3m_prev > 0 and current_price > high_3m_prev:
                cliff = dc_high_3m > 0 and current_price > dc_high_3m and k_3m > 70
                tp_price = (
                    current_price
                    if cliff
                    else (close_3m_prev if close_3m_prev > 0 else current_price)
                )
                tp_reason = f"HARD_RISE_ABOVE_PREV_HIGH:{current_price:.2f}>hi3prev:{high_3m_prev:.2f}{'_CLIFF_dc' if cliff else '_BOUNCE_WAIT'}"
            if tp_reason:
                logger.warning(
                    f"💰 [MOMENTUM_TP] {position_key}: Gain {current_gain:.2f}% tp_price={tp_price:.4f} reason={tp_reason}. Executing REDUCE."
                )
                side = "SELL" if is_long else "BUY"
                unique_id = generate_unique_id(position_key, side, "MOMENTUM_TP")
                result = await trade_manager.execute_now(
                    position_key,
                    account_key,
                    symbol,
                    position.positionAmt,
                    side,
                    position_side,
                    position.positionAmt,
                    tp_price,
                    unique_id,
                    tp_reason,
                    True,
                    "REDUCE",
                )
                if result and "SUCCESS" in result:
                    return f"{EvalStatus.ACTION_TAKEN}:MOMENTUM_TP"

        if not position:
            logger.warning(
                f"[{position_key}] CRITICAL7: Position vanished post-MOMENTUM_TP — Aborting evaluation."
            )
            return f"{EvalStatus.NO_ACTION}:POSITION_LOST_RACE_CONDITION"
        logger.info(f"[[PP2] {position_key}] afterstops")
        if config.VERBOSE:
            logger.info(
                f"[VERBOSE][CALC] {position_key} 📊 INDICATOR_VALUES: price=${current_price:.2f} ha_3m={ha_3m} ha_15m={ha_15m} k_3m={k_3m:} k_3m_prev={k_3m_prev:} d_3m={d_3m:} k_15m={k_15m:} d_15m={d_15m:} k_15m_prev={k_15m_prev:} k_1h={k_1h:} d_1h={d_1h:} k_4h={k_4h:} d_4h={d_4h:} t_up_3m={t_up_3m} t_up_15m={t_up_15m} sma_200_1m={sma_200_1m:.2f} gain={position.gain:.2f}% positionAmt={position.positionAmt:.6f} t15:{timestamp_15m} t3:{timestamp_3m} t1:{timestamp_1m}"
            )
        if is_long:
            ha_ok = (
                ha_3m == "green"
                and k_3m > k_3m_prev
                and (
                    t_up_3m
                    or k_15m > d_15m
                    or ((k_15m > 50 and k_3m > d_3m) or (k_15m < 30 and k_3m > d_3m))
                    or (k_15m > k_15m_prev and k_15m < 70)
                )
            )  # and ha_15m == 'green' and current_price >= sma_200_1m) #and atr_3m > atr_3m_prev
        else:
            ha_ok = (
                ha_3m == "red"
                and k_3m < k_3m_prev
                and (
                    (not t_up_3m)
                    or (not t_up_15m)
                    or k_15m < d_15m
                    or ((k_15m < 50 and k_3m < d_3m) or (k_15m > 70 and k_3m < d_3m))
                    or (k_15m < k_15m_prev and k_15m > 20)
                )
            )  # and ha_15m == 'red' and current_price <= sma_200_1m)#and atr_3m > atr_3m_prev
        if config.VERBOSE:
            logger.info(
                f"[VERBOSE][CALC] {position_key} TREND_GATE_CHECK: ha_ok={ha_ok} is_long={is_long} ha_3m={ha_3m} k_3m={k_3m:} k_3m_prev={k_3m_prev:} t_up_3m={t_up_3m} k_15m={k_15m:} d_15m={d_15m:}"
            )
        if not _recently_reduced and trade_manager._check_htf_confirmation(
            position_key,
            is_long,
            i,
            k_1h,
            k_1h_prev,
            k_4h,
            k_4h_prev,
            k_15m,
            k_15m_prev,
            d_15m,
            k_3m,
            k_3m_prev,
            safe_fetch_float(i.get("wt1_3m", 0), 0.0),
            safe_fetch_float(i.get("wt2_3m", 0), 0.0),
            safe_fetch_float(i.get("wt1_15m", 0), 0.0),
            safe_fetch_float(i.get("wt2_15m", 0), 0.0),
            current_price,
            sma_200_1m,
            safe_fetch_float(i.get("sma_200_1m_prev", 0), 0.0),
            config,
            action="OPEN",
        ):
            logger.debug(
                f"[HTF_CHECK] {position_key}: HTF confirmation failed — proceeding to evaluators anyway (sizing handles HTF disagree)"
            )
        if signal_data and isinstance(
            signal_data, dict
        ):  # DOUBLE INSTANCE SEE WHICH ONE LASTS
            event_hint = str(signal_data.get("event_type") or event_type or "")
            if event_hint and (
                "winners_all_green" in event_hint or "losers_all_red" in event_hint
            ):
                info = _parse_ranking_event_type(event_hint)
                sig_type = info.get("signal_type")
                direction = info.get("direction")
                group = info.get("group")
                if sig_type in ("all_green", "all_red") and direction == "entry":
                    if (is_long and group == "winners") or (
                        (not is_long) and group == "losers"
                    ):
                        base_amt = abs(
                            float(getattr(position, "positionAmt", 0.0) or 0.0)
                        )
                        auto_action = (
                            "OPEN"
                            if base_amt <= config.START_POSITION_SIZE / current_price
                            else "AUGMENT"
                        )
                        conviction_hint = float(signal_data.get("conviction") or 65.0)
                        reason_code = f"ALL_GREEN/RED_{sig_type.upper()}_{auto_action}_{event_hint}"
                        logger.warning(
                            f"[{position_key}] AUTO_SIGNAL_DIRECT {event_hint} -> {auto_action}"
                        )
                        queue_result = await queue_trade_action(
                            order_queue,
                            trade_manager,
                            position_key,
                            auto_action,
                            reason_code,
                            conviction_hint,
                        )
                        if isinstance(queue_result, str) and queue_result.startswith(
                            "QUEUED_"
                        ):
                            try:
                                await symbol_tracker.track_completion(
                                    position_key,
                                    f"{EvalStatus.ACTION_TAKEN}:{auto_action}:{event_hint}",
                                )
                            except Exception as e:
                                logger.warning(
                                    f"[{position_key}] Auto signal tracking failed: {e}"
                                )
                            return (
                                f"{EvalStatus.ACTION_TAKEN}:{auto_action}:{event_hint}"
                            )
                        logger.error(
                            f"[{position_key}] AUTO_SIGNAL_QUEUE_FAILED {event_hint} -> {queue_result}"
                        )
                        return f"{EvalStatus.EXECUTION_FAILED}:AUTO_SIGNAL_{event_hint}"
        eval_funcs = []
        include_reversal_eval = (
            account_key == "fin"
            and config.REV_MODE
            and abs(float(getattr(position, "positionAmt", 0.0))) > 0.0
        )
        if include_reversal_eval and not getattr(
            config, "ABLATION_DISABLE_ENTRY_REVERSAL", False
        ):
            eval_funcs.append(evaluate_reversal_entry)
        should_consider_reentry = (
            position.positionAmt
            < max(config.START_POSITION_SIZE / current_price, 1.5 * pos_min_qty)
        ) and (
            (is_long and k_3m > k_3m_prev)
            or (
                not is_long
                and (
                    k_3m < k_3m_prev
                    or (k_3m == 0 and k_15m > 30 and k_15m < d_15m)
                    or (k_15m > 30 and k_15m < d_15m and k_3m > 50)
                )
            )
        )
        if not should_consider_reentry and not is_long:
            logger.debug(
                f"[SHORT_REENTRY_CHECK] {position_key}: should_consider_reentry=False - positionAmt={position.positionAmt:.6f} max={max(config.START_POSITION_SIZE / current_price, 1.5 * pos_min_qty):.6f} k_3m={k_3m:} k_3m_prev={k_3m_prev:} condition={position.positionAmt < max(config.START_POSITION_SIZE / current_price, 1.5 * pos_min_qty)} and k_3m < k_3m_prev"
            )
        elif should_consider_reentry and not is_long:
            logger.info(
                f"[SHORT_REENTRY_CHECK] {position_key}: should_consider_reentry=True - positionAmt={position.positionAmt:.6f} k_3m={k_3m:} k_3m_prev={k_3m_prev:} - WILL EVALUATE REENTRY"
            )
        last_reduction_time = getattr(position, "last_reduction_time", None)
        last_reduction_amount = safe_fetch_float(
            getattr(position, "last_reduction_amount", 0.0), 0.0
        )
        gain_threshold = 0.3 * config.MIN_GAIN
        should_consider_augmentation = (
            (not should_consider_reentry)
            and position.positionAmt > pos_min_qty
            and position.gain > gain_threshold
            and ((is_long and k_3m > k_3m_prev) or (not is_long and k_3m < k_3m_prev))
        )
        # BACKTEST_CHANGE_115: FAST_RISER_DOUBLE disabled — net negative PnL in ablation test
        if (
            config.ENABLE_FAST_RISER_REDUCE
            and getattr(config, "FAST_RISER_DOUBLE_ENABLED", False)
            and not getattr(config, "ABLATION_DISABLE_FAST_RISER", False)
            and close_3m_prev > 0
            and position.positionAmt > 2 * pos_min_qty
            and current_gain > 0.8
            and low_3m > 0
            and low_3m_prev > 0
        ):
            current_low_below_prev_long = is_long and low_3m < low_3m_prev
            current_low_above_prev_short = not is_long and low_3m > low_3m_prev
            price_jump_pct = (
                (current_price - close_3m_prev) / close_3m_prev
                if close_3m_prev > 0
                else 0.0
            )
            quick_jump_long = (
                is_long
                and current_price > close_3m_prev
                and abs(price_jump_pct) >= 0.002
                and ha_3m == "green"
                and current_low_below_prev_long
            )
            quick_jump_short = (
                not is_long
                and current_price < close_3m_prev
                and abs(price_jump_pct) >= 0.002
                and ha_3m == "red"
                and current_low_above_prev_short
            )
            if quick_jump_long or quick_jump_short:
                opened_at_dt = (
                    safe_datetime(getattr(position, "opened_at", None))
                    if hasattr(position, "opened_at") and position.opened_at
                    else None
                )
                position_age_seconds = (
                    (now - opened_at_dt).total_seconds()
                    if opened_at_dt
                    else float("inf")
                )
                is_new_position = (
                    position_age_seconds < config.NEW_POSITION_MIN_AGE_SECONDS
                )
                if (
                    is_new_position
                    and position.gain > config.NEW_POSITION_MAX_LOSS_THRESHOLD
                ):
                    logger.debug(
                        f"[NEW_POSITION_PROTECTION] {position_key}: Blocking fast riser action - position is new ({position_age_seconds:.1f}s old) and gain {position.gain:.2f}% > threshold {config.NEW_POSITION_MAX_LOSS_THRESHOLD:.2f}%"
                    )
                elif (is_long and k_3m < 60 and k_3m > d_3m) or (
                    not is_long and k_3m > 40 and k_3m < d_3m
                ):
                    augment_qty = max(
                        abs(float(position.positionAmt)),
                        2 * config.START_POSITION_SIZE / current_price,
                    )
                    max_positionAmt = (
                        config.MAX_POSITION_SIZE / current_price
                        if current_price > 0
                        else float("inf")
                    )
                    if (
                        augment_qty > 0
                        and abs(float(position.positionAmt)) + augment_qty
                        <= max_positionAmt
                    ):
                        side = "BUY" if is_long else "SELL"
                        unique_id = generate_unique_id(
                            position_key, side, "FAST_RISER_DOUBLE"
                        )
                        logger.warning(
                            f"[FAST_RISER_DOUBLE] {position_key}: Quick jump detected (price={current_price:.6f} vs prev_close={close_3m_prev:.6f} k_3m={k_3m:.1f} gain={current_gain:.2%}) - DOUBLING position"
                        )
                        result = await trade_manager.execute_now(
                            position_key,
                            account_key,
                            symbol,
                            position.positionAmt,
                            side,
                            position_side,
                            augment_qty,
                            current_price,
                            unique_id,
                            f"FAST_RISER_DOUBLE_100%_k_3mm={k_3m:.1f}",
                            False,
                            "AUGMENT",
                        )
                        if result and "SUCCESS" in result:
                            logger.warning(
                                f"[FAST_RISER_DOUBLE] {position_key}: Successfully doubled position ({augment_qty:.6f})"
                            )
                            return f"{EvalStatus.ACTION_TAKEN}:FAST_RISER_DOUBLE"
                        elif result:
                            logger.warning(
                                f"[FAST_RISER_DOUBLE] {position_key}: Augmentation queued/executing: {result}"
                            )
                elif (
                    is_long
                    and k_3m > 95
                    and (
                        (
                            k_1m is not None
                            and k_1m_prev is not None
                            and k_1m > k_1m_prev
                        )
                        or k_3m < k_3m_prev
                    )
                ) or (
                    not is_long
                    and k_3m < 5
                    and (
                        (
                            k_1m is not None
                            and k_1m_prev is not None
                            and k_1m > k_1m_prev
                        )
                        or k_3m > k_3m_prev
                    )
                ):
                    mark_price = safe_fetch_float(
                        getattr(position, "mark_price", 0.0), 0.0
                    )
                    current_price_from_i = safe_fetch_float(
                        i.get("current_price", 0), current_price
                    )
                    if (
                        mark_price > 0
                        and current_price_from_i > 0
                        and mark_price < current_price_from_i
                    ):
                        last_reduction_time = getattr(
                            position, "last_reduction_time", None
                        )
                        reduction_cooldown_ok = (
                            not last_reduction_time
                            or (now - last_reduction_time).total_seconds()
                            >= config.REDUCTION_COOLDOWN_SECONDS
                        )
                        if reduction_cooldown_ok and config.MANAGE_REDUCE:
                            reduce_qty = abs(float(position.positionAmt)) * 0.5
                            if (
                                reduce_qty > pos_min_qty
                                and reduce_qty
                                < abs(float(position.positionAmt)) - pos_min_qty
                                and config.MANAGE_REDUCE
                            ):
                                side = "SELL" if is_long else "BUY"
                                unique_id = generate_unique_id(
                                    position_key, side, "FAST_RISER_REDUCE"
                                )
                                target_price = close_3m_prev
                                logger.warning(
                                    f"[FAST_RISER_REDUCE] {position_key}: Fast riser very overbought (price={current_price:.6f} vs prev_close={close_3m_prev:.6f} k_3m={k_3m:.1f} mark_price={mark_price:.6f} < current_price={current_price_from_i:.6f} gain={current_gain:.2%}) - Reducing 50% at prev close price {target_price:.6f}"
                                )
                                logger.info(
                                    f"[execute_trade_action][{account_key}] ❌ 'REDUCE' {position_key} {current_price:.6f} PROCESS_POSITION_3 REDUCE"
                                )
                                result = await trade_manager.execute_now(
                                    position_key,
                                    account_key,
                                    symbol,
                                    position.positionAmt,
                                    side,
                                    position_side,
                                    reduce_qty,
                                    target_price,
                                    unique_id,
                                    f"FAST_RISER_REDUCE_50%_at_prev_close_{close_3m_prev:.6f}",
                                    False,
                                    "REDUCE",
                                )
                                if result and "SUCCESS" in result:
                                    logger.warning(
                                        f"[FAST_RISER_REDUCE] {position_key}: Successfully reduced 50% ({reduce_qty:.6f}) at prev close price {target_price:.6f}"
                                    )
                                    return (
                                        f"{EvalStatus.ACTION_TAKEN}:FAST_RISER_REDUCE"
                                    )
                                elif result:
                                    logger.warning(
                                        f"[FAST_RISER_REDUCE] {position_key}: Reduction queued/executing: {result}"
                                    )
                            elif config.VERBOSE:
                                logger.info(
                                    f"[FAST_RISER_REDUCE] {position_key}: Skipped - reduce_qty={reduce_qty:.6f} pos_min_qty={pos_min_qty:.6f} positionAmt={abs(float(position.positionAmt)):.6f}"
                                )
                        elif config.VERBOSE:
                            logger.info(
                                f"[FAST_RISER_REDUCE] {position_key}: Skipped - reduction cooldown active"
                            )
                    elif config.VERBOSE:
                        logger.debug(
                            f"[FAST_RISER_REDUCE] {position_key}: Skipped - mark_price={mark_price:.6f} >= current_price={current_price_from_i:.6f} (condition not met)"
                        )
        if _recently_reduced and not should_consider_reentry:
            should_consider_reentry = True
            logger.info(
                f"[REENTRY_FORCE] {position_key}: Forcing reentry consideration — recently reduced, overriding momentum gate"
            )
        # DD BOUNCE STOP — cut extra leg if price continued below aug price after double-down
        if getattr(config, "DD_BOUNCE_ENABLED", False) and getattr(
            config, "DD_BOUNCE_DD_STOP_ENABLED", True
        ):
            _dbs = getattr(trade_manager, "_dd_bounce_state", {}).get(symbol, {})
            _dd_qty = float(_dbs.get("dd_qty", 0.0))
            _dd_aug_price = float(_dbs.get("last_aug_price", 0.0))
            _dd_stop_hit = (
                _dd_qty > pos_min_qty
                and _dd_aug_price > 0
                and (
                    (current_price < _dd_aug_price)
                    if is_long
                    else (current_price > _dd_aug_price)
                )
            )
            if _dd_stop_hit:
                _dd_reason = f"DD_BOUNCE_STOP px={current_price:.6f} aug_px={_dd_aug_price:.6f} qty={_dd_qty:.6f}"
                logger.info(f"[{account_key}] ✂️ DD_STOP {position_key}: {_dd_reason}")
                result = await queue_trade_action(
                    order_queue,
                    trade_manager,
                    position_key,
                    "REDUCE",
                    _dd_reason,
                    80.0,
                    override_qty=_dd_qty,
                )
                getattr(trade_manager, "_dd_bounce_state", {}).setdefault(symbol, {})[
                    "dd_qty"
                ] = 0.0
                return f"{EvalStatus.ACTION_TAKEN}:DD_BOUNCE_STOP"
        if not getattr(config, "ABLATION_DISABLE_ENTRY_TECHNICAL", False):
            eval_funcs.append(evaluate_technical_indicator_signals)
        if not getattr(config, "ABLATION_DISABLE_ENTRY_LEADERBOARD", False):
            eval_funcs.append(evaluate_leaderboard_entry)
        if not getattr(config, "ABLATION_DISABLE_ENTRY_RANKING", False):
            eval_funcs.append(evaluate_ranking_momentum_trade)
        if (
            should_consider_reentry
            and not getattr(config, "ABLATION_DISABLE_REENTRY", False)
            and bool(getattr(config, "EZ_REENTRY_INLINE_ENABLED", True))
        ):
            eval_funcs.append(evaluate_reentry)
        if should_consider_augmentation and not getattr(
            config, "ABLATION_DISABLE_AUGMENTATION", False
        ):
            eval_funcs.append(evaluate_augmentation)
        if getattr(config, "SATOSHIT_ENABLED", False) and account_key in getattr(
            config, "SATOSHIT_ACCOUNTS", []
        ):
            from ez_satoshit import evaluate_satoshit_entry

            eval_funcs.append(evaluate_satoshit_entry)
        eval_funcs = list(dict.fromkeys(eval_funcs))

        async def _timed_eval(fn):
            t0 = time.perf_counter()
            try:
                result = (
                    await fn(ctx)
                    if inspect.iscoroutinefunction(fn)
                    else await asyncio.to_thread(fn, ctx)
                )
                elapsed = time.perf_counter() - t0
                if config.VERBOSE:
                    action_str = (
                        result.action
                        if (result and hasattr(result, "action"))
                        else "NO_RESULT"
                    )
                    conviction_str = (
                        f" conviction={result.conviction:.2f}"
                        if (result and hasattr(result, "conviction"))
                        else ""
                    )
                    reason_str = (
                        f" reason={result.reason[:80]}"
                        if (result and hasattr(result, "reason"))
                        else ""
                    )
                    logger.info(
                        f"[VERBOSE][CALC] {position_key} 🔶 EVAL_COMPLETE: {fn.__name__} -> action={action_str}{conviction_str}{reason_str} (took {elapsed:.3f}s)"
                    )
                if (
                    result
                    and hasattr(result, "action")
                    and result.action != "NO_ACTION"
                ):
                    logger.info(
                        f"🔶 [ez_manage] EVAL_RESULT: {position_key} | {fn.__name__} -> {result.action}"
                    )
                if elapsed > 0.3:
                    logger.warning(
                        f"[{position_key}] SLOW_FUNCTION {fn.__name__} {elapsed:.3f}s"
                    )
                return result
            except Exception as e:
                logger.error(
                    f"[{position_key}] TIMER {fn.__name__} {time.perf_counter() - t0:.3f}s - FAILED: {e}"
                )
                return None

        tasks = [asyncio.create_task(_timed_eval(f)) for f in eval_funcs]
        async_signals = (
            await asyncio.gather(*tasks, return_exceptions=True) if tasks else []
        )
        signals = []
        logger.debug(
            f"[🔍 SIGNAL_TRACKING] {position_key}: Processing {len(async_signals)} async_signals from {[f.__name__ for f in eval_funcs]}"
        )
        for idx, r in enumerate(async_signals):
            eval_func_name = eval_funcs[idx].__name__
            if isinstance(r, Exception):
                logger.warning(
                    f"[❌ SIGNAL_ERROR] {position_key}: {eval_func_name} raised exception: {r}"
                )
                continue
            if r is None:
                logger.debug(
                    f"[🚫 NO_SIGNAL] {position_key}: {eval_func_name} returned None"
                )
                continue
            if isinstance(r, str):
                r = Signal(action="NO_ACTION", reason=str(r), conviction=0.0)
            if not hasattr(r, "action"):
                if isinstance(r, ReentryResult) and r.should_trigger and r.quantity > 0:
                    r = Signal(
                        action="REENTRY",
                        reason=f"{r.signal_name}_{r.reason}",
                        conviction=float(r.conviction or 50.0),
                        quantity=float(r.quantity),
                    )
                elif isinstance(r, ReentryResult):
                    r = Signal(
                        action="NO_ACTION",
                        reason=f"REENTRY_BLOCKED_{r.signal_name}_{r.reason}",
                        conviction=0.0,
                    )
                else:
                    r = Signal(
                        action="NO_ACTION",
                        reason=f"UNEXPECTED_RESULT_{type(r).__name__}",
                        conviction=0.0,
                    )
            signal_action = getattr(r, "action", "NO_ACTION")
            signal_conviction = getattr(r, "conviction", 0.0)
            signal_reason = getattr(r, "reason", "N/A")
            logger.info(
                f"[📊 SIGNAL_DETAILS] {position_key}: {eval_func_name} → action={signal_action}, conviction={signal_conviction:.2f}, reason={signal_reason[:100]}"
            )
            if signal_action and signal_action != "NO_ACTION":
                signals.append(r)
                logger.info(
                    f"[ TRADE_SIGNAL_ACCEPTED] {position_key}: {eval_func_name} → action={signal_action}, conviction={signal_conviction:.2f}, reason={signal_reason} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}"
                )
            else:
                logger.info(
                    f"[❌ SIGNAL_REJECTED] {position_key}: {eval_func_name} → action={signal_action} is NOT actionable"
                )
        if not signals:
            fallback_signal = None
            if signal_data and isinstance(signal_data, dict):
                action_hint = str(signal_data.get("action") or "").upper()
                event_hint = str(signal_data.get("event_type") or event_type or "")
                try:
                    fallback_conviction = float(signal_data.get("conviction") or 25.0)
                except (TypeError, ValueError):
                    fallback_conviction = 25.0
                pos_amt = (
                    abs(safe_float(getattr(position, "positionAmt", 0.0), 0.0))
                    if position
                    else 0.0
                )
                if action_hint == "BUY":
                    if position_side == "LONG":
                        fallback_action = (
                            "OPEN" if pos_amt <= pos_min_qty else "AUGMENT"
                        )
                        fallback_signal = Signal(
                            action=fallback_action,
                            reason=f"FALLBACK_{fallback_action}_{event_hint} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}",
                            conviction=fallback_conviction,
                        )
                    elif position_side == "SHORT" and pos_amt > pos_min_qty:
                        fallback_signal = Signal(
                            action="CLOSE",
                            reason=f"FALLBACK_CLOSE_{event_hint}",
                            conviction=fallback_conviction,
                        )
                elif action_hint == "SELL":
                    if position_side == "SHORT":
                        fallback_action = (
                            "OPEN" if pos_amt <= pos_min_qty else "AUGMENT"
                        )
                        fallback_signal = Signal(
                            action=fallback_action,
                            reason=f"FALLBACK_{fallback_action}_{event_hint} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}",
                            conviction=fallback_conviction,
                        )
                    elif position_side == "LONG" and pos_amt > pos_min_qty:
                        fallback_signal = Signal(
                            action="CLOSE",
                            reason=f"FALLBACK_CLOSE_{event_hint} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}",
                            conviction=fallback_conviction,
                        )
            if fallback_signal:
                signals.append(fallback_signal)
                logger.warning(
                    f"[{position_key}] FALLBACK_SIGNAL_USED action={fallback_signal.action} reason={fallback_signal.reason} ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}"
                )
        logger.debug(
            f"[ TTTTTTRADE_SIGNALS_FOUND] {position_key}: {len(signals)} actionable signals ready to execute"
        )

        def _signal_strength(sig: Signal) -> tuple:
            raw_conv = getattr(sig, "conviction", 0.0)
            try:
                conv_value = float(raw_conv)
            except (TypeError, ValueError):
                conv_value = 0.0
            magnitude = abs(conv_value)
            alignment = conv_value if is_long else -conv_value
            return (magnitude, alignment)

        valid_signals = sorted(signals, key=_signal_strength, reverse=True)
        if not valid_signals:
            return f"{EvalStatus.NO_ACTION}:NO_SIGNALS ts3/15:{i.get('timestamp_3m')}/{i.get('timestamp_15m')}"
        best_signal = valid_signals[0]
        logger.info(
            f"[🎯 SELECTING_BEST_SIGNAL] {position_key}: Selected action={best_signal.action}, conviction={best_signal.conviction:.2f}, reason={best_signal.reason[:200]}"
        )
        logger.info(
            f"[🚀 EXECUTING_TRADE] {position_key}: Calling queue _trade_action with action={best_signal.action}, conviction={best_signal.conviction:.2f}"
        )
        override_qty = (
            getattr(best_signal, "quantity", None)
            if hasattr(best_signal, "quantity")
            and getattr(best_signal, "quantity", 0.0) > 0.0
            else None
        )
        result = await queue_trade_action(
            order_queue,
            trade_manager,
            position_key,
            best_signal.action,
            best_signal.reason,
            best_signal.conviction,
            override_qty=override_qty,
        )
        try:
            await symbol_tracker.track_completion(
                position_key,
                f"{EvalStatus.ACTION_TAKEN}:{best_signal.action}:{best_signal.reason[:50]}",
            )
        except Exception as e:
            logger.warning(f"[{position_key}] Error tracking signal completion: {e}")
        return f"{EvalStatus.ACTION_TAKEN}:{best_signal.action}"
    except Exception as e:
        logger.exception(f"[{position_key}] Unhandled error in process_position")
        return f"{EvalStatus.ERROR}:UNHANDLED_EXCEPTION:{str(e)}"
    finally:
        trade_manager.position_last_processed[position_key] = time.time()
        if position_key in trade_manager.processing_keys:
            trade_manager.processing_keys.remove(position_key)


async def get_ladder_data(symbol, account_key, position, trade_manager):
    position_key = construct_position_key(
        account_key, position.symbol, position.position_side
    )
    if not position_key:
        logger.error(
            f"[getlad] ⚠️ SKIPPING - constrct_position_key returned None: account={account_key}, symbol={position.symbol}, pos_side={position.position_side}"
        )
        return
    ensure_refresh = getattr(trade_manager, "ensure_ladder_snapshot_fresh", None)
    if callable(ensure_refresh):
        await ensure_refresh()
    ladder_store = (
        getattr(trade_manager, "ladder_snapshot", {})
        if isinstance(getattr(trade_manager, "ladder_snapshot", {}), dict)
        else {}
    )
    entry = ladder_store.get(position_key)
    if isinstance(entry, dict):
        ladder_levels_store = getattr(trade_manager, "ladder_levels", {})
        if isinstance(ladder_levels_store, dict):
            ladder_levels_store[position_key] = entry
        return entry
    ladder_levels_store = getattr(trade_manager, "ladder_levels", {})
    fallback_entry = (
        ladder_levels_store.get(position_key)
        if isinstance(ladder_levels_store, dict)
        else None
    )
    if isinstance(fallback_entry, dict) and isinstance(ladder_store, dict):
        ladder_store[position_key] = fallback_entry
    return fallback_entry


