def _breakout_tf_size_mult(reason: str) -> tuple:
    """Parse TF marker from an entry reason and return (multiplier, tf_label) per BREAKOUT_TF_SIZE_MULT_* config.
    Returns (1.0, '') if disabled or no TF marker found. Matches tokens _3M_ / _15M_ / _1H_ / _4H_ / _D_
    (with word boundaries so '3m' inside another token doesn't double-match). Higher TF wins when multiple present."""
    if not bool(getattr(config, "BREAKOUT_TF_SIZE_ENABLED", True)):
        return 1.0, ""
    if not reason:
        return 1.0, ""
    _r = reason.upper()
    # Check highest TF first so the largest multiplier wins when multiple markers appear in the reason.
    _tf_checks = [
        ("_D_", float(getattr(config, "BREAKOUT_TF_SIZE_MULT_D", 4.0)), "D"),
        ("_4H_", float(getattr(config, "BREAKOUT_TF_SIZE_MULT_4H", 3.0)), "4H"),
        ("_1H_", float(getattr(config, "BREAKOUT_TF_SIZE_MULT_1H", 2.0)), "1H"),
        ("_15M_", float(getattr(config, "BREAKOUT_TF_SIZE_MULT_15M", 1.0)), "15M"),
        ("_3M_", float(getattr(config, "BREAKOUT_TF_SIZE_MULT_3M", 0.5)), "3M"),
    ]
    for _marker, _mult, _lbl in _tf_checks:
        if _marker in _r:
            _cap = float(getattr(config, "BREAKOUT_TF_SIZE_CAP_MULT", 5.0))
            return min(_mult, _cap), _lbl
    return 1.0, ""


async def queue_trade_action(
    order_queue: OrderQueue,
    trade_manager: "MultiAccountTradeManager",
    position_key: Optional[str] = None,
    action: str = "",
    reason: str = "",
    conviction: float = 0.5,
    override_qty: Optional[float] = None,
    account_key: Optional[str] = None,
) -> str:
    logger.info(f"[queue_trade_action] 🚨 Queueing: {position_key} ")
    now = datetime.now(timezone.utc)
    conviction = safe_fetch_float(conviction, 0.5)
    reason_str = str(reason or "")
    try:
        account_key, symbol, position_side = parse_position_key(position_key)
        if account_key not in trade_manager.accounts:
            logger.warning(
                f"[queue_trade_action] SKIPPING: {position_key} account mismatch"
            )
            return f"SKIPPED_ACCOUNT_MISMATCH_{account_key}"
        is_long = position_side == "LONG"
        if action in [
            "AUGMENT",
            "OPEN",
            "QUICK_OPEN",
            "QUICK_AUGMENT",
            "REENTRY",
            "HEDGE_OPEN",
            "REVERSE_AUGMENT",
        ]:
            side = "BUY" if is_long else "SELL"
        elif action in [
            "REDUCE",
            "QUICK_CLOSE",
            "CLOSE",
            "SELL",
            "PROFIT_TAKE",
            "HEDGE_CLOSE",
            "REVERSE_REDUCE",
        ]:
            side = "SELL" if is_long else "BUY"
        elif action == "REVERSE":
            side = "SELL" if is_long else "BUY"  # Initial action is close
        else:
            logger.critical(
                f"[UNMAPPED_ACTION_BLOCK] {position_key}: action='{action}' is NOT in any known action list — BLOCKING to prevent wrong-direction order. Fix the caller!"
            )
            return f"BLOCKED_UNMAPPED_ACTION_{action}"
        side, is_valid_side = trade_manager.validate_order_side(
            side, position_side, action, position_key
        )
        if not override_qty:  # Skip checks if manual override
            if action in ("OPEN", "AUGMENT", "REENTRY") and getattr(
                trade_manager, "redis_manager", None
            ):
                open_block = await trade_manager.redis_manager.get(
                    f"open_blocked:{position_key}"
                )
                if open_block:
                    logger.warning(
                        f"[{position_key}] {action} blocked: consecutive unverified OPEN failures. Key=open_blocked:{position_key}"
                    )
                    return f"SKIPPED_OPEN_BLOCKED_{action}"
            if await trade_manager.is_duplicate_order(
                position_key, 0.0, side, unique_id="queue_check"
            ):
                logger.debug(
                    f"[{position_key}] SKIPPED: Duplicate/Rapid-fire order detected"
                )
                return f"SKIPPED_DUPLICATE_{action}"
            if hasattr(trade_manager, "orders_in_limbo"):
                if (
                    position_key in trade_manager.orders_in_limbo
                    and side in trade_manager.orders_in_limbo[position_key]
                ):
                    limbo_ts = trade_manager.orders_in_limbo[position_key][side]
                    if time.time() - limbo_ts < 5.0:  # 5s hard lock
                        return f"SKIPPED_IN_LIMBO_{action}"
        final_order_qty = 0.0
        current_price = 0.0
        position = await trade_manager.get_position(position_key)
        current_price = await price(symbol, position)
        if not current_price or current_price <= 0:
            current_price = safe_fetch_float(getattr(position, "mark_price", 0.0), 0.0)
        positionAmt = (
            abs(safe_fetch_float(getattr(position, "positionAmt", 0.0), 0.0))
            if position
            else 0.0
        )
        if action in ("AUGMENT", "QUICK_AUGMENT") and position and current_price > 0:
            _pos_gain = safe_fetch_float(getattr(position, "gain", 0.0), 0.0)
            _pos_notional = (
                abs(safe_fetch_float(getattr(position, "positionAmt", 0.0), 0.0))
                * current_price
            )
            _dd_bypass = "DD_BOUNCE_AUG" in (reason or "").upper()
            if _pos_notional > 0 and _pos_gain < config.MIN_GAIN and not _dd_bypass:
                logger.warning(
                    f"[AUGMENT_GATE_QUEUE] {position_key}: Blocked {action} at gain={_pos_gain:.3f}% < {config.MIN_GAIN:.3f}% before queuing. reason={reason} — NO BYPASS"
                )
                return f"BLOCKED_AUGMENT_QUEUE_LOW_GAIN_{_pos_gain:.3f}%"
        pos_min_qty = max(
            config.MIN_POSITION_SIZE / current_price,
            1.2 * trade_manager.min_qty.get(symbol, 0.0001),
        )
        qty = pos_min_qty
        if override_qty:
            final_order_qty = override_qty
        elif position and current_price > 0:
            try:
                preliminary_qty = 0.0
                if action == "OPEN":
                    preliminary_qty = max(
                        trade_manager.config.START_POSITION_SIZE / current_price,
                        1.2 * trade_manager.min_qty.get(symbol, 0.001),
                    )
                    if "HEDGE" in reason.upper():
                        exchange_min = 5.5 / current_price
                        qty = max(qty, exchange_min)
                    else:
                        qty = max(
                            qty, config.START_POSITION_SIZE / current_price, pos_min_qty
                        )
                elif action == "AUGMENT":
                    preliminary_qty = max(
                        2 * trade_manager.config.START_POSITION_SIZE / current_price,
                        0.6 * position.positionAmt,
                    )
                elif action in [
                    "REENTRY",
                    "QUICK_OPEN",
                    "REENTRY",
                    "AUGMENT",
                    "REVERSE",
                    "HEDGE_OPEN",
                ]:
                    preliminary_qty = max(
                        2 * trade_manager.config.START_POSITION_SIZE / current_price,
                        0.6 * position.positionAmt,
                    )
                if preliminary_qty > 0:
                    # 2026-04-16: breakout TF-size multiplier. Hedges opt out (hedge sizing owned by HedgeEngine).
                    if "HEDGE" not in (reason or "").upper() and action not in (
                        "HEDGE_OPEN",
                    ):
                        _tf_mult, _tf_lbl = _breakout_tf_size_mult(reason)
                        if _tf_mult != 1.0:
                            _orig_q = preliminary_qty
                            preliminary_qty = preliminary_qty * _tf_mult
                            logger.info(
                                f"[BREAKOUT_TF_SIZE] {position_key} {action}: TF={_tf_lbl} mult={_tf_mult:.2f} qty {_orig_q:.6f}→{preliminary_qty:.6f} (reason={reason[:60]})"
                            )
                    final_order_qty = await calculate_final_order_quantity(
                        position_key,
                        account_key,
                        symbol,
                        position,
                        action,
                        trade_manager,
                        conviction,
                        preliminary_qty,
                        reason,
                        None,
                    )
            except Exception as e:
                logger.warning(
                    f"[{position_key}] Preliminary qty calc failed ({e}), using default for handler."
                )
                final_order_qty = config.START_POSITION_SIZE / current_price
        elif "REDUCE" in action or action in [
            "REDUCE",
            "QUICK_CLOSE",
            "CLOSE",
            "PROFIT_TAKE",
            "HEDGE_CLOSE",
            "REVERSE_REDUCE",
        ]:
            final_order_qty = positionAmt - pos_min_qty
        elif "CLOSE" in action:
            final_order_qty = positionAmt
        unique_id = generate_unique_id(position_key, side, reason)
        is_full_close = action in ["CLOSE", "QUICK_CLOSE", "FULL_CLOSE"]
        order = {
            "account_key": account_key,
            "position_key": position_key,
            "symbol": symbol,
            "side": side,
            "quantity": final_order_qty,
            "current_price": current_price,
            "position_side": position_side,
            "unique_id": unique_id,
            "is_full_close": is_full_close,
            "action": action,
            "reason": reason_str,
            "override_qty": override_qty,
            "conviction": conviction,
        }
        added = False
        queue_fail_reason = ""
        for i in range(3):
            success, msg = await order_queue.add_order(order)
            if success:
                added = True
                break
            else:
                queue_fail_reason = msg
                await asyncio.sleep(0.1)
        if not added and action in [
            "CLOSE",
            "REDUCE",
            "QUICK_CLOSE",
            "STOP_MAJOR_LOSS_REDUCE",
        ]:
            logger.warning(
                f"[{position_key}] 🚨 QUEUE FULL/FAILED ({queue_fail_reason}) for {action}. Bypassing queue to execute immediately."
            )
            asyncio.create_task(trade_manager.execute_trade_action(**order))
            return f"QUEUED_BYPASS_{action}"
        if added:
            if not hasattr(trade_manager, "orders_in_limbo"):
                trade_manager.orders_in_limbo = {}
            if position_key not in trade_manager.orders_in_limbo:
                trade_manager.orders_in_limbo[position_key] = {}
            trade_manager.orders_in_limbo[position_key][side] = time.time()
            asyncio.create_task(
                trade_manager._expire_limbo_order(position_key, side, 8.0)
            )
            return f"QUEUED_{action}_{position_side}"
        else:
            logger.error(
                f"[{position_key}] ❌ Failed to queue {action}: {queue_fail_reason}"
            )
            return f"FAILED_QUEUE_{queue_fail_reason}"
    except Exception as e:
        logger.error(
            f"[{position_key}] Exception in queue_trade_action: {e}", exc_info=True
        )
        return f"ERROR_QUEUE_EXCEPTION"


