async def cleanup_stale_locks(trade_manager: MultiAccountTradeManager):
    while True:
        await asyncio.sleep(20)  # Check every 30 seconds
        now_ts = time.time()
        STALE_PENDING_SECONDS = 70  # A lock stuck in "pending" for 2 minutes is stale.
        STALE_COMPLETE_SECONDS = (
            45  # A "completed" lock is kept for 45s to ensure state updates propagate.
        )
        stale_keys_to_release = []
        for key, lock_data in list(trade_manager.active_order_locks.items()):
            status = lock_data.get("status", "unknown")
            timestamp = lock_data.get("timestamp", 0)
            if status == "pending" and (now_ts - timestamp) > STALE_PENDING_SECONDS:
                stale_keys_to_release.append(key)
            elif (
                status in ["complete", "error"]
                and (now_ts - timestamp) > STALE_COMPLETE_SECONDS
            ):
                stale_keys_to_release.append(key)
        if stale_keys_to_release:
            for key in stale_keys_to_release:
                trade_manager.active_order_locks.pop(key, None)


@timed_function("process_symbols_periodically")
async def process_symbols_periodically(
    order_queue: OrderQueue, trade_manager: MultiAccountTradeManager, account_key: str
):
    managed_accounts = (
        set(trade_manager.accounts.keys())
        if hasattr(trade_manager, "accounts")
        else set()
    )
    if account_key not in managed_accounts:
        logger.warning(
            f"[process _symbols_periodically] SKIPPING: account '{account_key}' not in managed accounts - loop will not start"
        )
        return
    logger.info(
        f"🔄 [MONITORIN G_LOOP] Started periodic symbol processing for {account_key}"
    )
    while True:
        try:
            await process_all_symbols_for_account(
                order_queue, trade_manager, account_key, force=False
            )
        except Exception as e:
            logger.error(
                f"[{account_key}] process_all_symbols_for_account CRASHED: {e}",
                exc_info=True,
            )
        await asyncio.sleep(config.SLEEP_TIME_PROC_ACCT)


_last_reshuffle_time = {}


def should_reshuffle(account_key: str, interval_minutes: int = 3) -> bool:
    now = datetime.now(timezone.utc)
    last_time = _last_reshuffle_time.get(account_key)
    if not last_time or (minutes_since(last_time, now) > interval_minutes):
        _last_reshuffle_time[account_key] = now
        return True
    return False


_valid_symbols_cache = {"symbols": set(), "ts": 0.0}


def get_tradeable_position_keys_for(trade_manager, account_key: str) -> list:
    import time as _t

    if _t.time() - _valid_symbols_cache["ts"] > 300:
        try:
            _valid_symbols_cache["symbols"] = set(
                json.load(open(Path(config.BASE_PATH) / "symbols.json"))
            )
            _valid_symbols_cache["ts"] = _t.time()
        except Exception:
            pass
    _valid = _valid_symbols_cache["symbols"]
    keys = set()
    if account_key == "ang":
        for s in trade_manager.symbols_ang_long:
            keys.add(f"ang:{s}_LONG")
        for s in trade_manager.symbols_ang_short:
            keys.add(f"ang:{s}_SHORT")
    elif account_key == "inf":
        for s in trade_manager.symbols_inf_long:
            keys.add(f"inf:{s}_LONG")
        for s in trade_manager.symbols_inf_short:
            keys.add(f"inf:{s}_SHORT")
    elif account_key == "flz":
        for s in trade_manager.symbols_flz:
            keys.add(f"flz:{s}_LONG")
            keys.add(f"flz:{s}_SHORT")
    elif account_key == "men":
        for s in trade_manager.symbols_men:
            keys.add(f"men:{s}_LONG")
            keys.add(f"men:{s}_SHORT")
    elif account_key == "fin":
        for s in trade_manager.symbols_fin:
            keys.add(f"fin:{s}_LONG")
            keys.add(f"fin:{s}_SHORT")
    if account_key in trade_manager.positions_by_account:
        for k, pos in trade_manager.positions_by_account[account_key].items():
            if pos and abs(safe_fetch_float(getattr(pos, "positionAmt", 0.0), 0.0)) > 0:
                sym = getattr(pos, "symbol", "")
                if _valid and sym and sym not in _valid:
                    logger.warning(
                        f"[SYMBOL_GUARD] {k}: {sym} not in symbols.json — SKIPPING (orphaned position from scanner/outlier)"
                    )
                    continue
                keys.add(k)
    return list(keys)


@timed_function("process_all_symbols_for_account")
async def process_all_symbols_for_account(
    order_queue: OrderQueue,
    trade_manager: MultiAccountTradeManager,
    account_key: str,
    force: bool = False,
):
    if account_key not in trade_manager.accounts:
        return
    acct_pos = trade_manager.positions_by_account.get(account_key, {})
    current_open_keys = {
        k
        for k, p in acct_pos.items()
        if abs(safe_fetch_float(getattr(p, "positionAmt", 0.0), 0.0)) > 0.0001
    }
    all_tradeable_keys = await trade_manager.load_tradeable()
    watchlist_keys = {k for k in all_tradeable_keys if k.startswith(f"{account_key}:")}
    total_keys_to_monitor = current_open_keys | watchlist_keys
    now_ts = time.time()

    def staleness_for(k):
        return now_ts - trade_manager.last_monitored_positions.get(k, 0.0)

    starved_priority = []  # Open positions (Bleeding risk - check fast)
    starved_standard = []  # Watchlist items (Entry hunting - check slow)
    for k in total_keys_to_monitor:
        is_open = k in current_open_keys
        threshold = 20.0 if is_open else 150.0
        if staleness_for(k) > threshold:
            if is_open:
                starved_priority.append(k)
            else:
                starved_standard.append(k)
    qd = trade_manager.account_position_queues.get(account_key)
    queue_length = len(qd["queue"]) if qd else 0
    is_busy = queue_length > 150
    batch_limit = 60 if is_busy else 400
    random.shuffle(starved_standard)
    batch = (starved_priority + starved_standard)[:batch_limit]
    if batch:
        for k in batch:
            trade_manager.last_monitored_positions[k] = now_ts
        open_count = len([k for k in batch if k in current_open_keys])
        logger.info(
            f"[{account_key}] MONITOR_QUEUE: Total={len(batch)} (OPEN/PRIORITY={open_count}, WATCHLIST={len(batch) - open_count}) | Q={queue_length}"
        )
        await monitor_entries(
            order_queue, trade_manager, account_key, batch, force=True
        )


