async def periodic_tasks(
    order_queue: OrderQueue, trade_manager: MultiAccountTradeManager
):
    if not hasattr(trade_manager, "_last_priority_monitor"):
        trade_manager._last_priority_monitor = {}
    if not hasattr(trade_manager, "_last_regular_monitor"):
        trade_manager._last_regular_monitor = {}
    _oversize_cooldown = {}
    while True:
        await asyncio.sleep(config.SLEEP_TIME_PER_TASKS)
        # ═══ EMERGENCY POSITION SIZE GUARD — catches Finandy TP ladder bug ═══
        # Finandy TP orders bypass our guards. This catches ANY position that exceeds MAX_POSITION_SIZE
        # and force-closes the excess immediately. Runs every cycle.
        managed_accounts = set(trade_manager.accounts.keys())
        for _ak, _pdict in trade_manager.positions_by_account.items():
            if _ak not in managed_accounts:
                continue
            _max_usd = get_max_position_size(account_key=_ak)
            for _pk, _pos in _pdict.items():
                if not _pos:
                    continue
                _amt = abs(safe_fetch_float(getattr(_pos, "positionAmt", 0), 0))
                if _amt == 0:
                    continue
                _mp = safe_fetch_float(getattr(_pos, "mark_price", 0), 0)
                if _mp <= 0:
                    continue
                _notional = _amt * _mp
                if _notional > _max_usd * 1.5:
                    _cd_key = f"oversize:{_pk}"
                    # 2026-04-26 FIX: was 30s cooldown — when position at loss, NOLOSS_GATE correctly blocks
                    # the FORCE_REDUCE every 30s causing log spam + deadlock (37 firings/18min on flz:BNBUSDC_LONG).
                    # New: 600s cooldown when at loss (just log warn, don't try to reduce — respects user "never close at loss" rule).
                    # 30s cooldown when at gain (proceed with reduce — safe to realize).
                    _ov_gain = safe_fetch_float(getattr(_pos, "gain", 0), 0.0)
                    _ov_at_loss = _ov_gain < 0
                    _ov_cd = 600 if _ov_at_loss else 30
                    if time.time() - _oversize_cooldown.get(_cd_key, 0) < _ov_cd:
                        continue
                    _oversize_cooldown[_cd_key] = time.time()
                    _excess_usd = _notional - _max_usd
                    _excess_qty = _excess_usd / _mp
                    _, _sym, _ps = parse_position_key(_pk)
                    _is_long = _ps == "LONG"
                    _close_side = "SELL" if _is_long else "BUY"
                    if _ov_at_loss:
                        logger.warning(
                            f"⚠️ [EMERGENCY_OVERSIZE_AT_LOSS_SKIP] {_pk}: notional=${_notional:.2f} > max=${_max_usd:.2f} BUT gain={_ov_gain:.2f}%<0 — skipping FORCE_REDUCE (NOLOSS gate would block). Will recheck in {_ov_cd}s. Hedge it or wait for gain>=0."
                        )
                        continue
                    logger.critical(
                        f"🚨🚨🚨 [EMERGENCY_OVERSIZE] {_pk}: notional=${_notional:.2f} > max=${_max_usd:.2f} (150%) gain={_ov_gain:.2f}%. FORCE REDUCING excess ${_excess_usd:.2f} ({_excess_qty:.4f} qty)"
                    )
                    try:
                        await trade_manager.execute_now(
                            _pk,
                            _ak,
                            _sym,
                            _amt,
                            _close_side,
                            _ps,
                            _excess_qty,
                            _mp,
                            f"EMERGENCY_OVERSIZE_{int(time.time())}",
                            f"FORCE_REDUCE_OVERSIZE_{_notional:.0f}>${_max_usd:.0f}",
                            False,
                            "REDUCE",
                            is_hedge=False,
                        )
                    except Exception as _oe:
                        logger.error(
                            f"[EMERGENCY_OVERSIZE] Failed to reduce {_pk}: {_oe}"
                        )
        open_position_keys = []
        high_gain_positions = []
        for account_key, positions_dict in trade_manager.positions_by_account.items():
            if (
                account_key not in managed_accounts
                or account_key not in config.ACCOUNT_KEYS
            ):
                continue
            for position_key, position in positions_dict.items():
                if position and position.positionAmt > 0:
                    mark_price_val = safe_fetch_float(position.mark_price, 0.0)
                    if (
                        position.positionAmt * mark_price_val
                    ) > config.MIN_POSITION_SIZE:
                        if trade_manager.is_symbol_allowed(
                            account_key, position.symbol, position_key
                        ):
                            if position_key not in open_position_keys:
                                open_position_keys.append(position_key)
                            gain = safe_fetch_float(position.gain, 0.0)
                            high_gain_on_price = gain > config.MIN_GAIN
                            high_gain_on_realized = (
                                position.realized_pnl > config.MIN_GAIN and gain > 0
                            )

                            # MANDATORY AUGMENTATION BYPASS
                            # If gain is > 3.0%, we MUST evaluate for augmentation, ignoring static filters
                            is_huge_gain = gain > 3.0 or position.realized_pnl > 3.0

                            if high_gain_on_price or high_gain_on_realized:
                                min_since_last_aug = (
                                    (
                                        datetime.now(timezone.utc)
                                        - position.last_augmentation_time
                                    ).total_seconds()
                                    / 60
                                    if position.last_augmentation_time
                                    else 999
                                )
                                if min_since_last_aug > 5:
                                    trigger_reason = (
                                        "gain>MIN_GAIN"
                                        if high_gain_on_price
                                        else "realized_pnl>MIN_GAIN"
                                    )
                                    high_gain_positions.append(position_key)
                                    logger.info(
                                        f"[BIG_GAIN_ALERT] {position_key}: gain={position.gain:.2f}% reason={trigger_reason} but not augmented in {min_since_last_aug:.1f}min - forcing evaluation"
                                    )
        if high_gain_positions:
            logger.warning(
                f"[FORCE_AUGMENT_DIRECT] Processing {len(high_gain_positions)} high-gain positions with DIRECT augmentation"
            )
            for position_key in high_gain_positions:
                try:
                    account_key, symbol, position_side = parse_position_key(
                        position_key
                    )
                    position = trade_manager.positions_by_account.get(
                        account_key, {}
                    ).get(position_key) or trade_manager.positions.get(position_key)
                    logger.warning(
                        f"[FORCE_AUGMENT_DIRECT] {position_key}: gain={position.gain:.2f}% - DIRECT augmentation with fresh data"
                    )
                    normalized_symbol = symbol.strip().upper()
                    side = position_side

                    # HUGE GAIN BYPASS: Skip leaderboard check if gain is substantial
                    bypass_filter = position.gain > 3.0 or position.realized_pnl > 3.0

                    if not bypass_filter and not _check_leaderboard_allowed(
                        trade_manager,
                        normalized_symbol,
                        side,
                        account_key,
                        position_key,
                    ):
                        logger.debug(
                            f"[{account_key}] process_all_symbols_for_account FILTERED: {side} symbol {normalized_symbol} not in leaderboard lists (FORBIDDEN)"
                        )
                        continue
                    await direct_high_gain_augmentation(
                        position_key, order_queue, trade_manager
                    )
                    logger.warning(
                        f"[FORCE_AUGMENT_DIRECT] {position_key}: Completed direct augmentation"
                    )
                except Exception as e:
                    logger.error(
                        f"[FORCE_AUGMENT_DIRECT] Error processing {position_key}: {e}",
                        exc_info=True,
                    )
        if open_position_keys:
            logger.debug(
                f"[RISK_LOOP] Found {len(open_position_keys)} open positions to re-evaluate: {open_position_keys[:5]}..."
            )
            grouped_keys = defaultdict(list)
            for key in open_position_keys:
                try:
                    account_key, _, _ = parse_position_key(key)
                    grouped_keys[account_key].append(key)
                except ValueError:
                    continue  # Skip any malformed keys
            for account_key, keys_list in grouped_keys.items():
                logger.debug(
                    f"[PROCESS_SYMBOLS] (periodic_tasks) Calling monitor_entries for {account_key} with {len(keys_list)} positions"
                )
                allowed_batch = filter_monitor_keys(
                    trade_manager, account_key, keys_list
                )
                if allowed_batch:
                    await monitor_entries(
                        order_queue,
                        trade_manager,
                        account_key=account_key,
                        position_keys=allowed_batch,
                        event_type=None,
                        is_priority_add=False,
                        force=False,
                    )
        for account_key in managed_accounts:
            if (
                account_key not in trade_manager.positions_by_account
                or not trade_manager.positions_by_account.get(account_key)
            ):
                await monitor_entries(
                    order_queue,
                    trade_manager,
                    account_key=account_key,
                    position_keys=None,
                    event_type="periodic_tasks_no_positions",
                    is_priority_add=False,
                    force=False,
                )


