async def performance_report_loop(trade_manager: MultiAccountTradeManager):
    """Every 5 min: compute per-symbol rolling stats, write data/reports/performance_report.txt + .json."""
    await asyncio.sleep(30.0)
    report_dir = Path(config.BASE_PATH) / "data" / "reports"
    report_dir.mkdir(parents=True, exist_ok=True)
    while True:
        try:
            if not config.SYMBOL_PERF_ENABLED:
                await asyncio.sleep(300)
                continue
            from utils import _ensure_cache, refresh_cache

            stats = refresh_cache()
            if not stats:
                await asyncio.sleep(300)
                continue
            tiers = {"A": [], "B": [], "C": []}
            for sym, s in sorted(
                stats.items(), key=lambda x: x[1].get("total_pnl_pct", 0), reverse=True
            ):
                tiers[s.get("tier", "B")].append(s)
            now_str = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
            lines = [
                f"PERFORMANCE REPORT — {now_str}",
                f"{'=' * 80}",
                f"Total: {len(stats)} symbols | A={len(tiers['A'])} B={len(tiers['B'])} C={len(tiers['C'])}",
                f"Window: {config.SYMBOL_PERF_WINDOW_DAYS} days | Min trades: {config.SYMBOL_PERF_MIN_TRADES}",
                "",
            ]
            open_symbols = set()
            for acct, pdict in trade_manager.positions_by_account.items():
                for pk, pos in pdict.items():
                    if pos and abs(getattr(pos, "positionAmt", 0)) > 0:
                        sym = (
                            pk.split(":")[-1].rsplit("_", 1)[0]
                            if ":" in pk
                            else pk.rsplit("_", 1)[0]
                        )
                        open_symbols.add(sym)
            for tier_name in ("A", "B", "C"):
                items = tiers[tier_name]
                lines.append(f"--- TIER {tier_name} ({len(items)} symbols) ---")
                for s in items:
                    marker = " ** OPEN **" if s["symbol"] in open_symbols else ""
                    lines.append(
                        f"  {s['symbol']:>15s}  WR={s['win_rate']:.0%}  avg={s['avg_gain_pct']:+.2f}%  total={s['total_pnl_pct']:+.1f}%  trades={s['trade_count']:3d}  mult={s['order_multiplier']:.2f}{marker}"
                    )
                lines.append("")
            total_pnl = sum(s["total_pnl_pct"] for s in stats.values())
            avg_wr = sum(s["win_rate"] for s in stats.values()) / max(1, len(stats))
            lines.extend(
                [
                    "SUMMARY:",
                    f"  Total PnL (all symbols): {total_pnl:+.1f}%",
                    f"  Avg win rate: {avg_wr:.0%}",
                    f"  A-tier avg mult: {sum(s['order_multiplier'] for s in tiers['A']) / max(1, len(tiers['A'])):.2f}",
                    f"  C-tier avg mult: {sum(s['order_multiplier'] for s in tiers['C']) / max(1, len(tiers['C'])):.2f}",
                    "",
                ]
            )
            with open(report_dir / "performance_report.txt", "w") as f:
                f.write("\n".join(lines))
            import json as _json

            with open(report_dir / "performance_report.json", "w") as f:
                _json.dump(
                    {
                        "generated_at": now_str,
                        "stats": stats,
                        "tiers": {
                            k: [s["symbol"] for s in v] for k, v in tiers.items()
                        },
                        "total_pnl_pct": round(total_pnl, 2),
                        "avg_win_rate": round(avg_wr, 4),
                    },
                    f,
                    indent=1,
                )
            logger.info(
                f"[PERF_REPORT] Written: {len(stats)} symbols (A={len(tiers['A'])} B={len(tiers['B'])} C={len(tiers['C'])}) total_pnl={total_pnl:+.1f}%"
            )
        except Exception as e:
            logger.error(f"[PERF_REPORT] Error: {e}", exc_info=True)
        await asyncio.sleep(config.SYMBOL_PERF_REFRESH_SECONDS)


